// Magellan Lite's source, run in the browser by Try it: written by demo/build_site.py -- do not edit by hand
self.MAGELLAN_ENGINE = {"version": "0.2.0", "files": {"magellan_lite/__init__.py": "\"\"\"Magellan Lite: what a change touched, and the checklist of what it could break.\"\"\"\n\n__version__ = \"0.2.0\"\n", "magellan_lite/brief.py": "\"\"\"The brief: a verdict small enough for an AI agent to act on.\n\n``check`` is written for a person: every change, the whole checklist, the whole blast radius.\nAn agent that has just edited code wants the opposite: one line saying whether to stop, the\nfew things to fix (each with where it is and what to do), the files it did not edit but\nshould read again, and the tests to run. ``magellan-lite brief`` gives that, and so does the\nMCP tool ``magellan_lite_brief`` (mcp.py).\n\n    magellan-lite brief [PATH] [--against git:HEAD] [--format json|text] [--limit 8]\n\nThe JSON, with its keys kept stable (lists are cut at ``--limit``; ``omitted`` says how many\nentries each one lost, and ``check --format json`` has them all)::\n\n    {\n      \"verdict\": \"block\",                       # ok | review | block: the same as `check`\n      \"summary\": \"Do not commit yet: 1 critical finding, first signature-break at ...\",\n      \"against\": \"git:HEAD\",\n      \"counts\": {\"findings\": {\"critical\": 1, \"high\": 0, \"medium\": 0, \"low\": 0},\n                 \"changes\": 1, \"reached\": 2, \"errors\": 0},\n      \"changes\": [{\"name\": \"app.pay.charge\", \"kind\": \"signature\", \"where\": \"app/pay.py:1\",\n                   \"detail\": \"(amount)  ->  (amount, currency)\"}],\n      \"do_first\": [{\"severity\": \"critical\", \"rule\": \"signature-break\",\n                    \"where\": \"app/shop.py:5\", \"what\": \"...\", \"why\": \"...\", \"fix\": \"...\"}],\n      \"reaches\": [{\"name\": \"app.shop.checkout\", \"where\": \"app/shop.py:4\", \"hops\": 1,\n                   \"score\": 0.85, \"why\": \"app.shop.checkout calls app.pay.charge (...)\"}],\n      \"check_these_files\": [{\"path\": \"app/shop.py\", \"why\": \"signature-break at line 5; ...\"}],\n      \"tests_to_run\": [{\"path\": \"tests/test_pay.py\", \"why\": \"mentions charge\"}],\n      \"errors\": [\"legacy/old.py:3: invalid syntax\"],\n      \"omitted\": {\"changes\": 0, \"do_first\": 0, \"reaches\": 0, \"check_these_files\": 0,\n                  \"tests_to_run\": 0, \"errors\": 0}\n    }\n\n- ``do_first``: the checklist, worst first: by severity, then blocking rules, then closeness\n  to the edit (inside an edited definition, then one hop away, two...). Every finding is about\n  the change already: the engine keeps only what lands in edited code, or what the edit breaks.\n- ``reaches``: the blast radius (radius.py), the highest scores first; ``where`` is the file.\n- ``check_these_files``: files the change did not edit that hold a finding or a definition it\n  reaches, findings first, then by how hard they are hit.\n- ``tests_to_run``: test files (found by their names: ``test_*.py``, ``*_test.py``,\n  ``*Test.java``, ``*.spec.ts``, files under ``tests/`` in the other languages...) that the\n  change edited, or that mention a definition it changed or reaches closely. A plain text\n  search, so it errs quiet: a short or common name (``get``, ``run``) counts only when its\n  class or module is named in the file too.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport re\nfrom pathlib import Path\n\nfrom magellan_lite.combine import _changed\nfrom magellan_lite.defs import Definition, definitions\nfrom magellan_lite.engine import check_snapshots, load_before\nfrom magellan_lite.findings import SEVERITIES, Finding, blocking_rules\nfrom magellan_lite.graph import _NO_GUESS\nfrom magellan_lite.report import VERDICTS, Report\nfrom magellan_lite.source import Snapshot, module_name, working_tree\n\n#: how many entries each list keeps by default\nLIMIT = 8\n#: reached definitions this close (score) count for tests_to_run; the full brief's \"near\"\nNEAR = 0.25\n#: names too vague to look for alone in a test file\n_VAGUE = _NO_GUESS | {\"main\", \"init\", \"setup\", \"process\", \"handle\", \"test\", \"value\", \"data\",\n                      \"name\", \"result\", \"item\", \"call\", \"apply\", \"execute\", \"build\", \"make\",\n                      \"new\", \"reset\", \"next\", \"save\", \"check\", \"parse\", \"render\", \"create\"}\n_TOKENS = re.compile(r\"[A-Za-z_][A-Za-z0-9_]*\")\n_COBOL_TOKENS = re.compile(r\"[A-Za-z0-9_][A-Za-z0-9_-]*[A-Za-z0-9_]\")   # CALC-INTEREST\n\n\ndef brief(root: str | Path = \".\", against: str = \"git:HEAD\", limit: int = LIMIT) -> dict:\n    \"\"\"Check a project on disk against a baseline (``git:REV`` or a directory) and brief it.\"\"\"\n    root = Path(root).resolve()\n    before, after = load_before(root, against), working_tree(root)\n    return build(check_snapshots(before, after, root, against), before, after, limit)\n\n\ndef build(report: Report, before: Snapshot, after: Snapshot, limit: int = LIMIT) -> dict:\n    \"\"\"The brief of a finished check (see the module docstring for its shape).\"\"\"\n    limit = max(1, int(limit))\n    defs = definitions(after)                       # trees are parsed already: cheap\n    touched = _changed(before.files, after.files) | set(report.files_changed)\n    changed = {c.name for c in report.changes} | {c.before.name for c in report.changes\n                                                    if c.before}\n    reached = {a[\"name\"]: a for a in report.affected}\n    blocking = blocking_rules()\n    by_path: dict[str, list[Definition]] = {}\n    for d in defs.values():\n        by_path.setdefault(d.path, []).append(d)\n\n    def closeness(f: Finding) -> float:\n        d = _innermost(by_path.get(f.path, ()), f.line)\n        if d is not None and d.name in changed:\n            return 0\n        if d is not None and d.name in reached:\n            return reached[d.name][\"hops\"]\n        return 0.5 if f.path in touched else 99\n\n    findings = sorted(report.findings, key=lambda f: (\n        f.rank, f.rule not in blocking, closeness(f), f.path, f.line, f.rule))\n    severity = {s: sum(f.severity == s for f in findings) for s in SEVERITIES}\n\n    near = [defs[a[\"name\"]] for a in report.affected\n            if a[\"score\"] >= NEAR and a[\"name\"] in defs]\n    edited = [c.after or c.before for c in report.changes] + \\\n             [c.before for c in report.changes if c.kind == \"renamed\"]\n    lists = {\n        \"changes\": [{\"name\": c.name, \"kind\": c.kind, \"where\": f\"{c.path}:{c.line}\",\n                     \"detail\": _cut(c.detail, 160)} for c in report.changes],\n        \"do_first\": [{\"severity\": f.severity, \"rule\": f.rule, \"where\": f\"{f.path}:{f.line}\",\n                      \"what\": _cut(f.message, 240), \"why\": _cut(f.detail, 240),\n                      \"fix\": _cut(f.fix, 200)} for f in findings],\n        \"reaches\": [{\"name\": a[\"name\"], \"where\": f\"{a['path']}:{a['line']}\", \"hops\": a[\"hops\"],\n                     \"score\": a[\"score\"], \"why\": _cut(a[\"why\"], 200)} for a in report.affected],\n        \"check_these_files\": _files_to_check(findings, report.affected, touched),\n        \"tests_to_run\": find_tests(after, edited, near, touched),\n        \"errors\": list(report.errors),\n    }\n    counts = {\"findings\": severity, \"changes\": len(report.changes),\n              \"reached\": len(report.affected), \"errors\": len(report.errors)}\n    out = {\n        \"verdict\": report.verdict,\n        \"summary\": _summary(report, findings, counts,\n                            len({a[\"path\"] for a in report.affected} - touched)),\n        \"against\": report.against,\n        \"counts\": counts,\n    }\n    out.update({key: items[:limit] for key, items in lists.items()})\n    out[\"omitted\"] = {key: max(0, len(items) - limit) for key, items in lists.items()}\n    return out\n\n\ndef fails(b: dict, fail_on: str) -> bool:\n    \"\"\"Should this brief stop a commit? ``fail_on`` is a verdict, or ``never`` (as ``check``).\"\"\"\n    return fail_on != \"never\" and VERDICTS.index(b[\"verdict\"]) >= VERDICTS.index(fail_on)\n\n\n# -- the parts -------------------------------------------------------------------------------\n\ndef _innermost(defs, line: int) -> Definition | None:\n    \"\"\"The narrowest of ``defs`` (one file's) around ``line``: the method, not its class.\"\"\"\n    best = None\n    for d in defs:\n        if d.line <= line <= d.end_line:\n            if best is None or d.end_line - d.line < best.end_line - best.line:\n                best = d\n    return best\n\n\ndef _files_to_check(findings: list[Finding], affected: list[dict], touched: set[str]) -> list[dict]:\n    \"\"\"Files the change did not edit that hold a finding or a definition it reaches.\"\"\"\n    files: dict[str, dict] = {}\n    for f in findings:\n        if f.path in touched or not f.path:\n            continue\n        entry = files.setdefault(f.path, {\"rank\": 9, \"score\": 0.0, \"findings\": [], \"reached\": []})\n        entry[\"rank\"] = min(entry[\"rank\"], f.rank)\n        entry[\"findings\"].append(f\"{f.rule} at line {f.line}\")\n    for a in affected:\n        if a[\"path\"] in touched:\n            continue\n        entry = files.setdefault(a[\"path\"], {\"rank\": 9, \"score\": 0.0, \"findings\": [],\n                                             \"reached\": []})\n        entry[\"score\"] = max(entry[\"score\"], a[\"score\"])\n        entry[\"reached\"].append(a)\n\n    out = []\n    for path, e in sorted(files.items(), key=lambda kv: (kv[1][\"rank\"], -kv[1][\"score\"], kv[0])):\n        why = []\n        if e[\"findings\"]:\n            why.append(_listing(e[\"findings\"], 2))\n        if e[\"reached\"]:\n            why.append(\"the change reaches \" + _listing(\n                [f\"{a['name']} ({_plural(a['hops'], 'hop')})\" for a in e[\"reached\"]], 2))\n        out.append({\"path\": path, \"why\": \"; \".join(why)})\n    return out\n\n\ndef find_tests(snapshot: Snapshot, changed: list[Definition], near: list[Definition],\n               touched: set[str] = frozenset()) -> list[dict]:\n    \"\"\"Test files to run, best first: ``[{\"path\", \"why\"}]``. Those the change edited, then those\n    that mention a changed definition, then those that mention a closely reached one.\"\"\"\n    looks: dict[tuple[str, str], int] = {}       # (word, context) -> 0 changed, 1 reached\n    held: dict[str, list[str]] = {}             # test file -> its tests the change reaches\n    for tier, group in ((0, changed), (1, near)):\n        for d in group:\n            if d is None:\n                continue\n            if is_test_file(d.path):            # a test runs where it is: never \"mentioned\"\n                held.setdefault(d.path, []).append(_look_for(d)[0])\n                continue\n            key = _look_for(d)\n            looks[key] = min(looks.get(key, tier), tier)\n    out = []\n    for path in sorted(snapshot.files):\n        if not is_test_file(path):\n            continue\n        text = snapshot.files[path]\n        words = set(_TOKENS.findall(text))\n        if \"-\" in text:\n            words |= set(_COBOL_TOKENS.findall(text))\n        hits: list[list[str]] = [[], []]\n        for (word, context), tier in sorted(looks.items()):\n            if word in words and (not context or context in words) and word not in hits[tier]:\n                hits[tier].append(word)\n        mine = sorted(set(held.get(path, ())))\n        why = []\n        if path in touched:\n            why.append(\"this change edits it\")\n        if hits[0] or hits[1]:\n            why.append(\"mentions \" + _listing(hits[0] + hits[1], 4))\n        if mine and path not in touched:\n            why.append(f\"the change reaches {_listing(mine, 2)} here\")\n        if not why:\n            continue\n        out.append(((path not in touched, not hits[0], -len(hits[0]), -len(hits[1] + mine),\n                     path), {\"path\": path, \"why\": \"; \".join(why)}))\n    return [entry for _key, entry in sorted(out, key=lambda kv: kv[0])]\n\n\ndef is_test_file(path: str) -> bool:\n    \"\"\"A test file, by the names test runners look for. Python: ``test*.py`` (unittest) and\n    ``*_test.py`` (pytest). The other languages: ``*Test.java``, ``*.spec.ts``, ``test_*.c``,\n    or anything under a ``test``/``tests``/``__tests__`` folder (Maven's ``src/test``).\"\"\"\n    name = path.rsplit(\"/\", 1)[-1]\n    stem = name.rsplit(\".\", 1)[0]\n    if name.endswith(\".py\"):\n        return stem.startswith(\"test\") or stem.endswith(\"_test\")\n    if any(part in (\"test\", \"tests\", \"__tests__\", \"testing\") for part in path.split(\"/\")[:-1]):\n        return True\n    low = stem.lower()\n    return low.startswith(\"test\") or low.endswith((\"test\", \"tests\", \".spec\", \"_spec\"))\n\n\ndef _look_for(d: Definition) -> tuple[str, str]:\n    \"\"\"``(word, context)``: the name a test would use for ``d``, and, when that name is too\n    short or common to mean ``d`` alone, the class or module that must be named too.\"\"\"\n    word = (d.label or d.short).split(\"(\", 1)[0]\n    bare = d.name.split(\"@\", 1)[-1].split(\"(\", 1)[0]\n    owner = bare.rsplit(\".\", 1)[0] if \".\" in bare else \"\"\n    if d.kind == \"method\" and owner:\n        context = owner.rsplit(\".\", 1)[-1]                  # the class\n    elif d.path.endswith(\".py\"):\n        context = module_name(d.path).rsplit(\".\", 1)[-1]    # the module\n    else:\n        context = d.path.rsplit(\"/\", 1)[-1].split(\".\", 1)[0]\n    if word.startswith(\"__\") and word.endswith(\"__\") or word.startswith(\"<\"):   # __init__, <init>\n        return context, \"\"\n    if len(word) < 4 or word.lower() in _VAGUE:\n        return word, context\n    return word, \"\"\n\n\ndef _summary(report: Report, findings: list[Finding], counts: dict, other_files: int) -> str:\n    if not report.changes and not findings:\n        return (f\"Nothing to check: no function, class or constant differs from \"\n                f\"{report.against}.\" + _not_checked(counts[\"errors\"]))\n    sev = [f\"{n} {s}\" for s, n in counts[\"findings\"].items() if n]\n    found = (\" and \".join([\", \".join(sev[:-1]), sev[-1]] if len(sev) > 1 else sev)\n             + f\" finding{'' if len(findings) == 1 else 's'}\") if sev else \"\"\n    first = f\"{findings[0].rule} at {findings[0].path}:{findings[0].line}\" if findings else \"\"\n    reach = \"\"\n    if report.affected:\n        reach = (f\"; it reaches {_plural(len(report.affected), 'definition')} the change did \"\n                 f\"not edit\" + (f\", in {_plural(other_files, 'other file')}\" if other_files\n                                else \"\"))\n    changes = (f\"{_plural(len(report.changes), 'change')} in \"\n               f\"{_plural(len(report.files_changed), 'file')}\")\n    if report.verdict == \"block\":\n        head = f\"Do not commit yet: {found}, first {first}\"\n    elif report.verdict == \"review\":\n        head = f\"Review before committing: {found}, first {first}\"\n    elif findings:\n        head = f\"OK to commit after a look: {changes}, only {found} (first {first})\"\n    else:\n        head = f\"OK to commit as far as Magellan Lite can see: {changes}, nothing on the checklist\"\n    return head + reach + \".\" + _not_checked(counts[\"errors\"])\n\n\ndef _not_checked(n: int) -> str:\n    if not n:\n        return \"\"\n    return f\" {n} {'file or rule' if n == 1 else 'files or rules'} could not be checked: see errors.\"\n\n\ndef _plural(n: int, word: str) -> str:\n    return f\"{n} {word}{'' if n == 1 else 's'}\"\n\n\ndef _listing(items: list[str], most: int) -> str:\n    shown = \", \".join(items[:most])\n    return shown + (f\" and {len(items) - most} more\" if len(items) > most else \"\")\n\n\ndef _cut(text: str, most: int) -> str:\n    text = \" \".join((text or \"\").split())\n    return text if len(text) <= most else text[:most - 1].rstrip() + \"\u2026\"\n\n\n# -- the terminal ----------------------------------------------------------------------------\n\n_OMITTED = {\"changes\": (\"change\", \"changes\"), \"do_first\": (\"finding\", \"findings\"),\n            \"reaches\": (\"reached definition\", \"reached definitions\"),\n            \"check_these_files\": (\"file to check\", \"files to check\"),\n            \"tests_to_run\": (\"test file\", \"test files\"), \"errors\": (\"error\", \"errors\")}\n_KIND = {\"removed\": \"del\", \"renamed\": \"ren\", \"signature\": \"sig\", \"value\": \"val\", \"body\": \"body\",\n         \"added\": \"new\"}\n\n\ndef text(b: dict) -> str:\n    \"\"\"The brief in a terminal: terse, no colour, safe to paste into a prompt.\"\"\"\n    lines = [f\"magellan-lite brief: {b['verdict'].upper()} \u00b7 {b['summary']}\"]\n    if b[\"changes\"]:\n        lines.append(\"  changes\")\n        lines += [f\"    {_KIND.get(c['kind'], c['kind']):>4}  {c['name']}  {c['where']}\"\n                  for c in b[\"changes\"]]\n    if b[\"do_first\"]:\n        lines.append(\"  do first\")\n        for i, f in enumerate(b[\"do_first\"], 1):\n            lines.append(f\"    {i}. {f['severity'].upper()} {f['rule']}  {f['where']}\")\n            lines.append(f\"       {f['what']}\")\n            if f[\"why\"]:\n                lines.append(f\"       why: {f['why']}\")\n            if f[\"fix\"]:\n                lines.append(f\"       fix: {f['fix']}\")\n    if b[\"reaches\"]:\n        lines.append(\"  reaches\")\n        lines += [f\"    {a['score']:.2f}  {_plural(a['hops'], 'hop'):<7} {a['name']}  {a['where']}\"\n                  for a in b[\"reaches\"]]\n    if b[\"check_these_files\"]:\n        lines.append(\"  check these files (the change did not edit them)\")\n        lines += [f\"    {f['path']}  ({f['why']})\" for f in b[\"check_these_files\"]]\n    if b[\"tests_to_run\"]:\n        lines.append(\"  tests to run\")\n        lines += [f\"    {t['path']}  ({t['why']})\" for t in b[\"tests_to_run\"]]\n    if b[\"errors\"]:\n        lines.append(\"  not checked\")\n        lines += [f\"    {e}\" for e in b[\"errors\"]]\n    cut = [f\"{n} more {_OMITTED[key][n != 1]}\" for key, n in b[\"omitted\"].items() if n]\n    if cut:\n        lines.append(f\"  (not shown: {', '.join(cut)}; `magellan-lite check` lists everything)\")\n    return \"\\n\".join(lines)\n", "magellan_lite/combine.py": "\"\"\"Two people's work, checked together: the part of the team check that needs no git.\n\n``combine`` takes three versions of a project -- the shared base, your work and a teammate's --\nand reports only the problems the combination has. ``magellan-lite team`` (team.py) feeds it\nfrom git; the website's Team suite feeds it from GitHub, in the browser, so this module must\nstay free of git, subprocess and the file system.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom pathlib import Path\n\nfrom magellan_lite.engine import check_snapshots\nfrom magellan_lite.report import Report\nfrom magellan_lite.source import Snapshot\n\nWIP = \"refs/wip\"\n\n\n@dataclass\nclass Combination:\n    \"\"\"Your work and one teammate's, checked together.\"\"\"\n    name: str\n    shared: float                   # when they shared it (unix time)\n    their_changes: list = field(default_factory=list)\n    report: Report | None = None    # the problems only the combination has\n    overlap: list[str] = field(default_factory=list)   # files you both edited\n\n    @property\n    def verdict(self) -> str:\n        return self.report.verdict if self.report else \"ok\"\n\n    def to_dict(self) -> dict:\n        return {\"name\": self.name, \"shared\": self.shared, \"verdict\": self.verdict,\n                \"their_changes\": [c.to_dict() for c in self.their_changes],\n                \"findings\": [f.to_dict() for f in (self.report.findings if self.report else [])],\n                \"affected\": self.report.affected if self.report else [],\n                \"overlap\": self.overlap}\n\n\ndef _same(x: str | None, y: str | None) -> bool:\n    \"\"\"Equal apart from line endings: a Windows checkout (CRLF) of an unchanged file is\n    unchanged.\"\"\"\n    if x is None or y is None:\n        return x is y\n    return x.replace(\"\\r\\n\", \"\\n\") == y.replace(\"\\r\\n\", \"\\n\")\n\n\ndef _changed(a: dict, b: dict) -> set[str]:\n    return {p for p in set(a) | set(b) if not _same(a.get(p), b.get(p))}\n\n\ndef combine(root: Path, base: Snapshot, mine: Snapshot, theirs: Snapshot, name: str,\n            shared: float = 0.0, alone: tuple[Report, Report] | None = None) -> Combination:\n    \"\"\"Check ``mine`` and ``theirs`` (both made from ``base``) together. A file only they\n    changed comes from them; a file you both changed is checked with your version.\n    ``alone``: each one's own check, when the caller has them already.\"\"\"\n    b, m, t = base.files, mine.files, theirs.files\n    yours, their = _changed(b, m), _changed(b, t)\n    both = sorted(p for p in yours & their if not _same(m.get(p), t.get(p)))\n    together = dict(m)\n    for p in their - yours:\n        if p in t:\n            together[p] = t[p]\n        else:\n            together.pop(p, None)                       # they deleted it\n\n    def run(after: Snapshot) -> Report:\n        return check_snapshots(base, after, root, \"team\")\n\n    alone_mine, alone_theirs = alone or (run(mine), run(theirs))\n    joint = run(derive(base, together))\n    key = lambda f: (f.rule, f.path, f.line, f.message)   # noqa: E731\n    known = {key(f) for f in alone_mine.findings + alone_theirs.findings}\n    only = [f for f in joint.findings if key(f) not in known]\n    report = Report(root=root.as_posix(), against=f\"{WIP}/{name}\", changes=joint.changes,\n                    findings=only, affected=joint.affected if only else [], errors=joint.errors)\n    return Combination(name, shared, alone_theirs.changes, report, both)\n\n\ndef derive(base: Snapshot, files: dict[str, str], label: str = \"\") -> Snapshot:\n    \"\"\"A version made from ``base``: the files it did not change keep base's syntax trees, so\n    checking several people's work against one base parses each file once.\"\"\"\n    out = Snapshot(dict(files), label)\n    for path, tree in base._trees.items():\n        if files.get(path) is base.files.get(path) or _same(files.get(path), base.files.get(path)):\n            out._trees[path] = tree\n            if path in base.errors:\n                out.errors[path] = base.errors[path]\n    return out\n", "magellan_lite/defs.py": "\"\"\"The map: every function, method, class and constant in a snapshot, from its syntax tree.\n\nEach definition gets a stable name (``pkg.mod.Class.method``, no line numbers) and hashes of\nwhat it promises and what it does, so comparing two versions finds real changes: moving code,\nreformatting it, editing a docstring or switching line endings changes nothing.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nimport hashlib\nfrom dataclasses import dataclass\n\nfrom magellan_lite.source import Snapshot, module_name\n\nCALLABLE_KINDS = (\"function\", \"method\")\n\n\n@dataclass(frozen=True)\nclass Params:\n    \"\"\"What a function accepts, to check a call site against it.\"\"\"\n    positional: tuple[str, ...]          # positional parameters, in order (self included)\n    defaults: int                        # how many of the last positional ones have defaults\n    positional_only: int                 # how many lead the list before a `/`\n    varargs: bool                        # *args\n    keyword_only: tuple[str, ...]\n    keyword_required: tuple[str, ...]    # keyword-only parameters without a default\n    varkw: bool                          # **kwargs\n    binds_first: bool                    # a method (not a staticmethod): `self` is passed for you\n\n    def bound(self) -> \"Params\":\n        \"\"\"As seen through ``obj.method(...)``: the first parameter is filled already.\"\"\"\n        if not self.binds_first or not self.positional:\n            return self\n        return Params(self.positional[1:], min(self.defaults, len(self.positional) - 1),\n                      max(self.positional_only - 1, 0), self.varargs, self.keyword_only,\n                      self.keyword_required, self.varkw, False)\n\n    def problems(self, n_positional: int, keywords: tuple[str, ...]) -> list[str]:\n        \"\"\"Why a call with these arguments raises TypeError; empty when it fits.\"\"\"\n        out: list[str] = []\n        if not self.varargs and n_positional > len(self.positional):\n            out.append(f\"takes at most {len(self.positional)} positional argument(s), the call \"\n                       f\"passes {n_positional}\")\n        required = self.positional[:len(self.positional) - self.defaults]\n        missing = [p for i, p in enumerate(required)\n                   if i >= n_positional and (i < self.positional_only or p not in keywords)]\n        missing += [k for k in self.keyword_required if k not in keywords]\n        if missing:\n            out.append(f\"requires {', '.join(missing)}, which the call does not pass\")\n        accepted = set(self.positional[self.positional_only:]) | set(self.keyword_only)\n        unknown = [k for k in keywords if k not in accepted]\n        if unknown and not self.varkw:\n            out.append(f\"has no parameter named {', '.join(unknown)}\")\n        return out\n\n\n@dataclass(frozen=True)\nclass Definition:\n    name: str               # pkg.mod.Class.method: stable across moves and edits\n    kind: str               # function | method | class | constant\n    path: str\n    line: int\n    end_line: int\n    signature: str = \"\"     # callables: parameters and return type; classes: bases\n    body: str = \"\"          # hash of the body's syntax tree\n    value: str = \"\"         # constants: the value's source\n    params: Params | None = None     # callables: what a call must pass\n    lang: str = \"\"          # \"\" for Python; otherwise the language (languages.py)\n    label: str = \"\"         # how a person reads the name, when it isn't the last dotted part\n\n    @property\n    def short(self) -> str:\n        return self.name.rsplit(\".\", 1)[-1]\n\n\ndef _hash(*parts: str) -> str:\n    return hashlib.sha1(\"\\x00\".join(parts).encode(\"utf-8\")).hexdigest()[:12]\n\n\ndef _without_docstring(body: list[ast.stmt]) -> list[ast.stmt]:\n    if body and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) \\\n            and isinstance(body[0].value.value, str):\n        return body[1:]\n    return body\n\n\ndef _dump(nodes: list[ast.AST]) -> str:\n    return \"\\n\".join(ast.dump(n, include_attributes=False) for n in nodes)\n\n\ndef _signature(fn: ast.FunctionDef | ast.AsyncFunctionDef) -> str:\n    sig = f\"({ast.unparse(fn.args)})\"\n    if fn.returns is not None:\n        sig += f\" -> {ast.unparse(fn.returns)}\"\n    return (\"async \" if isinstance(fn, ast.AsyncFunctionDef) else \"\") + sig\n\n\ndef _params(fn, kind: str) -> Params:\n    a = fn.args\n    decorators = {d.id if isinstance(d, ast.Name) else getattr(d, \"attr\", \"\")\n                  for d in fn.decorator_list}\n    kw_required = tuple(arg.arg for arg, default in zip(a.kwonlyargs, a.kw_defaults)\n                        if default is None)\n    return Params(\n        positional=tuple(arg.arg for arg in a.posonlyargs + a.args),\n        defaults=len(a.defaults), positional_only=len(a.posonlyargs),\n        varargs=a.vararg is not None, keyword_only=tuple(arg.arg for arg in a.kwonlyargs),\n        keyword_required=kw_required, varkw=a.kwarg is not None,\n        binds_first=kind == \"method\" and \"staticmethod\" not in decorators)\n\n\ndef _function(fn, qual: str, kind: str, path: str) -> Definition:\n    return Definition(\n        name=qual, kind=kind, path=path, line=fn.lineno, end_line=fn.end_lineno or fn.lineno,\n        signature=_signature(fn),\n        body=_hash(_dump(fn.decorator_list), _dump(_without_docstring(fn.body))),\n        params=_params(fn, kind))\n\n\ndef _constants(stmt: ast.stmt, prefix: str, path: str) -> list[Definition]:\n    \"\"\"``NAME = value`` / ``NAME: T = value`` at module or class level.\"\"\"\n    if isinstance(stmt, ast.Assign):\n        targets, value = stmt.targets, stmt.value\n    elif isinstance(stmt, ast.AnnAssign) and stmt.value is not None:\n        targets, value = [stmt.target], stmt.value\n    else:\n        return []\n    text = ast.unparse(value)\n    return [Definition(name=f\"{prefix}.{t.id}\", kind=\"constant\", path=path, line=stmt.lineno,\n                       end_line=stmt.end_lineno or stmt.lineno, body=_hash(text), value=text)\n            for t in targets if isinstance(t, ast.Name)]\n\n\ndef _class(cls: ast.ClassDef, qual: str, path: str) -> list[Definition]:\n    members = [s for s in cls.body if not isinstance(s, (ast.FunctionDef, ast.AsyncFunctionDef))]\n    out = [Definition(\n        name=qual, kind=\"class\", path=path, line=cls.lineno, end_line=cls.end_lineno or cls.lineno,\n        signature=\", \".join(ast.unparse(b) for b in cls.bases),\n        body=_hash(_dump(cls.decorator_list), _dump(_without_docstring(members))))]\n    for stmt in cls.body:\n        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):\n            out.append(_function(stmt, f\"{qual}.{stmt.name}\", \"method\", path))\n        elif isinstance(stmt, ast.ClassDef):\n            out += _class(stmt, f\"{qual}.{stmt.name}\", path)\n        else:\n            out += _constants(stmt, qual, path)\n    return out\n\n\ndef definitions_in(tree: ast.Module, path: str) -> list[Definition]:\n    mod = module_name(path)\n    out: list[Definition] = []\n    for stmt in tree.body:\n        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):\n            out.append(_function(stmt, f\"{mod}.{stmt.name}\", \"function\", path))\n        elif isinstance(stmt, ast.ClassDef):\n            out += _class(stmt, f\"{mod}.{stmt.name}\", path)\n        else:\n            out += _constants(stmt, mod, path)\n    return out\n\n\ndef definitions(snapshot: Snapshot) -> dict[str, Definition]:\n    \"\"\"``{name: Definition}`` for the whole snapshot. A name defined twice keeps the last.\n    Python is read here; the other languages by their own frontends (languages.py).\"\"\"\n    out: dict[str, Definition] = {}\n    for path in sorted(snapshot.files):\n        tree = snapshot.tree(path) if path.endswith(\".py\") else None\n        if tree is not None:\n            for d in definitions_in(tree, path):\n                out[d.name] = d\n    if any(not p.endswith(\".py\") for p in snapshot.files):\n        from magellan_lite import languages\n        out.update(languages.definitions(snapshot))\n    return out\n", "magellan_lite/diff.py": "\"\"\"What changed between two maps, and which lines of the new version that covers.\"\"\"\n\nfrom __future__ import annotations\n\nfrom collections import defaultdict\nfrom dataclasses import dataclass\n\nfrom magellan_lite.defs import Definition\n\n#: how much each kind of change can do to the code that depends on it, worst first\nKINDS = (\"removed\", \"renamed\", \"signature\", \"value\", \"body\", \"added\")\n\n\n@dataclass\nclass Change:\n    kind: str                       # one of KINDS\n    name: str\n    path: str\n    line: int\n    before: Definition | None = None\n    after: Definition | None = None\n\n    @property\n    def detail(self) -> str:\n        if self.kind == \"signature\":\n            return f\"{self.before.signature}  ->  {self.after.signature}\"\n        if self.kind == \"value\":\n            return f\"{self.before.value}  ->  {self.after.value}\"\n        # one branch at a time: a removed change has no `after`, an added one no `before`\n        if self.kind == \"removed\":\n            return f\"{self.before.kind} deleted\"\n        if self.kind == \"added\":\n            return f\"new {self.after.kind}\"\n        if self.kind == \"renamed\":\n            return f\"renamed from {self.before.name}\"\n        return f\"{self.after.kind} body changed\"\n\n    def to_dict(self) -> dict:\n        return {\"kind\": self.kind, \"name\": self.name, \"path\": self.path, \"line\": self.line,\n                \"detail\": self.detail}\n\n\ndef diff(before: dict[str, Definition], after: dict[str, Definition]) -> list[Change]:\n    \"\"\"Every definition added, removed, renamed or edited. One change per definition: the worst.\"\"\"\n    out: list[Change] = []\n    for name in sorted(set(before) | set(after)):\n        b, a = before.get(name), after.get(name)\n        if a is None:\n            out.append(Change(\"removed\", name, b.path, b.line, before=b))\n        elif b is None:\n            out.append(Change(\"added\", name, a.path, a.line, after=a))\n        elif a.signature != b.signature:\n            out.append(Change(\"signature\", name, a.path, a.line, before=b, after=a))\n        elif a.kind == \"constant\" and a.value != b.value:\n            out.append(Change(\"value\", name, a.path, a.line, before=b, after=a))\n        elif a.body != b.body:\n            out.append(Change(\"body\", name, a.path, a.line, before=b, after=a))\n    out = _pair_overloads(_pair_renames(out))\n    out.sort(key=lambda c: (KINDS.index(c.kind), c.path, c.line))\n    return out\n\n\ndef _pair_renames(changes: list[Change]) -> list[Change]:\n    \"\"\"A function, method or class deleted under one name and added under another with the\n    same signature and body is one rename (or a move to another module), not two changes.\n\n    Pairs only when the match is unique. Constants are never paired: the same value under a\n    new name can be a new meaning -- Knight Capital's reused flag looked exactly like that.\n    \"\"\"\n    def key(d: Definition) -> tuple:\n        return d.kind, d.signature, d.body\n\n    removed: dict[tuple, list[Change]] = defaultdict(list)\n    added: dict[tuple, list[Change]] = defaultdict(list)\n    for c in changes:\n        if c.kind == \"removed\" and c.before.kind != \"constant\":\n            removed[key(c.before)].append(c)\n        elif c.kind == \"added\" and c.after.kind != \"constant\":\n            added[key(c.after)].append(c)\n    paired: set[int] = set()\n    renames: list[Change] = []\n    for k, gone in removed.items():\n        new = added.get(k, [])\n        if len(gone) == 1 and len(new) == 1:\n            old, now = gone[0], new[0]\n            renames.append(Change(\"renamed\", now.name, now.path, now.line,\n                                  before=old.before, after=now.after))\n            paired |= {id(old), id(now)}\n    return [c for c in changes if id(c) not in paired] + renames\n\n\ndef _pair_overloads(changes: list[Change]) -> list[Change]:\n    \"\"\"In Java (and C++) the parameter types are part of a method's name: adding a parameter\n    to ``area(double,double)`` deletes it and adds ``area(double,double,double)``. When one\n    method of a name goes and one comes, in the same file, that is its signature changing.\"\"\"\n    def stem(d: Definition) -> tuple:\n        return d.path, d.kind, d.name.split(\"(\", 1)[0]\n\n    removed: dict[tuple, list[Change]] = defaultdict(list)\n    added: dict[tuple, list[Change]] = defaultdict(list)\n    for c in changes:\n        if c.kind == \"removed\" and c.before.lang and \"(\" in c.before.name:\n            removed[stem(c.before)].append(c)\n        elif c.kind == \"added\" and c.after.lang and \"(\" in c.after.name:\n            added[stem(c.after)].append(c)\n    paired: set[int] = set()\n    out: list[Change] = []\n    for k, gone in removed.items():\n        new = added.get(k, [])\n        if len(gone) == 1 and len(new) == 1:\n            old, now = gone[0], new[0]\n            out.append(Change(\"signature\", now.name, now.path, now.line,\n                              before=old.before, after=now.after))\n            paired |= {id(old), id(now)}\n    return [c for c in changes if id(c) not in paired] + out\n\n\nSpans = dict[str, list[tuple[int, int]]]\n\n\ndef changed_spans(changes: list[Change]) -> Spans:\n    \"\"\"``{path: [(first line, last line)]}`` of every definition the change added or edited.\n\n    A class whose own body is unchanged but whose method changed contributes only the method:\n    findings belong to the narrowest thing that changed.\n    \"\"\"\n    out: Spans = {}\n    for c in changes:\n        if c.after is not None:\n            out.setdefault(c.after.path, []).append((c.after.line, c.after.end_line))\n    return {p: sorted(set(s)) for p, s in out.items()}\n\n\ndef in_spans(spans: Spans, path: str, line: int) -> bool:\n    return any(start <= line <= end for start, end in spans.get(path, ()))\n", "magellan_lite/engine.py": "\"\"\"One check: map both versions, diff them, run the checklist on what the change touched.\"\"\"\n\nfrom __future__ import annotations\n\nimport re\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\nfrom magellan_lite.defs import Definition, definitions\nfrom magellan_lite.diff import Change, Spans, changed_spans, diff, in_spans\nfrom magellan_lite.findings import Finding, iter_change_rules, run_file_rules\nfrom magellan_lite.graph import CallGraph, build_graph\nfrom magellan_lite.radius import blast_radius\nfrom magellan_lite.report import Report\nfrom magellan_lite.source import Snapshot, working_tree\n\n\n@dataclass\nclass ChangeContext:\n    \"\"\"Everything a ``@change_rule`` can look at.\"\"\"\n    root: Path\n    before: Snapshot\n    after: Snapshot\n    before_defs: dict[str, Definition]\n    after_defs: dict[str, Definition]\n    changes: list[Change]\n    spans: Spans\n    graph: CallGraph            # the new version's call graph (edges to deleted names kept)\n\n\ndef load_before(root: Path, against: str) -> Snapshot:\n    \"\"\"``git:REV`` (``git:`` alone means HEAD), or a directory holding the old version.\"\"\"\n    if against.startswith(\"git:\"):\n        from magellan_lite.git import snapshot_at   # only here: the website's copy has no git\n        return snapshot_at(root, against[4:] or \"HEAD\")\n    old = Path(against)\n    if old.is_dir():\n        return working_tree(old)\n    raise ValueError(f\"--against must be git:REV or a directory, not {against!r}\")\n\n\ndef check(root: str | Path = \".\", against: str = \"git:HEAD\") -> Report:\n    \"\"\"Compare a project on disk with a baseline (``git:REV`` or a directory).\"\"\"\n    root = Path(root).resolve()\n    return check_snapshots(load_before(root, against), working_tree(root), root, against)\n\n\ndef check_files(before: dict[str, str], after: dict[str, str]) -> Report:\n    \"\"\"Compare two versions given as ``{relative path: source}``: no disk, no git.\n    What the local server uses for code pasted into the website.\"\"\"\n    return check_snapshots(Snapshot(dict(before), \"before\"), Snapshot(dict(after), \"after\"),\n                           Path(\".\"), \"request\")\n\n\ndef check_snapshots(before: Snapshot, after: Snapshot, root: Path, against: str) -> Report:\n    import magellan_lite.rules  # noqa: F401  importing the package registers every rule\n\n    before_defs, after_defs = definitions(before), definitions(after)\n    changes = diff(before_defs, after_defs)\n    spans = changed_spans(changes)\n    report = Report(root=root.as_posix(), against=against, changes=changes)\n\n    for path in sorted(spans):\n        tree = after.tree(path)\n        if tree is None:\n            continue\n        found, errors = run_file_rules(tree, path)\n        report.findings += [f for f in found if in_spans(spans, path, f.line)]\n        report.errors += errors\n\n    # the blast radius: what the change reaches that it did not touch (radius.py)\n    graph = build_graph(after, after_defs, before_defs)\n    report.affected = blast_radius(changes, graph, after_defs)\n\n    ctx = ChangeContext(root, before, after, before_defs, after_defs, changes, spans, graph)\n    for r in iter_change_rules():\n        try:\n            report.findings += [f if f.fix or not r.fix else _with_fix(f, r.fix)\n                                for f in r.check(ctx)]\n        except Exception as exc:                    # noqa: BLE001 - reported, not hidden\n            report.errors.append(f\"rule {r.id} failed: {type(exc).__name__}: {exc}\")\n\n    kept = [f for f in report.findings if not suppressed(after, f)]\n    report.suppressed = len(report.findings) - len(kept)\n    report.findings = kept\n\n    report.errors += sorted(after.errors.values())\n    if any(not p.endswith(\".py\") for p in after.files):\n        from magellan_lite import languages\n        report.errors += languages.errors(after)\n    report.findings.sort(key=lambda f: (f.rank, f.path, f.line, f.rule))\n    return report\n\n\n#: ``# magellan: ignore[rule-id]``, or several ids: ``ignore[rule-a, rule-b]``\n_IGNORE = re.compile(r\"#\\s*magellan:\\s*ignore\\[([^\\]]*)\\]\")\n\n\ndef suppressed(after: Snapshot, f: Finding) -> bool:\n    \"\"\"Is ``f`` silenced by an ignore comment naming its rule, at the end of its own line or\n    on a comment line just above it? A comment silences only the rules it names.\"\"\"\n    source = after.files.get(f.path)\n    if source is None or f.line < 1 or \"magellan:\" not in source:\n        return False\n    lines = source.splitlines()\n    for n in (f.line, f.line - 1):\n        if not 1 <= n <= len(lines):\n            continue\n        line = lines[n - 1]\n        if n < f.line and not line.lstrip().startswith(\"#\"):\n            continue                        # the line above counts only when it is a comment\n        for m in _IGNORE.finditer(line):\n            if f.rule in {r.strip() for r in m.group(1).split(\",\")}:\n                return True\n    return False\n\n\ndef _with_fix(f: Finding, fix: str) -> Finding:\n    f.fix = fix\n    return f\n", "magellan_lite/findings.py": "\"\"\"Findings and the rule registry. This is the shared contract: change it together.\n\nThere are two kinds of rule.\n\n``@rule`` looks at one parsed file and yields ``(where, message)`` or\n``(where, message, detail)``, where ``where`` is an AST node or a line number. The engine\nkeeps only what lands inside code the change touched, so a rule never needs to know about\nthe change::\n\n    @rule(\"debug-leftover\", \"low\", fix=\"Remove it before committing.\")\n    def debug_leftover(tree, path):\n        for node in ast.walk(tree):\n            if isinstance(node, ast.Call) and getattr(node.func, \"id\", \"\") == \"breakpoint\":\n                yield node, \"breakpoint() left in\"\n\n``@change_rule`` sees the whole change -- both versions of every definition -- and returns\n``Finding`` objects itself. Use it for rules about what changed *between* versions, such as\na constant's value handed to a new meaning.\n\n``blocking=True`` lets a rule's high or critical findings make the verdict ``block``. Keep it\nfor rules that mean \"this change will break something\", not \"have a look\".\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nfrom dataclasses import asdict, dataclass\nfrom typing import Callable, Iterable\n\nSEVERITIES = (\"critical\", \"high\", \"medium\", \"low\")\n\n\n@dataclass\nclass Finding:\n    rule: str\n    severity: str\n    message: str            # one line: what is wrong, where\n    path: str               # relative to the project root, forward slashes on every OS\n    line: int\n    detail: str = \"\"        # why it matters\n    fix: str = \"\"           # what to do about it\n\n    @property\n    def rank(self) -> int:\n        \"\"\"0 for critical, 3 for low: sort by it to put the worst first.\"\"\"\n        return SEVERITIES.index(self.severity)\n\n    def to_dict(self) -> dict:\n        return asdict(self)\n\n\n@dataclass(frozen=True)\nclass Rule:\n    id: str\n    severity: str\n    fix: str\n    blocking: bool\n    per_file: bool          # True: @rule (one file at a time); False: @change_rule\n    check: Callable\n\n\nRULES: dict[str, Rule] = {}\n\n\ndef _register(rule_id: str, severity: str, fix: str, blocking: bool, per_file: bool):\n    if severity not in SEVERITIES:\n        raise ValueError(f\"{rule_id}: severity must be one of {SEVERITIES}, not {severity!r}\")\n\n    def register(check: Callable) -> Callable:\n        if rule_id in RULES and RULES[rule_id].check is not check:\n            raise ValueError(f\"two rules are called {rule_id!r}\")\n        RULES[rule_id] = Rule(rule_id, severity, fix, blocking, per_file, check)\n        return check\n    return register\n\n\ndef rule(rule_id: str, severity: str, fix: str = \"\", blocking: bool = False):\n    \"\"\"Register a check over one parsed file. See the module docstring.\"\"\"\n    return _register(rule_id, severity, fix, blocking, per_file=True)\n\n\ndef change_rule(rule_id: str, severity: str, fix: str = \"\", blocking: bool = False):\n    \"\"\"Register a check over the whole change. See the module docstring.\"\"\"\n    return _register(rule_id, severity, fix, blocking, per_file=False)\n\n\ndef run_file_rules(tree: ast.Module, path: str) -> tuple[list[Finding], list[str]]:\n    \"\"\"Every per-file rule's findings for one file, and the errors of rules that crashed.\n\n    A broken rule must not take the whole check down: its error is reported instead.\n    \"\"\"\n    out: list[Finding] = []\n    errors: list[str] = []\n    for r in RULES.values():\n        if not r.per_file:\n            continue\n        try:\n            for hit in r.check(tree, path):\n                where, message, *rest = hit\n                line = where if isinstance(where, int) else getattr(where, \"lineno\", 0)\n                out.append(Finding(r.id, r.severity, message, path, line,\n                                   detail=rest[0] if rest else \"\", fix=r.fix))\n        except Exception as exc:                    # noqa: BLE001 - reported, not hidden\n            errors.append(f\"rule {r.id} failed on {path}: {type(exc).__name__}: {exc}\")\n    return out, errors\n\n\ndef blocking_rules() -> set[str]:\n    return {r.id for r in RULES.values() if r.blocking}\n\n\ndef iter_change_rules() -> Iterable[Rule]:\n    return [r for r in RULES.values() if not r.per_file]\n", "magellan_lite/graph.py": "\"\"\"The call graph: which definition calls, constructs or reads which.\n\nBuilt from syntax trees alone; nothing is imported or run. A call is resolved by name:\n\n- ``f()``: a function in the same module, or one imported (``from a.b import f``);\n- ``mod.f()``: after ``import mod`` (or ``import a.b as mod``);\n- ``self.m()`` / ``cls.m()``: a method of the class the call is in;\n- ``Ledger.post(...)``, ``Ledger(...)``: a class of this module and its methods.\n\nA method call on anything else (``order.update()``) cannot be resolved without types. When\nexactly one method in the project has that name, it is linked as a *guess*, which the blast\nradius weighs less; otherwise it is left out. Edges to definitions the change deleted are kept\n(``dangling``), so code still calling them can be found.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nfrom collections import defaultdict\nfrom dataclasses import dataclass\n\nfrom magellan_lite.defs import Definition\nfrom magellan_lite.source import Snapshot, module_name\n\n#: method names too common to guess at: `d.get()` is almost never the project's `get`\n_NO_GUESS = frozenset({\n    \"get\", \"set\", \"add\", \"append\", \"extend\", \"insert\", \"pop\", \"remove\", \"clear\", \"copy\",\n    \"update\", \"items\", \"keys\", \"values\", \"join\", \"split\", \"strip\", \"format\", \"replace\",\n    \"read\", \"write\", \"close\", \"open\", \"run\", \"send\", \"start\", \"stop\", \"sort\",\n    \"count\", \"index\", \"find\", \"encode\", \"decode\", \"lower\", \"upper\", \"startswith\",\n    \"endswith\", \"match\", \"search\", \"sub\", \"load\", \"dump\", \"loads\", \"dumps\",\n})\n\n\n@dataclass(frozen=True)\nclass Edge:\n    src: str                       # the definition that calls or reads\n    dst: str                       # what it calls or reads\n    kind: str                      # \"calls\" | \"reads\"\n    path: str\n    line: int\n    guess: bool = False            # matched by method name alone\n    bound: bool = False            # obj.method(...): `self` is passed for you\n    positional: int = 0            # positional arguments at the call site\n    keywords: tuple[str, ...] = ()\n    unpacked: bool = False         # *args or **kwargs at the call site: the count is unknown\n\n\n@dataclass(frozen=True)\nclass ImportSite:\n    path: str\n    line: int\n    target: str                    # the dotted name an import statement binds\n\n\nclass CallGraph:\n    def __init__(self, edges: list[Edge], imports: list[ImportSite]) -> None:\n        self.edges = edges\n        self.imports = imports\n        self._in: dict[str, list[Edge]] = defaultdict(list)\n        self._out: dict[str, list[Edge]] = defaultdict(list)\n        for e in edges:\n            self._in[e.dst].append(e)\n            self._out[e.src].append(e)\n\n    def callers(self, name: str) -> list[Edge]:\n        \"\"\"Edges into ``name``: who calls or reads it.\"\"\"\n        return self._in.get(name, [])\n\n    def uses(self, name: str) -> list[Edge]:\n        \"\"\"Edges out of ``name``: what it calls or reads.\"\"\"\n        return self._out.get(name, [])\n\n\ndef build_graph(snapshot: Snapshot, defs: dict[str, Definition],\n                old_defs: dict[str, Definition] | None = None) -> CallGraph:\n    \"\"\"The graph of ``snapshot``. ``old_defs`` (the previous version's map) keeps edges to\n    definitions that no longer exist, so the code still using them can be reported.\"\"\"\n    # what each name is, in either version: a read of a deleted constant still counts\n    kinds = {n: d.kind for n, d in (old_defs or {}).items()}\n    kinds.update({n: d.kind for n, d in defs.items()})\n    known = set(kinds)\n    methods: dict[str, list[str]] = defaultdict(list)\n    for d in defs.values():\n        if d.kind == \"method\":\n            methods[d.short].append(d.name)\n\n    edges: list[Edge] = []\n    import_sites: list[ImportSite] = []\n    for path in sorted(snapshot.files):\n        tree = snapshot.tree(path)\n        if tree is None:\n            continue\n        mod = module_name(path)\n        package = mod if path.endswith(\"__init__.py\") else mod.rpartition(\".\")[0]\n        table, sites = _imports(tree, package, path)\n        import_sites += sites\n        for owner, fn, cls in _callables(tree, mod):\n            edges += _Resolver(owner, fn, cls, mod, path, table, kinds, methods).edges()\n    if any(not p.endswith(\".py\") for p in snapshot.files):\n        from magellan_lite import languages           # C, Java, COBOL, ...: their own frontends\n        edges += languages.edges(snapshot)\n    return CallGraph(edges, import_sites)\n\n\ndef _imports(tree: ast.Module, package: str, path: str) -> tuple[dict[str, str], list[ImportSite]]:\n    \"\"\"``{bound name: dotted target}`` for every import in the module, and where each is.\"\"\"\n    table: dict[str, str] = {}\n    sites: list[ImportSite] = []\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Import):\n            for a in node.names:\n                if a.asname:\n                    table[a.asname] = a.name\n                else:\n                    top = a.name.split(\".\")[0]\n                    table[top] = top\n        elif isinstance(node, ast.ImportFrom):\n            base = node.module or \"\"\n            if node.level:                              # relative: from . / .. / .mod import\n                parts = package.split(\".\") if package else []\n                if node.level > 1:\n                    parts = parts[:len(parts) - (node.level - 1)]\n                base = \".\".join(parts + ([node.module] if node.module else []))\n            for a in node.names:\n                if a.name == \"*\":\n                    continue\n                target = f\"{base}.{a.name}\" if base else a.name\n                table[a.asname or a.name] = target\n                sites.append(ImportSite(path, node.lineno, target))\n    return table, sites\n\n\ndef _callables(tree: ast.Module, mod: str):\n    \"\"\"``(definition name, function node, enclosing class name or None)``, named as the map\n    names them (defs.py).\"\"\"\n    def visit(body, prefix, cls):\n        for stmt in body:\n            if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):\n                yield f\"{prefix}.{stmt.name}\", stmt, cls\n            elif isinstance(stmt, ast.ClassDef):\n                qual = f\"{prefix}.{stmt.name}\"\n                yield from visit(stmt.body, qual, qual)\n    yield from visit(tree.body, mod, None)\n\n\nclass _Resolver:\n    \"\"\"The edges out of one function.\"\"\"\n\n    def __init__(self, owner, fn, cls, mod, path, imports, kinds, methods) -> None:\n        self.owner, self.fn, self.cls, self.mod, self.path = owner, fn, cls, mod, path\n        self.imports, self.kinds, self.methods = imports, kinds, methods\n        self.known = kinds.keys()\n        self.locals = self._local_names(fn)\n\n    @staticmethod\n    def _local_names(fn) -> set[str]:\n        \"\"\"Parameters and names assigned in the function: a call to one of them is a call to\n        whatever was passed in, not to a module-level definition of the same name.\"\"\"\n        a = fn.args\n        names = {arg.arg for arg in a.posonlyargs + a.args + a.kwonlyargs}\n        names |= {x.arg for x in (a.vararg, a.kwarg) if x is not None}\n        for node in ast.walk(fn):\n            if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):\n                names.add(node.id)\n            elif isinstance(node, ast.ExceptHandler) and node.name:\n                names.add(node.name)\n        return names\n\n    def _name(self, ident: str) -> str | None:\n        \"\"\"The definition a bare name refers to, if it is one of ours.\"\"\"\n        if ident in self.locals:\n            return None\n        if ident in self.imports and self.imports[ident] in self.known:\n            return self.imports[ident]\n        here = f\"{self.mod}.{ident}\"\n        return here if here in self.known else None\n\n    def _attribute(self, node: ast.Attribute) -> tuple[str | None, bool, bool]:\n        \"\"\"``(target, bound, guess)`` for ``X.attr``.\"\"\"\n        attr = node.attr\n        if isinstance(node.value, ast.Name):\n            base = node.value.id\n            if base in (\"self\", \"cls\") and self.cls:\n                target = f\"{self.cls}.{attr}\"\n                if target in self.known:\n                    return target, True, False\n            elif base not in self.locals:\n                if base in self.imports:\n                    target = f\"{self.imports[base]}.{attr}\"\n                    if target in self.known:\n                        return target, False, False\n                target = f\"{self.mod}.{base}.{attr}\"     # a class of this module\n                if target in self.known:\n                    return target, False, False\n        candidates = self.methods.get(attr, [])\n        if len(candidates) == 1 and attr not in _NO_GUESS:\n            return candidates[0], True, True\n        return None, False, False\n\n    def edges(self) -> list[Edge]:\n        out: list[Edge] = []\n        for node in ast.walk(self.fn):\n            if isinstance(node, ast.Call):\n                if isinstance(node.func, ast.Name):\n                    target, bound, guess = self._name(node.func.id), False, False\n                elif isinstance(node.func, ast.Attribute):\n                    target, bound, guess = self._attribute(node.func)\n                else:\n                    continue\n                if target and target != self.owner:\n                    out.append(Edge(\n                        self.owner, target, \"calls\", self.path, node.lineno, guess, bound,\n                        positional=sum(not isinstance(a, ast.Starred) for a in node.args),\n                        keywords=tuple(k.arg for k in node.keywords if k.arg),\n                        unpacked=any(isinstance(a, ast.Starred) for a in node.args)\n                        or any(k.arg is None for k in node.keywords)))\n            elif isinstance(node, (ast.Name, ast.Attribute)) and isinstance(node.ctx, ast.Load):\n                if isinstance(node, ast.Name):\n                    target = self._name(node.id)\n                else:\n                    target, _bound, guess = self._attribute(node)\n                    target = None if guess else target       # never guess at a read\n                if target and target != self.owner and self.kinds.get(target) == \"constant\":\n                    out.append(Edge(self.owner, target, \"reads\", self.path, node.lineno))\n        return out\n", "magellan_lite/hook.py": "\"\"\"``magellan-lite hook install``: run the check before every commit.\n\nIt writes git's pre-commit hook, which runs ``magellan-lite check``: a blocking verdict (or\nthe ``fail-on`` in pyproject.toml's ``[tool.magellan-lite]``) stops the commit, and\n``git commit --no-verify`` skips the check once. The hook runs the check with the Python that\ninstalled it, so it works from a virtual environment that is not active (an editor's commit\nbutton); when that Python is gone it falls back to the ``magellan-lite`` on PATH.\n\nA pre-commit hook that is someone else's is left alone unless ``--force`` is given; it is\nthen kept as ``pre-commit.bak``.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport os\nimport shlex\nimport sys\nfrom pathlib import Path\n\nfrom magellan_lite.git import GitError, _run\nfrom magellan_lite.source import decode\n\n#: the second line of every hook this module writes: how it knows its own\nMARKER = \"# magellan-lite pre-commit hook\"\n\n\ndef script(python: str, project: str = \".\") -> str:\n    \"\"\"The hook: sh, which git runs on Windows too. ``project`` is the checked folder,\n    relative to the repository's top (where git runs hooks).\"\"\"\n    target = \"\" if project == \".\" else \" \" + shlex.quote(project)\n    return (f\"#!/bin/sh\\n\"\n            f\"{MARKER}, written by `magellan-lite hook install`.\\n\"\n            f\"# A blocking verdict stops the commit; `git commit --no-verify` skips the check once.\\n\"\n            f\"python={shlex.quote(python)}\\n\"\n            f'if [ -x \"$python\" ]; then\\n'\n            f'    exec \"$python\" -m magellan_lite check{target}\\n'\n            f\"fi\\n\"\n            f\"if ! command -v magellan-lite >/dev/null 2>&1; then\\n\"\n            f'    echo \"magellan-lite: not found. Install it again, then run'\n            f' magellan-lite hook install.\" >&2\\n'\n            f\"    exit 1\\n\"\n            f\"fi\\n\"\n            f\"exec magellan-lite check{target}\\n\")\n\n\ndef hook_path(root: Path) -> Path:\n    \"\"\"Where git looks for the pre-commit hook (``core.hooksPath`` and worktrees included).\"\"\"\n    out = decode(_run(root, \"rev-parse\", \"--git-path\", \"hooks/pre-commit\")).strip()\n    return (root / out).resolve()\n\n\ndef install(path: str | Path = \".\", force: bool = False) -> int:\n    \"\"\"Write the hook and say so; 1 when an existing hook is not ours and ``force`` is off,\n    2 when there is no repository.\"\"\"\n    root = Path(path).resolve()\n    try:\n        hook = hook_path(root)\n        project = decode(_run(root, \"rev-parse\", \"--show-prefix\")).strip().rstrip(\"/\") or \".\"\n    except (GitError, OSError) as exc:\n        print(f\"magellan-lite: cannot install the hook: {exc}\", file=sys.stderr)\n        return 2\n    shown = _shown(hook, root)\n\n    kept = \"\"\n    if hook.exists():\n        mine = MARKER in hook.read_text(encoding=\"utf-8\", errors=\"replace\")\n        if not mine and not force:\n            print(f\"magellan-lite: {shown} already exists and is not Magellan Lite's, so it was \"\n                  f\"left as it is.\\n\"\n                  f\"  To replace it (the old one is kept as pre-commit.bak), run \"\n                  f\"`magellan-lite hook install --force`.\\n\"\n                  f\"  Or add `magellan-lite check` to it yourself.\", file=sys.stderr)\n            return 1\n        if not mine:\n            hook.replace(hook.with_name(\"pre-commit.bak\"))\n            kept = \" The hook that was there is kept as pre-commit.bak.\"\n\n    hook.parent.mkdir(parents=True, exist_ok=True)\n    python = Path(sys.executable).as_posix() if sys.executable else \"\"\n    hook.write_text(script(python, project), encoding=\"utf-8\", newline=\"\\n\")  # sh wants LF\n    os.chmod(hook, hook.stat().st_mode | 0o111)\n    print(f\"magellan-lite: installed the pre-commit hook ({shown}). Every commit is checked \"\n          f\"now, and a blocking verdict stops it; `git commit --no-verify` skips the check \"\n          f\"once.{kept}\")\n    return 0\n\n\ndef _shown(hook: Path, root: Path) -> str:\n    try:\n        return hook.relative_to(root).as_posix()\n    except ValueError:\n        return hook.as_posix()\n", "magellan_lite/languages.py": "\"\"\"The other languages: C, C++, Java, Fortran, COBOL, TypeScript/JavaScript, and Python 2.\n\nLite reads Python 3 itself (defs.py, graph.py). For everything else it uses the full\nMagellan's frontends, vendored in ``magellan_lite/polyglot``. Each frontend reads files from a\ndirectory, so a snapshot's files in those languages are written to a temporary one, mapped\nthere, and turned into what the rest of Lite already works with:\n\n- ``definitions(snapshot)``: a ``Definition`` per function, method, class and global, named\n  ``<lang>@<qualified name>`` (``c@parse.load``, ``java@geo.Shape.area(double,double)``) so it\n  can never collide with a Python name, and one per COBOL copybook (a class: its fields are\n  its members);\n- ``edges(snapshot)``: who calls and reads whom, inside a language and across languages (a\n  Java ``native`` method to its C function, a COBOL ``CALL`` to the program it names), and\n  who copies each copybook;\n- ``findings(ctx)``: what each language's own checks find in a change -- call sites a new\n  signature breaks, deleted code still referenced, and the language's hazards (a COBOL\n  copybook whose layout moved, a C ``goto fail``, a Fortran ``COMMON`` block that no longer\n  lines up). ``rules/languages.py`` puts them on the checklist.\n\nPython 2 files are read by ``source.Snapshot.tree`` through the same package (``py2.parse``),\nso code waiting for its 2-to-3 upgrade is on the map too.\n\nNothing here runs the code it reads. A frontend that fails on a file adds an error to the\nreport; the check goes on without it.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport shutil\nimport tempfile\nimport weakref\nfrom dataclasses import dataclass, field\nfrom pathlib import Path\n\nfrom magellan_lite.defs import Definition\nfrom magellan_lite.findings import Finding\nfrom magellan_lite.graph import Edge\nfrom magellan_lite.source import Snapshot\n\n#: file suffix -> language, as the frontends declare them (tests/test_languages.py checks).\n#: A ``.h`` header counts as C here; the C++ and Fortran frontends read it too when the\n#: project has their sources.\nLANGUAGE_OF: dict[str, str] = {\n    **dict.fromkeys((\".java\",), \"java\"),\n    **dict.fromkeys((\".f\", \".for\", \".f77\", \".ftn\", \".fpp\", \".f90\", \".f95\", \".f03\", \".f08\",\n                     \".f18\", \".f23\", \".F\", \".FOR\", \".F77\", \".FTN\", \".FPP\", \".F90\", \".F95\",\n                     \".F03\", \".F08\", \".F18\", \".F23\", \".inc\", \".INC\", \".fi\", \".fh\"), \"fortran\"),\n    **dict.fromkeys((\".cpp\", \".cc\", \".cxx\", \".c++\", \".hpp\", \".hh\", \".hxx\", \".h++\", \".ipp\",\n                     \".tpp\"), \"cpp\"),\n    **dict.fromkeys((\".c\", \".h\"), \"c\"),\n    **dict.fromkeys((\".cbl\", \".cob\", \".cpy\", \".cobol\", \".dcl\", \".CBL\", \".COB\", \".CPY\",\n                     \".COBOL\", \".DCL\", \".Cbl\", \".Cpy\"), \"cobol\"),\n    **dict.fromkeys((\".ts\", \".tsx\", \".mts\", \".cts\", \".js\", \".jsx\", \".mjs\", \".cjs\"),\n                    \"typescript\"),\n}\nSUFFIXES = tuple(LANGUAGE_OF)\n#: the language names a person reads\nNAMES = {\"python\": \"Python\", \"c\": \"C\", \"cpp\": \"C++\", \"java\": \"Java\", \"fortran\": \"Fortran\",\n         \"cobol\": \"COBOL\", \"typescript\": \"TypeScript/JavaScript\"}\n\n_KINDS = {\"function\": \"function\", \"method\": \"method\", \"class\": \"class\",\n          \"global_var\": \"constant\", \"class_attr\": \"constant\"}\n_CALLS = {\"calls\": \"calls\", \"instantiates\": \"calls\", \"reads\": \"reads\", \"writes\": \"reads\",\n          \"mutates\": \"reads\"}\n\n\ndef language(path: str) -> str:\n    \"\"\"``python`` for a ``.py`` file, else the language its suffix says (\"\" if none).\"\"\"\n    if path.endswith(\".py\"):\n        return \"python\"\n    dot = path.rfind(\".\")\n    return LANGUAGE_OF.get(path[dot:], \"\") if dot >= 0 else \"\"\n\n\ndef is_source(path: str) -> bool:\n    \"\"\"A file some frontend maps (Python included).\"\"\"\n    return bool(language(path))\n\n\n@dataclass\nclass Mapped:\n    \"\"\"One snapshot's files in the other languages, mapped.\"\"\"\n    graph: object                     # polyglot.core.model.Graph\n    root: str                         # where its files were written (removed with the snapshot)\n    defs: dict[str, Definition] = field(default_factory=dict)\n    edges: list[Edge] = field(default_factory=list)\n    ids: dict[str, str] = field(default_factory=dict)       # polyglot node id -> name\n    errors: list[str] = field(default_factory=list)\n    languages: set[str] = field(default_factory=set)\n\n\nclass _State:\n    \"\"\"What a frontend's ``merge(state, root)`` uses: the graph and labelling signals.\"\"\"\n\n    def __init__(self, graph) -> None:\n        self.graph = graph\n        self.signals: dict = {}\n\n    def sig(self, node_id: str):\n        from magellan_lite.polyglot.core.taxonomy import Signals\n        return self.signals.setdefault(node_id, Signals())\n\n\ndef mapped(snapshot: Snapshot) -> Mapped | None:\n    \"\"\"The snapshot's non-Python files, mapped once and kept on the snapshot.\"\"\"\n    if hasattr(snapshot, \"_polyglot\"):\n        return snapshot._polyglot\n    files = {p: t for p, t in snapshot.files.items() if language(p) not in (\"\", \"python\")}\n    snapshot._polyglot = _map(files) if files else None\n    if snapshot._polyglot and snapshot._polyglot.root:\n        # the files stay while the snapshot lives: the diff reads them again\n        weakref.finalize(snapshot, shutil.rmtree, snapshot._polyglot.root, True)\n    return snapshot._polyglot\n\n\ndef _map(files: dict[str, str]) -> Mapped:\n    try:\n        from magellan_lite.polyglot.analyze.frontends import all_frontends\n        from magellan_lite.polyglot.analyze.interop import link\n        from magellan_lite.polyglot.core.model import Graph\n    except ImportError:                       # the website's engine has Python only, so far\n        langs = sorted({NAMES[language(p)] for p in files})\n        return Mapped(None, \"\", errors=[f\"{', '.join(langs)} files skipped: this copy of \"\n                                        \"Magellan Lite reads Python only\"])\n\n    root = Path(tempfile.mkdtemp(prefix=\"magellan-lite-\"))\n    for rel, text in files.items():\n        p = root / rel\n        p.parent.mkdir(parents=True, exist_ok=True)\n        p.write_text(text, encoding=\"utf-8\", newline=\"\")\n    graph = Graph(str(root))\n    out = Mapped(graph, str(root))\n    state = _State(graph)\n    for lang, mod in all_frontends():\n        if not any(p.endswith(tuple(mod.SOURCE_SUFFIXES)) for p in files):\n            continue\n        if lang == \"cpp\" and not any(language(p) == \"cpp\" for p in files):\n            continue                          # headers alone: C reads them\n        try:\n            if not mod.available():\n                out.errors.append(f\"{NAMES[lang]} files skipped: \"\n                                  + (\"libclang is not installed (pip install libclang)\"\n                                     if lang == \"cpp\" else \"Node.js with TypeScript is not installed\"\n                                     if lang == \"typescript\" else \"its reader is unavailable\"))\n                continue\n            mod.merge(state, str(root))\n            out.languages.add(lang)\n        except Exception as exc:               # noqa: BLE001 - one language never stops a check\n            out.errors.append(f\"{NAMES.get(lang, lang)}: could not map: {exc}\")\n    try:\n        link(graph)\n    except Exception as exc:                   # noqa: BLE001\n        out.errors.append(f\"cross-language links skipped: {exc}\")\n    out.errors += [d for d in graph.diagnostics if \"error\" in d.lower()]\n\n    for node in graph.nodes.values():\n        kind = _KINDS.get(node.kind.value)\n        if node.kind.value == \"module\" and \"copybook\" in node.tags:\n            kind = \"class\"                    # so \"who copies ACCTREC?\" has an answer\n        if kind is None or node.path not in files:\n            continue\n        name = node.qualname\n        lang = node.meta.get(\"lang\") or language(node.path)\n        out.ids[node.id] = name\n        out.defs[name] = Definition(\n            name=name, kind=kind, path=node.path, line=node.lineno or 1,\n            end_line=max(node.end_lineno or node.lineno or 1, node.lineno or 1),\n            signature=(node.signature or \"\") + (f\" #{node.sig_hash}\" if node.sig_hash else \"\"),\n            body=node.body_hash or node.sig_hash or \"\",\n            value=node.body_hash if kind == \"constant\" else \"\",\n            lang=lang, label=node.name or name.rsplit(\".\", 1)[-1])\n    seen = set()\n    for e in graph.edges:\n        kind = _CALLS.get(e.kind.value)\n        src, dst = out.ids.get(e.src), out.ids.get(e.dst)\n        if e.kind.value == \"imports\" and dst and out.defs[dst].kind == \"class\" and \\\n                \"copybook\" in graph.nodes[e.dst].tags:\n            # COPY X: the program (whose module and entry share a name) or copybook reads X\n            kind, src = \"reads\", src or (graph.nodes[e.src].qualname if e.src in graph.nodes\n                                         and graph.nodes[e.src].qualname in out.defs else None)\n        if not kind or not src or not dst or src == dst or (src, dst, kind, e.lineno) in seen:\n            continue\n        seen.add((src, dst, kind, e.lineno))\n        out.edges.append(Edge(src, dst, kind, e.path or out.defs[src].path, e.lineno,\n                              guess=e.confidence < 1.0, positional=int(e.meta.get(\"args\", 0))))\n    # a Fortran routine passed as an argument is called by the routine it is passed to: no\n    # call there names it, so without this APPLY \"calls nothing\" and is missing from INTRST's\n    # callers (a guess: what runs depends on what each caller passes)\n    passed = {e.dst for e in graph.edges if (e.meta or {}).get(\"procedure_argument\")}\n    for t in sorted(passed & out.ids.keys()):\n        for _, _, callee, _, no, inner in _procedure_calls(graph, t, lambda p: files.get(p, \"\")):\n            src = out.ids.get(callee.id)\n            if src and src != out.ids[t] and (src, out.ids[t], \"calls\", no) not in seen:\n                seen.add((src, out.ids[t], \"calls\", no))\n                out.edges.append(Edge(src, out.ids[t], \"calls\", callee.path, no, guess=True,\n                                      positional=len(inner)))\n    return out\n\n\ndef definitions(snapshot: Snapshot) -> dict[str, Definition]:\n    m = mapped(snapshot)\n    return dict(m.defs) if m else {}\n\n\ndef edges(snapshot: Snapshot) -> list[Edge]:\n    m = mapped(snapshot)\n    return list(m.edges) if m else []\n\n\ndef errors(snapshot: Snapshot) -> list[str]:\n    m = mapped(snapshot)\n    return list(m.errors) if m else []\n\n\n# -- findings --------------------------------------------------------------------------------\n#: every rule the other languages report: severity when the language gives none, blocking,\n#: and what to do. The full Magellan's own words for each are in its findings.\nRULES: dict[str, tuple[str, bool, str]] = {\n    \"struct-layout-change\": (\"high\", True, \"Rebuild everything that includes the header, and \"\n                             \"check code that reads the struct as raw bytes.\"),\n    \"enum-values-shifted\": (\"high\", True, \"Add new members at the end, or give each one an \"\n                            \"explicit value, so stored and exchanged numbers keep their meaning.\"),\n    \"unreachable-statement\": (\"high\", True, \"Put the guarded statements in braces: what is \"\n                              \"indented under the if is not inside it.\"),\n    \"non-exhaustive-match\": (\"medium\", False, \"Handle the new member, or add a default that \"\n                             \"fails loudly.\"),\n    \"unhandled-new-member\": (\"medium\", False, \"Handle the new member everywhere the type is \"\n                             \"switched on.\"),\n    \"overload-rebinds-call\": (\"high\", True, \"Make the call pick the overload it means (a cast, \"\n                              \"or a distinct name).\"),\n    \"common-layout-mismatch\": (\"critical\", True, \"Declare the COMMON block the same way in \"\n                               \"every unit: one INCLUDE file or a module.\"),\n    \"implicit-interface-arg-mismatch\": (\"critical\", True, \"Give the routine an explicit \"\n                                        \"interface (a module), then fix the calls.\"),\n    \"intent-out-read-before-write\": (\"high\", True, \"Set the INTENT(OUT) argument before \"\n                                     \"reading it, or make it INTENT(INOUT).\"),\n    \"reads-unset-local\": (\"medium\", False, \"Give the variable a value on every path before \"\n                          \"it is read.\"),\n    \"perform-thru-range-changed\": (\"high\", True, \"Check every PERFORM ... THRU that spans the \"\n                                   \"paragraphs you moved or added.\"),\n    \"copybook-layout-changed\": (\"critical\", True, \"Recompile every program that copies the \"\n                                \"copybook, and convert data written with the old layout.\"),\n    \"call-using-mismatch\": (\"critical\", True, \"Make every CALL ... USING pass what the \"\n                            \"called program's LINKAGE SECTION now expects.\"),\n    \"move-truncates\": (\"high\", True, \"Widen the receiving field, or check the value fits \"\n                       \"before the MOVE.\"),\n    \"fall-through-changed\": (\"medium\", False, \"Check the paragraphs control now falls \"\n                             \"into.\"),\n    \"legacy-construct-introduced\": (\"low\", False, \"Prefer the structured form (EVALUATE, \"\n                                    \"PERFORM, inline code) to GO TO and ALTER.\"),\n}\n_SEVERITIES = (\"critical\", \"high\", \"medium\", \"low\")\n\n\ndef findings(ctx) -> list[Finding]:\n    \"\"\"Everything the other languages find in this change, worked out once per check.\"\"\"\n    if hasattr(ctx, \"_polyglot_findings\"):\n        return ctx._polyglot_findings\n    b, a = mapped(ctx.before), mapped(ctx.after)\n    b, a = (b if b and b.graph is not None else None), (a if a and a.graph is not None else None)\n    ctx._polyglot_findings = _findings(b, a) if (b or a) else []\n    return ctx._polyglot_findings\n\n\n# -- Fortran: a routine passed as an argument ------------------------------------------------\n_FIXED_FORM = (\".f\", \".for\", \".f77\", \".ftn\", \".fpp\", \".inc\", \".fi\", \".fh\")\n\n\ndef _fortran_statements(text: str, fixed: bool) -> list[tuple[int, str]]:\n    \"\"\"``(first line, statement)`` with comments dropped and continuation lines joined.\"\"\"\n    out: list[tuple[int, str]] = []\n    pending = False\n    for no, line in enumerate(text.splitlines(), 1):\n        if fixed:\n            if not line.strip() or line[:1] in \"cC*!dD\":\n                continue\n            body = line[6:72]\n            if len(line) > 5 and line[5] not in \" 0\" and out:\n                out[-1] = (out[-1][0], out[-1][1] + \" \" + body)\n                continue\n            out.append((no, body))\n        else:\n            body = line.split(\"!\", 1)[0].rstrip()\n            if not body.strip():\n                continue\n            more = body.endswith(\"&\")\n            body = body.rstrip(\"&\").lstrip().lstrip(\"&\")\n            if pending and out:\n                out[-1] = (out[-1][0], out[-1][1] + \" \" + body)\n            else:\n                out.append((no, body))\n            pending = more\n    return out\n\n\ndef _call_args(stmt: str, name: str) -> list[str] | None:\n    \"\"\"The actual arguments of ``CALL name(...)`` in ``stmt`` (any case), or None.\"\"\"\n    import re\n    m = re.search(r\"\\bCALL\\s+\" + re.escape(name) + r\"\\s*\\((.*)\\)\\s*$\", stmt, re.I)\n    if not m:\n        return None\n    args, depth, cur = [], 0, \"\"\n    for ch in m.group(1):\n        if ch == \",\" and depth == 0:\n            args.append(cur.strip())\n            cur = \"\"\n            continue\n        depth += (ch == \"(\") - (ch == \")\")\n        cur += ch\n    if cur.strip():\n        args.append(cur.strip())\n    return args\n\n\ndef _procedure_calls(g, target_id: str, source):\n    \"\"\"Every call made to ``target`` through a procedure argument.\n\n    ``CALL APPLY(INTRST, P, R, D, X)`` hands INTRST to APPLY, which runs it as ``CALL FN(P,\n    R, D, X)``. No call names INTRST there, so the call graph and a Fortran 77 compiler both\n    pass it by. This finds the parameter it lands in and every call made through it, as\n    ``(passing edge, call edge, callee, dummy, line, arguments)``; ``source(path)`` is a\n    file's text.\"\"\"\n    from magellan_lite.polyglot.core.model import EdgeKind\n    name = (g.nodes[target_id].name or \"\").lower()\n    for e in g.in_edges(target_id):\n        if not (e.meta or {}).get(\"procedure_argument\"):\n            continue\n        for c in g.out_edges(e.src):\n            if c.kind is not EdgeKind.CALLS or c.lineno != e.lineno or c.dst not in g.nodes:\n                continue\n            callee = g.nodes[c.dst]\n            params = ((callee.meta or {}).get(\"arity\") or {}).get(\"positional\") or []\n            fixed = c.path.lower().endswith(_FIXED_FORM)\n            stmt = next((st for no, st in _fortran_statements(source(c.path), fixed)\n                         if no <= c.lineno and _call_args(st, callee.name) is not None\n                         and no >= c.lineno - 20), None)\n            args = _call_args(stmt, callee.name) if stmt else None\n            if not args:\n                continue\n            slots = [i for i, a in enumerate(args) if a.strip().lower() == name]\n            for k in slots:\n                if k >= len(params):\n                    continue\n                cfixed = callee.path.lower().endswith(_FIXED_FORM)\n                for no, st in _fortran_statements(source(callee.path), cfixed):\n                    inner = _call_args(st, params[k])\n                    if inner is not None and callee.lineno <= no <= (callee.end_lineno or no):\n                        yield e, c, callee, params[k], no, inner\n\n\ndef _through_procedure_arguments(g, target_id: str, hard: list, root: str, label, affects,\n                                 EdgeKind) -> list[Finding]:\n    \"\"\"Calls made to ``target`` through a procedure argument, judged against its new signature\n    (a wrapper with the old argument list, passed instead, is the usual fix).\"\"\"\n    target = g.nodes[target_id]\n    out: list[Finding] = []\n    seen: set[tuple[str, int]] = set()\n\n    def source(path: str) -> str:\n        try:\n            return (Path(root) / path).read_text(encoding=\"utf-8\", errors=\"replace\")\n        except OSError:\n            return \"\"\n\n    for e, c, callee, dummy, no, inner in _procedure_calls(g, target_id, source):\n        if (callee.path, no) in seen:\n            continue\n        site = {\"positional\": len(inner), \"keywords\": set(), \"star\": False,\n                \"dstar\": False, \"known\": True, \"handled\": []}\n        hits = [h for h in hard if affects(h, site, 0)]\n        if hits:\n            seen.add((callee.path, no))\n            out.append(Finding(\n                \"signature-break\", \"critical\",\n                f\"{label(g, callee.id)} calls {label(g, target_id)} through its \"\n                f\"procedure argument {dummy.upper()} the old way: {hits[0]['text']}\",\n                callee.path, no,\n                detail=(f\"{label(g, e.src)} passes {target.name.upper()} to \"\n                        f\"{callee.name.upper()} ({c.path}:{c.lineno}), which calls it \"\n                        f\"as {dummy.upper()}. Fortran checks neither.\"),\n                fix=(f\"Pass a wrapper with the old argument list, or have \"\n                     f\"{callee.name.upper()} pass the new argument.\")))\n    return out\n\n\ndef _copiers(g, copybook_id: str) -> list[str]:\n    \"\"\"Every COBOL program that copies the copybook, directly or through other copybooks.\"\"\"\n    names, seen, todo = set(), {copybook_id}, [copybook_id]\n    while todo:\n        for e in g.in_edges(todo.pop()):\n            src = g.nodes.get(e.src)\n            if e.kind.value != \"imports\" or src is None or e.src in seen:\n                continue\n            seen.add(e.src)\n            if \"copybook\" in src.tags:\n                todo.append(e.src)\n            elif \"cobol-program\" in src.tags:\n                names.add(src.name)\n    return sorted(names)\n\n\ndef _findings(b: Mapped | None, a: Mapped | None) -> list[Finding]:\n    from magellan_lite.polyglot.analyze.frontends import language_findings\n    from magellan_lite.polyglot.core.diff import (ChangeKind, affects, call_shape, diff_graphs,\n                                                  surviving_references)\n    from magellan_lite.polyglot.core.model import EdgeKind, Graph\n\n    old = b.graph if b else Graph()\n    new = a.graph if a else Graph()\n    label = lambda g, nid: (g.nodes[nid].qualname.split(\"@\", 1)[-1]   # noqa: E731\n                            if nid in g.nodes else nid)\n    cs = diff_graphs(old, new)\n    out: list[Finding] = []\n\n    for ch in cs.changes:\n        # a signature some call sites can no longer satisfy: each such call site\n        if ch.kind in (ChangeKind.SIGNATURE_CHANGED, ChangeKind.RENAMED) and ch.specs:\n            hard = [s for s in ch.specs if s.get(\"hard\")]\n            for e in new.in_edges(ch.node_id):\n                if e.kind not in (EdgeKind.CALLS, EdgeKind.INSTANTIATES):\n                    continue\n                hits = [s for s in hard if affects(s, call_shape(e), 0)]\n                if hits:\n                    out.append(Finding(\n                        \"signature-break\", \"critical\",\n                        f\"{label(new, e.src)} calls {label(new, ch.node_id)} the old way: \"\n                        f\"{hits[0]['text']}\", e.path, e.lineno,\n                        detail=\"The call compiled against the old signature; it no longer \"\n                               \"matches.\",\n                        fix=\"Update the call, or keep the old signature next to the new one.\"))\n            # passed as an argument (EXTERNAL INTRST; CALL APPLY(INTRST, ...)): the calls that\n            # matter are the ones made through the parameter, inside the routine it is passed to\n            if a and new.nodes.get(ch.node_id) is not None and \\\n                    (new.nodes[ch.node_id].meta or {}).get(\"lang\") == \"fortran\":\n                out += _through_procedure_arguments(new, ch.node_id, hard, a.root, label, affects,\n                                                    EdgeKind)\n        # deleted, and code nobody edited still uses it\n        elif ch.kind is ChangeKind.REMOVED and ch.breaks:\n            root = a.root if a else None\n            for e in surviving_references(old, new, ch.node_id, source_root=root):\n                where = new.nodes.get(e.src)\n                out.append(Finding(\n                    \"removed-still-referenced\", \"critical\",\n                    f\"{label(old, e.src)} still uses {label(old, ch.node_id)}, which this \"\n                    f\"change deletes\",\n                    where.path if where else e.path,\n                    e.lineno if where is None or where.lineno <= e.lineno <= where.end_lineno\n                    else where.lineno,\n                    fix=\"Keep it, or move every user to its replacement first.\"))\n\n    try:\n        theirs = language_findings(old, new, cs, a.root if a else (b.root if b else \".\"))\n    except Exception as exc:                   # noqa: BLE001\n        theirs = []\n        new.diagnostics.append(f\"language findings skipped: {exc}\")\n    for f in theirs:\n        # Lite's checklist says how serious each rule is (RULES): the verdict blocks only on\n        # high or critical findings of blocking rules\n        ours = RULES.get(f.rule)\n        severity = ours[0] if ours else f.severity if f.severity in _SEVERITIES else \"low\"\n        detail = f.detail\n        if f.rule == \"copybook-layout-changed\" and f.node_id in new.nodes:\n            # its fix says \"recompile every program listed\": list them, all of them\n            progs = _copiers(new, f.node_id)\n            if progs:\n                detail += f\" Copied by {len(progs)} program(s): {', '.join(progs)}.\"\n        out.append(Finding(f.rule, severity, f.title, f.path, f.lineno or 1,\n                           detail=detail, fix=f.suggestion or (ours[2] if ours else \"\")))\n\n    unique, seen = [], set()\n    for f in out:\n        if (f.rule, f.path, f.line) not in seen:\n            seen.add((f.rule, f.path, f.line))\n            unique.append(f)\n    return unique\n", "magellan_lite/mcp.py": "\"\"\"Magellan Lite as tools an AI agent can call: a Model Context Protocol (MCP) server.\n\n    magellan-lite mcp [PATH]\n    claude mcp add magellan-lite -- python -m magellan_lite mcp\n\nIt speaks MCP over stdin and stdout: newline-delimited JSON-RPC 2.0, one message per line,\nstandard library only. It answers ``initialize``, ``ping``, ``tools/list`` and ``tools/call``;\nother requests get JSON-RPC's \"method not found\", and notifications get no answer. Nothing but\nprotocol messages is written to stdout: anything else a tool prints goes to stderr.\n\nEvery tool takes an optional ``path``: the project's root folder (default: the PATH the server\nwas started with, else its working directory). Each returns JSON text. A call that cannot be\nanswered (no such definition, not a git repository) comes back as a tool result with\n``isError`` and a JSON ``{\"error\": ...}`` saying why in plain words; an unknown tool or a\nmalformed request is a JSON-RPC error.\n\n``magellan_lite_plan``    before a change: the edits intended, checked in memory; every other\n                          place to change with its code, and what was ruled out (plan.py)\n``magellan_lite_progress`` what is left of the plan; ``magellan_lite_done``: finished?\n``magellan_lite_brief``   after an edit: ok / review / block, what to fix first, files to\n                          re-read, tests to run (brief.py)\n``magellan_lite_check``   the full report behind the brief, optionally with the code map\n``magellan_lite_reach``   who depends on a definition: its callers and theirs, hop by hop\n``magellan_lite_node``    one definition: where it is, its signature, both sides of its edges\n``magellan_lite_unused``  definitions nothing in the project mentions: probably dead code\n``magellan_lite_team``    your work against your teammates' shared work in progress\n``magellan_lite_rules``   the checklist\n\n``reach``, ``node`` and ``unused`` read the working tree only (no git needed) and keep the\nlast project's map until a file changes, so asking about several functions in a row is quick.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport contextlib\nimport difflib\nimport json\nimport os\nimport re\nimport sys\nfrom dataclasses import dataclass, field\nfrom pathlib import Path\n\nfrom magellan_lite import __version__\nfrom magellan_lite.git import GitError\n\n#: the protocol versions this server can speak (it uses nothing that differs between them)\nVERSIONS = (\"2025-11-25\", \"2025-06-18\", \"2025-03-26\", \"2024-11-05\")\n#: what it answers a client that names no version (the full Magellan's choice)\nPROTOCOL = \"2024-11-05\"\n\nINSTRUCTIONS = (\n    \"Magellan Lite reads a project's code (Python, Java, C, C++, Fortran, COBOL, TypeScript) \"\n    \"without running it. For a change that reaches many places (a signature, a record \"\n    \"layout), call magellan_lite_plan first with the edit you intend: it lists every other \"\n    \"place to change, with the code, and what it ruled out; then edit, call \"\n    \"magellan_lite_progress after each batch, and magellan_lite_done at the end. Before \"\n    \"changing a function, magellan_lite_reach shows what depends on it. After any edit, before \"\n    \"committing or saying you are done, call magellan_lite_brief: on block, fix do_first and \"\n    \"call it again; re-read check_these_files and run tests_to_run.\")\n\n\nclass ToolError(Exception):\n    \"\"\"A call the tool cannot answer, said plainly; ``extra`` goes into the JSON.\"\"\"\n\n    def __init__(self, message: str, **extra) -> None:\n        super().__init__(message)\n        self.extra = extra\n\n\n# -- the project, mapped once per state of its files ------------------------------------------\n\n@dataclass\nclass Project:\n    \"\"\"The working tree's definitions and call graph.\"\"\"\n    root: Path\n    snapshot: object\n    defs: dict\n    graph: object\n    _unused: set | None = field(default=None, repr=False)\n\n    @property\n    def unused(self) -> set[str]:\n        if self._unused is None:\n            from magellan_lite.web import _unmentioned\n            self._unused = _unmentioned(self.snapshot, self.defs)\n        return self._unused\n\n\n_LAST: dict[Path, tuple[tuple, Project]] = {}\n\n\ndef project(root: Path) -> Project:\n    \"\"\"The project as it is on disk now; mapped again only when a source file changed.\"\"\"\n    from magellan_lite.defs import definitions\n    from magellan_lite.graph import build_graph\n    from magellan_lite.source import Snapshot, decode, iter_source_files\n\n    files = iter_source_files(root)\n    stamp = []\n    for rel in files:                           # look before reading: an edit made meanwhile\n        st = os.stat(root / rel)                # shows up as a new stamp on the next call\n        stamp.append((rel, st.st_mtime_ns, st.st_size))\n    hit = _LAST.get(root)\n    if hit and hit[0] == tuple(stamp):\n        return hit[1]\n    snap = Snapshot({rel: decode((root / rel).read_bytes()) for rel in files}, label=str(root))\n    defs = definitions(snap)\n    p = Project(root, snap, defs, build_graph(snap, defs))\n    _LAST.clear()                               # one project at a time: one agent, one repo\n    _LAST[root] = (tuple(stamp), p)\n    return p\n\n\n# -- the tools ---------------------------------------------------------------------------------\n\n_PATH = {\"type\": \"string\",\n         \"description\": \"The project's root folder (default: the folder the server was \"\n                        \"started for).\"}\n_AGAINST = {\"type\": \"string\",\n            \"description\": \"The baseline to compare with: git:REV (default git:HEAD, the last \"\n                           \"commit) or a folder holding the old version.\"}\n_NAME = {\"type\": \"string\",\n         \"description\": \"The definition: a qualified name (billing.ledger.post, \"\n                        \"billing.Ledger.post, c@parse.load, java@geo.Shape.area(double,double)), \"\n                        \"a short name (post) that the tool resolves, or path:line.\"}\n\n\ndef _limit(default: int) -> dict:\n    return {\"type\": \"integer\", \"minimum\": 1, \"description\": f\"Entries per list (default {default}).\"}\n\n\ndef _int(a: dict, key: str, default: int, lo: int = 1, hi: int = 10_000) -> int:\n    v = a.get(key, default)\n    if v is None:\n        return default\n    if isinstance(v, bool) or not isinstance(v, int):\n        raise ToolError(f\"{key} must be a whole number, not {v!r}\")\n    return max(lo, min(hi, v))\n\n\ndef _str(a: dict, key: str, default: str = \"\") -> str:\n    v = a.get(key)\n    if v is None or v == \"\":\n        return default\n    if not isinstance(v, str):\n        raise ToolError(f\"{key} must be a string, not {v!r}\")\n    return v\n\n\ndef _against(root: Path, a: dict) -> str:\n    \"\"\"``git:REV``, or a folder (relative to the project) holding the old version.\"\"\"\n    against = _str(a, \"against\", \"git:HEAD\")\n    if against.startswith(\"git:\"):\n        return against\n    folder = (root / against).resolve()\n    if not folder.is_dir():\n        raise ToolError(f\"against must be git:REV (git:HEAD, git:main, ...) or a folder holding \"\n                        f\"the old version; {against!r} is neither\")\n    return str(folder)\n\n\ndef _brief(root: Path, a: dict):\n    from magellan_lite.brief import LIMIT, brief\n    return brief(root, _against(root, a), _int(a, \"limit\", LIMIT))\n\n\ndef _check(root: Path, a: dict):\n    from magellan_lite.engine import check_snapshots, load_before\n    from magellan_lite.source import working_tree\n    against = _against(root, a)\n    before, after = load_before(root, against), working_tree(root)\n    out = check_snapshots(before, after, root, against).to_dict()\n    if a.get(\"map\"):\n        from magellan_lite.web import code_map\n        out[\"map\"] = code_map(before, after, out)\n    return out\n\n\ndef _plan(root: Path, a: dict):\n    from magellan_lite.plan import PlanError, plan\n    edits = a.get(\"edits\")\n    if isinstance(edits, dict):\n        edits = [edits]\n    if not isinstance(edits, list) or not all(isinstance(e, dict) for e in edits):\n        raise ToolError(\"edits must be a list of {path, old, new}: old is text in the file now \"\n                        \"(exactly once), new replaces it\")\n    try:\n        return plan(root, edits, _against(root, a))\n    except PlanError as exc:\n        raise ToolError(str(exc)) from None\n\n\ndef _stage(name: str):\n    def run(root: Path, a: dict):\n        from magellan_lite import plan\n        try:\n            return getattr(plan, name)(root)\n        except plan.PlanError as exc:\n            raise ToolError(str(exc)) from None\n    return run\n\n\ndef _reach(root: Path, a: dict):\n    from magellan_lite.brief import NEAR, find_tests\n    from magellan_lite.diff import Change\n    from magellan_lite.radius import MAX_HOPS, blast_radius\n\n    p = project(root)\n    d = resolve(p, _str(a, \"name\"))\n    depth = _int(a, \"depth\", MAX_HOPS, 1, MAX_HOPS)\n    limit = _int(a, \"limit\", 40)\n    # scored as `check` scores the usual edit: a new signature (a new value, for a constant)\n    kind = \"value\" if d.kind == \"constant\" else \"signature\"\n    hit = [x for x in blast_radius([Change(kind, d.name, d.path, d.line, before=d, after=d)],\n                                   p.graph, p.defs) if x[\"hops\"] <= depth]\n    shown = hit[:limit]\n    hops = []\n    for n in sorted({x[\"hops\"] for x in shown}):\n        hops.append({\"hop\": n, \"definitions\": [\n            {\"name\": x[\"name\"], \"kind\": p.defs[x[\"name\"]].kind if x[\"name\"] in p.defs else \"\",\n             \"where\": f\"{x['path']}:{x['line']}\", \"score\": x[\"score\"], \"via\": x[\"why\"]}\n            for x in shown if x[\"hops\"] == n]})\n    files: dict[str, dict] = {}\n    for x in hit:\n        f = files.setdefault(x[\"path\"], {\"path\": x[\"path\"], \"definitions\": 0, \"nearest_hop\": 99})\n        f[\"definitions\"] += 1\n        f[\"nearest_hop\"] = min(f[\"nearest_hop\"], x[\"hops\"])\n    imported = sorted({f\"{i.path}:{i.line}\" for i in p.graph.imports if i.target == d.name})\n    direct = sum(x[\"hops\"] == 1 for x in hit)\n    if hit:\n        summary = (f\"{_n(len(hit), 'definition')} in {_n(len(files), 'file')} \"\n                   f\"depend{'s' if len(hit) == 1 else ''} on {d.name}; {direct} \"\n                   f\"use{'s' if direct == 1 else ''} it directly.\")\n    else:\n        summary = (f\"Nothing in this project calls or reads {d.name}\"\n                   + (f\" (it is imported at {', '.join(imported[:3])})\" if imported else \"\")\n                   + \": see note for what a code reading cannot see.\")\n    near = [p.defs[x[\"name\"]] for x in hit if x[\"score\"] >= NEAR and x[\"name\"] in p.defs]\n    files_ranked = sorted(files.values(), key=lambda f: (f[\"nearest_hop\"], -f[\"definitions\"],\n                                                         f[\"path\"]))\n    tests = find_tests(p.snapshot, [d], near)\n    return {\n        \"target\": _card(d),\n        \"summary\": summary,\n        \"hops\": hops,\n        \"files\": files_ranked[:limit],\n        \"imported_at\": imported[:limit],\n        \"tests\": tests[:limit],\n        \"omitted\": {\"definitions\": max(0, len(hit) - len(shown)),\n                    \"files\": max(0, len(files_ranked) - limit),\n                    \"imported_at\": max(0, len(imported) - limit),\n                    \"tests\": max(0, len(tests) - limit)},\n        \"note\": \"Found by reading the code, not running it: a call through a computed name \"\n                \"(getattr, reflection, a function pointer, a dynamic COBOL CALL) or from \"\n                \"outside this project is not seen. A 'via' ending in 'a guess' was matched by \"\n                \"method name alone. Scores fade with each hop (a call x0.9).\",\n    }\n\n\ndef _node(root: Path, a: dict):\n    p = project(root)\n    d = resolve(p, _str(a, \"name\"))\n    limit = _int(a, \"limit\", 30)\n\n    def group(edges, other) -> list[dict]:\n        by: dict[tuple, dict] = {}\n        for e in edges:\n            entry = by.setdefault((other(e), e.kind), {\"name\": other(e), \"how\": e.kind,\n                                                       \"at\": [], \"guess\": e.guess})\n            entry[\"guess\"] = entry[\"guess\"] and e.guess\n            site = f\"{e.path}:{e.line}\"\n            if site not in entry[\"at\"]:\n                entry[\"at\"].append(site)\n        return sorted(by.values(), key=lambda x: (x[\"guess\"], x[\"name\"], x[\"how\"]))\n\n    called_by = group(p.graph.callers(d.name), lambda e: e.src)\n    calls = group(p.graph.uses(d.name), lambda e: e.dst)\n    stem = d.name.split(\"(\", 1)[0]\n    members = sorted(n for n in p.defs if n.startswith(stem + \".\") and n != d.name\n                     and \".\" not in n[len(stem) + 1:].split(\"(\", 1)[0])\n    owner = stem.rsplit(\".\", 1)[0]\n    out = _card(d)\n    out.update({\n        \"end_line\": d.end_line,\n        \"member_of\": owner if owner in p.defs else \"\",\n        \"members\": members[:limit],\n        \"called_by\": called_by[:limit],\n        \"calls\": calls[:limit],\n        \"imported_at\": sorted({f\"{i.path}:{i.line}\" for i in p.graph.imports\n                               if i.target == d.name})[:limit],\n        \"probably_unused\": d.name in p.unused,\n        \"counts\": {\"called_by\": len(called_by), \"calls\": len(calls), \"members\": len(members)},\n    })\n    return out\n\n\n_UNUSED_CAVEAT = (\n    \"Probably dead code: each name appears nowhere in the project except where it is defined. \"\n    \"It can still be used through a computed name (getattr, reflection, a plugin registry, a \"\n    \"dynamic COBOL CALL), by code outside this project (a library's users, a script, a \"\n    \"scheduled job), or by a framework convention. Check each one before deleting it. \"\n    \"Decorated definitions, dunder methods, subclasses and tests are left out.\")\n\n\ndef _unused(root: Path, a: dict):\n    p = project(root)\n    under = _str(a, \"under\").replace(\"\\\\\", \"/\").strip(\"/\")\n    limit = _int(a, \"limit\", 50)\n    names = [n for n in p.unused\n             if not under or p.defs[n].path == under or p.defs[n].path.startswith(under + \"/\")]\n    names.sort(key=lambda n: (p.defs[n].path, p.defs[n].line))\n    return {\"count\": len(names), \"caveat\": _UNUSED_CAVEAT,\n            \"definitions\": [{k: v for k, v in _card(p.defs[n]).items()\n                             if k in (\"name\", \"kind\", \"lang\", \"where\")} for n in names[:limit]],\n            \"omitted\": max(0, len(names) - limit)}\n\n\ndef _team(root: Path, a: dict):\n    from magellan_lite import team\n    from magellan_lite.report import VERDICTS\n    remote = _str(a, \"remote\", \"origin\")\n    try:                                        # git's own words for these are no help\n        remotes = team._git(root, \"remote\").split()\n    except GitError:\n        raise ToolError(f\"{root.as_posix()} is not in a git repository. The team check reads \"\n                        \"teammates' shared work in progress from a git remote, so it only \"\n                        \"works inside a clone that teammates share to.\") from None\n    if remote not in remotes:\n        raise ToolError(f\"this repository has no remote named {remote!r}\"\n                        + (f\" (it has {', '.join(remotes)}: pass one as remote)\" if remotes\n                           else \" (it has none)\")\n                        + \". The team check reads teammates' work in progress from the remote \"\n                          \"they run `magellan-lite share` against.\")\n    results = team.team(root, remote, _str(a, \"name\") or None)\n    verdict = max((c.verdict for c in results), key=VERDICTS.index, default=\"ok\")\n    if not results:\n        summary = (\"Nobody else has shared work in progress on this remote yet (teammates run \"\n                   \"`magellan-lite share`), so there is nothing to combine.\")\n    else:\n        bad = [c.name for c in results if c.verdict != \"ok\"]\n        whose = \"1 teammate's\" if len(results) == 1 else f\"{len(results)} teammates'\"\n        summary = (f\"Your work against {whose} shared work in progress: \"\n                   + (f\"problems only the combination has with {', '.join(bad)}.\" if bad\n                      else \"fine together.\"))\n    return {\"verdict\": verdict, \"summary\": summary,\n            \"teammates\": [c.to_dict() for c in results]}\n\n\ndef _rules(root: Path, a: dict):\n    import magellan_lite.rules  # noqa: F401  registers every rule\n    from magellan_lite.findings import RULES\n    return {\"rules\": [{\"id\": r.id, \"severity\": r.severity, \"blocking\": r.blocking,\n                       \"kind\": \"file\" if r.per_file else \"change\", \"fix\": r.fix}\n                      for r in sorted(RULES.values(), key=lambda r: r.id)],\n            \"note\": \"A file rule looks at each edited definition; a change rule at the whole \"\n                    \"change and the code it reaches. A blocking rule's high or critical \"\n                    \"finding makes the verdict block; any medium or worse makes it review.\"}\n\n\n_BASELINE_HELP = (\"Magellan Lite compares the working tree with a baseline. With against=git:REV \"\n                  \"(the default is git:HEAD) the project must be in a git repository with at \"\n                  \"least one commit, and REV must exist; otherwise pass against as a folder \"\n                  \"holding the old version.\")\n\nTOOLS: dict[str, dict] = {\n    \"magellan_lite_plan\": {\n        \"description\": \"Call this first for a change that reaches many places (a signature, a \"\n                       \"record layout, a renamed or widened field), before editing anything. \"\n                       \"Give the edits you intend (usually just the definition: the new \"\n                       \"signature line, the new PIC); they are made in memory, checked against \"\n                       \"the last commit, and you get the worklist: every other place that must \"\n                       \"change with its code as written (calls inside INCLUDE files and through \"\n                       \"procedure arguments included), programs to recompile, uses that need \"\n                       \"nothing, and mentions of the same names that are not uses (comments, \"\n                       \"locals, look-alikes) with why. Work through it, then call \"\n                       \"magellan_lite_progress.\",\n        \"properties\": {\"path\": _PATH, \"against\": _AGAINST,\n                       \"edits\": {\"type\": \"array\", \"description\": \"The edits you intend.\",\n                                 \"items\": {\"type\": \"object\", \"properties\": {\n                                     \"path\": {\"type\": \"string\",\n                                              \"description\": \"File, relative to the project.\"},\n                                     \"old\": {\"type\": \"string\",\n                                             \"description\": \"Text in the file now, exactly once.\"},\n                                     \"new\": {\"type\": \"string\", \"description\": \"What replaces it.\"}},\n                                     \"required\": [\"path\", \"old\", \"new\"]}}},\n        \"required\": [\"edits\"], \"run\": _plan, \"git_help\": _BASELINE_HELP,\n    },\n    \"magellan_lite_progress\": {\n        \"description\": \"After a batch of edits: what is left of the plan from magellan_lite_plan \"\n                       \"(planned edits you have not made yet are applied in memory, so the order \"\n                       \"of your work does not matter) and any new problem, each with its code. \"\n                       \"Call it until nothing is left, then magellan_lite_done.\",\n        \"properties\": {\"path\": _PATH}, \"run\": _stage(\"progress\"), \"git_help\": _BASELINE_HELP,\n    },\n    \"magellan_lite_done\": {\n        \"description\": \"At the end: confirms every planned edit is made and nothing is left to \"\n                       \"change, and returns what a report needs: each file's changed lines, the \"\n                       \"places the plan listed, and the programs to recompile. If anything is \"\n                       \"left it says what.\",\n        \"properties\": {\"path\": _PATH}, \"run\": _stage(\"done\"), \"git_help\": _BASELINE_HELP,\n    },\n    \"magellan_lite_brief\": {\n        \"description\": \"Call this after editing code, before committing or saying you are \"\n                       \"done. Compares the working tree with the last commit (or `against`) and \"\n                       \"returns a short JSON verdict (ok / review / block) with do_first (the \"\n                       \"findings to fix, each with path:line and a fix), check_these_files \"\n                       \"(files you did not edit that your change reaches), and tests_to_run. On \"\n                       \"block, fix do_first and call it again.\",\n        \"properties\": {\"path\": _PATH, \"against\": _AGAINST, \"limit\": _limit(8)},\n        \"run\": _brief, \"git_help\": _BASELINE_HELP,\n    },\n    \"magellan_lite_check\": {\n        \"description\": \"The full report behind the brief: every changed definition, every \"\n                       \"finding, the whole blast radius (affected) and anything not checked \"\n                       \"(errors). Use it when the brief's lists were cut (its omitted counts) or \"\n                       \"you need everything; set map for the code map's nodes and edges.\",\n        \"properties\": {\"path\": _PATH, \"against\": _AGAINST,\n                       \"map\": {\"type\": \"boolean\",\n                               \"description\": \"Add the code map (nodes and edges) the editor \"\n                                              \"and website draw.\"}},\n        \"run\": _check, \"git_help\": _BASELINE_HELP,\n    },\n    \"magellan_lite_reach\": {\n        \"description\": \"Before changing a function, method, class or constant (especially old \"\n                       \"code you are modernizing), call this to see what depends on it: its \"\n                       \"callers, their callers, hop by hop, each with the call site that links \"\n                       \"it, the files they are in, and tests that mention them. An ambiguous \"\n                       \"short name returns the candidates to choose from.\",\n        \"properties\": {\"path\": _PATH, \"name\": _NAME,\n                       \"depth\": {\"type\": \"integer\", \"minimum\": 1,\n                                 \"description\": \"Hops to follow (default and most: 6). 1 lists \"\n                                                \"the direct callers only.\"},\n                       \"limit\": _limit(40)},\n        \"required\": [\"name\"], \"run\": _reach,\n    },\n    \"magellan_lite_node\": {\n        \"description\": \"One definition up close: where it is, its language and signature, who \"\n                       \"calls or reads it and what it calls or reads (with the call sites), \"\n                       \"where it is imported, and its members if it is a class. Use it to \"\n                       \"understand code before editing it, or to walk the call graph a step at \"\n                       \"a time.\",\n        \"properties\": {\"path\": _PATH, \"name\": _NAME, \"limit\": _limit(30)},\n        \"required\": [\"name\"], \"run\": _node,\n    },\n    \"magellan_lite_unused\": {\n        \"description\": \"Definitions whose name appears nowhere else in the project: probably \"\n                       \"dead code, each with path:line. Use it before modernizing, to skip or \"\n                       \"remove code nothing uses, and check each one first: a call by a \"\n                       \"computed name, reflection, or a user outside the project is not seen.\",\n        \"properties\": {\"path\": _PATH,\n                       \"under\": {\"type\": \"string\",\n                                 \"description\": \"Only definitions in this folder or file, \"\n                                                \"relative to the project root.\"},\n                       \"limit\": _limit(50)},\n        \"run\": _unused,\n    },\n    \"magellan_lite_team\": {\n        \"description\": \"Your uncommitted work checked against each teammate's shared work in \"\n                       \"progress (published with `magellan-lite share` to refs/wip/* on the git \"\n                       \"remote): only the problems the combination has, such as their new call \"\n                       \"to a function you changed. Only meaningful in a git repository whose \"\n                       \"remote teammates share to; it fetches from that remote.\",\n        \"properties\": {\"path\": _PATH,\n                       \"remote\": {\"type\": \"string\",\n                                  \"description\": \"The git remote (default origin).\"},\n                       \"name\": {\"type\": \"string\",\n                                \"description\": \"Your own name under refs/wip/, so your own \"\n                                               \"share is skipped (default: git's user.name).\"}},\n        \"run\": _team,\n        \"git_help\": \"The team check needs a git repository with a remote where teammates \"\n                    \"publish their work in progress with `magellan-lite share`.\",\n    },\n    \"magellan_lite_rules\": {\n        \"description\": \"The checklist Magellan Lite runs on a change: each rule's id, severity, \"\n                       \"whether it can block, and its usual fix. Use it to understand a rule id \"\n                       \"seen in a finding.\",\n        \"properties\": {\"path\": _PATH},\n        \"run\": _rules,\n    },\n}\n\n\n# -- finding a definition by name --------------------------------------------------------------\n\ndef resolve(p: Project, query: str):\n    \"\"\"The definition ``query`` names: exact, then without the language prefix or Java's\n    parameter list, then by its last dotted parts, then by its short name, then ignoring case\n    (COBOL). ``path:line`` names the innermost definition there. Raises ``ToolError`` with the\n    candidates when the name is ambiguous, and close names when it is unknown.\"\"\"\n    q = query.strip()\n    if not q:\n        raise ToolError(\"name is empty: give a definition's name (pkg.mod.func, or a short \"\n                        \"name) or path:line\")\n    m = re.fullmatch(r\"(.+):(\\d+)\", q)\n    if m and m.group(1).replace(\"\\\\\", \"/\") in p.snapshot.files:\n        path, line = m.group(1).replace(\"\\\\\", \"/\"), int(m.group(2))\n        here = [d for d in p.defs.values() if d.path == path and d.line <= line <= d.end_line]\n        if here:\n            return min(here, key=lambda d: d.end_line - d.line)\n        raise ToolError(f\"no function, class or constant around {path}:{line}\")\n\n    def bare(n: str) -> str:\n        return n.split(\"@\", 1)[-1]\n\n    def stem(n: str) -> str:\n        return bare(n).split(\"(\", 1)[0]\n\n    low = q.lower()\n    tiers = (\n        lambda n, d: n == q,\n        lambda n, d: bare(n) == q,\n        lambda n, d: stem(n) == q,\n        lambda n, d: stem(n).endswith(\".\" + q) or bare(n).endswith(\".\" + q),\n        lambda n, d: (d.label or d.short).split(\"(\", 1)[0] == q,\n        lambda n, d: stem(n).lower() == low or stem(n).lower().endswith(\".\" + low),\n    )\n    for match in tiers:\n        found = sorted((d for n, d in p.defs.items() if match(n, d)),\n                       key=lambda d: (d.path, d.line))\n        if len(found) == 1:\n            return found[0]\n        if found:\n            raise ToolError(\n                f\"{q!r} matches {len(found)} definitions: call again with one of these names\",\n                candidates=[{k: v for k, v in _card(d).items() if k in (\"name\", \"kind\", \"where\")}\n                            for d in found[:20]],\n                more=max(0, len(found) - 20))\n    words = {stem(n) for n in p.defs} | {stem(n).rsplit(\".\", 1)[-1] for n in p.defs}\n    close = difflib.get_close_matches(q, sorted(words), n=6, cutoff=0.6)\n    raise ToolError(f\"no function, method, class or constant named {q!r} in {p.root.as_posix()}\",\n                    did_you_mean=close)\n\n\ndef _card(d) -> dict:\n    from magellan_lite.languages import NAMES\n    lang = d.lang or \"python\"\n    out = {\"name\": d.name, \"kind\": d.kind, \"lang\": NAMES.get(lang, lang),\n           \"where\": f\"{d.path}:{d.line}\",\n           \"signature\": re.sub(r\"\\s*#[0-9a-f]{8,}$\", \"\", d.signature)}\n    if d.kind == \"constant\" and d.value and not d.lang:\n        out[\"value\"] = d.value if len(d.value) <= 200 else d.value[:199] + \"\u2026\"\n    return out\n\n\ndef _n(n: int, word: str) -> str:\n    return f\"{n} {word}{'' if n == 1 else 's'}\"\n\n\n# -- the protocol -------------------------------------------------------------------------------\n\ndef _reply(id_, result) -> dict:\n    return {\"jsonrpc\": \"2.0\", \"id\": id_, \"result\": result}\n\n\ndef _error(id_, code: int, message: str) -> dict:\n    return {\"jsonrpc\": \"2.0\", \"id\": id_, \"error\": {\"code\": code, \"message\": message}}\n\n\nclass Server:\n    \"\"\"The tools for one default project; ``handle`` takes one JSON-RPC message.\"\"\"\n\n    def __init__(self, root: str | Path = \".\") -> None:\n        self.root = Path(root).resolve()\n\n    def handle(self, msg) -> dict | None:\n        \"\"\"One message in, at most one out: notifications and stray responses get none.\"\"\"\n        if not isinstance(msg, dict):\n            return _error(None, -32600, \"invalid request: expected a JSON object\")\n        if \"method\" not in msg and (\"result\" in msg or \"error\" in msg):\n            return None                             # a response to a request we never sent\n        method, id_ = msg.get(\"method\"), msg.get(\"id\")\n        if not isinstance(method, str) or msg.get(\"jsonrpc\") not in (\"2.0\", None):\n            return _error(id_, -32600, \"invalid request: a JSON-RPC 2.0 request has a \"\n                                       \"string 'method'\")\n        if \"id\" not in msg:\n            return None                             # notifications/initialized, cancelled...\n        params = msg.get(\"params\")\n        if params is None:\n            params = {}\n        if not isinstance(params, dict):\n            return _error(id_, -32602, \"invalid params: expected an object\")\n\n        if method == \"initialize\":\n            asked = params.get(\"protocolVersion\")\n            return _reply(id_, {\n                \"protocolVersion\": asked if asked in VERSIONS else\n                                   VERSIONS[0] if isinstance(asked, str) and asked else PROTOCOL,\n                \"capabilities\": {\"tools\": {\"listChanged\": False}},\n                \"serverInfo\": {\"name\": \"magellan-lite\", \"version\": __version__},\n                \"instructions\": INSTRUCTIONS,\n            })\n        if method == \"ping\":\n            return _reply(id_, {})\n        if method == \"tools/list\":\n            return _reply(id_, {\"tools\": [\n                {\"name\": name, \"description\": spec[\"description\"],\n                 \"inputSchema\": {\"type\": \"object\", \"properties\": spec[\"properties\"],\n                                 \"required\": spec.get(\"required\", []),\n                                 \"additionalProperties\": False}}\n                for name, spec in TOOLS.items()]})\n        if method == \"tools/call\":\n            name, args = params.get(\"name\"), params.get(\"arguments\")\n            if name not in TOOLS:\n                return _error(id_, -32602, f\"unknown tool: {name!r} (tools/list has the \"\n                                           f\"names: {', '.join(TOOLS)})\")\n            if args is not None and not isinstance(args, dict):\n                return _error(id_, -32602, \"invalid params: arguments must be an object\")\n            text, is_error = self.call(name, args or {})\n            return _reply(id_, {\"content\": [{\"type\": \"text\", \"text\": text}],\n                                \"isError\": is_error})\n        return _error(id_, -32601, f\"method not found: {method}\")\n\n    def call(self, name: str, args: dict) -> tuple[str, bool]:\n        \"\"\"Run one tool: ``(JSON text, is_error)``. Never raises.\"\"\"\n        spec = TOOLS[name]\n        unknown = sorted(set(args) - set(spec[\"properties\"]))\n        try:\n            if unknown:\n                raise ToolError(f\"unknown argument {', '.join(map(repr, unknown))}: {name} takes \"\n                                f\"{', '.join(spec['properties'])}\")\n            for key in spec.get(\"required\", ()):\n                if args.get(key) in (None, \"\"):\n                    raise ToolError(f\"{name} needs {key!r}\")\n            result = spec[\"run\"](self._root(args), args)\n        except ToolError as exc:\n            return _dumps({\"error\": str(exc), **exc.extra}), True\n        except GitError as exc:\n            return _dumps({\"error\": f\"{spec.get('git_help', 'git could not answer.')} \"\n                                    f\"Git said: {exc}\"}), True\n        except (ValueError, OSError) as exc:\n            return _dumps({\"error\": str(exc)}), True\n        except Exception as exc:                    # noqa: BLE001 - a tool never stops the server\n            return _dumps({\"error\": f\"{name} failed: {type(exc).__name__}: {exc}\"}), True\n        return _dumps(result), False\n\n    def _root(self, args: dict) -> Path:\n        given = _str(args, \"path\")\n        root = (self.root / given if given else self.root).resolve()\n        if not root.is_dir():\n            raise ToolError(f\"not a folder: {root.as_posix()}\")\n        return root\n\n\ndef _dumps(obj) -> str:\n    return json.dumps(obj, indent=2, ensure_ascii=False)\n\n\ndef serve(root: str | Path = \".\", stdin=None, stdout=None) -> int:\n    \"\"\"Answer JSON-RPC messages, one per line, until stdin closes.\"\"\"\n    if stdin is None:\n        stdin = sys.stdin\n        if hasattr(stdin, \"reconfigure\"):           # MCP is UTF-8; Windows pipes are not\n            stdin.reconfigure(encoding=\"utf-8\", errors=\"replace\")\n    if stdout is None:\n        stdout = sys.stdout\n        if hasattr(stdout, \"reconfigure\"):          # \"\\n\" ends a message, also on Windows\n            stdout.reconfigure(encoding=\"utf-8\", newline=\"\\n\")\n    server = Server(root)\n\n    def send(msg) -> None:\n        stdout.write(json.dumps(msg) + \"\\n\")        # ASCII on the wire: no code page trouble\n        stdout.flush()\n\n    while True:\n        line = stdin.readline()\n        if not line:\n            return 0\n        line = line.strip()\n        if not line:\n            continue\n        try:\n            msg = json.loads(line)\n        except ValueError:\n            send(_error(None, -32700, \"parse error: each line must be one JSON-RPC message\"))\n            continue\n        # a tool's stray print() must never reach the protocol stream\n        with contextlib.redirect_stdout(sys.stderr):\n            if isinstance(msg, list):                # a batch (older protocol versions)\n                out = [r for r in map(server.handle, msg) if r is not None] if msg else \\\n                    [_error(None, -32600, \"invalid request: empty batch\")]\n            else:\n                out = server.handle(msg)\n        if out:\n            send(out)\n", "magellan_lite/output.py": "\"\"\"How a report reads in a terminal (``text``) and in a pull request (``markdown``). JSON is\n``Report.to_dict``.\"\"\"\n\nfrom __future__ import annotations\n\nimport os\nimport re\n\nfrom magellan_lite.report import Report\n\n_KIND = {\"removed\": \"del\", \"renamed\": \"ren\", \"signature\": \"sig\", \"value\": \"val\", \"body\": \"body\",\n         \"added\": \"new\"}\n\n#: the verdict's colour in a terminal: ANSI bold red, yellow, green\n_COLOUR = {\"block\": \"1;31\", \"review\": \"1;33\", \"ok\": \"1;32\"}\n\n\ndef _count(n: int, word: str) -> str:\n    return f\"{n} {word}{'' if n == 1 else 's'}\"\n\n\ndef _summary(report: Report, verdict: str) -> str:\n    \"\"\"``REVIEW \u00b7 1 finding \u00b7 1 suppressed \u00b7 2 changes in 1 file``\"\"\"\n    return (f\"{verdict} \u00b7 {_count(len(report.findings), 'finding')}\"\n            + (f\" \u00b7 {report.suppressed} suppressed\" if report.suppressed else \"\")\n            + f\" \u00b7 {_count(len(report.changes), 'change')} in \"\n              f\"{_count(len(report.files_changed), 'file')}\")\n\n\ndef wants_colour(stream, environ=None) -> bool:\n    \"\"\"Colour only for a person at a terminal: never when ``NO_COLOR`` is set (no-color.org),\n    into a pipe or a file, or on a dumb terminal.\"\"\"\n    environ = os.environ if environ is None else environ\n    if environ.get(\"NO_COLOR\") or environ.get(\"TERM\") == \"dumb\":\n        return False\n    isatty = getattr(stream, \"isatty\", None)\n    if not (isatty and isatty()):\n        return False\n    return os.name != \"nt\" or _windows_console_colour()\n\n\ndef _windows_console_colour() -> bool:\n    \"\"\"Ask the Windows console to read colour codes (Windows 10 and later can); False when\n    it will not, so the codes are never printed as junk.\"\"\"\n    try:\n        import ctypes\n        kernel32 = ctypes.windll.kernel32\n        handle = kernel32.GetStdHandle(-11)                 # standard output\n        mode = ctypes.c_uint32()\n        if not kernel32.GetConsoleMode(handle, ctypes.byref(mode)):\n            return False\n        vt = 0x0004                                         # ENABLE_VIRTUAL_TERMINAL_PROCESSING\n        return bool(mode.value & vt or kernel32.SetConsoleMode(handle, mode.value | vt))\n    except (AttributeError, OSError, ValueError):\n        return False\n\n\ndef text(report: Report, max_changes: int = 12, max_affected: int = 10,\n         colour: bool = False) -> str:\n    verdict = report.verdict.upper()\n    if colour:\n        verdict = f\"\\033[{_COLOUR[report.verdict]}m{verdict}\\033[0m\"\n    lines = [f\"magellan-lite: {_summary(report, verdict)} (against {report.against})\"]\n\n    if report.changes:\n        lines += [\"\", \"  changes\"]\n        width = max(len(c.name) for c in report.changes[:max_changes])\n        for c in report.changes[:max_changes]:\n            lines.append(f\"    {_KIND[c.kind]:>4}  {c.name:<{width}}  {c.path}:{c.line}\")\n        if len(report.changes) > max_changes:\n            lines.append(f\"    ... and {len(report.changes) - max_changes} more\")\n\n    if report.affected:\n        lines += [\"\", f\"  reaches {_count(len(report.affected), 'definition')} the change \"\n                      f\"did not touch (score fades with distance)\"]\n        width = max(len(a[\"name\"]) for a in report.affected[:max_affected])\n        for i, a in enumerate(report.affected[:max_affected]):\n            lines.append(f\"    {a['score']:.2f}  {_count(a['hops'], 'hop'):<7} \"\n                         f\"{a['name']:<{width}}  {a['path']}:{a['line']}\")\n            if i < 3:\n                lines.append(f\"          because {a['why']}\")\n        if len(report.affected) > max_affected:\n            lines.append(f\"    ... and {len(report.affected) - max_affected} more\")\n\n    lines += [\"\", \"  checklist\"]\n    if not report.findings:\n        lines.append(\"    nothing to check in what this change touched\")\n    for f in report.findings:\n        lines.append(f\"    [ ] {f.severity.upper():<8} {f.rule}  {f.path}:{f.line}\")\n        lines.append(f\"        {f.message}\")\n        if f.detail:\n            lines.append(f\"        {f.detail}\")\n        if f.fix:\n            lines.append(f\"        fix: {f.fix}\")\n\n    if report.errors:\n        lines += [\"\", \"  not checked\"]\n        lines += [f\"    {e}\" for e in report.errors]\n    return \"\\n\".join(lines)\n\n\n_VERDICT_MEANS = {\n    \"block\": \"A blocking finding: as it stands, this change breaks something.\",\n    \"review\": \"Nothing blocking, but something here needs a person to look.\",\n    \"ok\": \"Nothing in what this change touched needs a person.\",\n}\n\n\ndef _md(s: str) -> str:\n    \"\"\"Plain text for markdown: `code spans` stay code; outside them, characters markdown\n    would read as formatting (``__init__`` turning bold, ``<x>`` vanishing) are escaped.\"\"\"\n    parts = s.split(\"`\")\n    if len(parts) % 2 == 0:                     # an unpaired backtick: no code spans at all\n        return re.sub(r\"([\\\\`*_<>\\[\\]])\", r\"\\\\\\1\", s)\n    return \"`\".join(re.sub(r\"([\\\\*_<>\\[\\]])\", r\"\\\\\\1\", p) if i % 2 == 0 else p\n                    for i, p in enumerate(parts))\n\n\ndef markdown(report: Report, max_changes: int = 30, max_affected: int = 15) -> str:\n    \"\"\"The report as GitHub markdown, to paste into a pull request: the checklist is a task\n    list, one ``- [ ]`` line per finding. The pull request bot\n    (.github/workflows/magellan-lite.yml) posts it as a comment.\"\"\"\n    lines = [f\"### Magellan Lite: {_summary(report, '**' + report.verdict.upper() + '**')}\",\n             \"\",\n             f\"{_VERDICT_MEANS[report.verdict]} Checked against `{report.against}`.\",\n             \"\"]\n\n    if not report.findings:\n        lines.append(\"Nothing to check in what this change touched.\")\n    for f in report.findings:\n        lines.append(f\"- [ ] **{f.severity.upper()}** `{f.path}:{f.line}` {_md(f.message)} \"\n                     f\"(`{f.rule}`)\")\n        if f.detail:\n            lines.append(f\"  - {_md(f.detail)}\")\n        if f.fix:\n            lines.append(f\"  - Fix: {_md(f.fix)}\")\n\n    def details(summary: str, body: list[str]) -> None:\n        lines.extend([\"\", f\"<details><summary>{summary}</summary>\", \"\", *body, \"\", \"</details>\"])\n\n    if report.changes:\n        body = [f\"- {c.kind} `{c.name}` in `{c.path}:{c.line}`\"\n                for c in report.changes[:max_changes]]\n        if len(report.changes) > max_changes:\n            body.append(f\"- ... and {len(report.changes) - max_changes} more\")\n        details(f\"What changed: {_count(len(report.changes), 'change')} in \"\n                f\"{_count(len(report.files_changed), 'file')}\", body)\n\n    if report.affected:\n        body = [f\"- `{a['name']}` in `{a['path']}:{a['line']}`, \"\n                f\"{_count(a['hops'], 'hop')} away: {_md(a.get('why', ''))}\"\n                for a in report.affected[:max_affected]]\n        if len(report.affected) > max_affected:\n            body.append(f\"- ... and {len(report.affected) - max_affected} more\")\n        details(f\"What it reaches: {_count(len(report.affected), 'definition')} the change \"\n                f\"did not touch\", body)\n\n    if report.errors:\n        details(f\"Not checked: {len(report.errors)}\", [f\"- {_md(e)}\" for e in report.errors])\n    return \"\\n\".join(lines)\n", "magellan_lite/plan.py": "\"\"\"Staged work for an AI agent: plan a change, follow its progress, confirm it is done.\n\n    magellan-lite plan [PATH] --edit FILE OLD NEW [--edit ...] | --edits EDITS.json\n    magellan-lite progress [PATH]\n    magellan-lite done [PATH]\n\nA plan is the check run on a change before it is made. The agent names the edits it intends,\neach ``{path, old, new}`` (usually the definition itself: the new signature line, the wider\nPIC). They are applied to the working tree in memory and checked against the last commit, and\nwhat the check finds becomes a worklist:\n\n- ``edit``: every other line that has to change, with the code as written there (a call split\n  over continuation lines comes whole; a call inside an INCLUDE file points at that file once,\n  with the routines that include it; a field a MOVE would truncate points at its PIC);\n- ``recompile``: programs that copy a copybook whose layout changes;\n- ``unchanged_uses``: code that uses what changes and needs nothing;\n- ``ruled_out``: mentions of the same names that are not uses (a comment, a local array,\n  another definition with the same or a similar name), each with the reason.\n\nSo an agent does not have to find it all again by hand, which is what agents given only\n``reach`` and ``check`` did in the modernization experiment (twice, once per language).\n\n``progress`` checks the working tree as it is now, with any planned edit not made yet applied\non top, so the order of the work does not matter: what is left. ``done`` says whether nothing\nis, and lists what a report needs. The plan is kept in the git directory, never in the working\ntree.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport difflib\nimport hashlib\nimport json\nimport re\nimport tempfile\nfrom pathlib import Path\n\nfrom magellan_lite.languages import _FIXED_FORM, language\n\n#: findings that are about rebuilding, not editing: they go in ``recompile``\nREBUILD = (\"copybook-layout-changed\", \"struct-layout-change\")\n#: lines of code shown per item at most\nCODE_LINES = 6\n#: ruled-out sites listed at most (the rest are counted)\nRULED_OUT = 40\n\n\nclass PlanError(ValueError):\n    \"\"\"An edit that cannot be placed, said plainly.\"\"\"\n\n\n# -- the edits ---------------------------------------------------------------------------------\n\ndef _place(text: str, old: str, path: str) -> tuple[int, str]:\n    \"\"\"Where ``old`` is in ``text`` (exactly once), and ``old`` with the file's line endings.\"\"\"\n    for o in (old, old.replace(\"\\n\", \"\\r\\n\")):\n        n = text.count(o) if o else 0\n        if n == 1:\n            return text.index(o), o\n        if n > 1:\n            raise PlanError(f\"the old text occurs {n} times in {path}: include more of the line \"\n                            f\"around it so it names one place\")\n    near = difflib.get_close_matches(old.strip().splitlines()[0] if old.strip() else \"\",\n                                     [l.strip() for l in text.splitlines()], n=3, cutoff=0.6)\n    raise PlanError(f\"the old text is not in {path}\"\n                    + (f\"; the closest lines are: {' | '.join(near)}\" if near else\n                       \": copy it from the file exactly, spaces included\"))\n\n\ndef apply(files: dict[str, str], edits: list[dict]) -> tuple[dict[str, str], list[dict]]:\n    \"\"\"The files with each edit made in memory, and where each edit landed.\"\"\"\n    out, placed = dict(files), []\n    for e in edits:\n        path = str(e.get(\"path\", \"\")).replace(\"\\\\\", \"/\").lstrip(\"./\") if e.get(\"path\") else \"\"\n        old, new = e.get(\"old\"), e.get(\"new\")\n        if not path or not isinstance(old, str) or not isinstance(new, str):\n            raise PlanError(\"each edit needs path, old and new (old: text in the file now, \"\n                            \"new: what replaces it)\")\n        if path not in out:\n            raise PlanError(f\"no source file {path} in this project (paths are relative to \"\n                            f\"its root, with forward slashes)\")\n        at, o = _place(out[path], old, path)\n        out[path] = out[path][:at] + (new.replace(\"\\n\", \"\\r\\n\") if o != old else new) + \\\n            out[path][at + len(o):]\n        line = out[path].count(\"\\n\", 0, at) + 1\n        placed.append({\"path\": path, \"line\": line, \"end_line\": line + new.count(\"\\n\"),\n                       \"old\": old, \"new\": new})\n    return out, placed\n\n\ndef _made(text: str, edit: dict) -> bool:\n    \"\"\"Is a planned edit in ``text`` already? (Text deleted: the old is gone; else the new is\n    there. An edit made some other way counts as made: the check judges the result.)\"\"\"\n    old, new = edit[\"old\"], edit[\"new\"]\n    if \"\\r\\n\" in text and \"\\r\\n\" not in old:      # the file's line endings, not the edit's\n        old, new = old.replace(\"\\n\", \"\\r\\n\"), new.replace(\"\\n\", \"\\r\\n\")\n    if new and new in old:\n        return old not in text\n    return new in text or old not in text\n\n\n# -- reading code --------------------------------------------------------------------------------\n\ndef _comment(line: str, path: str) -> bool:\n    lang, s = language(path) or \"python\", line.strip()\n    if lang == \"fortran\":\n        fixed = path.lower().endswith(_FIXED_FORM)\n        return (fixed and line[:1] in \"cC*!dD\") or s.startswith(\"!\")\n    if lang == \"cobol\":\n        return len(line) > 6 and line[6] in \"*/\"\n    if lang == \"python\":\n        return s.startswith(\"#\")\n    return s.startswith((\"//\", \"/*\", \"*\"))\n\n\ndef statement(lines: list[str], line: int, path: str) -> tuple[int, int]:\n    \"\"\"The first and last line (1-based) of the statement at ``line``: a Fortran call with its\n    continuation lines, a COBOL sentence up to its period, other code until brackets close.\"\"\"\n    i = max(0, min(line - 1, len(lines) - 1))\n    lang = language(path) or \"python\"\n    start = end = i\n    if lang == \"fortran\" and path.lower().endswith(_FIXED_FORM):\n        cont = lambda s: len(s) > 5 and s[:1] not in \"cC*!\" and s[5] not in \" 0\"   # noqa: E731\n        while start > 0 and cont(lines[start]):\n            start -= 1\n        while end + 1 < len(lines) and cont(lines[end + 1]):\n            end += 1\n    elif lang == \"fortran\":\n        while start > 0 and lines[start - 1].split(\"!\", 1)[0].rstrip().endswith(\"&\"):\n            start -= 1\n        while end + 1 < len(lines) and lines[end].split(\"!\", 1)[0].rstrip().endswith(\"&\"):\n            end += 1\n    elif lang == \"cobol\":\n        while end + 1 < len(lines) and end < i + 5 and not lines[end].rstrip().endswith(\".\"):\n            end += 1\n    else:\n        depth = 0\n        for j in range(i, min(len(lines), i + 10)):\n            depth += sum(lines[j].count(c) for c in \"([{\") - sum(lines[j].count(c) for c in \")]}\")\n            end = j\n            if depth <= 0:\n                break\n    return start + 1, end + 1\n\n\ndef _code(lines: list[str], first: int, last: int) -> list[str]:\n    return [lines[n - 1].rstrip() for n in range(first, min(last, first + CODE_LINES - 1) + 1)]\n\n\ndef _name_re(name: str, path: str) -> re.Pattern:\n    \"\"\"``name`` as a whole word: COBOL words carry hyphens; Fortran and COBOL ignore case.\"\"\"\n    lang = language(path)\n    edge = r\"[\\w-]\" if lang == \"cobol\" else r\"\\w\"\n    return re.compile(rf\"(?<!{edge}){re.escape(name)}(?!{edge})\",\n                      re.I if lang in (\"fortran\", \"cobol\") else 0)\n\n\n# -- the worklist ----------------------------------------------------------------------------------\n\ndef _site(path: str, first: int, last: int) -> str:\n    return f\"{path}:{first}\" + (f\"-{last}\" if last > first else \"\")\n\n\ndef _include_target(snapshot, path: str, text: str) -> str | None:\n    \"\"\"The file a Fortran ``INCLUDE 'x'`` (or C ``#include \"x\"``) line names, if it is here.\"\"\"\n    m = re.search(r\"\"\"^\\s*(?:INCLUDE|#\\s*include)\\s*['\"<]([^'\">]+)['\">]\"\"\", text, re.I)\n    if not m:\n        return None\n    base = m.group(1).replace(\"\\\\\", \"/\").rsplit(\"/\", 1)[-1].lower()\n    found = sorted(p for p in snapshot.files if p.rsplit(\"/\", 1)[-1].lower() == base)\n    if len(found) > 1:                     # the one nearest the including file\n        here = path.rsplit(\"/\", 1)[0]\n        found.sort(key=lambda p: (not p.startswith(here), len(p)))\n    return found[0] if found else None\n\n\ndef _edit_items(report, after, targets: list) -> tuple[list[dict], list[dict], list[dict]]:\n    \"\"\"``(edit, recompile, notes)`` from a check's findings.\"\"\"\n    edit: dict[str, dict] = {}\n    recompile, notes = [], []\n    names = {d.short.split(\"(\", 1)[0] for d in targets} | {(d.label or \"\").split(\"(\", 1)[0]\n                                                           for d in targets}\n    names.discard(\"\")\n    for f in report.findings:\n        if f.rule in REBUILD:\n            m = re.search(r\"Copied by (\\d+) program\\(s\\): (.*?)\\.?$\", f.detail or \"\")\n            recompile.append({\"where\": f\"{f.path}:{f.line}\", \"what\": f.message,\n                              \"programs\": m.group(2).split(\", \") if m else []})\n            continue\n        if f.severity not in (\"critical\", \"high\"):\n            notes.append({\"where\": f\"{f.path}:{f.line}\", \"rule\": f.rule, \"what\": f.message})\n            continue\n        lines = after.files.get(f.path, \"\").splitlines()\n        reason = f.message.split(\": \", 1)[1].split(\" -- \")[0] if \": \" in f.message else f.message\n        item = {\"where\": \"\", \"rule\": f.rule, \"what\": f.message, \"code\": [], \"fix\": f.fix,\n                \"group\": f\"{f.rule}: {reason}\", \"note\": \"\"}\n        if \"procedure argument\" in f.message:\n            item[\"note\"] = (f.detail or \"\").split(\". \", 1)[0]\n        first, last = statement(lines, f.line, f.path)\n        m = re.match(r\"MOVE (\\S+) TO (\\S+) now drops\", f.message)\n        inc = _include_target(after, f.path, lines[f.line - 1]) if 0 < f.line <= len(lines) \\\n            else None\n        if m and f.rule == \"move-truncates\":\n            # the work is at the receiving field's PIC, not at the MOVE\n            decl = _declaration(after, f.path, m.group(2))\n            if decl:\n                path, line = decl\n                dl = after.files[path].splitlines()\n                item.update(where=_site(path, line, line), code=_code(dl, line, line),\n                            moved_at=f\"{f.path}:{f.line}\")\n                need = re.search(r\"holds (\\d+) (digits|bytes)\", f.detail or \"\")\n                if need:\n                    item[\"needs\"] = f\"at least {need.group(1)} integer {need.group(2)}\" \\\n                        if need.group(2) == \"digits\" else f\"at least {need.group(1)} bytes\"\n                    item[\"group\"] = f\"{f.rule}: widen to {item['needs']}\"\n                drops = f.message.split(\" now \", 1)[-1]\n                item[\"note\"] = f\"MOVE {m.group(1)} TO {m.group(2)} at {f.path}:{f.line} {drops}\"\n                key = item[\"where\"]\n            else:\n                item.update(where=_site(f.path, first, last), code=_code(lines, first, last))\n                key = item[\"where\"]\n        elif inc:\n            # the call is inside the INCLUDE file: change it there, once, for every includer\n            il = after.files[inc].splitlines()\n            # the name the finding says is called, as well as the plan's own names\n            called = re.match(r\"\\S+ calls (\\S+?) (?:the old way|through)\", f.message)\n            want = names | ({called.group(1).rsplit(\".\", 1)[-1]} if called else set())\n            hit = next((n for n, l in enumerate(il, 1) if not _comment(l, inc)\n                        and any(_name_re(x, inc).search(l) for x in want)), None)\n            if hit is None:\n                item.update(where=_site(f.path, first, last), code=_code(lines, first, last))\n                key = item[\"where\"]\n            else:\n                a, b = statement(il, hit, inc)\n                key = _site(inc, a, b)\n                if key in edit:\n                    edit[key][\"included_by\"].append(f\"{f.path}:{f.line}\")\n                    continue\n                item.update(where=key, code=_code(il, a, b), included_by=[f\"{f.path}:{f.line}\"],\n                            what=f\"inside {inc}, which {f.path} includes at line {f.line}: \"\n                                 + f.message.split(\" -- \")[0])\n        else:\n            item.update(where=_site(f.path, first, last), code=_code(lines, first, last))\n            key = item[\"where\"]\n        if key not in edit:\n            edit[key] = item\n    return list(edit.values()), recompile, notes\n\n\ndef _declaration(snapshot, path: str, field: str) -> tuple[str, int] | None:\n    \"\"\"Where a COBOL field is declared (its level number and PIC): the program, else the one\n    copybook that declares it.\"\"\"\n    pat = re.compile(rf\"^\\s*\\d+\\s+{re.escape(field)}(?![\\w-]).*\\bPIC\", re.I)\n    for p in [path] + sorted(p for p in snapshot.files if p != path):\n        for n, l in enumerate(snapshot.files[p].splitlines(), 1):\n            if pat.search(l) and not _comment(l, p):\n                return p, n\n    return None\n\n\ndef _unchanged_uses(report, graph, after_defs, edit: list[dict]) -> list[dict]:\n    \"\"\"Code that uses what the change changes and needs nothing (copybook users are in\n    ``recompile``).\"\"\"\n    covered = set()\n    for item in edit:\n        path, span = item[\"where\"].rsplit(\":\", 1)\n        a, _, b = span.partition(\"-\")\n        covered |= {(path, n) for n in range(int(a), int(b or a) + 1)}\n        for site in item.get(\"included_by\", []) + [item.get(\"moved_at\", \"\")]:\n            if site:\n                p, n = site.rsplit(\":\", 1)\n                covered.add((p, int(n)))\n    out, seen = [], set()\n    for c in report.changes:\n        d = after_defs.get(c.name)\n        if d is None or (d.lang == \"cobol\" and d.kind == \"class\"):\n            continue\n        for e in graph.callers(c.name):\n            if (e.path, e.line) in covered or (e.path, e.line, c.name) in seen:\n                continue\n            seen.add((e.path, e.line, c.name))\n            out.append({\"where\": f\"{e.path}:{e.line}\", \"who\": e.src, \"uses\": c.name,\n                        \"how\": e.kind + (\" (a guess)\" if e.guess else \"\")})\n    return sorted(out, key=lambda x: x[\"where\"])\n\n\ndef _ruled_out(after, graph, after_defs, targets: list, sites: set,\n               copying: set[str]) -> tuple[list[dict], int]:\n    \"\"\"Mentions of each target's name that are not uses of it, grouped by why. ``copying``:\n    the files of the programs that copy a changed copybook.\"\"\"\n    by_site: dict[tuple[str, int], list[str]] = {}\n    for e in graph.edges:\n        by_site.setdefault((e.path, e.line), []).append(e.dst)\n    reasons: dict[str, list[str]] = {}\n    for d in targets:\n        name = (d.label or d.short).split(\"(\", 1)[0]\n        shown = name.upper() if d.lang in (\"fortran\", \"cobol\") else name\n        same = {n for n, x in after_defs.items() if n != d.name and\n                (x.label or x.short).split(\"(\", 1)[0].lower() == name.lower()}\n        book = re.match(r\"cobol@copy:([^.]+)\\.\", d.name)\n        for path, text in sorted(after.files.items()):\n            pat = _name_re(name, path)\n            if not pat.search(text):\n                continue\n            lines = text.splitlines()\n            local = _local_declaration(lines, name, path)\n            for n, l in enumerate(lines, 1):\n                if not pat.search(l) or (path, n) in sites or \\\n                        (path == d.path and d.line <= n <= d.end_line and not _comment(l, path)):\n                    continue\n                others = [x for x in by_site.get((path, n), []) if x in same] + \\\n                    [x for x in same if after_defs[x].path == path and\n                     after_defs[x].line <= n <= after_defs[x].end_line]\n                if d.name in by_site.get((path, n), []):\n                    continue                          # a use: listed elsewhere\n                if others:\n                    o = after_defs[others[0]]\n                    why = f\"a different {shown}: {o.name} ({o.path}:{o.line})\"\n                elif _comment(l, path):\n                    why = \"a comment\"\n                elif local:\n                    why = (f\"a local variable or array named {shown}, not the \"\n                           f\"{'routine' if d.lang == 'fortran' else d.kind}\")\n                elif d.lang == \"fortran\" and re.match(r\"\\s*EXTERNAL\\b\", l, re.I):\n                    why = (f\"EXTERNAL {shown}: it is passed as an argument there (the calls \"\n                           f\"made through it are in edit)\")\n                elif book and language(path) == \"cobol\" and path not in copying \\\n                        and not path.lower().endswith((\".cpy\", \".dcl\")):\n                    why = f\"in a program that does not copy {book.group(1)}\"\n                else:\n                    why = f\"no reference to {d.name} is read here\"\n                reasons.setdefault(why, []).append(f\"{path}:{n}\")\n        # definitions with a similar name, so nobody has to check they are different\n        labels = {(x.label or x.short).split(\"(\", 1)[0]: x for x in after_defs.values()\n                  if x.lang == d.lang and x.name != d.name}\n        close = set(difflib.get_close_matches(name, list(labels), n=8, cutoff=0.8))\n        close |= {l for l in labels if l.lower().startswith(name.lower() + \"-\")}\n        for l in sorted(close):\n            x = labels[l]\n            if x.name not in same:                    # those are among the mentions above\n                reasons.setdefault(\"a different definition with a similar name (not changed)\",\n                                   []).append(f\"{x.path}:{x.line} \"\n                                              + (l.upper() if x.lang in (\"fortran\", \"cobol\") else l))\n    out, total = [], sum(len(v) for v in reasons.values())\n    shown = 0\n    for why, where in sorted(reasons.items(), key=lambda kv: (-len(kv[1]), kv[0])):\n        keep = where[:max(3, RULED_OUT - shown)]\n        shown += len(keep)\n        out.append({\"why\": why, \"count\": len(where), \"where\": keep})\n    return out, max(0, total - shown)\n\n\ndef _local_declaration(lines: list[str], name: str, path: str) -> int | None:\n    \"\"\"The line declaring a Fortran local (``REAL INTRST(12)``) named ``name``, if any.\"\"\"\n    if language(path) != \"fortran\":\n        return None\n    pat = re.compile(r\"^\\s*(REAL|INTEGER|DOUBLE\\s+PRECISION|LOGICAL|CHARACTER|COMPLEX|DIMENSION)\"\n                     rf\"\\b[^!]*(?<!\\w){re.escape(name)}(?!\\w)\", re.I)\n    return next((n for n, l in enumerate(lines, 1) if not _comment(l, path) and pat.search(l)),\n                None)\n\n\ndef _coverage(snapshot, report) -> dict:\n    from magellan_lite.languages import NAMES\n    counts: dict[str, int] = {}\n    for p in snapshot.files:\n        lang = NAMES.get(language(p) or \"python\", \"Python\")\n        counts[lang] = counts.get(lang, 0) + 1\n    return {\"files\": len(snapshot.files), \"by_language\": dict(sorted(counts.items())),\n            \"not_read\": report.errors}\n\n\n# -- the stages ------------------------------------------------------------------------------------\n\ndef _store(root: Path) -> Path:\n    \"\"\"Where a project's plan is kept: its git directory, else the temp folder.\"\"\"\n    git = root / \".git\"\n    if git.is_dir():\n        return git / \"magellan-lite\" / \"plan.json\"\n    key = hashlib.sha1(str(root).encode()).hexdigest()[:16]\n    return Path(tempfile.gettempdir()) / \"magellan-lite-plans\" / f\"{key}.json\"\n\n\ndef _run(root: Path, against: str, edits: list[dict]):\n    \"\"\"Check the working tree with ``edits`` made in memory: ``(report, after, graph, defs,\n    placed)``.\"\"\"\n    from magellan_lite.defs import definitions\n    from magellan_lite.engine import check_snapshots, load_before\n    from magellan_lite.graph import build_graph\n    from magellan_lite.source import Snapshot, working_tree\n\n    now = working_tree(root)\n    files, placed = apply(now.files, edits)\n    after = Snapshot(files, \"plan\")\n    before = load_before(root, against)\n    report = check_snapshots(before, after, root, against)\n    after_defs = definitions(after)\n    graph = build_graph(after, after_defs, definitions(before))\n    return report, after, graph, after_defs, placed\n\n\ndef _targets(after_defs, placed: list[dict]) -> list:\n    \"\"\"The innermost definition each edit lands in.\"\"\"\n    out = []\n    for p in placed:\n        here = [d for d in after_defs.values()\n                if d.path == p[\"path\"] and d.line <= p[\"end_line\"] and p[\"line\"] <= d.end_line]\n        if here:\n            d = min(here, key=lambda d: d.end_line - d.line)\n            if d not in out:\n                out.append(d)\n    return out\n\n\ndef plan(root: str | Path, edits: list[dict], against: str = \"git:HEAD\", save: bool = True) -> dict:\n    \"\"\"The worklist for ``edits`` (see the module's docstring).\"\"\"\n    root = Path(root).resolve()\n    if not edits:\n        raise PlanError(\"plan needs the edits you intend: a list of {path, old, new}\")\n    report, after, graph, after_defs, placed = _run(root, against, edits)\n    targets = _targets(after_defs, placed)\n    edit, recompile, notes = _edit_items(report, after, targets)\n    uses = _unchanged_uses(report, graph, after_defs, edit)\n    sites = {(u[\"where\"].rsplit(\":\", 1)[0], int(u[\"where\"].rsplit(\":\", 1)[1])) for u in uses}\n    for item in edit:\n        path, span = item[\"where\"].rsplit(\":\", 1)\n        a, _, b = span.partition(\"-\")\n        sites |= {(path, n) for n in range(int(a), int(b or a) + 1)}\n        for s in item.get(\"included_by\", []) + [item.get(\"moved_at\", \"\")]:\n            if s:\n                sites.add((s.rsplit(\":\", 1)[0], int(s.rsplit(\":\", 1)[1])))\n    progs = {p for r in recompile for p in r[\"programs\"]}\n    copying = {d.path for d in after_defs.values()\n               if d.lang == \"cobol\" and d.name.split(\"@\", 1)[-1] in progs}\n    ruled, more = _ruled_out(after, graph, after_defs, targets, sites, copying)\n    out = {\n        \"stage\": \"plan\",\n        \"summary\": _summary(edit, recompile, uses, ruled),\n        \"planned\": [{\"where\": _site(p[\"path\"], p[\"line\"], p[\"end_line\"]),\n                     \"changes\": [d.name for d in targets if d.path == p[\"path\"]\n                                 and d.line <= p[\"end_line\"] and p[\"line\"] <= d.end_line]}\n                    for p in placed],\n        \"edit\": edit, \"recompile\": recompile, \"unchanged_uses\": uses,\n        \"ruled_out\": ruled, \"ruled_out_omitted\": more, \"notes\": notes,\n        \"coverage\": _coverage(after, report),\n        \"next\": \"Make the planned edits and every edit item (in any order), then call \"\n                \"progress; when it says nothing is left, call done.\",\n    }\n    if save:\n        store = _store(root)\n        store.parent.mkdir(parents=True, exist_ok=True)\n        store.write_text(json.dumps({\"against\": against, \"edits\": [\n            {k: p[k] for k in (\"path\", \"old\", \"new\")} for p in placed],\n            \"edit\": [{k: i[k] for k in (\"where\", \"rule\", \"what\")} for i in edit],\n            \"recompile\": recompile}, indent=1), encoding=\"utf-8\")\n    return out\n\n\ndef _summary(edit, recompile, uses, ruled) -> str:\n    files = len({i[\"where\"].rsplit(\":\", 1)[0] for i in edit})\n    parts = [f\"{len(edit)} place{'s' if len(edit) != 1 else ''} to change in \"\n             f\"{files} file{'s' if files != 1 else ''}\" if edit else \"nothing else to change\"]\n    progs = sorted({p for r in recompile for p in r[\"programs\"]})\n    if progs:\n        parts.append(f\"{len(progs)} program{'s' if len(progs) != 1 else ''} to recompile\")\n    if uses:\n        parts.append(f\"{len(uses)} use{'s' if len(uses) != 1 else ''} that need nothing\")\n    n = sum(r[\"count\"] for r in ruled)\n    if n:\n        parts.append(f\"{n} mention{'s' if n != 1 else ''} ruled out\")\n    return \"; \".join(parts) + \".\"\n\n\ndef _saved(root: Path) -> dict:\n    store = _store(root)\n    if not store.is_file():\n        raise PlanError(\"no plan for this project yet: call plan first with the edits you intend\")\n    return json.loads(store.read_text(encoding=\"utf-8\"))\n\n\ndef progress(root: str | Path) -> dict:\n    \"\"\"What is left of the plan: the working tree now, planned edits not made yet applied.\"\"\"\n    root = Path(root).resolve()\n    saved = _saved(root)\n    from magellan_lite.source import working_tree\n    now = working_tree(root).files\n    pending = [e for e in saved[\"edits\"] if e[\"path\"] in now and not _made(now[e[\"path\"]], e)]\n    report, after, graph, after_defs, placed = _run(root, saved[\"against\"], pending)\n    edit, recompile, notes = _edit_items(report, after, _targets(after_defs, placed))\n    planned = len(saved[\"edit\"])\n    left = [i for i in edit]\n    out = {\n        \"stage\": \"progress\",\n        \"done\": not pending and not left,\n        \"summary\": (f\"planned edits: {len(saved['edits']) - len(pending)} of \"\n                    f\"{len(saved['edits'])} made; places to change: {len(left)} left\"\n                    + (f\" (the plan listed {planned})\" if planned else \"\") + \".\"),\n        \"planned_not_made\": [{\"where\": _site(p[\"path\"], p[\"line\"], p[\"end_line\"]),\n                              \"new\": p[\"new\"]} for p in placed],\n        \"left\": left, \"recompile\": recompile, \"notes\": notes,\n        \"not_read\": report.errors,\n        \"next\": (\"Nothing is left: call done.\" if not pending and not left else\n                 \"Change what is left, then call progress again.\"),\n    }\n    return out\n\n\ndef done(root: str | Path) -> dict:\n    \"\"\"Is the plan finished? If so, what a report needs: every line changed, and each item the\n    plan listed; if not, what is left.\"\"\"\n    root = Path(root).resolve()\n    out = progress(root)\n    saved = _saved(root)\n    if not out[\"done\"]:\n        out[\"stage\"] = \"done\"\n        out[\"next\"] = \"Not done: change what is left (left, planned_not_made), then call done again.\"\n        return out\n    from magellan_lite.engine import load_before\n    from magellan_lite.source import working_tree\n    before, now = load_before(root, saved[\"against\"]).files, working_tree(root).files\n    changed = {}\n    for path in sorted(set(before) | set(now)):\n        a, b = before.get(path, \"\").splitlines(), now.get(path, \"\").splitlines()\n        if a == b:\n            continue\n        lines = [j + 1 for tag, _, _, j1, j2 in difflib.SequenceMatcher(None, a, b).get_opcodes()\n                 if tag != \"equal\" for j in range(j1, j2)]\n        changed[path] = _ranges(lines) if lines else \"deleted lines only\"\n    return {\n        \"stage\": \"done\", \"done\": True,\n        \"summary\": (f\"Done: every planned edit made and nothing left to change; \"\n                    f\"{len(changed)} file{'s' if len(changed) != 1 else ''} changed.\"),\n        \"changed\": changed,\n        \"planned_items\": saved[\"edit\"],\n        \"recompile\": out[\"recompile\"], \"notes\": out[\"notes\"], \"not_read\": out[\"not_read\"],\n        \"next\": \"Run the project's own tests or build if it has them; behaviour is not checked \"\n                \"by reading code.\",\n    }\n\n\ndef _ranges(nums: list[int]) -> str:\n    out, start, prev = [], None, None\n    for n in sorted(set(nums)):\n        if start is None:\n            start = prev = n\n        elif n == prev + 1:\n            prev = n\n        else:\n            out.append(f\"{start}-{prev}\" if prev > start else str(start))\n            start = prev = n\n    if start is not None:\n        out.append(f\"{start}-{prev}\" if prev > start else str(start))\n    return \",\".join(out)\n\n\n# -- text --------------------------------------------------------------------------------------------\n\ndef text(result: dict) -> str:\n    \"\"\"The same, for a terminal or an agent that reads text.\"\"\"\n    out = [f\"magellan-lite {result['stage']}: {result['summary']}\"]\n    if result.get(\"planned\"):\n        out.append(\"  planned (applied in memory)\")\n        out += [f\"     {p['where']}  {', '.join(p['changes'])}\" for p in result[\"planned\"]]\n    if result.get(\"planned_not_made\"):\n        out.append(\"  planned, not made yet\")\n        out += [f\"     {p['where']}\" for p in result[\"planned_not_made\"]]\n    items = result.get(\"edit\", result.get(\"left\", []))\n    if items:\n        out.append(f\"  {'edit' if result['stage'] == 'plan' else 'left'} ({len(items)})\")\n        groups: dict[str, list[dict]] = {}\n        for i in items:\n            groups.setdefault(i.get(\"group\") or i[\"rule\"], []).append(i)\n        for g, members in groups.items():\n            out.append(f\"    {g}  [{len(members)}]\")\n            for i in members:\n                note = i.get(\"note\") or (f\"included by {', '.join(i['included_by'])}\"\n                                         if i.get(\"included_by\") else \"\")\n                if len(i[\"code\"]) == 1 and not note:\n                    out.append(f\"      {i['where']:<26} |{i['code'][0]}\")\n                    continue\n                out.append(f\"      {i['where']}\" + (f\"  ({note})\" if note else \"\"))\n                out += [f\"      {'':<26} |{c}\" for c in i[\"code\"]]\n    for r in result.get(\"recompile\", []):\n        out.append(f\"  recompile ({r['where']}): {', '.join(r['programs']) or r['what']}\")\n    if result.get(\"unchanged_uses\"):\n        out.append(\"  uses that need nothing\")\n        out += [f\"     {u['where']}  {u['who']} {u['how']} {u['uses']}\"\n                for u in result[\"unchanged_uses\"]]\n    if result.get(\"ruled_out\"):\n        out.append(\"  ruled out (mention the name, not a use)\")\n        out += [f\"     {r['why']}: {', '.join(r['where'])}\"\n                + (f\" (+{r['count'] - len(r['where'])})\" if r[\"count\"] > len(r[\"where\"]) else \"\")\n                for r in result[\"ruled_out\"]]\n    if result.get(\"changed\"):\n        out.append(\"  changed\")\n        out += [f\"     {p}: {lines}\" for p, lines in result[\"changed\"].items()]\n    for n in result.get(\"notes\", [])[:8]:\n        out.append(f\"  note {n['where']}  {n['rule']}: {n['what']}\")\n    cov = result.get(\"coverage\")\n    if cov:\n        langs = \", \".join(f\"{k} {v}\" for k, v in cov[\"by_language\"].items())\n        out.append(f\"  read {cov['files']} files ({langs})\"\n                   + (f\"; not read: {'; '.join(cov['not_read'])}\" if cov[\"not_read\"] else\n                      \"; every file read\"))\n    elif result.get(\"not_read\"):\n        out.append(f\"  not read: {'; '.join(result['not_read'])}\")\n    out.append(f\"  next: {result['next']}\")\n    return \"\\n\".join(out)\n", "magellan_lite/polyglot/__init__.py": "\"\"\"The other languages: C, C++, Java, Fortran, COBOL and TypeScript/JavaScript.\n\nVendored from the full Magellan (commit 66387d3 and its work in progress at the time),\nwith its imports pointed here. Magellan Lite uses it through ``magellan_lite/languages.py``,\nwhich runs each language's frontend on a snapshot and turns what it finds into Lite's\ndefinitions, call edges and findings. Fix bugs in the full Magellan first, then copy them\nhere: this copy is not where those parsers are developed.\n\nStandard library only, like the rest of Lite. C++ also needs libclang (``pip install\nlibclang``), and TypeScript/JavaScript Node.js with the ``typescript`` package; without them\nthose two languages are skipped, and so are they in the browser.\n\"\"\"\n\n__version__ = \"0.1.0\"\n\nfrom magellan_lite.polyglot.core.model import Edge, EdgeKind, Graph, Node, NodeKind\n\n__all__ = [\"Edge\", \"EdgeKind\", \"Graph\", \"Node\", \"NodeKind\", \"__version__\"]\n", "magellan_lite/polyglot/core/__init__.py": "\"\"\"Language-neutral core: the graph model, edge conventions, hashing, layer labels,\npropagation, diffing and findings. Nothing here knows which language produced a graph.\"\"\"\n", "magellan_lite/polyglot/core/model.py": "\"\"\"The Magellan graph: node kinds, edge kinds, and the container that holds them.\n\nIdentity convention\n-------------------\nEvery node has a string id of the form ``<kind-prefix>:<dotted.path>``. The\nprefix makes ids self-describing and keeps namespaces from colliding (a class\n``Config`` and a global ``Config`` in the same module are different nodes).\n\n    pkg:app.services              package\n    mod:app.services.billing      module\n    cls:app.services.billing.Ledger\n    fn:app.services.billing.charge            module-level function\n    fn:app.services.billing.Ledger.post       method (same prefix, longer path)\n    var:app.services.billing.RETRY_LIMIT      module global\n    attr:app.services.billing.Ledger.rate     class attribute\n    iattr:app.services.billing.Ledger.entries instance attribute (self.entries)\n    loc:app.services.billing.charge.total     local variable\n    par:app.services.billing.charge.amount    parameter\n    ali:app.services.billing.Decimal          name bound by an import\n    ext:requests.get                          outside the analyzed project\n\nIds are stable across line-number changes, which is what lets the differ tell\n\"this function moved\" from \"this function changed\".\n\"\"\"\n\nfrom __future__ import annotations\n\nimport enum\nimport hashlib\nimport json\nfrom dataclasses import dataclass, field\nfrom typing import Any, Iterable, Iterator\n\n\nclass NodeKind(str, enum.Enum):\n    PACKAGE = \"package\"\n    MODULE = \"module\"\n    CLASS = \"class\"\n    FUNCTION = \"function\"\n    METHOD = \"method\"\n    GLOBAL = \"global_var\"\n    CLASS_ATTR = \"class_attr\"\n    INSTANCE_ATTR = \"instance_attr\"\n    LOCAL = \"local_var\"\n    PARAMETER = \"parameter\"\n    IMPORT_ALIAS = \"import_alias\"\n    EXTERNAL = \"external\"\n\n    @property\n    def prefix(self) -> str:\n        return _KIND_PREFIX[self]\n\n    @property\n    def is_callable(self) -> bool:\n        return self in (NodeKind.FUNCTION, NodeKind.METHOD)\n\n    @property\n    def is_container(self) -> bool:\n        \"\"\"Containers own other nodes and get a 'shell' hash rather than a body hash.\"\"\"\n        return self in (NodeKind.PACKAGE, NodeKind.MODULE, NodeKind.CLASS)\n\n    @property\n    def is_data(self) -> bool:\n        return self in (\n            NodeKind.GLOBAL,\n            NodeKind.CLASS_ATTR,\n            NodeKind.INSTANCE_ATTR,\n            NodeKind.LOCAL,\n            NodeKind.PARAMETER,\n        )\n\n\n_KIND_PREFIX: dict[NodeKind, str] = {\n    NodeKind.PACKAGE: \"pkg\",\n    NodeKind.MODULE: \"mod\",\n    NodeKind.CLASS: \"cls\",\n    NodeKind.FUNCTION: \"fn\",\n    NodeKind.METHOD: \"fn\",\n    NodeKind.GLOBAL: \"var\",\n    NodeKind.CLASS_ATTR: \"attr\",\n    NodeKind.INSTANCE_ATTR: \"iattr\",\n    NodeKind.LOCAL: \"loc\",\n    NodeKind.PARAMETER: \"par\",\n    NodeKind.IMPORT_ALIAS: \"ali\",\n    NodeKind.EXTERNAL: \"ext\",\n}\n\n\ndef make_id(kind: NodeKind, qualname: str) -> str:\n    return f\"{kind.prefix}:{qualname}\"\n\n\nclass EdgeKind(str, enum.Enum):\n    \"\"\"Relations between nodes. See :mod:`magellan_lite.polyglot.core.edges` for the propagation table.\"\"\"\n\n    # --- structural: who owns whom -------------------------------------\n    CONTAINS = \"contains\"          # module -> class, class -> method, fn -> local\n    PARAM_OF = \"param_of\"          # parameter -> function\n\n    # --- linkage: how names reach across modules ------------------------\n    IMPORTS = \"imports\"            # module -> module\n    BINDS = \"binds\"                # import alias -> the thing it names\n    REEXPORTS = \"reexports\"        # module -> symbol it republishes via __all__\n\n    # --- type: the shape contract ---------------------------------------\n    INHERITS = \"inherits\"          # class -> base class\n    OVERRIDES = \"overrides\"        # method -> method it shadows in an ancestor\n    ANNOTATES = \"annotates\"        # function/var -> class named in its annotation\n\n    # --- control: who runs whom -----------------------------------------\n    CALLS = \"calls\"                # callable -> callable\n    INSTANTIATES = \"instantiates\"  # callable -> class\n    DECORATES = \"decorates\"        # decorator callable -> decorated node\n    RAISES = \"raises\"              # callable -> exception class\n    HANDLES = \"handles\"            # callable -> exception class it catches\n\n    # --- data: who touches which state ----------------------------------\n    READS = \"reads\"                # callable -> variable/attribute\n    WRITES = \"writes\"              # callable -> variable/attribute it rebinds\n    MUTATES = \"mutates\"            # callable -> variable/attribute it mutates in place\n    ASSIGNS_FROM = \"assigns_from\"  # variable -> callable whose result it holds\n\n    # --- lifecycle: resources ------------------------------------------\n    ACQUIRES = \"acquires\"          # callable -> resource-producing callable\n    RELEASES = \"releases\"          # callable -> resource-closing callable\n\n\n@dataclass\nclass Node:\n    id: str\n    kind: NodeKind\n    name: str\n    qualname: str\n    module: str\n    path: str = \"\"\n    lineno: int = 0\n    end_lineno: int = 0\n    col: int = 0\n\n    parent: str | None = None\n    signature: str | None = None\n    bases: list[str] = field(default_factory=list)\n    decorators: list[str] = field(default_factory=list)\n    public: bool = True\n\n    # systems-design labelling, consumed by the UI (see magellan_lite.polyglot.core.taxonomy)\n    layer: str = \"unknown\"\n    data_role: str = \"unknown\"\n    tags: list[str] = field(default_factory=list)\n    evidence: list[str] = field(default_factory=list)\n\n    # change detection\n    sig_hash: str = \"\"\n    body_hash: str = \"\"\n    doc_hash: str = \"\"\n\n    meta: dict[str, Any] = field(default_factory=dict)\n\n    @property\n    def label(self) -> str:\n        \"\"\"Short human label, e.g. ``billing.Ledger.post``.\"\"\"\n        return self.qualname\n\n    @property\n    def location(self) -> str:\n        return f\"{self.path}:{self.lineno}\" if self.path else self.module\n\n    def to_dict(self) -> dict[str, Any]:\n        d = dict(self.__dict__)\n        d[\"kind\"] = self.kind.value\n        return d\n\n    @staticmethod\n    def from_dict(d: dict[str, Any]) -> Node:\n        d = dict(d)\n        d[\"kind\"] = NodeKind(d[\"kind\"])\n        return Node(**d)\n\n\n#: Edge kinds whose every occurrence is a distinct site with its own data.\n_PER_SITE_KINDS = frozenset({EdgeKind.CALLS, EdgeKind.INSTANTIATES})\n\n\n@dataclass\nclass Edge:\n    src: str\n    dst: str\n    kind: EdgeKind\n    lineno: int = 0\n    path: str = \"\"\n    # 1.0 = statically certain; lower when we inferred it by duck typing etc.\n    confidence: float = 1.0\n    # True when the relation only fires on some paths (inside if/try/loop).\n    conditional: bool = False\n    # True when the target was reached through dynamic machinery (getattr, **kwargs).\n    dynamic: bool = False\n    context: str = \"\"\n    meta: dict[str, Any] = field(default_factory=dict)\n    #: Column of the expression. Part of the identity of call-shaped edges only: two\n    #: calls on one line (`f(\"a\") + f(\"b\")`) are two call sites with different\n    #: arguments, and collapsing them lost the second one's literals -- which let\n    #: value-domain analysis call a live branch impossible.\n    col: int = 0\n\n    @property\n    def key(self) -> tuple[str, str, str, int, int]:\n        col = self.col if self.kind in _PER_SITE_KINDS else 0\n        return (self.src, self.dst, self.kind.value, self.lineno, col)\n\n    def to_dict(self) -> dict[str, Any]:\n        d = dict(self.__dict__)\n        d[\"kind\"] = self.kind.value\n        return d\n\n    @staticmethod\n    def from_dict(d: dict[str, Any]) -> Edge:\n        d = dict(d)\n        d[\"kind\"] = EdgeKind(d[\"kind\"])\n        return Edge(**d)\n\n\n@dataclass\nclass FileRecord:\n    \"\"\"One analyzed source file. ``sha256`` is the cheap first-pass change filter.\"\"\"\n\n    path: str\n    module: str\n    sha256: str\n    lines: int = 0\n    source_root: str = \"\"\n    parse_error: str | None = None\n\n    def to_dict(self) -> dict[str, Any]:\n        return dict(self.__dict__)\n\n    @staticmethod\n    def from_dict(d: dict[str, Any]) -> FileRecord:\n        return FileRecord(**d)\n\n\ndef _fold(a: str, b: str) -> str:\n    return hashlib.sha256(f\"{a}|{b}\".encode()).hexdigest()[:16]\n\n\ndef _merge_redefinition(existing: Node, node: Node) -> None:\n    \"\"\"Fold a second definition of the same name into the first.\n\n    The same id is defined more than once by ``@overload`` stubs followed by the\n    implementation, ``@property`` plus ``@x.setter``, and ``if``/``else`` or\n    ``try``/``except ImportError`` alternatives. Keeping only the first meant the\n    code that actually runs -- the overload implementation, the setter -- had no\n    hash at all, so editing it produced no change and a clean verdict.\n\n    Every definition's hashes are folded in, in source order, so an edit to any of\n    them is a change. The location stays at the first definition, but the span grows\n    to cover all of them. Signature and arity come from the last definition that is\n    neither an ``@overload`` stub nor a property accessor, which is what callers bind to.\n    \"\"\"\n    existing.tags = sorted(set(existing.tags) | set(node.tags))\n    for attr in (\"sig_hash\", \"body_hash\", \"doc_hash\"):\n        mine, theirs = getattr(existing, attr), getattr(node, attr)\n        if theirs:\n            setattr(existing, attr, _fold(mine, theirs) if mine else theirs)\n    existing.end_lineno = max(existing.end_lineno, node.end_lineno)\n    existing.decorators = existing.decorators + [\n        d for d in node.decorators if d not in existing.decorators]\n    tails = {d.split(\"(\")[0].rsplit(\".\", 1)[-1] for d in node.decorators}\n    is_stub = \"overload\" in tails\n    is_accessor = bool(tails & {\"setter\", \"deleter\", \"getter\"})\n    if node.signature and not is_stub and not is_accessor:\n        existing.signature = node.signature\n        if \"arity\" in node.meta:\n            existing.meta[\"arity\"] = node.meta[\"arity\"]\n    elif not existing.signature:\n        existing.signature = node.signature\n    existing.meta[\"redefined\"] = existing.meta.get(\"redefined\", 0) + 1\n\n\nclass Graph:\n    \"\"\"Nodes, edges, and the adjacency indexes propagation walks over.\"\"\"\n\n    def __init__(self, root: str = \"\") -> None:\n        self.root = root\n        self.nodes: dict[str, Node] = {}\n        self.edges: list[Edge] = []\n        self.files: dict[str, FileRecord] = {}\n        self._edge_keys: set[tuple[str, str, str, int, int]] = set()\n        self._out: dict[str, list[int]] = {}\n        self._in: dict[str, list[int]] = {}\n        self.diagnostics: list[str] = []\n\n    # -- construction ---------------------------------------------------\n    def add_node(self, node: Node) -> Node:\n        existing = self.nodes.get(node.id)\n        if existing is not None:\n            _merge_redefinition(existing, node)\n            return existing\n        self.nodes[node.id] = node\n        return node\n\n    #: Self-edges are noise for most relations (a module \"containing\" itself), but\n    #: for a call they are the whole point: direct recursion. Dropping them made\n    #: `def walk(n): return walk(n)` look like a function with no callers.\n    SELF_EDGE_KINDS = frozenset({EdgeKind.CALLS, EdgeKind.INSTANTIATES})\n\n    def add_edge(self, edge: Edge) -> Edge | None:\n        if edge.src == edge.dst and edge.kind not in self.SELF_EDGE_KINDS:\n            return None\n        if edge.key in self._edge_keys:\n            return None\n        self._edge_keys.add(edge.key)\n        idx = len(self.edges)\n        self.edges.append(edge)\n        self._out.setdefault(edge.src, []).append(idx)\n        self._in.setdefault(edge.dst, []).append(idx)\n        return edge\n\n    def reindex(self) -> None:\n        self._out.clear()\n        self._in.clear()\n        self._edge_keys.clear()\n        for idx, e in enumerate(self.edges):\n            self._edge_keys.add(e.key)\n            self._out.setdefault(e.src, []).append(idx)\n            self._in.setdefault(e.dst, []).append(idx)\n\n    # -- queries --------------------------------------------------------\n    def out_edges(self, node_id: str) -> list[Edge]:\n        return [self.edges[i] for i in self._out.get(node_id, ())]\n\n    def in_edges(self, node_id: str) -> list[Edge]:\n        return [self.edges[i] for i in self._in.get(node_id, ())]\n\n    def neighbors(self, node_id: str) -> Iterator[tuple[Edge, str, bool]]:\n        \"\"\"Yield ``(edge, other_id, outgoing)`` for every edge touching ``node_id``.\"\"\"\n        for e in self.out_edges(node_id):\n            yield e, e.dst, True\n        for e in self.in_edges(node_id):\n            yield e, e.src, False\n\n    def of_kind(self, *kinds: NodeKind) -> Iterator[Node]:\n        wanted = set(kinds)\n        for n in self.nodes.values():\n            if n.kind in wanted:\n                yield n\n\n    def children(self, node_id: str) -> list[Node]:\n        return [\n            self.nodes[e.dst]\n            for e in self.out_edges(node_id)\n            if e.kind is EdgeKind.CONTAINS and e.dst in self.nodes\n        ]\n\n    def enclosing_module(self, node_id: str) -> Node | None:\n        node = self.nodes.get(node_id)\n        if node is None:\n            return None\n        if node.kind is NodeKind.MODULE:\n            return node\n        return self.nodes.get(make_id(NodeKind.MODULE, node.module))\n\n    def stats(self) -> dict[str, Any]:\n        by_node: dict[str, int] = {}\n        for n in self.nodes.values():\n            by_node[n.kind.value] = by_node.get(n.kind.value, 0) + 1\n        by_edge: dict[str, int] = {}\n        for e in self.edges:\n            by_edge[e.kind.value] = by_edge.get(e.kind.value, 0) + 1\n        return {\n            \"files\": len(self.files),\n            \"nodes\": len(self.nodes),\n            \"edges\": len(self.edges),\n            \"nodes_by_kind\": dict(sorted(by_node.items(), key=lambda kv: -kv[1])),\n            \"edges_by_kind\": dict(sorted(by_edge.items(), key=lambda kv: -kv[1])),\n        }\n\n    # -- serialization --------------------------------------------------\n    def to_dict(self) -> dict[str, Any]:\n        return {\n            \"magellan\": 1,\n            \"root\": self.root,\n            \"files\": [f.to_dict() for f in self.files.values()],\n            \"nodes\": [n.to_dict() for n in self.nodes.values()],\n            \"edges\": [e.to_dict() for e in self.edges],\n            \"diagnostics\": self.diagnostics,\n        }\n\n    def save(self, path: str) -> None:\n        with open(path, \"w\", encoding=\"utf-8\") as fh:\n            json.dump(self.to_dict(), fh, indent=1, sort_keys=False)\n\n    @staticmethod\n    def from_dict(d: dict[str, Any]) -> Graph:\n        g = Graph(root=d.get(\"root\", \"\"))\n        for fd in d.get(\"files\", []):\n            rec = FileRecord.from_dict(fd)\n            g.files[rec.path] = rec\n        for nd in d.get(\"nodes\", []):\n            n = Node.from_dict(nd)\n            g.nodes[n.id] = n\n        g.edges = [Edge.from_dict(ed) for ed in d.get(\"edges\", [])]\n        g.diagnostics = list(d.get(\"diagnostics\", []))\n        g.reindex()\n        return g\n\n    @staticmethod\n    def load(path: str) -> Graph:\n        with open(path, encoding=\"utf-8\") as fh:\n            return Graph.from_dict(json.load(fh))\n\n    def __repr__(self) -> str:  # pragma: no cover - debugging aid\n        return f\"<Graph nodes={len(self.nodes)} edges={len(self.edges)} files={len(self.files)}>\"\n", "magellan_lite/polyglot/python/__init__.py": "\"\"\"Python support: the AST frontend (collect -> resolve -> refs), jedi type inference,\nthe runtime tracer and coverage merge, and confidence calibration from traces.\"\"\"\n", "magellan_lite/polyglot/python/py2.py": "\"\"\"Read Python 2 source, so code awaiting a 2-to-3 upgrade is still on the map.\n\n``ast`` only parses Python 3. A Python 2 file used to be a syntax error and dropped out of\nthe graph entirely, so the \"before\" side of a 2-to-3 upgrade had none of its modules and\neverything they held looked newly introduced by the upgrade (requests 0.6: ``models.py``).\n\n:func:`parse` tries Python 3 first. On a syntax error it rewrites the Python 2 forms that\n3 rejects into their Python 3 spelling and tries again, keeping every statement on its own\nline so line numbers still match the file. The rewrite is what 2to3 would produce, so a\nfile before and after a 2-to-3 port parses to the same tree, and the port hashes as\nunchanged except where the code really changed. Anything it cannot rewrite raises the\noriginal error.\n\"\"\"\nfrom __future__ import annotations\n\nimport ast\nimport re\n\n_STRING = re.compile(r\"\"\"(?:[rRbBuU]{0,2})(?:'''.*?'''|\\\"\\\"\\\".*?\\\"\\\"\\\"|'(?:\\\\.|[^'\\\\\\n])*'|\"(?:\\\\.|[^\"\\\\\\n])*\")\"\"\",\n                     re.S)\n_EXCEPT = re.compile(r\"^(\\s*except\\s+)(\\([^()]*\\)|[\\w.]+)\\s*,\\s*(\\w+)\\s*:\")\n_PRINT = re.compile(r\"^(\\s*)print\\b(?!\\s*[(=.\\[,)])(.*)$\")\n_EXEC = re.compile(r\"^(\\s*)exec\\b(?!\\s*\\()\\s+(.+?)(?:\\s+in\\s+(.+))?\\s*$\")\n_RAISE = re.compile(r\"^(\\s*raise\\s+)([\\w.]+)\\s*,\\s*(.+?)\\s*$\")\n_BACKTICK = re.compile(r\"`([^`\\n]+)`\")\n_OCTAL = re.compile(r\"(?<![\\w.])0([0-7]+)(?![\\w.])\")\n_LONG = re.compile(r\"(?<![\\w.])(\\d+)[lL](?!\\w)\")\n_UR = re.compile(r\"(?<![\\w])[uU][rR](['\\\"])\")\n\n\ndef parse(source: str, filename: str = \"<unknown>\") -> ast.Module:\n    \"\"\"``ast.parse``, falling back to a Python 2 reading of ``source``.\"\"\"\n    try:\n        return ast.parse(source, filename=filename)\n    except SyntaxError as first:\n        try:\n            return ast.parse(to_python3(source), filename=filename)\n        except SyntaxError:\n            raise first from None\n\n\ndef is_python2(source: str) -> bool:\n    \"\"\"Parses only once rewritten from Python 2.\"\"\"\n    try:\n        ast.parse(source)\n        return False\n    except SyntaxError:\n        pass\n    try:\n        ast.parse(to_python3(source))\n        return True\n    except SyntaxError:\n        return False\n\n\ndef _mask(line: str) -> str:\n    \"\"\"The line with string literals blanked to the same length (so offsets still match).\"\"\"\n    return _STRING.sub(lambda m: \"_\" * len(m.group()), line)\n\n\ndef _depth(text: str) -> int:\n    \"\"\"Open brackets minus closed ones, outside strings and comments.\"\"\"\n    code = _mask(text).split(\"#\", 1)[0]\n    return sum(code.count(c) for c in \"([{\") - sum(code.count(c) for c in \")]}\")\n\n\ndef to_python3(source: str) -> str:\n    \"\"\"Rewrite Python 2-only syntax line by line; the line count never changes.\"\"\"\n    lines = source.split(\"\\n\")\n    out: list[str] = []\n    i = 0\n    while i < len(lines):\n        line = lines[i]\n        masked = _mask(line)\n        code_part = masked.split(\"#\", 1)[0]\n        m = _EXCEPT.match(line)\n        if m:\n            line = f\"{m.group(1)}{m.group(2)} as {m.group(3)}:\" + line[m.end():]\n        m = _PRINT.match(line) if _PRINT.match(code_part) else None\n        if m:\n            indent, rest = m.group(1), m.group(2)\n            # a print statement that continues over several lines closes where its\n            # brackets balance (or where its backslash continuations end)\n            j, depth = i, _depth(rest)\n            tail = rest\n            while (depth > 0 or tail.rstrip().endswith(\"\\\\\")) and j + 1 < len(lines):\n                j += 1\n                tail = lines[j]\n                depth += _depth(tail)\n            if j == i:\n                out.append(_tokens(indent + \"print(\" + _print_args(rest) + \")\"))\n            else:\n                # the arguments span lines: `>>f` and a trailing comma become keywords\n                # on the last line, where the call closes\n                body, extra = rest.strip(), []\n                if body.startswith(\">>\"):\n                    target, _, body = body[2:].partition(\",\")\n                    extra.append(f\"file={target.strip()}\")\n                out.append(_tokens(indent + \"print(\" + body.strip()))\n                for k in range(i + 1, j):\n                    out.append(_tokens(lines[k]))\n                last = lines[j].rstrip()\n                if last.endswith(\",\") and _depth(last) <= 0:\n                    last = last[:-1]\n                    extra.append(\"end=' '\")\n                out.append(_tokens(last + \"\".join(\", \" + x for x in extra) + \")\"))\n            i = j + 1\n            continue\n        m = _EXEC.match(line) if _EXEC.match(code_part) else None\n        if m:\n            line = f\"{m.group(1)}exec({m.group(2)}\" + (f\", {m.group(3)})\" if m.group(3) else \")\")\n        m = _RAISE.match(line)\n        if m and _depth(m.group(3)) == 0 and \"#\" not in _mask(m.group(3)):\n            parts = _split_top(m.group(3))\n            line = f\"{m.group(1)}{m.group(2)}({parts[0]})\"\n        out.append(_tokens(line))\n        i += 1\n    return \"\\n\".join(out)\n\n\ndef _tokens(line: str) -> str:\n    \"\"\"Backticks, ``<>``, ``0777``, ``10L`` and ``ur''`` outside string literals.\"\"\"\n    line = _outside_strings(line, lambda s: _OCTAL.sub(r\"0o\\1\", _LONG.sub(r\"\\1\", _BACKTICK.sub(\n        r\"repr(\\1)\", s.replace(\"<>\", \"!=\")))))\n    return _UR.sub(r\"r\\1\", line)\n\n\ndef _print_args(rest: str) -> str:\n    \"\"\"``>>f, a, b,`` -> ``a, b, file=f, end=' '`` (the arguments only; no parentheses).\"\"\"\n    body = rest.strip()\n    if not body:\n        return \"\"\n    extra = []\n    if body.startswith(\">>\"):\n        target, _, body = body[2:].partition(\",\")\n        extra.append(f\"file={target.strip()}\")\n        body = body.strip()\n    if body.endswith(\",\") and _depth(body) == 0:\n        body = body[:-1].rstrip()\n        extra.append(\"end=' '\")\n    return \", \".join(x for x in [body] + extra if x)\n\n\ndef _split_top(text: str) -> list[str]:\n    parts, depth, cur = [], 0, \"\"\n    for ch, mk in zip(text, _mask(text)):\n        if mk in \"([{\":\n            depth += 1\n        elif mk in \")]}\":\n            depth -= 1\n        if mk == \",\" and depth == 0:\n            parts.append(cur.strip())\n            cur = \"\"\n        else:\n            cur += ch\n    parts.append(cur.strip())\n    return parts\n\n\ndef _outside_strings(line: str, fix) -> str:\n    \"\"\"Apply ``fix`` to the code between string literals (and before any comment).\"\"\"\n    out, last = [], 0\n    for m in _STRING.finditer(line):\n        out.append(fix(line[last:m.start()]))\n        out.append(m.group())\n        last = m.end()\n    rest = line[last:]\n    code, hash_, comment = rest.partition(\"#\")\n    out.append(fix(code) + hash_ + comment)\n    return \"\".join(out)\n", "magellan_lite/radius.py": "\"\"\"The blast radius: code the change did not touch that it can still break, ranked.\n\nImpact travels *against* the call graph. If ``parse_record`` changes, the code that calls it\nis at risk; then whatever calls that code, and so on. Each change starts with a weight for how\nmuch it can do to the code that depends on it, and every hop multiplies the weight down, so a\nchain of direct calls stays hot while a long or uncertain chain fades out:\n\n    deleted or renamed 1.0   signature 0.95   value 0.8   body 0.6     (the seed)\n    a call 0.9   reading a constant 0.85   a guessed call x0.5         (each hop)\n\nA definition is listed with the best score any path gives it; propagation stops below\n``THRESHOLD`` or after ``MAX_HOPS``. Definitions the change edited are not listed: they are\nalready in the change.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom magellan_lite.defs import Definition\nfrom magellan_lite.diff import Change\nfrom magellan_lite.graph import CallGraph, Edge\n\nSEED = {\"removed\": 1.0, \"renamed\": 1.0, \"signature\": 0.95, \"value\": 0.8, \"body\": 0.6}\nSTEP = {\"calls\": 0.9, \"reads\": 0.85}\nGUESS = 0.5\nTHRESHOLD = 0.1\nMAX_HOPS = 6\n\n\ndef blast_radius(changes: list[Change], graph: CallGraph,\n                 defs: dict[str, Definition]) -> list[dict]:\n    \"\"\"The affected definitions, worst first: ``{name, path, line, hops, score, why}``.\"\"\"\n    changed = {c.name for c in changes} | {c.before.name for c in changes if c.before}\n    frontier: list[tuple[float, int, str]] = []\n    for c in changes:\n        seed = SEED.get(c.kind)\n        if seed is None:\n            continue\n        frontier.append((seed, 0, c.name))\n        if c.kind == \"renamed\":                     # callers of the old name are hit too\n            frontier.append((seed, 0, c.before.name))\n\n    best: dict[str, tuple[float, int, Edge]] = {}\n    while frontier:\n        score, hops, name = frontier.pop()\n        if hops >= MAX_HOPS:\n            continue\n        for e in graph.callers(name):\n            s = score * STEP[e.kind] * (GUESS if e.guess else 1.0)\n            if s < THRESHOLD or e.src in changed:\n                continue\n            if e.src not in best or s > best[e.src][0] + 1e-9:\n                best[e.src] = (s, hops + 1, e)\n                frontier.append((s, hops + 1, e.src))\n\n    out = []\n    for name, (score, hops, e) in best.items():\n        d = defs.get(name)\n        out.append({\n            \"name\": name, \"path\": d.path if d else e.path, \"line\": d.line if d else e.line,\n            \"hops\": hops, \"score\": round(score, 2),\n            \"why\": (f\"{e.src} {e.kind} {e.dst} ({e.path}:{e.line})\"\n                    + (\" -- a guess\" if e.guess else \"\")),\n        })\n    out.sort(key=lambda a: (-a[\"score\"], a[\"hops\"], a[\"name\"]))\n    return out\n", "magellan_lite/report.py": "\"\"\"What one check produces: the changes, the checklist, and a verdict. Shared contract.\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\n\nfrom magellan_lite.diff import Change\nfrom magellan_lite.findings import Finding, blocking_rules\n\nVERDICTS = (\"ok\", \"review\", \"block\")\n\n\n@dataclass\nclass Report:\n    root: str\n    against: str\n    changes: list[Change] = field(default_factory=list)\n    findings: list[Finding] = field(default_factory=list)\n    #: the blast radius: unedited code the change can break -- the engine's next step\n    affected: list[dict] = field(default_factory=list)\n    #: files that did not parse, rules that crashed: reported, never hidden\n    errors: list[str] = field(default_factory=list)\n    #: findings silenced by a ``# magellan: ignore[rule-id]`` comment: counted, not listed\n    suppressed: int = 0\n\n    @property\n    def verdict(self) -> str:\n        \"\"\"``block``: a blocking rule found something high or worse. ``review``: something\n        medium or worse. ``ok``: nothing that needs a person.\"\"\"\n        blocking = blocking_rules()\n        if any(f.rule in blocking and f.severity in (\"critical\", \"high\") for f in self.findings):\n            return \"block\"\n        if any(f.severity in (\"critical\", \"high\", \"medium\") for f in self.findings):\n            return \"review\"\n        return \"ok\"\n\n    @property\n    def files_changed(self) -> list[str]:\n        return sorted({c.path for c in self.changes})\n\n    def fails(self, fail_on: str) -> bool:\n        \"\"\"Should this report stop a commit? ``fail_on`` is a verdict, or ``never``.\"\"\"\n        if fail_on == \"never\":\n            return False\n        return VERDICTS.index(self.verdict) >= VERDICTS.index(fail_on)\n\n    def to_dict(self) -> dict:\n        return {\n            \"verdict\": self.verdict,\n            \"root\": self.root,\n            \"against\": self.against,\n            \"files_changed\": self.files_changed,\n            \"changes\": [c.to_dict() for c in self.changes],\n            \"findings\": [f.to_dict() for f in self.findings],\n            \"affected\": self.affected,\n            \"errors\": self.errors,\n            \"suppressed\": self.suppressed,\n        }\n", "magellan_lite/rules/__init__.py": "\"\"\"The checklist. Importing this package registers every rule.\n\nAdd a rule: write it in its own module here (one rule, or a few related ones, per file),\nthen import that module below. Give it a test in ``tests/rules/``, with cases that must stay\nquiet. After changing a rule, ``python demo/run.py`` must still show no MISSED, and\n``python demo/build_site.py`` refreshes what the website shows.\n\"\"\"\n\nfrom magellan_lite.rules import defaults  # noqa: F401\n\n# Calls the change breaks (signature-break, removed-still-referenced): need the call graph.\nfrom magellan_lite.rules import breaks  # noqa: F401\n\n# The small rules, short and commented step by step. New to the checklist? Read them first,\n# in this order: bare_except.py -> assert_tuple.py -> compare_none.py -> debug_leftover.py,\n# each beside its test in tests/rules/. They show the whole shape of a rule in a page.\nfrom magellan_lite.rules import assert_tuple, bare_except, compare_none, debug_leftover  # noqa: F401,E501\n\n# The other languages' own checks (a COBOL copybook whose layout moved, a C `goto fail`, a\n# Fortran COMMON block that no longer lines up): languages.py runs them, this lists them.\nfrom magellan_lite.rules import languages  # noqa: F401\n\n# The famous failures, one rule each (demo/incidents/ replays them: `python demo/run.py`).\nfrom magellan_lite.rules import dates  # noqa: F401      leap-day-date: Azure, 2012\nfrom magellan_lite.rules import reuse  # noqa: F401      reused-value: Knight Capital, 2012\nfrom magellan_lite.rules import loops  # noqa: F401      loop-without-progress: Knight, Zune\nfrom magellan_lite.rules import regexes  # noqa: F401    regex-catastrophic-backtracking: Cloudflare\nfrom magellan_lite.rules import threads  # noqa: F401    unsynchronized-shared-state: Therac-25\n\n# Ported from the full Magellan's checklist: the generic ones worth stopping a commit for.\nfrom magellan_lite.rules import undefined_names  # noqa: F401  undefined-name: a NameError left behind\nfrom magellan_lite.rules import deps  # noqa: F401       dependency-undeclared / -removed-still-used\nfrom magellan_lite.rules import taint  # noqa: F401      unvalidated-input-reaches-sink\nfrom magellan_lite.rules import envvars  # noqa: F401    env-var-renamed / env-var-default-changed\nfrom magellan_lite.rules import recursion  # noqa: F401  recursive-cycle: recursion with no end\nfrom magellan_lite.rules import cost  # noqa: F401       complexity-regression: newly quadratic\nfrom magellan_lite.rules import imports  # noqa: F401    import-cycle: modules importing each other\nfrom magellan_lite.rules import cochange  # noqa: F401   co-change: git history's usual partner\nfrom magellan_lite.rules import deadcode  # noqa: F401   unreachable-code / constant-condition\nfrom magellan_lite.rules import exceptions  # noqa: F401  swallowed-exception: except Exception: pass\nfrom magellan_lite.rules import newcode  # noqa: F401    near-duplicate / new-unreferenced\n", "magellan_lite/rules/assert_tuple.py": "\"\"\"assert-on-tuple: `assert (x, \"message\")` -- an assert that can never fail.\n\nWhy it matters: the parentheses turn the condition and the message into one tuple, and a\ntuple with something in it is always true. The assert passes even when x is False, so the\ncheck you meant to have is not there. (Python 3.8+ warns about it, but only when it runs.)\nThe intended code is `assert x, \"message\"` -- no parentheses.\n\"\"\"\n\nimport ast\n\nfrom magellan_lite.findings import rule  # noqa: F401\n\n\n@rule(\"assert-on-tuple\", \"medium\", fix='Drop the parentheses: `assert x, \"message\"`.')\ndef assert_on_tuple(tree: ast.Module, path: str):\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Assert) and isinstance(node.test, ast.Tuple) and node.test.elts:\n            yield node, \"This assert checks a tuple, which is always true\"\n", "magellan_lite/rules/bare_except.py": "\"\"\"bare-except: an `except:` with no exception type.\n\nWhy it matters: a bare `except:` also catches KeyboardInterrupt and SystemExit, so Ctrl+C\nstops working, and any real error inside the `try` disappears without a trace.\n\"\"\"\n\nimport ast\n\nfrom magellan_lite.findings import rule  # noqa: F401\n\n\n@rule(\"bare-except\", \"low\", fix=\"Catch what you expect, e.g. `except ValueError:`.\")\ndef bare_except(tree: ast.Module, path: str):\n    for node in ast.walk(tree):\n        if isinstance(node, ast.ExceptHandler) and node.type is None:\n            yield node, \"a bare `except:` also catches Ctrl+C and SystemExit\"\n\n\n", "magellan_lite/rules/breaks.py": "\"\"\"Calls the change breaks: a signature they no longer fit, or a definition that is gone.\n\nThese need the whole picture -- the old and new version of what changed, and the call graph\nof who uses it -- so they are change rules. Both block a commit: each one is a TypeError,\nNameError or ImportError waiting for the code path to run.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom magellan_lite.findings import Finding, change_rule\n\n\n@change_rule(\"signature-break\", \"critical\", blocking=True,\n             fix=\"Update the call, or give the new parameter a default so existing calls \"\n                 \"keep working.\")\ndef signature_break(ctx):\n    return list(_python_signature_breaks(ctx)) + _other_languages(ctx, \"signature-break\")\n\n\ndef _other_languages(ctx, rule_id: str) -> list[Finding]:\n    \"\"\"The same break in C, Java, Fortran, COBOL, ...: their frontends judge their call sites\n    (languages.py).\"\"\"\n    if all(p.endswith(\".py\") for p in set(ctx.before.files) | set(ctx.after.files)):\n        return []\n    from magellan_lite import languages\n    return [f for f in languages.findings(ctx) if f.rule == rule_id]\n\n\ndef _python_signature_breaks(ctx):\n    \"\"\"A call that fit the old signature and does not fit the new one.\"\"\"\n    edited = {c.name for c in ctx.changes}\n    seen = set()\n    for c in ctx.changes:\n        if c.kind != \"signature\" or not (c.before.params and c.after.params):\n            continue\n        for e in ctx.graph.callers(c.name):\n            if e.kind != \"calls\" or e.unpacked or e.guess or (e.path, e.line) in seen:\n                continue\n            new = c.after.params.bound() if e.bound else c.after.params\n            old = c.before.params.bound() if e.bound else c.before.params\n            now = new.problems(e.positional, e.keywords)\n            if not now or old.problems(e.positional, e.keywords):\n                continue                        # fits the new one, or never fit the old one\n            seen.add((e.path, e.line))\n            untouched = (\"It is in code this change did not touch, so nobody updated it: \"\n                         if e.src not in edited else \"\")\n            yield Finding(\n                \"signature-break\", \"critical\",\n                f\"{e.src} calls {c.after.short}() the old way: it now {now[0]}\",\n                e.path, e.line,\n                detail=(f\"{c.name} went from {c.before.signature} to {c.after.signature}. \"\n                        f\"{untouched}the call raises TypeError when it runs.\"))\n\n\n@change_rule(\"removed-still-referenced\", \"critical\", blocking=True,\n             fix=\"Restore it, or update the code that still uses it in the same change.\")\ndef removed_still_referenced(ctx):\n    return list(_python_removed(ctx)) + _other_languages(ctx, \"removed-still-referenced\")\n\n\ndef _python_removed(ctx):\n    \"\"\"Code that still calls, reads or imports something the change deleted or renamed.\"\"\"\n    seen = set()\n    for c in ctx.changes:\n        if c.kind not in (\"removed\", \"renamed\"):\n            continue\n        gone = c.before.name\n        if gone in ctx.after_defs:\n            continue\n        what = (f\"which this change renamed to {c.after.name}\" if c.kind == \"renamed\"\n                else \"which this change deleted\")\n        uses = [(e.path, e.line, f\"{e.src} still {e.kind} {gone}\") for e in ctx.graph.callers(gone)]\n        uses += [(i.path, i.line, f\"{i.path} still imports {gone}\")\n                 for i in ctx.graph.imports if i.target == gone]\n        for path, line, message in uses:\n            if (path, line) in seen:\n                continue\n            seen.add((path, line))\n            yield Finding(\n                \"removed-still-referenced\", \"critical\", f\"{message}, {what}\", path, line,\n                detail=\"It fails when that line runs: NameError or AttributeError for a call \"\n                       \"or read, ImportError as soon as the module is imported.\")\n", "magellan_lite/rules/cochange.py": "\"\"\"co-change: a file that history says moves with the one you edited was left alone.\n\nFrom the full Magellan (``magellan/rules/cochange.py``). The code says what depends on what;\nversion control says what people *found* they had to change together, which includes\neverything a parser cannot see: a config schema and the code that reads it, both ends of a\nwire format, a migration and the model it mirrors, generated files and their generator. Two\nfiles edited in most of the same commits are coupled, whether or not any import connects them.\n\nMined from ``git log`` (the last 300 commits, merges and sweeping commits of more than 25\nfiles left out); nothing is run. Confidence is one-way: if ``schema.py`` changed in 6 commits\nand ``parser.py`` in 5 of them, editing ``schema.py`` alone is worth a look, even when\n``parser.py`` also changes on its own all the time. Reported when the two shared at least 4\ncommits and at least 60% of the edited file's commits.\n\nOnly for a real project checked against a git revision (``magellan-lite check``, the editor):\nwith no repository behind the check -- code pasted into the website, a baseline directory --\nit says nothing, and does not try.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom collections import Counter\nfrom itertools import combinations\n\nfrom magellan_lite.findings import Finding, change_rule\nfrom magellan_lite.languages import is_source\nfrom magellan_lite.rules.common import baseline, changed_files, git, on_disk\n\nMAX_COMMITS = 300\nMAX_FILES = 25          # a commit touching more is a sweep (rename, formatter), not coupling\nMIN_SUPPORT = 4\nMIN_CONFIDENCE = 0.6\n\n_cache: dict[tuple[str, str], \"History\"] = {}\n\n\nclass History:\n    \"\"\"For each file and each pair of files, how many commits touched them.\"\"\"\n\n    def __init__(self) -> None:\n        self.files: Counter = Counter()\n        self.pairs: Counter = Counter()\n\n    def add(self, files: list[str]) -> None:\n        if not files or len(files) > MAX_FILES:\n            return\n        self.files.update(files)\n        self.pairs.update(combinations(sorted(files), 2))\n\n    def partners(self, path: str) -> list[tuple[str, int, float]]:\n        \"\"\"``(other file, commits shared, share of path's commits)``, strongest first.\"\"\"\n        mine = self.files.get(path, 0)\n        if not mine:\n            return []\n        out = []\n        for (a, b), n in self.pairs.items():\n            if path not in (a, b) or n < MIN_SUPPORT:\n                continue\n            conf = n / mine\n            if conf >= MIN_CONFIDENCE:\n                out.append((b if a == path else a, n, conf))\n        out.sort(key=lambda r: (-r[2], -r[1], r[0]))\n        return out\n\n\ndef parse_log(text: str) -> History:\n    \"\"\"``git log --name-only --pretty=format:%x1e%H`` output, as a History.\"\"\"\n    h = History()\n    for block in text.split(\"\\x1e\"):\n        lines = [ln.strip() for ln in block.splitlines() if ln.strip()]\n        h.add(sorted({ln for ln in lines[1:] if is_source(ln)}))\n    return h\n\n\ndef mine(root, head: str) -> History | None:\n    key = (str(root), head)\n    if key not in _cache:\n        out = git(root, \"log\", \"--no-merges\", \"--name-only\", \"--relative\", \"-M\",\n                  f\"-n{MAX_COMMITS}\", \"--pretty=format:%x1e%H\", \"--\", \".\", timeout=15)\n        if out is None:\n            return None\n        if len(_cache) >= 8:\n            _cache.clear()                          # a long-running process: keep it small\n        _cache[key] = parse_log(out)\n    return _cache[key]\n\n\ndef _linked(ctx, a: str, b: str) -> bool:\n    \"\"\"Does a call, read or import already connect the two files?\"\"\"\n    for e in ctx.graph.edges:\n        if e.path in (a, b):\n            d = ctx.after_defs.get(e.dst)\n            if d is not None and {e.path, d.path} == {a, b}:\n                return True\n    return False\n\n\n@change_rule(\"co-change\", \"medium\",\n             fix=\"Check whether the other file needs the matching change; if it does not, \"\n                 \"nothing to do.\")\ndef co_change(ctx):\n    root = on_disk(ctx)\n    base = baseline(ctx) if root is not None else None\n    if base is None or base[0] != \"git\":\n        return\n    a = ctx.after.files\n    changed = changed_files(ctx, \"\")\n    if not changed:\n        return\n    head = git(root, \"rev-parse\", \"HEAD\")\n    history = mine(root, (head or \"\").strip()) if head else None\n    if history is None:\n        return\n    seen: set[tuple[str, str]] = set()\n    for path in sorted(changed):\n        if path not in a:\n            continue\n        for other, together, conf in history.partners(path):\n            pair = tuple(sorted((path, other)))\n            if other in changed or other not in a or pair in seen:\n                continue\n            seen.add(pair)\n            linked = _linked(ctx, path, other)\n            total = history.files[path]\n            yield Finding(\n                \"co-change\", \"medium\" if conf >= 0.8 and not linked else \"low\",\n                f\"{path} usually changes together with {other}, which this change leaves \"\n                f\"alone\",\n                path, 1,\n                detail=(f\"They changed together in {together} of the last {total} commits \"\n                        f\"that touched {path} ({conf:.0%}). \"\n                        + (\"No import or call connects them, so nothing else would point you \"\n                           \"at it.\" if not linked else \"They are also connected in the code.\")),\n                fix=f\"Check whether {other} needs the matching change.\")\n", "magellan_lite/rules/common.py": "\"\"\"Helpers for the rules ported from the full Magellan. Not a rule: nothing here registers.\n\nThey answer the questions several change rules ask: which definitions this change touched,\nthe old version's call graph (built once per check), where a definition's syntax tree is,\nand whether the check is looking at a real project on disk (the command line, the editor) or\nat code handed over as text (the website, the local server, tests). Rules that read files\nother than source (manifests) or ask git (history) must stay quiet in the second case: there\nis no disk and no git behind ``ctx.root`` then, and in the browser no subprocess either.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nfrom pathlib import Path\n\nfrom magellan_lite.source import decode, module_name\n\n#: change kinds that leave a definition in the new version\n_LIVE = (\"added\", \"body\", \"signature\", \"value\", \"renamed\")\n\n\ndef edited(ctx) -> set[str]:\n    \"\"\"Names of the definitions this change added or edited, as the new version names them.\"\"\"\n    return {c.name for c in ctx.changes if c.kind in _LIVE and c.after is not None}\n\n\ndef changed_files(ctx, suffix: str = \".py\") -> set[str]:\n    \"\"\"Files (ending in ``suffix``) whose text differs between the two versions, both ways.\"\"\"\n    b, a = ctx.before.files, ctx.after.files\n    return {p for p in set(b) | set(a)\n            if p.endswith(suffix) and _norm(b.get(p)) != _norm(a.get(p))}\n\n\ndef _norm(text: str | None) -> str | None:\n    return None if text is None else text.replace(\"\\r\\n\", \"\\n\")\n\n\ndef old_graph(ctx):\n    \"\"\"The previous version's call graph, built once per check whichever rule asks first.\"\"\"\n    graph = getattr(ctx, \"_lite_old_graph\", None)\n    if graph is None:\n        from magellan_lite.graph import build_graph\n        graph = build_graph(ctx.before, ctx.before_defs)\n        ctx._lite_old_graph = graph\n    return graph\n\n\ndef is_test_path(path: str) -> bool:\n    \"\"\"A test file: under a tests/ or test/ directory, or named test_*.py / *_test.py.\"\"\"\n    parts = path.split(\"/\")\n    name = parts[-1]\n    return (any(p in (\"tests\", \"test\", \"testing\") for p in parts[:-1])\n            or name.startswith(\"test_\") or name.endswith(\"_test.py\") or name == \"conftest.py\")\n\n\ndef callables(tree: ast.Module, path: str):\n    \"\"\"``(definition name, function node, enclosing class name or None)`` for every function\n    and method, named as defs.py names them (``pkg.mod.Class.method``).\"\"\"\n    def visit(body, prefix, cls):\n        for stmt in body:\n            if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):\n                yield f\"{prefix}.{stmt.name}\", stmt, cls\n            elif isinstance(stmt, ast.ClassDef):\n                qual = f\"{prefix}.{stmt.name}\"\n                yield from visit(stmt.body, qual, qual)\n    yield from visit(tree.body, module_name(path), None)\n\n\ndef functions(snapshot, paths=None) -> dict[str, tuple[str, ast.AST, str | None]]:\n    \"\"\"``{definition name: (path, function node, class name or None)}`` for Python files.\"\"\"\n    out: dict[str, tuple[str, ast.AST, str | None]] = {}\n    for path in sorted(paths if paths is not None else snapshot.files):\n        if not path.endswith(\".py\") or path not in snapshot.files:\n            continue\n        tree = snapshot.tree(path)\n        if tree is not None:\n            for name, fn, cls in callables(tree, path):\n                out[name] = (path, fn, cls)\n    return out\n\n\ndef dotted(node: ast.AST) -> str:\n    \"\"\"``os.path.join`` for an attribute chain on a name; ``\"\"`` for anything else.\"\"\"\n    parts = []\n    while isinstance(node, ast.Attribute):\n        parts.append(node.attr)\n        node = node.value\n    if isinstance(node, ast.Name):\n        return \".\".join([node.id, *reversed(parts)])\n    return \"\"\n\n\ndef call_name(call: ast.Call) -> str:\n    \"\"\"The last part of what a call calls: ``run`` for ``subprocess.run(...)``.\"\"\"\n    f = call.func\n    return f.attr if isinstance(f, ast.Attribute) else f.id if isinstance(f, ast.Name) else \"\"\n\n\ndef own_nodes(fn: ast.AST):\n    \"\"\"Every node in a function's body, without going into nested functions, lambdas or\n    classes (they run later, if at all).\"\"\"\n    todo = list(getattr(fn, \"body\", []))\n    while todo:\n        node = todo.pop()\n        yield node\n        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda,\n                                 ast.ClassDef)):\n            todo.extend(ast.iter_child_nodes(node))\n\n\ndef names_in(an: ast.AST, *, store: bool = False) -> set[str]:\n    \"\"\"Names an expression or statement reads (``store``: assigns).\"\"\"\n    want = ast.Store if store else ast.Load\n    return {n.id for n in ast.walk(an) if isinstance(n, ast.Name) and isinstance(n.ctx, want)}\n\n\ndef under_import_guard(tree: ast.Module) -> set[int]:\n    \"\"\"Line numbers of imports that may fail on purpose: inside ``try`` blocks that catch\n    ImportError (or anything broader), and under ``if TYPE_CHECKING:``.\"\"\"\n    lines: set[int] = set()\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Try) and any(_catches_import_error(h) for h in node.handlers):\n            for stmt in node.body:\n                lines |= {n.lineno for n in ast.walk(stmt)\n                          if isinstance(n, (ast.Import, ast.ImportFrom))}\n        elif isinstance(node, ast.If) and \"TYPE_CHECKING\" in ast.unparse(node.test):\n            for stmt in node.body:\n                lines |= {n.lineno for n in ast.walk(stmt)\n                          if isinstance(n, (ast.Import, ast.ImportFrom))}\n    return lines\n\n\ndef _catches_import_error(handler: ast.ExceptHandler) -> bool:\n    if handler.type is None:\n        return True\n    names = handler.type.elts if isinstance(handler.type, ast.Tuple) else [handler.type]\n    return any(dotted(n).rsplit(\".\", 1)[-1] in (\"ImportError\", \"ModuleNotFoundError\",\n                                               \"Exception\", \"BaseException\") for n in names)\n\n\n# -- the project on disk, and git ----------------------------------------------------------\ndef on_disk(ctx) -> Path | None:\n    \"\"\"``ctx.root`` when the new version is the project as it is on disk there: what\n    ``magellan-lite check`` and the editor look at. ``None`` for code handed over as text\n    (the website's Try it, the local server, the team check's combinations, tests that use\n    ``check_files``): nothing on disk belongs to it.\"\"\"\n    label = getattr(ctx.after, \"label\", \"\")\n    return ctx.root if label and label == str(ctx.root) and ctx.root.is_dir() else None\n\n\ndef baseline(ctx) -> tuple[str, str | Path] | None:\n    \"\"\"Where the old version came from: ``(\"git\", rev)``, ``(\"dir\", path)``, or None when it\n    was handed over as text. Only meaningful when ``on_disk(ctx)`` is not None.\"\"\"\n    label = getattr(ctx.before, \"label\", \"\") or \"\"\n    if label.startswith(\"git \"):\n        return \"git\", label[4:]\n    p = Path(label)\n    if label and p.is_absolute() and p.is_dir():\n        return \"dir\", p\n    return None\n\n\ndef git(root: Path, *args: str, timeout: float = 10.0) -> str | None:\n    \"\"\"git's output decoded as UTF-8, or None when git is missing, slow or says no.\"\"\"\n    import subprocess                               # only here: the website's copy has no git\n    try:\n        r = subprocess.run([\"git\", \"-c\", \"core.quotepath=off\", *args], cwd=root,\n                           capture_output=True, timeout=timeout)\n    except (OSError, subprocess.SubprocessError):\n        return None\n    return decode(r.stdout) if r.returncode == 0 else None\n", "magellan_lite/rules/compare_none.py": "\"\"\"compare-to-none: `x == None` or `x != None` instead of `x is None`.\n\nWhy it matters: `==` asks the object whether it equals None, and a class can answer\nanything (numpy arrays and some ORM columns do). `is None` always means what it says.\n\"\"\"\n\nimport ast\n\nfrom magellan_lite.findings import rule  # noqa: F401\n\n\n@rule(\"compare-to-none\", \"low\", fix=\"Use `is None` / `is not None`.\")\ndef compare_to_none(tree: ast.Module, path: str):\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Compare):\n            for op, right in zip(node.ops, node.comparators):\n                if isinstance(op, (ast.Eq, ast.NotEq)) and isinstance(right, ast.Constant) and right.value is None:\n                    yield node, \"compare with None using `is` / `is not`, not `==` / `!=`\"\n\n", "magellan_lite/rules/cost.py": "\"\"\"complexity-regression: an edited function whose work now grows faster with its input.\n\nFrom the full Magellan (``magellan/python/rules/complexity.py``). Not \"is this slow\" -- a\nparser cannot see constant factors, I/O or memory -- but \"did this change make it slower in\na way that gets worse as data grows\": a loop added inside a loop, a list scanned with ``in``\nfor every item, a sort inside a loop, a helper that loops over its input called once per item\n(the N+1 shape). Every estimate is made the same way on both versions, so only the change\nshows up; a function that was already quadratic is not news.\n\nThe estimate is the shape, from the syntax tree:\n\n* a loop over something that grows (a parameter, ``self.items``, ``range(n)``) is one level;\n  ``range(10)``, a literal, an ``ALL_CAPS`` table or a parameter with a numeric default is not;\n* a loop over a piece of an outer loop's element (``for cell in row`` inside ``for row in\n  grid``) adds up to the total, not a product, so it is not a level;\n* ``x in some_list`` (a list the function built, or a parameter annotated as one), ``.index``,\n  ``.remove``, ``.insert(0, ...)``, ``sorted``/``.sort()``, ``sum``/``min``/``max`` over a\n  collection each cost one more level where they run;\n* a call to one of the project's functions costs what that function costs, multiplied by the\n  loops around the call when it is handed something that grows (not a piece of the current\n  item).\n\nReported when the edited function reaches quadratic or worse and is worse than it was.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nfrom dataclasses import dataclass, field\n\nfrom magellan_lite.findings import Finding, change_rule\nfrom magellan_lite.rules.common import call_name, functions, old_graph\n\n_PASSTHROUGH = {\"enumerate\", \"reversed\", \"sorted\", \"list\", \"tuple\", \"set\", \"iter\", \"filter\",\n                \"map\", \"zip\", \"frozenset\"}\n_VIEWS = {\"items\", \"keys\", \"values\"}\n_SCANS = {\"sum\", \"min\", \"max\", \"any\", \"all\"}\n_COPIES = {\"list\", \"tuple\", \"set\", \"frozenset\", \"dict\", \"deepcopy\"}\n_LIST_SCANS = {\"index\", \"count\", \"remove\"}\n_LIST_TYPES = (\"list\", \"List\", \"Sequence\", \"tuple\", \"Tuple\")\n_HASHED = {\"set\", \"frozenset\", \"dict\", \"defaultdict\", \"Counter\", \"OrderedDict\"}\n_MAX_DEPTH = 6\n\n\n@dataclass\nclass Cost:\n    degree: int = 0\n    log: int = 0\n    why: str = \"\"\n    #: the parameters that make it grow; None when something else does (state, globals)\n    drivers: set | None = field(default_factory=set)\n\n    @property\n    def rank(self) -> tuple[int, int]:\n        return self.degree, self.log\n\n    def notation(self) -> str:\n        if not self.degree and not self.log:\n            return \"O(1)\"\n        n = {0: \"\", 1: \"n\"}.get(self.degree, f\"n^{self.degree}\")\n        log = \"log n\" if self.log == 1 else f\"log^{self.log} n\" if self.log else \"\"\n        return f\"O({' '.join(p for p in (n, log) if p)})\"\n\n\ndef _root(expr: ast.AST) -> str:\n    \"\"\"What an iterable or argument is a view of: ``xs`` for ``enumerate(xs)``,\n    ``self.items`` for ``self.items.values()``; ``\"\"`` when it cannot be told.\"\"\"\n    while True:\n        if isinstance(expr, ast.Call):\n            name = call_name(expr)\n            if isinstance(expr.func, ast.Name) and name in _PASSTHROUGH and expr.args:\n                expr = expr.args[0]\n                continue\n            if isinstance(expr.func, ast.Attribute) and name in _VIEWS:\n                expr = expr.func.value\n                continue\n            return \"\"\n        if isinstance(expr, (ast.Subscript, ast.Starred)):\n            expr = expr.value\n            continue\n        break\n    if isinstance(expr, ast.Name):\n        return expr.id\n    if isinstance(expr, ast.Attribute) and isinstance(expr.value, ast.Name):\n        return f\"{expr.value.id}.{expr.attr}\" if expr.value.id == \"self\" else expr.value.id\n    return \"\"\n\n\nclass _Walker:\n    \"\"\"One function body: how deep its growing loops nest, and what else costs a level.\"\"\"\n\n    def __init__(self, fn, cls, project, owner: str, own: bool = False) -> None:\n        self.fn, self.project, self.owner = fn, project, owner\n        #: True for the function a finding is about: only what *it* multiplies counts, not a\n        #: one-off call to something expensive (that function is responsible for itself)\n        self.own = own\n        args = fn.args\n        self.params = [a.arg for a in [*args.posonlyargs, *args.args, *args.kwonlyargs]]\n        if cls is not None and self.params[:1] in ([\"self\"], [\"cls\"]):\n            self.params = self.params[1:]\n        self.fixed: set[str] = set()                # don't grow: numeric-default parameters\n        self.lists: set[str] = set()                # known lists: `in` scans them\n        self.hashed: set[str] = set()\n        positional = [*args.posonlyargs, *args.args]\n        defaults = [None] * (len(positional) - len(args.defaults)) + list(args.defaults)\n        for a, d in [*zip(positional, defaults), *zip(args.kwonlyargs, args.kw_defaults)]:\n            ann = ast.unparse(a.annotation) if a.annotation is not None else \"\"\n            if isinstance(d, ast.Constant) and isinstance(d.value, (int, float)) \\\n                    and not isinstance(d.value, bool):\n                self.fixed.add(a.arg)\n            if ann.startswith(_LIST_TYPES):\n                self.lists.add(a.arg)\n            if any(h in ann.lower() for h in (\"set\", \"dict\", \"mapping\", \"counter\")):\n                self.hashed.add(a.arg)\n        self.loops: list[str] = []                  # what each enclosing growing loop is over\n        self.derived: set[str] = set()              # pieces of an enclosing loop's element\n        self.best = Cost()\n        self.drivers: set | None = set()\n\n    # -- what grows ---------------------------------------------------------------------------\n    def grows(self, expr: ast.AST | None) -> bool:\n        if expr is None or isinstance(expr, (ast.Constant, ast.List, ast.Tuple, ast.Set,\n                                             ast.Dict, ast.JoinedStr)):\n            return False\n        called = {id(n.func) for n in ast.walk(expr) if isinstance(n, ast.Call)}\n        values = {n.id for n in ast.walk(expr) if isinstance(n, ast.Name)\n                  and isinstance(n.ctx, ast.Load) and id(n) not in called}\n        if all(v in self.derived or v in self.fixed or (v.isupper() and len(v) > 1)\n               for v in values):\n            return False            # made only of constants and pieces of the current item\n        if isinstance(expr, ast.Call):\n            name = call_name(expr)\n            if name == \"range\" and isinstance(expr.func, ast.Name):\n                return bool(expr.args) and self.grows(expr.args[-1] if len(expr.args) < 3\n                                                      else expr.args[1])\n            if name == \"len\" and expr.args:\n                return self.grows(expr.args[0])\n            if name == \"get\" and isinstance(expr.func, ast.Attribute):\n                return False                        # one bucket of an index\n        if isinstance(expr, ast.BinOp):\n            return self.grows(expr.left) or self.grows(expr.right)\n        if isinstance(expr, ast.UnaryOp):\n            return self.grows(expr.operand)\n        root = _root(expr)\n        if not root and isinstance(expr, ast.Call):\n            return bool(expr.args) and self.grows(expr.args[0])\n        base = root.split(\".\")[0]\n        if base in self.fixed or (base.isupper() and len(base) > 1) or base in self.derived:\n            return False\n        return True\n\n    def _driver(self, expr: ast.AST) -> str:\n        \"\"\"The name whose size makes ``expr`` grow: ``n`` for ``range(n - 1)``, ``xs`` for\n        ``len(xs)`` or ``enumerate(xs)``; ``\"\"`` when it cannot be told.\"\"\"\n        for _ in range(8):\n            if isinstance(expr, ast.Call):\n                name = call_name(expr)\n                if name == \"range\" and expr.args:\n                    expr = expr.args[-1] if len(expr.args) < 3 else expr.args[1]\n                    continue\n                if name == \"len\" and expr.args:\n                    expr = expr.args[0]\n                    continue\n                root = _root(expr)\n                if root or not expr.args:\n                    return root\n                expr = expr.args[0]\n            elif isinstance(expr, ast.BinOp):\n                expr = expr.left if self.grows(expr.left) else expr.right\n            elif isinstance(expr, ast.UnaryOp):\n                expr = expr.operand\n            else:\n                return _root(expr)\n        return \"\"\n\n    def _note_driver(self, expr: ast.AST) -> None:\n        root = self._driver(expr).split(\".\")[0]\n        if self.drivers is not None:\n            if root in self.params:\n                self.drivers.add(root)\n            else:\n                self.drivers = None                 # state, a global, a local of unknown size\n\n    def _inside(self) -> str:\n        return f\" inside a loop over {self.loops[-1]}\" if self.loops else \"\"\n\n    def bump(self, extra: int, log: int, why: str, line: int | None = None) -> None:\n        degree = len(self.loops) + extra\n        if (degree, log) > self.best.rank:\n            self.best = Cost(degree, log, why if line is None else f\"{why} (line {line})\")\n\n    # -- walking -------------------------------------------------------------------------------\n    def run(self) -> Cost:\n        self.block(self.fn.body)\n        self.best.drivers = self.drivers\n        return self.best\n\n    def block(self, body) -> None:\n        for st in body:\n            self.stmt(st)\n\n    def enter(self, iter_expr: ast.AST, target: ast.AST | None, line: int) -> bool:\n        \"\"\"Start a loop over ``iter_expr``; True when it is a growing level.\"\"\"\n        root = _root(iter_expr).split(\".\")[0]\n        names = set() if target is None else \\\n            {n.id for n in ast.walk(target) if isinstance(n, ast.Name)}\n        if root and root in self.derived:\n            self.derived |= names                   # a piece of a piece\n            return False\n        if not self.grows(iter_expr):\n            return False\n        self._note_driver(iter_expr)\n        what = ast.unparse(iter_expr)\n        what = what if len(what) <= 40 else what[:37] + \"...\"\n        inner = f\" inside a loop over {self.loops[-1]}\" if self.loops else \"\"\n        self.loops.append(what)\n        self.bump(0, 0, f\"loops over {what}{inner}\", line)\n        self.derived |= names\n        return True\n\n    def stmt(self, st: ast.stmt) -> None:\n        if isinstance(st, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):\n            return\n        if isinstance(st, (ast.For, ast.AsyncFor)):\n            self.expr(st.iter)\n            entered = self.enter(st.iter, st.target, st.lineno)\n            self.block(st.body)\n            self.block(st.orelse)\n            if entered:\n                self.loops.pop()\n            return\n        if isinstance(st, ast.While):\n            self.expr(st.test)\n            entered = False\n            if not isinstance(st.test, ast.Constant) and not _geometric(st):\n                bound = next((n.args[0] for n in ast.walk(st.test) if isinstance(n, ast.Call)\n                              and call_name(n) == \"len\" and n.args), None)\n                if bound is None:\n                    bound = next((n for n in ast.walk(st.test) if isinstance(n, ast.Name)\n                                  and n.id in self.params and n.id not in self.fixed), None)\n                if bound is not None:\n                    entered = self.enter(bound, None, st.lineno)\n            self.block(st.body)\n            self.block(st.orelse)\n            if entered:\n                self.loops.pop()\n            return\n        if isinstance(st, ast.Assign):\n            self._assigned(st.targets, st.value)\n        elif isinstance(st, ast.AnnAssign) and st.value is not None:\n            self._assigned([st.target], st.value)\n        for child in ast.iter_child_nodes(st):\n            if isinstance(child, ast.expr):\n                self.expr(child)\n            elif isinstance(child, ast.stmt):\n                self.stmt(child)\n            elif isinstance(child, ast.withitem):\n                self.expr(child.context_expr)\n            elif isinstance(child, (ast.excepthandler, getattr(ast, \"match_case\", ()))):\n                self.block(child.body)\n\n    def _assigned(self, targets, value) -> None:\n        names = [t.id for t in targets if isinstance(t, ast.Name)]\n        is_list = isinstance(value, (ast.List, ast.ListComp)) or (\n            isinstance(value, ast.Call) and call_name(value) == \"list\"\n            and isinstance(value.func, ast.Name))\n        is_hashed = isinstance(value, (ast.Set, ast.Dict, ast.SetComp, ast.DictComp)) or (\n            isinstance(value, ast.Call) and call_name(value) in _HASHED) or (\n            isinstance(value, ast.BoolOp) and any(\n                isinstance(v, (ast.Set, ast.Dict)) or (isinstance(v, ast.Call)\n                                                       and call_name(v) in _HASHED)\n                for v in value.values))\n        # made from a piece of the current item (`tree = load(path) if ok else None`)\n        from_piece = bool(self.loops) and bool(\n            {n.id for n in ast.walk(value) if isinstance(n, ast.Name)\n             and isinstance(n.ctx, ast.Load)} & self.derived)\n        for n in names:\n            self.lists.discard(n)\n            self.hashed.discard(n)\n            if is_list:\n                self.lists.add(n)\n            if is_hashed:\n                self.hashed.add(n)\n            if from_piece:\n                self.derived.add(n)\n\n    def expr(self, e: ast.AST) -> None:\n        if isinstance(e, (ast.Lambda,)):\n            return\n        if isinstance(e, (ast.ListComp, ast.SetComp, ast.GeneratorExp, ast.DictComp)):\n            entered = 0\n            for gen in e.generators:\n                self.expr(gen.iter)\n                if self.enter(gen.iter, gen.target, e.lineno):\n                    entered += 1\n                for cond in gen.ifs:\n                    self.expr(cond)\n            for part in (getattr(e, \"elt\", None), getattr(e, \"key\", None),\n                         getattr(e, \"value\", None)):\n                if part is not None:\n                    self.expr(part)\n            if entered:\n                del self.loops[-entered:]\n            return\n        if isinstance(e, ast.Compare):\n            for op, comp in zip(e.ops, e.comparators):\n                if isinstance(op, (ast.In, ast.NotIn)) and isinstance(comp, ast.Name) \\\n                        and comp.id in self.lists and comp.id not in self.hashed \\\n                        and self.loops:\n                    self._note_driver(comp)\n                    self.bump(1, 0, f\"checks `in {comp.id}` (a list, so each check scans \"\n                                    f\"all of it) inside a loop over {self.loops[-1]}\", e.lineno)\n        if isinstance(e, ast.Call):\n            self.call(e)\n        for child in ast.iter_child_nodes(e):\n            if isinstance(child, ast.expr):\n                self.expr(child)\n\n    def call(self, c: ast.Call) -> None:\n        name = call_name(c)\n        func = c.func\n        recv = func.value if isinstance(func, ast.Attribute) else None\n        arg = c.args[0] if c.args else None\n        comprehension = isinstance(arg, (ast.GeneratorExp, ast.ListComp, ast.SetComp))\n        if name == \"sorted\" and isinstance(func, ast.Name) and arg is not None \\\n                and not comprehension and self.grows(arg):\n            self._note_driver(arg)\n            self.bump(1, 1, f\"sorts {ast.unparse(arg)}{self._inside()}\", c.lineno)\n        elif name == \"sort\" and recv is not None and self.grows(recv):\n            self._note_driver(recv)\n            self.bump(1, 1, f\"sorts {ast.unparse(recv)}{self._inside()}\", c.lineno)\n        elif name in _SCANS | _COPIES and isinstance(func, ast.Name) and arg is not None \\\n                and not comprehension and isinstance(arg, (ast.Name, ast.Attribute)) \\\n                and self.grows(arg):\n            self._note_driver(arg)\n            self.bump(1, 0, f\"calls {name}({ast.unparse(arg)}), which goes through all of it\"\n                            f\"{self._inside()}\", c.lineno)\n        elif recv is not None and isinstance(recv, ast.Name) and recv.id in self.lists \\\n                and (name in _LIST_SCANS or (\n                    name in (\"insert\", \"pop\") and c.args and isinstance(c.args[0], ast.Constant)\n                    and c.args[0].value == 0)):\n            self._note_driver(recv)\n            self.bump(1, 0, f\"calls {recv.id}.{name}(), which goes through the whole list\"\n                            f\"{self._inside()}\", c.lineno)\n        for target in self.project.targets(self, c):\n            callee = self.project.cost(target)\n            if callee is None or not callee.rank > (0, 0):\n                continue\n            carries = bool(self.loops) and self._carries(c, target, callee)\n            if self.own and not carries:\n                continue\n            extra = callee.degree if carries else max(callee.degree - len(self.loops), 0)\n            if self.drivers is not None:\n                for a in self._args_for(c, target, callee):\n                    self._note_driver(a)\n                if callee.drivers is None:\n                    self.drivers = None\n            where = f\" inside a loop over {self.loops[-1]}\" if carries else \"\"\n            short = target.rsplit(\".\", 1)[-1]\n            self.bump(extra, callee.log,\n                      f\"calls {short}(){where} (line {c.lineno}), and {short}() is \"\n                      f\"{callee.notation()} by itself: it {callee.why}\")\n\n    def _args_for(self, c: ast.Call, target: str, callee: Cost) -> list[ast.AST]:\n        _path, fn, cls = self.project.fns[target]\n        names = [a.arg for a in [*fn.args.posonlyargs, *fn.args.args]]\n        if cls is not None and names[:1] in ([\"self\"], [\"cls\"]):\n            names = names[1:]\n        bound = dict(zip(names, c.args))\n        bound.update({k.arg: k.value for k in c.keywords if k.arg})\n        return [bound[d] for d in (callee.drivers or ()) if d in bound]\n\n    def _carries(self, c: ast.Call, target: str, callee: Cost) -> bool:\n        \"\"\"Does the call hand the callee the thing that makes it grow -- something that grows\n        here too, and not a piece of the current item? Then its cost multiplies with the loops\n        around the call. A callee that grows with something else (its object's state, a\n        global) is not judged: how big that is cannot be told from here.\"\"\"\n        if not callee.drivers:\n            return False\n        return any(self.grows(a) for a in self._args_for(c, target, callee))\n\n\ndef _geometric(loop: ast.While) -> bool:\n    \"\"\"Does the loop halve or double what its condition reads, or bisect?\"\"\"\n    test_names = {n.id for n in ast.walk(loop.test) if isinstance(n, ast.Name)}\n    for st in ast.walk(loop):\n        if isinstance(st, ast.AugAssign) and isinstance(st.target, ast.Name) \\\n                and st.target.id in test_names \\\n                and isinstance(st.op, (ast.FloorDiv, ast.Div, ast.RShift, ast.Mult, ast.LShift)):\n            return True\n        if isinstance(st, ast.Assign) and isinstance(st.value, ast.BinOp) \\\n                and isinstance(st.value.op, (ast.FloorDiv, ast.RShift)):\n            return True                             # mid = (lo + hi) // 2\n    return False\n\n\nclass _Project:\n    \"\"\"Costs of every function in one version, worked out on demand.\"\"\"\n\n    def __init__(self, snapshot, graph) -> None:\n        self.fns = functions(snapshot)\n        self.graph = graph\n        self.costs: dict[str, Cost | None] = {}\n        self.busy: list[str] = []\n\n    def targets(self, walker: _Walker, c: ast.Call) -> list[str]:\n        edges = [e for e in self.graph.uses(walker.owner) if e.kind == \"calls\" and not e.guess\n                 and e.line == c.lineno and e.dst.rsplit(\".\", 1)[-1] == call_name(c)]\n        return sorted({e.dst for e in edges if e.dst in self.fns})\n\n    def cost(self, name: str) -> Cost | None:\n        if name in self.costs:\n            return self.costs[name]\n        if name in self.busy or len(self.busy) >= _MAX_DEPTH or name not in self.fns:\n            return None                             # recursion, or too deep to follow\n        self.busy.append(name)\n        _path, fn, cls = self.fns[name]\n        self.costs[name] = _Walker(fn, cls, self, name).run()\n        self.busy.pop()\n        return self.costs[name]\n\n    def own(self, name: str) -> Cost | None:\n        \"\"\"What the function's own loops and calls multiply, the part a change to it is\n        responsible for.\"\"\"\n        if name not in self.fns:\n            return None\n        _path, fn, cls = self.fns[name]\n        return _Walker(fn, cls, self, name, own=True).run()\n\n\ndef _steps(degree: int, log: int) -> str:\n    n = 10_000\n    value = n ** degree * (14 ** log)\n    for size, word in ((10 ** 12, \"trillion\"), (10 ** 9, \"billion\"), (10 ** 6, \"million\"),\n                       (10 ** 3, \"thousand\")):\n        if value >= size:\n            return f\"{value // size:,} {word}\"\n    return str(value)\n\n\n@change_rule(\"complexity-regression\", \"medium\",\n             fix=\"Move the inner work out of the loop: build a set or dict once and look up in \"\n                 \"it, sort once before the loop, or fetch everything in one call instead of \"\n                 \"one per item.\")\ndef complexity_regression(ctx):\n    edited = [c for c in ctx.changes if c.kind in (\"body\", \"signature\")\n              and c.after is not None and c.after.kind in (\"function\", \"method\")\n              and not c.after.lang]\n    if not edited:\n        return\n    now = _Project(ctx.after, ctx.graph)\n    then = None\n    for c in edited:\n        after = now.own(c.name)\n        if after is None or after.degree < 2:\n            continue\n        if then is None:\n            then = _Project(ctx.before, old_graph(ctx))\n        before = then.own(c.before.name)\n        if before is None or after.rank <= before.rank:\n            continue\n        severity = \"high\" if after.degree >= 3 and after.degree - before.degree >= 2 else \"medium\"\n        yield Finding(\n            \"complexity-regression\", severity,\n            f\"{c.after.short}() went from {before.notation()} to {after.notation()}: its work \"\n            f\"now grows {'with the square' if after.degree == 2 else 'faster than the square'} \"\n            f\"of its input\",\n            c.after.path, c.after.line,\n            detail=(f\"It now {after.why}. At 10,000 items that is about \"\n                    f\"{_steps(after.degree, after.log)} steps where it used to be about \"\n                    f\"{_steps(before.degree, before.log)}: fine in a test, slow or timing \"\n                    f\"out on real data. Estimated from the shape of the code, not measured.\"))\n", "magellan_lite/rules/dates.py": "\"\"\"leap-day-date: a date rebuilt with another year, which fails on February 29.\n\nWindows Azure, February 29 2012: every new VM's guest agent made a certificate valid until\n\"the same date next year\" by adding one to the year. February 29 2013 does not exist, the\ncertificate could not be created, and the failure cascaded through Azure's clusters for 34\nhours.\n\nPython fails the same way: ``date(2025, 2, 29)`` raises ValueError. So\n``d.replace(year=d.year + 1)`` and ``date(d.year + 1, d.month, d.day)`` (or the same with\nkeywords, ``date(year=..., month=..., day=...)``) pass every test on every day but one in\nfour years. Quiet when the year moves by a multiple of 4 (a leap year again), when the month\nis a fixed one other than February, inside a ``try`` that catches ValueError, and in a\nfunction that already deals with the day: it compares something with 29 or a ``.month``\nwith 2, or asks ``isleap`` or ``monthrange``. Date libraries that add a year for you\n(``relativedelta(years=1)``, arrow's and pendulum's ``.shift(years=1)``) fall back to\nFebruary 28 by themselves, and are left alone.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\n\nfrom magellan_lite.findings import rule\n\n_CONSTRUCTORS = {\"date\", \"datetime\"}\n_CATCHES = {\"ValueError\", \"Exception\", \"BaseException\"}\n_LEAP_AWARE = {\"isleap\", \"monthrange\", \"leapdays\"}\n\n\ndef _year_offset(expr: ast.expr | None):\n    \"\"\"``x.year + n``, ``n + x.year`` or ``x.year - n``: the offset (an int, or the\n    expression when it is not a number); ``None`` when ``expr`` is not a year moved.\"\"\"\n    if not isinstance(expr, ast.BinOp) or not isinstance(expr.op, (ast.Add, ast.Sub)):\n        return None\n    is_year = lambda e: isinstance(e, ast.Attribute) and e.attr == \"year\"   # noqa: E731\n    if is_year(expr.left):\n        n = expr.right\n    elif is_year(expr.right) and isinstance(expr.op, ast.Add):\n        n = expr.left\n    else:\n        return None\n    if isinstance(n, ast.Constant) and type(n.value) is int:\n        return n.value if isinstance(expr.op, ast.Add) else -n.value\n    return n\n\n\ndef _arg(call: ast.Call, index: int, name: str) -> ast.expr | None:\n    if len(call.args) > index:\n        return call.args[index]\n    return next((k.value for k in call.keywords if k.arg == name), None)\n\n\ndef _risky(call: ast.Call):\n    \"\"\"The year offset when ``call`` keeps a date's month and day but moves its year.\"\"\"\n    func = call.func\n    if isinstance(func, ast.Attribute) and func.attr == \"replace\" and not call.args:\n        # d.replace(year=...): the keyword makes it a date's replace, not a string's. Setting\n        # the day or month too (day=28) picks a date that exists, unless it copies them.\n        for k in call.keywords:\n            if k.arg in (\"day\", \"month\") and not (isinstance(k.value, ast.Attribute)\n                                                  and k.value.attr == k.arg):\n                return None\n        return _year_offset(next((k.value for k in call.keywords if k.arg == \"year\"), None))\n    name = func.id if isinstance(func, ast.Name) else func.attr if isinstance(func, ast.Attribute) else \"\"\n    # date(d.year + 1, d.month, d.day), or with keywords: date(year=..., month=..., day=...)\n    day, month = _arg(call, 2, \"day\"), _arg(call, 1, \"month\")\n    if isinstance(month, ast.Constant) and month.value != 2:\n        return None             # not February: that month has the same days every year\n    if name in _CONSTRUCTORS and isinstance(day, ast.Attribute) and day.attr == \"day\":\n        return _year_offset(_arg(call, 0, \"year\"))\n    return None\n\n\ndef _handles_leap_day(scope: ast.AST) -> bool:\n    \"\"\"Does this function already think about February 29?\"\"\"\n    for node in ast.walk(scope):\n        if isinstance(node, ast.Compare):\n            parts = [node.left, *node.comparators]\n            numbers = {p.value for p in parts if isinstance(p, ast.Constant)}\n            if 29 in numbers:\n                return True\n            if 2 in numbers and any(isinstance(p, ast.Attribute) and p.attr == \"month\" for p in parts):\n                return True\n        if isinstance(node, ast.Call):\n            f = node.func\n            if (f.id if isinstance(f, ast.Name) else getattr(f, \"attr\", \"\")) in _LEAP_AWARE:\n                return True\n    return False\n\n\ndef _catches_value_error(handler: ast.ExceptHandler) -> bool:\n    if handler.type is None:\n        return True\n    types = handler.type.elts if isinstance(handler.type, ast.Tuple) else [handler.type]\n    return any((t.id if isinstance(t, ast.Name) else getattr(t, \"attr\", \"\")) in _CATCHES\n               for t in types)\n\n\ndef _walk(node: ast.AST, scope: ast.AST, guarded: bool):\n    \"\"\"Every call, with the function it is in and whether a try around it catches\n    ValueError.\"\"\"\n    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):\n        scope, guarded = node, False\n    if isinstance(node, ast.Call):\n        yield node, scope, guarded\n    if isinstance(node, ast.Try):\n        caught = guarded or any(_catches_value_error(h) for h in node.handlers)\n        for child in node.body:\n            yield from _walk(child, scope, caught)\n        for child in [*node.handlers, *node.orelse, *node.finalbody]:\n            yield from _walk(child, scope, guarded)\n        return\n    for child in ast.iter_child_nodes(node):\n        yield from _walk(child, scope, guarded)\n\n\n@rule(\"leap-day-date\", \"high\", blocking=True,\n      fix=\"Add a timedelta instead (days=365), or handle February 29 yourself (fall back to \"\n          \"February 28).\")\ndef leap_day_date(tree: ast.Module, path: str):\n    for call, scope, guarded in _walk(tree, tree, False):\n        offset = _risky(call)\n        if offset is None or guarded or (isinstance(offset, int) and offset % 4 == 0):\n            continue\n        if _handles_leap_day(scope):\n            continue\n        if isinstance(offset, int):\n            n = abs(offset)\n            when = (f\"{'a year' if n == 1 else f'{n} years'} \"\n                    f\"{'later' if offset > 0 else 'earlier'} there is no February 29\")\n        else:\n            when = f\"{ast.unparse(offset)} years later there may be no February 29\"\n        yield (call, f\"`{ast.unparse(call)}` raises ValueError on February 29: {when}\",\n               \"It works on every other day, so every test passes. Windows Azure, 2012: \"\n               \"certificates dated this way failed on leap day and took services down for \"\n               \"34 hours.\")\n", "magellan_lite/rules/deadcode.py": "\"\"\"Code that can never run, in what the change touched.\n\nFrom the full Magellan (``rule_unreachable_statements`` and ``rule_constant_condition`` in\n``magellan/python/rules/reachability.py``). New code that never runs is a change that does\nnot do what it looks like it does: the logging added after a ``return``, the cleanup after a\n``raise``, a branch switched off with ``if False:`` while debugging and committed that way.\n\n* ``unreachable-code``: statements after a ``return``, ``raise``, ``break`` or ``continue`` in\n  the same block. (C's ``goto fail`` kind is ``unreachable-statement``, a C rule.) Left\n  alone: ``return`` followed by ``yield`` (the idiom that makes an empty generator), and\n  leftovers that do nothing (``pass``, ``...``).\n* ``constant-condition``: an ``if`` or ``while`` whose condition is a literal, so one side\n  never runs -- ``if False:``, ``if 0:``, ``while False:``, or the ``else`` of ``if True:``.\n  ``while True:`` is a loop on purpose, and is never reported.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\n\nfrom magellan_lite.findings import rule\n\n_TERMINATORS = {ast.Return: \"return\", ast.Raise: \"raise\", ast.Break: \"break\",\n                ast.Continue: \"continue\"}\n\n\ndef _inert(stmt: ast.stmt) -> bool:\n    return isinstance(stmt, ast.Pass) or (isinstance(stmt, ast.Expr)\n                                          and isinstance(stmt.value, ast.Constant))\n\n\n@rule(\"unreachable-code\", \"medium\",\n      fix=\"Move the statements above the line that leaves the block, or delete them.\")\ndef unreachable_code(tree: ast.Module, path: str):\n    for node in ast.walk(tree):\n        for field in (\"body\", \"orelse\", \"finalbody\"):\n            block = getattr(node, field, None)\n            if not isinstance(block, list):\n                continue\n            for i, stmt in enumerate(block[:-1]):\n                kind = _TERMINATORS.get(type(stmt))\n                if kind is None:\n                    continue\n                rest = block[i + 1:]\n                if all(_inert(s) for s in rest):\n                    break\n                if any(isinstance(n, (ast.Yield, ast.YieldFrom)) for s in rest\n                       for n in ast.walk(s)):\n                    break                       # `return` then `yield`: an empty generator\n                yield (rest[0],\n                       f\"line {rest[0].lineno} never runs: the {kind} on line {stmt.lineno} \"\n                       f\"leaves the block first\",\n                       f\"Everything after a {kind} in the same block is skipped every time\"\n                       + (f\" ({len(rest)} statements here)\" if len(rest) > 1 else \"\")\n                       + \". If this change added it, the change does not do what it looks \"\n                         \"like it does.\")\n                break\n\n\ndef _literal(test: ast.AST):\n    \"\"\"``(True, value)`` for a literal condition (numbers, True/False/None), else ``(False,\n    None)``. Strings and ``...`` are left alone: nobody writes them as a switch.\"\"\"\n    if isinstance(test, ast.Constant) and not isinstance(test.value, (str, bytes)) \\\n            and test.value is not Ellipsis:\n        return True, test.value\n    return False, None\n\n\n@rule(\"constant-condition\", \"low\",\n      fix=\"Put back the condition that was meant, or remove the branch that can never run.\")\ndef constant_condition(tree: ast.Module, path: str):\n    for node in ast.walk(tree):\n        if not isinstance(node, (ast.If, ast.While)):\n            continue\n        literal, value = _literal(node.test)\n        if not literal:\n            continue\n        written = ast.unparse(node.test)\n        keyword = \"if\" if isinstance(node, ast.If) else \"while\"\n        if not value:\n            yield (node, f\"the body of `{keyword} {written}:` never runs\",\n                   \"The condition is a literal that is always false, so the code under it is \"\n                   \"switched off -- often a debugging change that was committed.\")\n        elif isinstance(node, ast.If) and node.orelse:\n            yield (node.orelse[0], f\"the else of `if {written}:` never runs\",\n                   \"The condition is a literal that is always true, so the other branch is \"\n                   \"dead code.\")\n", "magellan_lite/rules/debug_leftover.py": "\"\"\"debug-leftover: print(), breakpoint() and pdb.set_trace() left in changed code.\n\nWhy it matters: a stray breakpoint() hangs a server waiting for a debugger nobody attached;\na stray print() fills logs or corrupts output another program reads.\n\nBut print() is also how a command-line tool talks to its user, so it is left alone where it\nis the program's output: in a file that is a command-line program (named cli.py or\n__main__.py, or with an ``if __name__ == \"__main__\":`` block, a ``main()`` function or an\nargparse command line), inside a function whose name says it prints (``main``,\n``print_report``, ``show_usage``), and when it says where it writes\n(``print(..., file=sys.stderr)``).\n\"\"\"\n\nimport ast\nimport re\n\nfrom magellan_lite.findings import rule  # noqa: F401\n\n#: a file with one of these names is a program's entry point\n_PROGRAM_FILES = {\"cli.py\", \"__main__.py\"}\n#: modules that read a command line: a file that imports one is a command-line program\n_COMMAND_LINE = {\"argparse\", \"optparse\", \"getopt\", \"click\", \"typer\"}\n#: words in a function's name that say printing is its job\n_OUTPUT_WORDS = {\"main\", \"cli\", \"print\", \"pprint\", \"show\", \"display\", \"output\", \"echo\",\n                 \"report\", \"dump\", \"usage\", \"help\", \"banner\"}\n\n\ndef _is_main_check(test: ast.expr) -> bool:\n    \"\"\"``__name__ == \"__main__\"``, either way round.\"\"\"\n    if not (isinstance(test, ast.Compare) and len(test.comparators) == 1):\n        return False\n    sides = [test.left, test.comparators[0]]\n    return (any(isinstance(s, ast.Name) and s.id == \"__name__\" for s in sides)\n            and any(isinstance(s, ast.Constant) and s.value == \"__main__\" for s in sides))\n\n\ndef _is_program(tree: ast.Module, path: str) -> bool:\n    \"\"\"Is this file a command-line program, whose print() calls are its output?\"\"\"\n    if path.rsplit(\"/\", 1)[-1] in _PROGRAM_FILES:\n        return True\n    for node in tree.body:\n        if isinstance(node, ast.If) and _is_main_check(node.test):\n            return True\n        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == \"main\":\n            return True\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Import):\n            if any(a.name.split(\".\")[0] in _COMMAND_LINE for a in node.names):\n                return True\n        elif isinstance(node, ast.ImportFrom) and node.level == 0:\n            if (node.module or \"\").split(\".\")[0] in _COMMAND_LINE:\n                return True\n    return False\n\n\ndef _prints_by_name(name: str) -> bool:\n    \"\"\"``print_report``, ``showUsage``, ``main``: a name that says it prints.\"\"\"\n    words = re.findall(r\"[A-Z]?[a-z]+|[A-Z]+(?![a-z])\", name)\n    return any(w.lower() in _OUTPUT_WORDS for w in words)\n\n\n@rule(\"debug-leftover\", \"low\", fix=\"Remove it before committing (use logging for output).\")\ndef debug_leftover(tree: ast.Module, path: str):\n    # 1. a command-line program: its print() calls are what it is for\n    program = _is_program(tree, path)\n\n    # 2. where else print() is fine: inside functions whose name says they print, and inside\n    #    `if __name__ == \"__main__\":` blocks wherever they are\n    output_spans = []\n    for node in ast.walk(tree):\n        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and _prints_by_name(node.name):\n            output_spans.append((node.lineno, node.end_lineno))\n        elif isinstance(node, ast.If) and _is_main_check(node.test):\n            output_spans.append((node.lineno, node.end_lineno))\n\n    # 3. every call: is it one of the debugging leftovers?\n    for node in ast.walk(tree):\n        if not isinstance(node, ast.Call):\n            continue                      # not a call: skip to the next node\n        func = node.func\n        if isinstance(func, ast.Name) and func.id == \"breakpoint\":\n            yield node, \"breakpoint() left in\"\n        elif isinstance(func, ast.Name) and func.id == \"print\":\n            if program or any(k.arg == \"file\" for k in node.keywords):\n                continue                  # the program's output, or written somewhere on purpose\n            if not any(start <= node.lineno <= end for start, end in output_spans):\n                yield node, \"print() left in\"\n        elif (isinstance(func, ast.Attribute) and func.attr == \"set_trace\"\n              and isinstance(func.value, ast.Name) and func.value.id in (\"pdb\", \"ipdb\")):\n            yield node, \"pdb.set_trace() left in\"\n", "magellan_lite/rules/defaults.py": "\"\"\"Mutable default arguments: the example rule. Copy its shape for a new one.\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\n\nfrom magellan_lite.findings import rule\n\n_MUTABLE_CALLS = {\"list\", \"dict\", \"set\", \"bytearray\", \"defaultdict\", \"deque\", \"OrderedDict\"}\n\n\ndef _is_mutable(node: ast.expr) -> bool:\n    if isinstance(node, (ast.List, ast.Dict, ast.Set, ast.ListComp, ast.DictComp, ast.SetComp)):\n        return True\n    if isinstance(node, ast.Call):\n        name = node.func.id if isinstance(node.func, ast.Name) else \\\n            node.func.attr if isinstance(node.func, ast.Attribute) else \"\"\n        return name in _MUTABLE_CALLS\n    return False\n\n\n@rule(\"mutable-default-argument\", \"medium\",\n      fix=\"Default to None and build the container inside the function.\")\ndef mutable_default_argument(tree: ast.Module, path: str):\n    for fn in ast.walk(tree):\n        if not isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):\n            continue\n        defaults = fn.args.defaults + [d for d in fn.args.kw_defaults if d is not None]\n        for d in defaults:\n            if _is_mutable(d):\n                name = getattr(fn, \"name\", \"lambda\")\n                yield (d, f\"{name}() has a mutable default argument `{ast.unparse(d)}`\",\n                       \"It is created once, when the function is defined, and every call \"\n                       \"that leaves the argument out shares it: state leaks between calls.\")\n", "magellan_lite/rules/deps.py": "\"\"\"Dependencies: imports the project's manifests do not back up.\n\nFrom the full Magellan (``magellan/rules/deps.py``). Every ``import requests`` leans on\nsomething you do not own, and the manifests (``pyproject.toml``, ``requirements*.txt``,\n``setup.py``, ``setup.cfg``, ``Pipfile``) say what a fresh install will get. Two ways they\ndisagree break a deploy while working fine on the author's machine:\n\n* ``dependency-undeclared``: the change adds an import of a package no manifest declares. It\n  imports on a machine that happens to have it, and fails with ModuleNotFoundError in CI, on\n  a colleague's machine, on the server.\n* ``dependency-removed-still-used``: the change takes a package out of the manifest while the\n  code still imports it. Fresh installs stop getting it; the import fails at startup.\n\nManifests are files, not source, so these rules read them from disk: only when the check is\non a real project (``magellan-lite check``, the editor), never for code handed over as text.\nThe old manifests come from git (``--against git:REV``) or the baseline directory.\n``pyproject.toml`` is read with ``tomllib`` on Python 3.11+, and with a small reader of the\ndependency tables on 3.10. Imports that may fail on purpose (inside ``try: ... except\nImportError``, under ``if TYPE_CHECKING:``) are left alone, and when a manifest cannot be read\nfor sure (dependencies computed in ``setup.py``, a conda ``environment.yml``) the rules stay\nquiet rather than guess.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nimport configparser\nimport os\nimport re\nimport sys\nfrom dataclasses import dataclass, field\nfrom functools import cached_property\nfrom pathlib import Path\n\nfrom magellan_lite.findings import Finding, change_rule\nfrom magellan_lite.rules.common import (baseline, changed_files, git, is_test_path, on_disk,\n                                        under_import_guard)\nfrom magellan_lite.source import is_skipped_dir, module_name\n\n_MANIFEST = re.compile(r\"(^|/)(pyproject\\.toml|requirements[\\w.-]*\\.(txt|in)|requirements/[\\w.-]+\"\n                       r\"\\.(txt|in)|setup\\.py|setup\\.cfg|Pipfile|environment\\.ya?ml)$\")\n_SKIP = {\"node_modules\", \"venv\", \"env\", \"build\", \"dist\", \"site-packages\", \"__pycache__\"}\n\n#: import name -> distribution name, for the common ones that differ\nPY_ALIASES = {\n    \"pil\": \"pillow\", \"yaml\": \"pyyaml\", \"sklearn\": \"scikit-learn\", \"cv2\": \"opencv-python\",\n    \"bs4\": \"beautifulsoup4\", \"dateutil\": \"python-dateutil\", \"dotenv\": \"python-dotenv\",\n    \"jwt\": \"pyjwt\", \"openssl\": \"pyopenssl\", \"attr\": \"attrs\", \"git\": \"gitpython\",\n    \"serial\": \"pyserial\", \"crypto\": \"pycryptodome\", \"magic\": \"python-magic\",\n    \"mysqldb\": \"mysqlclient\", \"psycopg2\": \"psycopg2-binary\", \"skimage\": \"scikit-image\",\n    \"docx\": \"python-docx\", \"zmq\": \"pyzmq\", \"usb\": \"pyusb\", \"gi\": \"pygobject\",\n    \"ruamel\": \"ruamel-yaml\", \"socks\": \"pysocks\", \"faiss\": \"faiss-cpu\",\n    \"google\": \"google-api-python-client\", \"multipart\": \"python-multipart\",\n    \"jose\": \"python-jose\", \"slugify\": \"python-slugify\", \"telegram\": \"python-telegram-bot\",\n    \"pkg_resources\": \"setuptools\",\n}\n#: where imports are tooling, not the product: a missing declaration breaks CI, not a deploy\n_TOOLING_DIRS = {\"docs\", \"doc\", \"scripts\", \"tools\", \"examples\", \"benchmarks\", \"bench\"}\n_TOOLING_FILES = {\"setup.py\", \"noxfile.py\", \"tasks.py\", \"fabfile.py\", \"conftest.py\"}\n#: standard-library modules of earlier Pythons that this interpreter no longer lists\n_PAST_STDLIB = frozenset(\"\"\"\n    imp distutils asyncore asynchat smtpd cgi cgitb crypt imghdr pipes telnetlib nntplib\n    audioop uu xdrlib msilib nis ossaudiodev spwd sndhdr sunau chunk mailcap lib2to3 binhex\n    formatter parser symbol macpath dummy_threading urllib2 urlparse httplib cookielib Cookie\n    HTMLParser htmlentitydefs xmlrpclib SimpleXMLRPCServer BaseHTTPServer SimpleHTTPServer\n    CGIHTTPServer SocketServer ConfigParser Queue StringIO cStringIO cPickle copy_reg repr\n    anydbm commands sets md5 sha new mimetools rfc822 thread exceptions __builtin__ Tkinter\n    tkMessageBox ttk UserDict UserList UserString robotparser\n\"\"\".split())\n_STDLIB = frozenset(getattr(sys, \"stdlib_module_names\", ())) | _PAST_STDLIB | {\"__future__\"}\n\n\ndef norm(name: str) -> str:\n    return re.sub(r\"[-_.]+\", \"-\", name.strip()).lower()\n\n\n# -- reading manifests ----------------------------------------------------------------------\n@dataclass\nclass Manifests:\n    declared: dict[str, str] = field(default_factory=dict)    # normalized name -> manifest\n    found: list[str] = field(default_factory=list)            # manifest paths that declare\n    certain: bool = True        # False: some manifest computes its list; do not judge by it\n\n\n_REQ = re.compile(r\"^\\s*([A-Za-z0-9][A-Za-z0-9._-]*)\")\n\n\ndef _requirement(text: str) -> str | None:\n    t = text.strip()\n    if not t or t.startswith((\"#\", \"-\", \"git+\", \"http\", \".\", \"/\")):\n        return None\n    if \" @ \" in t:                                  # name @ git+https://...\n        t = t.split(\" @ \", 1)[0]\n    m = _REQ.match(t)\n    return norm(m.group(1)) if m else None\n\n\ndef _read_toml(text: str) -> dict | None:\n    try:\n        import tomllib                              # Python 3.11+\n    except ImportError:\n        return _mini_toml(text)\n    try:\n        return tomllib.loads(text)\n    except (ValueError, TypeError):\n        return None\n\n\ndef _mini_toml(text: str) -> dict | None:\n    \"\"\"Just enough TOML for dependency tables, for Python 3.10: ``[a.b]`` headers, and keys\n    whose value is a string, an array of strings (over several lines) or an inline table of\n    strings. Anything else is skipped.\"\"\"\n    data: dict = {}\n    table: dict | None = data\n    lines = text.splitlines()\n    i = 0\n    while i < len(lines):\n        line = lines[i].strip()\n        i += 1\n        if not line or line.startswith(\"#\"):\n            continue\n        if line.startswith(\"[[\"):\n            table = None                            # an array of tables: not needed here\n            continue\n        if line.startswith(\"[\"):\n            table = data\n            for part in _keys(line.strip(\"[] \\t\")):\n                table = table.setdefault(part, {})\n                if not isinstance(table, dict):\n                    table = None\n                    break\n            continue\n        if table is None or \"=\" not in line:\n            continue\n        key, value = line.split(\"=\", 1)\n        value = value.strip()\n        if value.startswith(\"[\"):\n            while _depth(value) > 0 and i < len(lines):\n                value += \"\\n\" + lines[i]\n                i += 1\n            parsed = _strings(value)\n        elif value.startswith(\"{\"):\n            parsed = dict(re.findall(r\"\"\"([\\w-]+)\\s*=\\s*[\"']([^\"']*)[\"']\"\"\", value))\n        elif value[:1] in \"\\\"'\":\n            found = _strings(value)\n            parsed = found[0] if found else \"\"\n        else:\n            continue\n        keys = _keys(key.strip())\n        target = table\n        for part in keys[:-1]:\n            target = target.setdefault(part, {})\n            if not isinstance(target, dict):\n                break\n        else:\n            target[keys[-1]] = parsed\n    return data\n\n\ndef _keys(dotted: str) -> list[str]:\n    return [k.strip().strip(\"\\\"'\") for k in dotted.split(\".\")]\n\n\ndef _strings(value: str) -> list[str]:\n    return [a or b for a, b in re.findall(r'\"([^\"]*)\"|\\'([^\\']*)\\'', _no_comments(value))]\n\n\ndef _no_comments(value: str) -> str:\n    \"\"\"Drop ``# ...`` comments that are not inside a string.\"\"\"\n    out, quote = [], \"\"\n    for line in value.splitlines():\n        keep = []\n        for ch in line:\n            if quote:\n                quote = \"\" if ch == quote else quote\n            elif ch in \"\\\"'\":\n                quote = ch\n            elif ch == \"#\":\n                break\n            keep.append(ch)\n        out.append(\"\".join(keep))\n        quote = \"\"\n    return \"\\n\".join(out)\n\n\ndef _depth(value: str) -> int:\n    text = _no_comments(value)\n    text = re.sub(r'\"[^\"]*\"|\\'[^\\']*\\'', \"\", text)\n    return text.count(\"[\") - text.count(\"]\")\n\n\ndef _pyproject(text: str, path: str, m: Manifests) -> None:\n    data = _read_toml(text)\n    if data is None:\n        m.certain = False\n        return\n    project = data.get(\"project\") if isinstance(data.get(\"project\"), dict) else {}\n    poetry = (data.get(\"tool\") or {}).get(\"poetry\") if isinstance(data.get(\"tool\"), dict) else None\n    groups = data.get(\"dependency-groups\") if isinstance(data.get(\"dependency-groups\"), dict) else {}\n    lists: list = []\n    if project:\n        lists.append(project.get(\"dependencies\") or [])\n        lists += list((project.get(\"optional-dependencies\") or {}).values())\n        if \"dependencies\" in (project.get(\"dynamic\") or []):\n            m.certain = False                       # setuptools fills it in from elsewhere\n        if isinstance(project.get(\"name\"), str):\n            m.declared.setdefault(norm(project[\"name\"]), path)\n    lists += list(groups.values())\n    build = data.get(\"build-system\") if isinstance(data.get(\"build-system\"), dict) else {}\n    lists.append(build.get(\"requires\") or [])\n    for entries in lists:\n        for entry in entries if isinstance(entries, list) else []:\n            if isinstance(entry, str) and (name := _requirement(entry)):\n                m.declared.setdefault(name, path)\n    if isinstance(poetry, dict):\n        tables = [poetry.get(\"dependencies\") or {}, poetry.get(\"dev-dependencies\") or {}]\n        tables += [g.get(\"dependencies\") or {} for g in (poetry.get(\"group\") or {}).values()\n                   if isinstance(g, dict)]\n        for table in tables:\n            for name in table if isinstance(table, dict) else []:\n                if name.lower() != \"python\":\n                    m.declared.setdefault(norm(name), path)\n    if project or poetry or groups:\n        m.found.append(path)\n\n\ndef _setup_py(text: str, path: str, m: Manifests) -> None:\n    try:\n        tree = ast.parse(text)\n    except (SyntaxError, ValueError):\n        m.certain = False\n        return\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Call):\n            for kw in node.keywords:\n                if kw.arg in (\"install_requires\", \"extras_require\", \"tests_require\"):\n                    try:\n                        value = ast.literal_eval(kw.value)\n                    except (ValueError, SyntaxError, TypeError):\n                        m.certain = False           # computed: cannot be read for sure\n                        continue\n                    lists = value.values() if isinstance(value, dict) else [value]\n                    for entries in lists:\n                        for entry in [entries] if isinstance(entries, str) else entries:\n                            if isinstance(entry, str) and (name := _requirement(entry)):\n                                m.declared.setdefault(name, path)\n                    m.found.append(path)\n\n\ndef _setup_cfg(text: str, path: str, m: Manifests) -> None:\n    cfg = configparser.ConfigParser(interpolation=None)\n    try:\n        cfg.read_string(text)\n    except configparser.Error:\n        m.certain = False\n        return\n    values = []\n    if cfg.has_option(\"options\", \"install_requires\"):\n        values.append(cfg.get(\"options\", \"install_requires\"))\n    if cfg.has_section(\"options.extras_require\"):\n        values += [v for _k, v in cfg.items(\"options.extras_require\")]\n    for value in values:\n        for line in value.splitlines():\n            if name := _requirement(line):\n                m.declared.setdefault(name, path)\n    if values:\n        m.found.append(path)\n\n\ndef parse_manifests(files: dict[str, str]) -> Manifests:\n    \"\"\"What ``{path: text}`` of manifest files declares, all of them together.\"\"\"\n    m = Manifests()\n    for path, text in sorted(files.items()):\n        base = path.rsplit(\"/\", 1)[-1]\n        if base == \"pyproject.toml\":\n            _pyproject(text, path, m)\n        elif base.startswith(\"requirements\") or f\"/{path}\".count(\"/requirements/\"):\n            for line in text.splitlines():\n                if name := _requirement(line.split(\";\", 1)[0]):\n                    m.declared.setdefault(name, path)\n            m.found.append(path)\n        elif base == \"setup.py\":\n            _setup_py(text, path, m)\n        elif base == \"setup.cfg\":\n            _setup_cfg(text, path, m)\n        elif base == \"Pipfile\":\n            data = _read_toml(text) or {}\n            for table in (\"packages\", \"dev-packages\"):\n                for name in data.get(table) or {}:\n                    m.declared.setdefault(norm(name), path)\n            m.found.append(path)\n        elif base.startswith(\"environment.\"):\n            m.certain = False                       # conda: other names, other channels\n    return m\n\n\ndef manifests_on_disk(root: Path) -> dict[str, str]:\n    out: dict[str, str] = {}\n    for dirpath, dirnames, filenames in os.walk(root):\n        dirnames[:] = sorted(d for d in dirnames if d not in _SKIP and not is_skipped_dir(d))\n        for name in filenames:\n            rel = Path(dirpath, name).relative_to(root).as_posix()\n            if _MANIFEST.search(rel):\n                try:\n                    out[rel] = (Path(dirpath) / name).read_text(encoding=\"utf-8\",\n                                                                errors=\"replace\")\n                except OSError:\n                    pass\n    return out\n\n\ndef manifests_at(root: Path, rev: str) -> dict[str, str] | None:\n    \"\"\"The manifests under ``root`` as they were at git revision ``rev``; None if unknown.\"\"\"\n    top = git(root, \"rev-parse\", \"--show-toplevel\")\n    if top is None:\n        return None\n    try:\n        prefix = root.resolve().relative_to(Path(top.strip()).resolve()).as_posix()\n    except ValueError:\n        return None\n    prefix = \"\" if prefix == \".\" else prefix + \"/\"\n    listing = git(Path(top.strip()), \"ls-tree\", \"-r\", \"--full-tree\", \"--name-only\", rev)\n    if listing is None:\n        return None\n    out: dict[str, str] = {}\n    for line in listing.splitlines():\n        if not line.startswith(prefix):\n            continue\n        rel = line[len(prefix):]\n        if any(part in _SKIP or is_skipped_dir(part) for part in rel.split(\"/\")[:-1]):\n            continue\n        if _MANIFEST.search(rel):\n            text = git(Path(top.strip()), \"show\", f\"{rev}:{line}\")\n            if text is None:\n                return None\n            out[rel] = text\n    return out\n\n\n# -- imports ----------------------------------------------------------------------------------\n_dists: dict[str, list[str]] | None = None\n\n\ndef _installed(import_name: str) -> list[str]:\n    \"\"\"The installed distributions that provide an import name (this environment's view).\"\"\"\n    global _dists\n    if _dists is None:\n        try:\n            from importlib.metadata import packages_distributions\n            _dists = {k: [norm(x) for x in v] for k, v in packages_distributions().items()}\n        except Exception:                               # noqa: BLE001 - only a hint\n            _dists = {}\n    return _dists.get(import_name, [])\n\n\ndef declared_as(import_root: str, declared: dict[str, str]) -> str | None:\n    \"\"\"The declared distribution that provides ``import_root``, if any.\"\"\"\n    low = norm(import_root)\n    candidates = {low, norm(PY_ALIASES.get(import_root.lower(), low)), *_installed(import_root)}\n    for c in candidates:\n        if c in declared:\n            return c\n    for name in declared:                              # namespaces: google-cloud-*, azure-*\n        if name.startswith(low + \"-\") or low.startswith(name + \"-\"):\n            return name\n    return None\n\n\ndef imports(snapshot, paths=None) -> dict[str, list[tuple[str, int]]]:\n    \"\"\"``{top-level module: [(path, line)]}`` for every absolute import in ``paths`` (default:\n    every file) that is not guarded (``try/except ImportError``, ``if TYPE_CHECKING``).\"\"\"\n    out: dict[str, list[tuple[str, int]]] = {}\n    for path in sorted(snapshot.files if paths is None else paths):\n        tree = snapshot.tree(path) if path.endswith(\".py\") and path in snapshot.files else None\n        if tree is None:\n            continue\n        guarded = under_import_guard(tree)\n        for node in ast.walk(tree):\n            if not isinstance(node, (ast.Import, ast.ImportFrom)) or node.lineno in guarded:\n                continue\n            if isinstance(node, ast.Import):\n                roots = [a.name.split(\".\")[0] for a in node.names]\n            elif isinstance(node, ast.ImportFrom) and not node.level and node.module:\n                roots = [node.module.split(\".\")[0]]\n            else:\n                continue\n            for r in roots:\n                out.setdefault(r, []).append((path, node.lineno))\n    return out\n\n\ndef _internal(*snapshots) -> set[str]:\n    \"\"\"Names the project's own code can be imported by: every module and directory name.\"\"\"\n    out: set[str] = set()\n    for snap in snapshots:\n        for path in snap.files:\n            parts = path.split(\"/\")\n            out |= set(parts[:-1])\n            out.add(parts[-1].rsplit(\".\", 1)[0])\n            if path.endswith(\".py\"):\n                out.add(module_name(path).split(\".\")[0])\n    return out\n\n\ndef _third_party(name: str, internal: set[str]) -> bool:\n    return name not in _STDLIB and name not in internal and not name.startswith(\"_\")\n\n\nclass _State:\n    \"\"\"What both rules read, each part worked out once per check and only when asked.\"\"\"\n\n    def __init__(self, ctx, root: Path) -> None:\n        self.ctx, self.root = ctx, root\n\n    @cached_property\n    def now(self) -> Manifests:\n        return parse_manifests(manifests_on_disk(self.root))\n\n    @cached_property\n    def manifests_changed(self) -> bool:\n        \"\"\"Did any manifest change against the baseline? One cheap question before the\n        expensive ones.\"\"\"\n        base = baseline(self.ctx)\n        if base is None:\n            return False\n        if base[0] == \"git\":\n            changed = git(self.root, \"diff\", \"--name-only\", \"--relative\", base[1], \"--\", \".\")\n            return changed is not None and any(_MANIFEST.search(line.strip())\n                                               for line in changed.splitlines())\n        return manifests_on_disk(base[1]) != manifests_on_disk(self.root)\n\n    @cached_property\n    def old(self) -> Manifests | None:\n        base = baseline(self.ctx)\n        if base is None:\n            return None\n        files = manifests_at(self.root, base[1]) if base[0] == \"git\" \\\n            else manifests_on_disk(base[1])\n        return parse_manifests(files) if files is not None else None\n\n    @cached_property\n    def internal(self) -> set[str]:\n        return _internal(self.ctx.after, self.ctx.before)\n\n\ndef _state(ctx) -> _State | None:\n    if not hasattr(ctx, \"_lite_deps\"):\n        root = on_disk(ctx)\n        ctx._lite_deps = _State(ctx, root) if root is not None else None\n    return ctx._lite_deps\n\n\ndef _tooling(path: str) -> bool:\n    parts = path.split(\"/\")\n    return is_test_path(path) or parts[0] in _TOOLING_DIRS or parts[-1] in _TOOLING_FILES\n\n\ndef _where(sites: list[tuple[str, int]]) -> str:\n    files = sorted({p for p, _ in sites})\n    return files[0] if len(files) == 1 else f\"{files[0]} and {len(files) - 1} other file(s)\"\n\n\ndef _new_imports(ctx, state: _State) -> dict[str, list[tuple[str, int]]]:\n    \"\"\"Third-party imports this change adds: imported in an edited file now, and nowhere in\n    the old version.\"\"\"\n    changed = changed_files(ctx)\n    now = imports(ctx.after, [p for p in changed if p in ctx.after.files])\n    was = imports(ctx.before, [p for p in changed if p in ctx.before.files])\n    fresh = {n: s for n, s in now.items() if n not in was}\n    if not fresh:\n        return {}\n    fresh = {n: s for n, s in fresh.items() if _third_party(n, state.internal)}\n    untouched = [p for p in ctx.before.files if p.endswith(\".py\") and p not in changed]\n    for name in list(fresh):\n        mention = [p for p in untouched if name in ctx.before.files[p]]   # text first: cheap\n        if mention and name in imports(ctx.before, mention):\n            del fresh[name]\n    return fresh\n\n\n@change_rule(\"dependency-undeclared\", \"high\",\n             fix=\"Add it to the project's dependencies (pyproject.toml or requirements.txt), \"\n                 \"or import something the project already depends on.\")\ndef dependency_undeclared(ctx):\n    state = _state(ctx)\n    if state is None:\n        return\n    fresh = _new_imports(ctx, state)\n    if not fresh or not state.now.found or not state.now.certain:\n        return\n    now = state.now\n    for name, sites in sorted(fresh.items()):\n        if declared_as(name, now.declared) is not None:\n            continue\n        product = [s for s in sites if not _tooling(s[0])]\n        path, line = (product or sites)[0]\n        yield Finding(\n            \"dependency-undeclared\", \"high\" if product else \"medium\",\n            f\"{name} is imported in {_where(sites)} but no manifest declares it\",\n            path, line,\n            detail=(f\"It imports here because it happens to be installed on this machine. A \"\n                    f\"fresh install (CI, a colleague, the server) reads \"\n                    f\"{', '.join(now.found[:3])} and never installs {name}, so the import \"\n                    f\"fails with ModuleNotFoundError there.\"\n                    + (\"\" if product else \" Only tests or tooling import it, so it is CI \"\n                                          \"that breaks, not the product.\")))\n\n\n@change_rule(\"dependency-removed-still-used\", \"critical\", blocking=True,\n             fix=\"Put the dependency back, or remove the imports that still need it in the \"\n                 \"same change.\")\ndef dependency_removed_still_used(ctx):\n    state = _state(ctx)\n    if state is None or not state.manifests_changed:\n        return\n    now, old = state.now, state.old\n    if not now.found or not now.certain or old is None or not old.found or not old.certain:\n        return\n    gone = sorted(set(old.declared) - set(now.declared))\n    if not gone:\n        return\n    used = imports(ctx.after)\n    for dep in gone:\n        for name, sites in sorted(used.items()):\n            if not _third_party(name, state.internal) or declared_as(name, {dep: \"\"}) is None:\n                continue\n            path, line = sites[0]\n            yield Finding(\n                \"dependency-removed-still-used\", \"critical\",\n                f\"{dep} was removed from {old.declared[dep]}, but {_where(sites)} still \"\n                f\"imports {name}\",\n                path, line,\n                detail=(f\"Installs from the new manifest no longer get {dep}. On any fresh \"\n                        f\"machine `import {name}` fails with ModuleNotFoundError as soon as \"\n                        f\"this module is imported ({len(sites)} import(s) left).\"))\n", "magellan_lite/rules/envvars.py": "\"\"\"Environment variables: a contract with every deployment, and no import statement says so.\n\nFrom the full Magellan (``magellan/rules/envvars.py``). A function that reads\n``DATABASE_URL`` depends on whoever deploys it. Rename the variable, change its default or\nstart requiring it, and every server, container, CI job and colleague's ``.env`` that was\nfine yesterday fails -- or worse, quietly falls back to a default. The edit is one line; the\nfault shows up in a deployment nobody looked at.\n\n* ``env-var-renamed``: code that read one variable now reads another in its place. Everything\n  that sets the old name is silently ignored.\n* ``env-var-default-changed``: the fallback for a variable changed, or an optional variable\n  became required (``os.getenv(\"X\", \"d\")`` -> ``os.environ[\"X\"]``).\n\nReads are ``os.environ[...]``, ``os.environ.get(...)`` and ``os.getenv(...)`` (also imported\nas ``environ`` / ``getenv``), with the name written as a string or a module constant. Each read\nbelongs to the function that does it, or to the module constant it initialises. A read whose\nname is computed at run time is left alone.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nfrom dataclasses import dataclass\n\nfrom magellan_lite.findings import Finding, change_rule\nfrom magellan_lite.rules.common import callables, changed_files, dotted\nfrom magellan_lite.source import module_name\n\n\n@dataclass(frozen=True)\nclass Read:\n    var: str\n    reader: str            # the function, or module constant, that reads it\n    required: bool         # os.environ[...]: KeyError when unset\n    default: str           # the fallback as written (\"\" when none)\n    shape: str             # the fallback's syntax tree, so quoting never counts as a change\n    path: str\n    line: int\n\n\ndef _aliases(tree: ast.Module) -> dict[str, str]:\n    out: dict[str, str] = {}\n    for node in tree.body:\n        if isinstance(node, ast.Import):\n            for a in node.names:\n                out[a.asname or a.name.split(\".\")[0]] = a.name if a.asname else a.name.split(\".\")[0]\n        elif isinstance(node, ast.ImportFrom) and node.module and not node.level:\n            for a in node.names:\n                out[a.asname or a.name] = f\"{node.module}.{a.name}\"\n    return out\n\n\ndef _canonical(node: ast.AST, aliases: dict[str, str]) -> str:\n    name = dotted(node)\n    head, _, rest = name.partition(\".\")\n    if head in aliases:\n        return aliases[head] + (\".\" + rest if rest else \"\")\n    return name\n\n\ndef _strings(tree: ast.Module) -> dict[str, str]:\n    \"\"\"Module constants holding a string: ``KEY = \"API_URL\"`` lets ``getenv(KEY)`` be read.\"\"\"\n    out: dict[str, str] = {}\n    for node in tree.body:\n        if isinstance(node, ast.Assign) and isinstance(node.value, ast.Constant) \\\n                and isinstance(node.value.value, str):\n            out.update({t.id: node.value.value for t in node.targets if isinstance(t, ast.Name)})\n    return out\n\n\ndef _name(node: ast.AST | None, consts: dict[str, str]) -> str | None:\n    if isinstance(node, ast.Constant) and isinstance(node.value, str) and node.value:\n        return node.value\n    if isinstance(node, ast.Name) and node.id in consts:\n        return consts[node.id]\n    return None\n\n\ndef _reads_in(nodes, reader: str, path: str, aliases, consts) -> list[Read]:\n    out: list[Read] = []\n    for node in nodes:\n        if isinstance(node, ast.Subscript) and isinstance(node.ctx, ast.Load) \\\n                and _canonical(node.value, aliases) == \"os.environ\":\n            var = _name(node.slice, consts)\n            if var:\n                out.append(Read(var, reader, True, \"\", \"\", path, node.lineno))\n        elif isinstance(node, ast.Call) \\\n                and _canonical(node.func, aliases) in (\"os.environ.get\", \"os.getenv\"):\n            var = _name(node.args[0] if node.args else\n                        next((k.value for k in node.keywords if k.arg == \"key\"), None), consts)\n            if not var:\n                continue\n            default = node.args[1] if len(node.args) > 1 else next(\n                (k.value for k in node.keywords if k.arg == \"default\"), None)\n            out.append(Read(var, reader, False,\n                            ast.unparse(default) if default is not None else \"\",\n                            ast.dump(default) if default is not None else \"\",\n                            path, node.lineno))\n    return out\n\n\ndef env_reads(snapshot, paths=None) -> list[Read]:\n    \"\"\"Every environment variable read in the snapshot's Python files (or in ``paths``).\"\"\"\n    out: list[Read] = []\n    for path, text in sorted(snapshot.files.items()):\n        if not path.endswith(\".py\") or (\"environ\" not in text and \"getenv\" not in text)                 or (paths is not None and path not in paths):\n            continue\n        tree = snapshot.tree(path)\n        if tree is None:\n            continue\n        aliases, consts = _aliases(tree), _strings(tree)\n        if not any(v.startswith(\"os\") for v in aliases.values()):\n            continue\n        mod = module_name(path)\n        for name, fn, _cls in callables(tree, path):\n            out += _reads_in(ast.walk(fn), name, path, aliases, consts)\n\n        def top(body, prefix):\n            for stmt in body:\n                if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):\n                    continue\n                if isinstance(stmt, ast.ClassDef):\n                    top(stmt.body, f\"{prefix}.{stmt.name}\")\n                    continue\n                targets = stmt.targets if isinstance(stmt, ast.Assign) else \\\n                    [stmt.target] if isinstance(stmt, ast.AnnAssign) else []\n                named = [t.id for t in targets if isinstance(t, ast.Name)]\n                reader = f\"{prefix}.{named[0]}\" if len(named) == 1 else prefix\n                out.extend(_reads_in(ast.walk(stmt), reader, path, aliases, consts))\n        top(tree.body, mod)\n    return out\n\n\ndef _by_reader(reads: list[Read]) -> dict[str, dict[str, list[Read]]]:\n    out: dict[str, dict[str, list[Read]]] = {}\n    for r in reads:\n        out.setdefault(r.reader, {}).setdefault(r.var, []).append(r)\n    return out\n\n\ndef _state(ctx):\n    if not hasattr(ctx, \"_lite_env\"):\n        files = changed_files(ctx)\n        ctx._lite_env = None\n        if files:                                   # a reader in an untouched file is unchanged\n            ctx._lite_env = (_by_reader(env_reads(ctx.before, files)),\n                             _by_reader(env_reads(ctx.after, files)), files)\n    return ctx._lite_env\n\n\ndef _who(reader: str) -> str:\n    \"\"\"How a person names a reader: ``db()`` for a function, ``DB_URL`` for a constant.\"\"\"\n    short = reader.rsplit(\".\", 1)[-1]\n    return short if short.isupper() or \".\" not in reader else f\"{short}()\"\n\n\ndef _fallback(r: Read) -> str:\n    return \"raises KeyError where it is not set\" if r.required else (\n        f\"falls back to {r.default}\" if r.default else \"gets None where it is not set\")\n\n\n@change_rule(\"env-var-renamed\", \"high\",\n             fix=\"Read the old name as a fallback (`os.getenv(NEW) or os.getenv(OLD)`), or \"\n                 \"update every deployment that sets it in the same release.\")\ndef env_var_renamed(ctx):\n    state = _state(ctx)\n    if state is None:\n        return\n    before, after, files = state\n    read_before = None\n    for reader in sorted(set(before) & set(after)):\n        old, new = before[reader], after[reader]\n        lost = sorted(set(old) - set(new))\n        gained = sorted(set(new) - set(old))\n        if len(lost) != 1 or len(gained) != 1:\n            continue\n        if read_before is None:                     # was the new name in use already?\n            read_before = {r.var for r in env_reads(ctx.before)}\n        if gained[0] in read_before:\n            continue\n        r = new[gained[0]][0]\n        if r.path not in files:\n            continue\n        still = sorted({x.path for vars_ in after.values() for x in vars_.get(lost[0], [])})\n        yield Finding(\n            \"env-var-renamed\", \"high\",\n            f\"{_who(reader)} now reads the environment variable {gained[0]} instead of \"\n            f\"{lost[0]}\",\n            r.path, r.line,\n            detail=(f\"Every server, container, CI job and .env file that sets {lost[0]} is \"\n                    f\"now ignored here, and where {gained[0]} is not set yet the code \"\n                    f\"{_fallback(r)}. Nothing fails at the commit; it fails, or quietly \"\n                    f\"misbehaves, in the deployment.\"\n                    + (f\" {lost[0]} is still read in {', '.join(still[:3])}, so the two \"\n                       f\"places now disagree.\" if still else \"\")))\n\n\n@change_rule(\"env-var-default-changed\", \"medium\",\n             fix=\"Check that every deployment sets the variable explicitly, or keep the old \"\n                 \"default.\")\ndef env_var_default_changed(ctx):\n    state = _state(ctx)\n    if state is None:\n        return\n    before, after, files = state\n    for reader in sorted(set(before) & set(after)):\n        for var in sorted(set(before[reader]) & set(after[reader])):\n            old_variants = {(r.required, r.shape) for r in before[reader][var]}\n            new_variants = {(r.required, r.shape) for r in after[reader][var]}\n            if len(old_variants) != 1 or len(new_variants) != 1 or old_variants == new_variants:\n                continue\n            was, now = before[reader][var][0], after[reader][var][0]\n            if now.path not in files:\n                continue\n            if now.required and not was.required:\n                message = (f\"{_who(reader)} now requires the environment variable {var}: it \"\n                           f\"used to {'fall back to ' + was.default if was.default else 'get None'}\"\n                           f\" when it was not set\")\n                detail = (f\"Every environment that never set {var} -- because it did not \"\n                          f\"have to -- now raises KeyError here.\")\n            elif was.required or now.required:\n                continue                                # required -> optional: looser\n            else:\n                message = (f\"the default for the environment variable {var} changed in \"\n                           f\"{_who(reader)}: {was.default or 'None'} -> {now.default or 'None'}\")\n                detail = (f\"Every environment that does not set {var} now behaves \"\n                          f\"differently, without anyone editing its configuration.\")\n            yield Finding(\"env-var-default-changed\", \"medium\", message, now.path, now.line,\n                          detail=detail)\n", "magellan_lite/rules/exceptions.py": "\"\"\"swallowed-exception: a broad handler that throws the error away.\n\nFrom the full Magellan (``rule_swallowed_exception`` in ``magellan/rules/risk.py``).\n``except Exception: pass`` catches everything that can go wrong in the ``try`` -- a typo, a\nfailing disk, the bug this very change brings in -- and leaves no trace: no log, no failure,\njust wrong results later, found by someone else. ``with suppress(Exception):`` does the same.\n\nReported in code the change touched, when the handler catches ``Exception`` or\n``BaseException`` and does nothing (``pass``, ``continue``, ``...``). A handler for one\nspecific exception is a decision and is left alone; a bare ``except:`` is ``bare-except``.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\n\nfrom magellan_lite.findings import rule\nfrom magellan_lite.rules.common import call_name, dotted\n\n_BROAD = {\"Exception\", \"BaseException\"}\n\n\ndef _broad(node: ast.AST | None) -> bool:\n    if isinstance(node, ast.Tuple):\n        return any(_broad(e) for e in node.elts)\n    return node is not None and dotted(node).rsplit(\".\", 1)[-1] in _BROAD\n\n\ndef _does_nothing(body: list[ast.stmt]) -> bool:\n    return all(isinstance(s, (ast.Pass, ast.Continue)) or (\n        isinstance(s, ast.Expr) and isinstance(s.value, ast.Constant)) for s in body)\n\n\n@rule(\"swallowed-exception\", \"low\",\n      fix=\"Log it, catch only the exception you expect, or let it propagate.\")\ndef swallowed_exception(tree: ast.Module, path: str):\n    why = (\"Whatever goes wrong inside -- including a bug this change brings in -- disappears \"\n           \"without a trace: no log, no failure, just wrong results later.\")\n    for node in ast.walk(tree):\n        if isinstance(node, ast.ExceptHandler) and node.type is not None \\\n                and _broad(node.type) and _does_nothing(node.body):\n            first = ast.unparse(node.body[0]).splitlines()[0]\n            yield (node, f\"`except {ast.unparse(node.type)}: {first}` throws the error away\",\n                   why)\n        elif isinstance(node, (ast.With, ast.AsyncWith)):\n            for item in node.items:\n                c = item.context_expr\n                if isinstance(c, ast.Call) and call_name(c) == \"suppress\" \\\n                        and any(_broad(a) for a in c.args):\n                    yield (c, f\"`{ast.unparse(c)}` throws every error in this block away\",\n                           why)\n", "magellan_lite/rules/imports.py": "\"\"\"import-cycle: the change makes modules import each other when they load.\n\nFrom the full Magellan (``rule_import_cycle`` in ``magellan/rules/risk.py``), narrowed to the\ncase a commit can be blamed for: a cycle that did not exist before. When ``a`` imports ``b``\nwhile ``b`` imports ``a``, whichever is imported first sees the other half-built. ``from a\nimport name`` then fails with ``ImportError: cannot import name ... (most likely due to a\ncircular import)`` -- or works, depending on which module some entry point happens to import\nfirst, which is how it passes every test and breaks in production.\n\nOnly imports that run when the module loads count: top-level ones, in class bodies, under\n``if``/``try``/``with`` -- not inside functions, and not under ``if TYPE_CHECKING:`` or ``if\n__name__ == \"__main__\":``. A cycle is reported when it is new, it runs through a file the\nchange edited, and at least one of its imports takes a name out of a half-built module\n(``from a import name``); cycles of plain ``import a`` (used later, as ``a.name``) are left\nalone, since those load fine.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\n\nfrom magellan_lite.findings import Finding, change_rule\nfrom magellan_lite.rules.common import changed_files\nfrom magellan_lite.source import module_name\n\n\ndef _skipped_if(node: ast.If) -> bool:\n    test = ast.unparse(node.test)\n    return \"TYPE_CHECKING\" in test or \"__name__\" in test\n\n\ndef _load_time(body):\n    \"\"\"Import statements that run when the module is imported.\"\"\"\n    for stmt in body:\n        if isinstance(stmt, (ast.Import, ast.ImportFrom)):\n            yield stmt\n        elif isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):\n            continue\n        elif isinstance(stmt, ast.If):\n            if not _skipped_if(stmt):\n                yield from _load_time(stmt.body)\n                yield from _load_time(stmt.orelse)\n        elif isinstance(stmt, ast.ClassDef):\n            yield from _load_time(stmt.body)\n        else:\n            for field in (\"body\", \"orelse\", \"finalbody\"):\n                yield from _load_time(getattr(stmt, field, []) or [])\n            for h in getattr(stmt, \"handlers\", []) or []:\n                yield from _load_time(h.body)\n\n\ndef import_edges(snapshot) -> dict[tuple[str, str], tuple[str, str, int]]:\n    \"\"\"``{(module, imported module): (how, path, line)}`` for load-time imports between the\n    project's own modules. ``how`` is ``from`` when a name is taken out of the module, else\n    ``import``.\"\"\"\n    modules = {module_name(p): p for p in snapshot.files if p.endswith(\".py\")}\n    out: dict[tuple[str, str], tuple[str, str, int]] = {}\n    for mod, path in sorted(modules.items()):\n        tree = snapshot.tree(path)\n        if tree is None:\n            continue\n        package = mod if path.endswith(\"__init__.py\") else mod.rpartition(\".\")[0]\n        for node in _load_time(tree.body):\n            if isinstance(node, ast.Import):\n                for a in node.names:\n                    parts = a.name.split(\".\")\n                    target = next((\".\".join(parts[:i]) for i in range(len(parts), 0, -1)\n                                   if \".\".join(parts[:i]) in modules), None)\n                    if target and target != mod:\n                        out.setdefault((mod, target), (\"import\", path, node.lineno))\n                continue\n            base = node.module or \"\"\n            if node.level:\n                parts = package.split(\".\") if package else []\n                if node.level > 1:\n                    parts = parts[:len(parts) - (node.level - 1)]\n                base = \".\".join(parts + ([node.module] if node.module else []))\n            for a in node.names:\n                sub = f\"{base}.{a.name}\" if base else a.name\n                if sub in modules:\n                    if sub != mod:\n                        out.setdefault((mod, sub), (\"import\", path, node.lineno))\n                elif base in modules and base != mod:\n                    key = (mod, base)\n                    if out.get(key, (\"import\",))[0] != \"from\":\n                        out[key] = (\"from\", path, node.lineno)\n    return out\n\n\ndef _sccs(edges) -> list[set[str]]:\n    adj: dict[str, set[str]] = {}\n    for a, b in edges:\n        adj.setdefault(a, set()).add(b)\n    index: dict[str, int] = {}\n    low: dict[str, int] = {}\n    stack: list[str] = []\n    on: set[str] = set()\n    out: list[set[str]] = []\n    counter = 0\n    for root in sorted(adj):\n        if root in index:\n            continue\n        work = [(root, iter(sorted(adj.get(root, ()))))]\n        index[root] = low[root] = counter\n        counter += 1\n        stack.append(root)\n        on.add(root)\n        while work:\n            v, it = work[-1]\n            advanced = False\n            for w in it:\n                if w not in index:\n                    index[w] = low[w] = counter\n                    counter += 1\n                    stack.append(w)\n                    on.add(w)\n                    work.append((w, iter(sorted(adj.get(w, ())))))\n                    advanced = True\n                    break\n                if w in on:\n                    low[v] = min(low[v], index[w])\n            if advanced:\n                continue\n            work.pop()\n            if work:\n                low[work[-1][0]] = min(low[work[-1][0]], low[v])\n            if low[v] == index[v]:\n                comp = set()\n                while True:\n                    w = stack.pop()\n                    on.discard(w)\n                    comp.add(w)\n                    if w == v:\n                        break\n                if len(comp) > 1:\n                    out.append(comp)\n    return out\n\n\ndef _ring(start: str, comp: set[str], edges) -> list[str]:\n    \"\"\"A shortest way round the cycle from ``start`` back to it.\"\"\"\n    prev: dict[str, str] = {}\n    todo = [start]\n    while todo:\n        nxt = []\n        for v in todo:\n            for (a, b) in sorted(edges):\n                if a != v or b not in comp:\n                    continue\n                if b == start:\n                    path = [v]\n                    while path[-1] != start:\n                        path.append(prev[path[-1]])\n                    return list(reversed(path))\n                if b not in prev:\n                    prev[b] = v\n                    nxt.append(b)\n        todo = nxt\n    return [start]\n\n\n@change_rule(\"import-cycle\", \"medium\",\n             fix=\"Move one of the imports into the function that uses it, or move what both \"\n                 \"modules need into a third module that imports neither.\")\ndef import_cycle(ctx):\n    files = changed_files(ctx)\n    if not files:\n        return\n    after = import_edges(ctx.after)\n    cycles = [c for c in _sccs(after) if any(module_name(f) in c for f in files)]\n    if not cycles:\n        return\n    before = import_edges(ctx.before)\n    old = {}\n    for i, comp in enumerate(_sccs(before)):\n        for m in comp:\n            old[m] = i\n    for comp in cycles:\n        if len({old.get(m, -1 - k) for k, m in enumerate(sorted(comp))}) == 1:\n            continue                                # the same cycle was there before\n        inside = {k: v for k, v in after.items() if k[0] in comp and k[1] in comp}\n        if not any(how == \"from\" for how, _p, _l in inside.values()):\n            continue                                # plain `import a` both ways loads fine\n        fresh = sorted((k for k in inside if k not in before and inside[k][1] in files),\n                       key=lambda k: (inside[k][1], inside[k][2]))\n        if not fresh:\n            continue\n        a, b = fresh[0]\n        _how, path, line = inside[(a, b)]\n        ring = _ring(a, comp, inside)\n        shown = \" -> \".join(ring + [ring[0]])\n        names = sorted(comp)\n        yield Finding(\n            \"import-cycle\", \"medium\",\n            f\"this import closes a circle: {shown}\",\n            path, line,\n            detail=(f\"{_and(names)} now import each other while they load. Whichever is \"\n                    f\"imported first sees the other half-built, so `from ... import name` \"\n                    f\"fails with ImportError (\\\"most likely due to a circular import\\\") -- or \"\n                    f\"works, depending on which module an entry point happens to import \"\n                    f\"first. Before this change there was no such circle.\"))\n\n\ndef _and(items: list[str]) -> str:\n    return items[0] if len(items) == 1 else \", \".join(items[:-1]) + \" and \" + items[-1]\n", "magellan_lite/rules/languages.py": "\"\"\"The checklist's rules for C, C++, Java, Fortran and COBOL.\n\nEach language's frontend (vendored from the full Magellan, run by ``magellan_lite/languages.py``)\nfinds its own hazards in a change; this registers each of them as a rule, so they are on the\nchecklist (``magellan-lite rules``), count toward the verdict, and can be told apart. The work\nis done once per check, whichever of these rules asks first.\n\"\"\"\n\nfrom magellan_lite import languages\nfrom magellan_lite.findings import change_rule\n\n\ndef _rule(rule_id: str):\n    def check(ctx):\n        if all(p.endswith(\".py\") for p in set(ctx.before.files) | set(ctx.after.files)):\n            return []\n        return [f for f in languages.findings(ctx) if f.rule == rule_id]\n    check.__name__ = rule_id.replace(\"-\", \"_\")\n    return check\n\n\nfor _id, (_severity, _blocking, _fix) in languages.RULES.items():\n    change_rule(_id, _severity, _fix, blocking=_blocking)(_rule(_id))\n", "magellan_lite/rules/loops.py": "\"\"\"loop-without-progress: a ``while`` loop that nothing inside it can stop.\n\n* Knight Capital: Power Peg sent child orders ``while order.filled < order.qty``. A 2005\n  change moved the fill counting out of the loop, so nothing in it changed ``order.filled``\n  any more. Woken up in 2012, it sent orders without end: $460 million in 45 minutes.\n* Microsoft Zune, December 31 2008: ``while days > 365`` subtracted 366 in a leap year only\n  ``if days > 366``. On day 366 of a leap year no path changed anything, and every Zune 30\n  froze at boot.\n\nOne finding per loop, for loops in code the change touched:\n\n* the whole loop: nothing in the body changes what the condition reads, hands it to a call\n  that could change it, or leaves the loop (break, return, raise, sys.exit);\n* one path: some way through the body's if/else changes nothing that the condition or that\n  path's own tests read, and does not leave -- and simple integer reasoning over those tests\n  says the path can be taken (``days == 366``).\n\nPrecision first, because a gate people learn to ignore is worthless. Quiet for\n``while True``, conditions that call something (polling; ``len(items)`` is the exception and\nreads like ``items`` itself, since only a change to ``items`` can move it), loops that sleep,\nwait, await or yield (something else moves them on), conditions on globals when the body\ncalls anything, and bodies too tangled to enumerate.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\n\nfrom magellan_lite.findings import rule\n\nMAX_PATHS = 64\n_EXITS = {\"exit\", \"_exit\", \"quit\", \"abort\"}\n_WAITS = {\"sleep\", \"wait\", \"join\", \"select\", \"poll\", \"acquire\", \"recv\", \"accept\"}\n_IMMUTABLE_TYPES = {\"int\", \"float\", \"str\", \"bool\", \"bytes\", \"complex\"}\n_NUMERIC_CALLS = {\"int\", \"float\", \"len\", \"abs\", \"round\", \"min\", \"max\", \"sum\", \"ord\", \"str\"}\n\n\ndef _dotted(node: ast.AST) -> str | None:\n    \"\"\"``order.filled`` for an attribute chain on a name, ``days`` for a name.\"\"\"\n    parts = []\n    while isinstance(node, ast.Attribute):\n        parts.append(node.attr)\n        node = node.value\n    if isinstance(node, ast.Name):\n        return \".\".join([node.id, *reversed(parts)])\n    return None\n\n\ndef _name(func: ast.AST) -> str:\n    return func.id if isinstance(func, ast.Name) else func.attr if isinstance(func, ast.Attribute) else \"\"\n\n\ndef _sized(call: ast.Call) -> bool:\n    \"\"\"``len(items)`` or ``len(self.items)``: a plain value, which only a change to\n    ``items`` can move, and the body's changes are checked for that like any other read.\"\"\"\n    return (isinstance(call.func, ast.Name) and call.func.id == \"len\" and len(call.args) == 1\n            and not call.keywords and _dotted(call.args[0]) is not None)\n\n\ndef _reads(expr: ast.AST) -> set[str]:\n    \"\"\"What an expression reads: the outermost name or attribute chains in it.\"\"\"\n    if (d := _dotted(expr)) is not None:\n        return {d}\n    out = set()\n    if isinstance(expr, ast.Call):                      # is_leap_year(year) reads year\n        children = [*expr.args, *(k.value for k in expr.keywords)]\n        if isinstance(expr.func, ast.Attribute):\n            children.append(expr.func.value)            # q.empty() reads q\n    else:\n        children = list(ast.iter_child_nodes(expr))\n    for child in children:\n        out |= _reads(child)\n    return out\n\n\ndef _nodes(stmts: list[ast.AST]):\n    \"\"\"Every node under ``stmts``, without going into nested functions or classes.\"\"\"\n    todo = list(stmts)\n    while todo:\n        node = todo.pop()\n        yield node\n        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda, ast.ClassDef)):\n            todo.extend(ast.iter_child_nodes(node))\n\n\nclass _Function:\n    \"\"\"What the loop's function says about its own names.\"\"\"\n\n    def __init__(self, fn: ast.AST | None) -> None:\n        self.locals: set[str] = set()\n        self.immutable: set[str] = set()\n        #: names that are another way to reach an object: ``pop = queue.popleft`` -> queue\n        self.aliases: dict[str, str] = {}\n        if fn is None:\n            return\n        args = fn.args\n        assigned: dict[str, list] = {}\n        for a in [*args.posonlyargs, *args.args, *args.kwonlyargs, args.vararg, args.kwarg]:\n            if a is None:\n                continue\n            self.locals.add(a.arg)\n            if isinstance(a.annotation, ast.Name) and a.annotation.id in _IMMUTABLE_TYPES:\n                self.immutable.add(a.arg)\n        shared: set[str] = set()\n        for node in _nodes(fn.body):\n            if isinstance(node, (ast.Global, ast.Nonlocal)):\n                shared |= set(node.names)               # assigned here, but not ours\n            elif isinstance(node, (ast.Assign, ast.AugAssign, ast.AnnAssign)):\n                targets = node.targets if isinstance(node, ast.Assign) else [node.target]\n                for t in targets:\n                    if isinstance(t, ast.Name):\n                        self.locals.add(t.id)\n                        assigned.setdefault(t.id, []).append(node)\n                value = getattr(node, \"value\", None)\n                obj = value.value if isinstance(value, ast.Attribute) else value\n                if isinstance(node, ast.Assign) and (d := _dotted(obj) if obj is not None else None):\n                    for t in node.targets:\n                        if isinstance(t, ast.Name):\n                            self.aliases[t.id] = d\n            elif isinstance(node, (ast.For, ast.AsyncFor, ast.comprehension)):\n                self.locals |= {n.id for n in ast.walk(node.target) if isinstance(n, ast.Name)}\n            elif isinstance(node, ast.NamedExpr):\n                self.locals.add(node.target.id)\n        self.locals -= shared\n        for name, nodes in assigned.items():\n            if name not in shared and all(self._numeric(n) for n in nodes):\n                self.immutable.add(name)\n\n    @staticmethod\n    def _numeric(node: ast.AST) -> bool:\n        \"\"\"Is this assignment's value a number or a string (which no call can change)?\"\"\"\n        if isinstance(node, ast.AugAssign):\n            return True\n        value = node.value\n        if value is None:\n            return False\n        if isinstance(value, ast.Constant):\n            return not isinstance(value.value, (list, dict, set))\n        if isinstance(value, (ast.BinOp, ast.UnaryOp, ast.BoolOp, ast.Compare, ast.JoinedStr)):\n            return True\n        if isinstance(value, ast.Name):\n            return value.id.isupper()                   # ORIGIN_YEAR: a module constant\n        if isinstance(value, ast.Call):\n            return _name(value.func) in _NUMERIC_CALLS\n        return False\n\n\ndef _changes(nodes: list[ast.AST], fn: _Function) -> set[str]:\n    \"\"\"What these statements (and tests) may change. ``*`` for anything.\"\"\"\n    out: set[str] = set()\n\n    def target(t: ast.AST) -> None:\n        if isinstance(t, (ast.Tuple, ast.List)):\n            for e in t.elts:\n                target(e)\n        elif isinstance(t, ast.Starred):\n            target(t.value)\n        elif isinstance(t, ast.Subscript):\n            target(t.value)                             # d[k] = v changes d\n        elif (d := _dotted(t)) is not None:\n            out.add(d)\n\n    for node in _nodes(nodes):\n        if isinstance(node, (ast.Global, ast.Nonlocal)):\n            out.add(\"*\")\n        elif isinstance(node, ast.Assign):\n            for t in node.targets:\n                target(t)\n        elif isinstance(node, (ast.AugAssign, ast.AnnAssign)):\n            target(node.target)\n        elif isinstance(node, (ast.For, ast.AsyncFor)):\n            target(node.target)\n        elif isinstance(node, ast.Delete):\n            for t in node.targets:\n                target(t)\n        elif isinstance(node, ast.withitem) and node.optional_vars is not None:\n            target(node.optional_vars)\n        elif isinstance(node, ast.NamedExpr):\n            target(node.target)\n        elif isinstance(node, ast.Call):\n            if isinstance(node.func, ast.Attribute) and (d := _dotted(node.func.value)):\n                out.add(d)                              # obj.method() may change obj\n            if isinstance(node.func, ast.Name) and node.func.id in fn.aliases:\n                out.add(node.func.id)                   # pop() where pop = queue.popleft\n            for arg in [*node.args, *(k.value for k in node.keywords)]:\n                if isinstance(arg, ast.Starred):\n                    arg = arg.value\n                d = _dotted(arg)\n                if d is not None and d not in fn.immutable:\n                    out.add(d)                          # a call can change what it is given\n    # a change through an alias is a change to what it stands for\n    out |= {fn.aliases[c.split(\".\")[0]] for c in out if c.split(\".\")[0] in fn.aliases}\n    return out\n\n\ndef _affects(changed: set[str], read: str) -> bool:\n    return \"*\" in changed or any(\n        read == c or read.startswith(c + \".\") or c.startswith(read + \".\") for c in changed)\n\n\ndef _leaves(node: ast.AST, inner: bool = False) -> bool:\n    \"\"\"Can this leave the loop: break (not an inner loop's), return, raise, sys.exit()?\"\"\"\n    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda, ast.ClassDef)):\n        return False\n    if isinstance(node, (ast.Return, ast.Raise)):\n        return True\n    if isinstance(node, ast.Break):\n        return not inner\n    if isinstance(node, ast.Call) and _name(node.func) in _EXITS:\n        return True\n    inner = inner or isinstance(node, (ast.For, ast.AsyncFor, ast.While))\n    return any(_leaves(c, inner) for c in ast.iter_child_nodes(node))\n\n\ndef _paths(stmts: list[ast.stmt]):\n    \"\"\"Every way through ``stmts`` along its if/else: ``(tests, statements)`` with each test\n    as ``(expression, taken)``. ``None`` past MAX_PATHS.\"\"\"\n    paths = [([], [])]\n    for s in stmts:\n        if isinstance(s, ast.If):\n            yes, no = _paths(s.body), _paths(s.orelse)\n            if yes is None or no is None:\n                return None\n            paths = [(t + [(s.test, True)] + t2, b + b2) for t, b in paths for t2, b2 in yes] + \\\n                    [(t + [(s.test, False)] + t2, b + b2) for t, b in paths for t2, b2 in no]\n            if len(paths) > MAX_PATHS:\n                return None\n        else:\n            paths = [(t, b + [s]) for t, b in paths]\n    return paths\n\n\n_FLIP = {ast.Lt: ast.GtE, ast.LtE: ast.Gt, ast.Gt: ast.LtE, ast.GtE: ast.Lt, ast.Eq: ast.NotEq,\n         ast.NotEq: ast.Eq}\n_MIRROR = {ast.Lt: ast.Gt, ast.LtE: ast.GtE, ast.Gt: ast.Lt, ast.GtE: ast.LtE, ast.Eq: ast.Eq,\n           ast.NotEq: ast.NotEq}\n\n\ndef _bounds(tests) -> dict[str, list] | None:\n    \"\"\"Integer ranges the tests allow for plain names (``days > 365`` and not\n    ``days > 366`` leave 366..366). ``None`` when no value can satisfy them.\"\"\"\n    env: dict[str, list] = {}\n\n    def constrain(e: ast.AST, taken: bool) -> None:\n        if isinstance(e, ast.UnaryOp) and isinstance(e.op, ast.Not):\n            return constrain(e.operand, not taken)\n        if isinstance(e, ast.BoolOp) and isinstance(e.op, ast.And) == taken:\n            for v in e.values:                          # a and b true; a or b false\n                constrain(v, taken)\n            return\n        if not (isinstance(e, ast.Compare) and len(e.ops) == 1 and type(e.ops[0]) in _FLIP):\n            return\n        left, right, op = e.left, e.comparators[0], type(e.ops[0])\n        if isinstance(left, ast.Constant) and isinstance(right, ast.Name):\n            left, right, op = right, left, _MIRROR[op]\n        if not (isinstance(left, ast.Name) and isinstance(right, ast.Constant)\n                and type(right.value) is int):\n            return\n        if not taken:\n            op = _FLIP[op]\n        c = right.value\n        lo, hi = env.setdefault(left.id, [float(\"-inf\"), float(\"inf\")])\n        lo, hi = {ast.Lt: (lo, min(hi, c - 1)), ast.LtE: (lo, min(hi, c)),\n                  ast.Gt: (max(lo, c + 1), hi), ast.GtE: (max(lo, c), hi),\n                  ast.Eq: (max(lo, c), min(hi, c)), ast.NotEq: (lo, hi)}[op]\n        if op is ast.NotEq and lo == hi == c:\n            lo, hi = 1, 0\n        env[left.id] = [lo, hi]\n\n    for e, taken in tests:\n        constrain(e, taken)\n    return None if any(lo > hi for lo, hi in env.values()) else env\n\n\ndef _list(names) -> str:\n    names = sorted(names)\n    return names[0] if len(names) == 1 else \", \".join(names[:-1]) + \" or \" + names[-1]\n\n\ndef _stuck(loop: ast.While, fn: _Function):\n    \"\"\"``(message)`` when some way through the loop can never end it, else ``None``.\"\"\"\n    cond = loop.test\n    if isinstance(cond, ast.Constant):\n        return None                                     # while True: leaves some other way\n    if any(isinstance(n, (ast.Await, ast.NamedExpr)) or (isinstance(n, ast.Call) and not _sized(n))\n           for n in ast.walk(cond)):\n        return None                                     # polling: the call can change\n    reads = _reads(cond)\n    body = list(_nodes(loop.body))\n    if not reads or any(isinstance(n, (ast.Yield, ast.YieldFrom, ast.Await)) for n in body):\n        return None\n    calls = [n for n in body if isinstance(n, ast.Call)]\n    if any(_name(c.func) in _WAITS for c in calls):\n        return None                                     # waits for another thread\n    roots = {r.split(\".\")[0] for r in reads}\n    if calls and any(r not in fn.locals and r != \"self\" for r in roots):\n        return None                                     # a global any call might change\n    heap = any(\".\" in r for r in reads) or any(isinstance(n, ast.Subscript) for n in ast.walk(cond))\n    if heap and any(isinstance(c.func, ast.Attribute) for c in calls):\n        return None     # node.remove() can change parent.children: other references, unseen\n    paths = _paths(loop.body)\n    if paths is None:\n        return None\n    for tests, stmts in paths:\n        if any(_leaves(s) for s in stmts):\n            continue\n        watched = reads | {r for e, _ in tests for r in _reads(e)}\n        changed = _changes([*stmts, *(e for e, _ in tests)], fn)\n        if any(_affects(changed, r) for r in watched):\n            continue\n        env = _bounds([(cond, True), *tests])\n        if env is None:\n            continue                                    # this path cannot be taken\n        what = _list(watched)\n        if len(paths) == 1:\n            return (f\"this loop never ends once it starts: nothing in it changes {what}, and \"\n                    f\"nothing leaves it\")\n        witness = [f\"{n} == {int(lo if lo != float('-inf') else hi)}\"\n                   for n, (lo, hi) in sorted(env.items())\n                   if n in reads and (lo != float(\"-inf\") or hi != float(\"inf\"))]\n        where = \" and \".join(ast.unparse(e) if taken else f\"not {ast.unparse(e)}\"\n                             for e, taken in tests)\n        return (f\"this loop never ends when {where}\"\n                f\"{' (' + ', '.join(witness) + ')' if witness else ''}: nothing on that path \"\n                f\"changes {what}, and nothing leaves the loop\")\n    return None\n\n\n@rule(\"loop-without-progress\", \"high\", blocking=True,\n      fix=\"Make every way through the loop change what its condition reads, or leave the \"\n          \"loop (break, return or raise) where it cannot.\")\ndef loop_without_progress(tree: ast.Module, path: str):\n    def visit(node: ast.AST, fn: _Function):\n        for child in ast.iter_child_nodes(node):\n            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):\n                yield from visit(child, _Function(child))\n            elif isinstance(child, ast.While):\n                message = _stuck(child, fn)\n                if message:\n                    yield child, message\n                yield from visit(child, fn)\n            else:\n                yield from visit(child, fn)\n\n    for loop, message in visit(tree, _Function(None)):\n        yield (loop, message,\n               \"Once it runs, the program hangs or keeps doing the same thing forever. Knight \"\n               \"Capital, 2012: a loop like this sent orders without end ($460 million in 45 \"\n               \"minutes). Zune, 2008: one like it froze every Zune 30 on the last day of a \"\n               \"leap year.\")\n", "magellan_lite/rules/newcode.py": "\"\"\"New code: checks on what a change adds, rather than what it edits.\n\nFrom the full Magellan (``magellan/python/rules/newcode.py``). An edited function has callers\nthat might break; a new one has none, so the other rules have little to say about it -- yet\nit is where an author (a person, or a model) who does not know the code base well leaves\nthings behind:\n\n* ``near-duplicate``: the new function has the same shape as one the project already has.\n  Shapes are compared on the syntax tree with local names and constants erased, keeping what\n  is called, so a renamed copy matches and two functions that merely have the same length do\n  not. Two copies drift: the next fix lands in one and not the other.\n* ``new-unreferenced``: a new private function (``_name``) that nothing calls or mentions.\n  A helper written but never wired in is usually a step the change forgot -- the validation\n  that never runs -- or a leftover.\n\nTests are left out of both (test functions are alike on purpose), and so are small functions\n(fewer than 30 syntax nodes: getters and one-liners are alike by nature), overrides of a\nmethod with the same name, and methods of classes whose base comes from outside the project\n(a framework may call them by name).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nimport re\n\nfrom magellan_lite.findings import Finding, change_rule\nfrom magellan_lite.rules.common import functions, is_test_path\n\nMIN_TOKENS = 30\nSIMILAR = 0.82            # share of four-step sequences the two shapes have in common\nSHINGLE = 4\n_SAME_ON_PURPOSE = re.compile(r\"^(__\\w+__|visit_\\w+|test_\\w+|setUp|tearDown|run|main|handle|\"\n                              r\"process|setup|teardown)$\")\n\n\ndef tokens(fn: ast.AST) -> list[str]:\n    \"\"\"The function's shape: node types in order, with called and attribute names kept and\n    local names and constant values erased.\"\"\"\n    out: list[str] = []\n    body = list(getattr(fn, \"body\", []))\n    if body and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) \\\n            and isinstance(body[0].value.value, str):\n        body = body[1:]                             # the docstring is not the shape\n    stack = list(reversed(body))\n    while stack:\n        n = stack.pop()\n        if isinstance(n, (ast.Name, ast.arg)):\n            out.append(\"N\")\n        elif isinstance(n, ast.Constant):\n            out.append(\"C:\" + type(n.value).__name__)\n        elif isinstance(n, ast.Attribute):\n            out.append(\"A:\" + n.attr)\n        elif isinstance(n, ast.Call):\n            f = n.func\n            out.append(\"call:\" + (f.attr if isinstance(f, ast.Attribute) else getattr(f, \"id\", \"?\")))\n        else:\n            out.append(type(n).__name__)\n        stack.extend(reversed(list(ast.iter_child_nodes(n))))\n    return out\n\n\ndef _shingles(toks: list[str]) -> frozenset:\n    if len(toks) < SHINGLE:\n        return frozenset({tuple(toks)})\n    return frozenset(tuple(toks[i:i + SHINGLE]) for i in range(len(toks) - SHINGLE + 1))\n\n\ndef _similarity(a: frozenset, b: frozenset) -> float:\n    return len(a & b) / len(a | b) if a and b else 0.0\n\n\ndef _added(ctx) -> list:\n    return [c.after for c in ctx.changes\n            if c.kind == \"added\" and c.after.kind in (\"function\", \"method\") and not c.after.lang\n            and c.after.path.endswith(\".py\") and not is_test_path(c.after.path)]\n\n\ndef _short(name: str) -> str:\n    return name.rsplit(\".\", 1)[-1]\n\n\ndef _copies(a: str, b: str, files: dict) -> bool:\n    \"\"\"Are the two files copies of one module -- a vendored or bundled copy, where one path\n    ends with the other, or the same text twice? Then every function in them repeats, on\n    purpose, and saying so a hundred times helps nobody.\"\"\"\n    if a == b:\n        return False\n    if a.endswith(\"/\" + b) or b.endswith(\"/\" + a):\n        return True\n    ta, tb = files.get(a), files.get(b)\n    return ta is not None and ta.replace(\"\\r\\n\", \"\\n\") == (tb or \"\").replace(\"\\r\\n\", \"\\n\")\n\n\nMAX_FINDINGS = 10\n#: more new functions than this is a code base being imported, not a change to review\nMAX_ADDED = 200\n\n\ndef _names(toks) -> set[str]:\n    \"\"\"What a shape calls and reads by name: a near copy calls most of the same things.\"\"\"\n    return {t.split(\":\", 1)[1] for t in toks if t.startswith((\"call:\", \"A:\"))}\n\n\ndef _mentions(text: str, names: set[str]) -> bool:\n    return not names or sum(n in text for n in names) >= 0.7 * len(names)\n\n\n@change_rule(\"near-duplicate\", \"low\",\n             fix=\"Call or extend the existing function, or say in a comment why the two must \"\n                 \"differ.\")\ndef near_duplicate(ctx):\n    added = [d for d in _added(ctx) if not _SAME_ON_PURPOSE.match(d.short)]\n    if not added or len(added) > MAX_ADDED:\n        return\n    fns = functions(ctx.after)\n    mine: dict[str, tuple[tuple, frozenset, set]] = {}\n    for d in added:\n        if d.name in fns:\n            toks = tuple(tokens(fns[d.name][1]))\n            if len(toks) >= MIN_TOKENS:\n                mine[d.name] = (toks, _shingles(list(toks)), _names(toks))\n    if not mine:\n        return\n    lines: dict[str, list[str]] = {}\n    best: dict[str, tuple[float, object]] = {}\n    for other, (path, fn, _cls) in fns.items():\n        if is_test_path(path) or _SAME_ON_PURPOSE.match(fn.name):\n            continue\n        text = ctx.after.files[path]\n        if not any(_mentions(text, m[2]) for m in mine.values()):\n            continue                                # text first: most files are no match\n        body = \"\\n\".join(lines.setdefault(path, text.splitlines())[fn.lineno - 1:fn.end_lineno])\n        hopeful = [n for n, m in mine.items() if n != other and _mentions(body, m[2])]\n        if not hopeful:\n            continue\n        o = ctx.after_defs.get(other)\n        otoks = tuple(tokens(fn))\n        if o is None or len(otoks) < MIN_TOKENS:\n            continue\n        theirs = None\n        for name in hopeful:\n            d = ctx.after_defs[name]\n            toks, shingles, _ = mine[name]\n            if not 0.6 * len(toks) <= len(otoks) <= len(toks) / 0.6:\n                continue\n            if o.kind == \"method\" and d.kind == \"method\" and o.short == d.short:\n                continue                            # an override, or a sibling implementation\n            if o.path == d.path and (d.line <= o.line <= d.end_line or o.line <= d.line <= o.end_line):\n                continue                            # one inside the other\n            if _copies(d.path, o.path, ctx.after.files):\n                continue\n            if theirs is None:\n                theirs = _shingles(list(otoks))\n            sim = 1.0 if otoks == toks else _similarity(shingles, theirs)\n            if sim >= SIMILAR and sim > best.get(name, (0.0, None))[0]:\n                best[name] = (sim, o)\n    hits, reported = [], set()\n    for name, (score, other) in sorted(best.items(), key=lambda kv: (-kv[1][0], kv[0])):\n        pair = frozenset((name, other.name))\n        if pair in reported:\n            continue\n        reported.add(pair)\n        hits.append((ctx.after_defs[name], other, score))\n    for d, other, score in hits[:MAX_FINDINGS]:\n        exact_copy = score >= 0.999\n        where = \"in the same file\" if other.path == d.path else f\"in {other.path}\"\n        yield Finding(\n            \"near-duplicate\", \"low\",\n            f\"new {d.short}() {'repeats' if exact_copy else 'closely resembles'} \"\n            f\"{other.short}() {where}\",\n            d.path, d.line,\n            detail=((\"The same steps and the same calls; only the names differ. \"\n                     if exact_copy else f\"About {score:.0%} of their shape is the same. \")\n                    + f\"Two copies drift apart: the next fix lands in one and not the other \"\n                      f\"({other.path}:{other.line}).\"))\n\n\ndef _external_base(tree: ast.Module, cls_name: str | None, project_classes: set[str]) -> bool:\n    \"\"\"Does the class inherit from something outside the project (a framework class that may\n    call its methods by name)?\"\"\"\n    if cls_name is None:\n        return False\n    short = cls_name.rsplit(\".\", 1)[-1]\n    for node in ast.walk(tree):\n        if isinstance(node, ast.ClassDef) and node.name == short:\n            for b in node.bases:\n                base = ast.unparse(b).split(\"[\", 1)[0].rsplit(\".\", 1)[-1]\n                if base not in (\"object\", \"Generic\", \"Protocol\", \"ABC\") \\\n                        and base not in project_classes:\n                    return True\n    return False\n\n\n@change_rule(\"new-unreferenced\", \"low\",\n             fix=\"Call it where it was meant to be used, or delete it.\")\ndef new_unreferenced(ctx):\n    candidates = []\n    for d in _added(ctx):\n        if not d.short.startswith(\"_\") or d.short.startswith(\"__\"):\n            continue\n        if ctx.graph.callers(d.name) or any(i.target == d.name for i in ctx.graph.imports):\n            continue\n        candidates.append(d)\n    if not candidates:\n        return\n    wanted = {d.short for d in candidates}\n    mentions: dict[str, list[tuple[str, int]]] = {}\n    strings: dict[str, set[str]] = {}\n    for path, text in sorted(ctx.after.files.items()):\n        if not path.endswith(\".py\") or not any(w in text for w in wanted):\n            continue                                # text first: most files never mention it\n        tree = ctx.after.tree(path)\n        if tree is None:\n            continue\n        for n in ast.walk(tree):\n            word = n.id if isinstance(n, ast.Name) else n.attr if isinstance(n, ast.Attribute) \\\n                else n.value if isinstance(n, ast.Constant) and isinstance(n.value, str) else None\n            if word in wanted:\n                mentions.setdefault(word, []).append((path, n.lineno))\n            elif isinstance(n, ast.Constant) and isinstance(n.value, str) and 3 <= len(n.value) < 40:\n                strings.setdefault(path, set()).add(n.value)\n    fns = functions(ctx.after, {d.path for d in candidates})\n    project_classes = {d.short for d in ctx.after_defs.values() if d.kind == \"class\"}\n    for d in candidates:\n        elsewhere = [(p, ln) for p, ln in mentions.get(d.short, [])\n                     if not (p == d.path and d.line <= ln <= d.end_line)]\n        if elsewhere:\n            continue\n        if any(d.short.startswith(s) and s != d.short for s in strings.get(d.path, ())):\n            continue                                # getattr(self, \"_visit_\" + kind) dispatch\n        entry = fns.get(d.name)\n        if entry is None or entry[1].decorator_list:\n            continue                                # registered by a decorator\n        if d.kind == \"method\" and _external_base(ctx.after.tree(d.path), entry[2],\n                                                 project_classes):\n            continue\n        yield Finding(\n            \"new-unreferenced\", \"low\",\n            f\"new {d.short}() is never called\",\n            d.path, d.line,\n            detail=(\"Nothing in the project calls it, reads it or names it. A private helper \"\n                    \"written but never wired in is usually a step this change forgot (the \"\n                    \"check that never runs), or a leftover.\"))\n", "magellan_lite/rules/recursion.py": "\"\"\"recursive-cycle: recursion the change creates, with nothing visible to stop it.\n\nFrom the full Magellan (``rule_recursive_cycle`` in ``magellan/rules/risk.py``). Mutual\nrecursion is the dangerous kind: ``a -> b -> c -> a`` reads as three ordinary functions, and\nnothing at any one of them says \"this is a loop\". Adding one call to the wrong one of them is\nhow an edit that looked local turns into a RecursionError (or a hang) in production.\n\nTwo findings, both only for code this change added or edited:\n\n* high (blocks the commit): a function that now calls itself on *every* path -- before any\n  ``return`` or ``raise`` could leave, outside every ``if`` and loop. It can never return:\n  ``return self.name`` inside the ``name`` property, ``self.x = v`` inside ``__setattr__``,\n  ``def get(self, k): return self.get(k)`` meant for ``self._data.get``.\n* medium: functions that existed before and now call each other in a circle, when none of\n  them takes a depth, limit, budget or visited parameter. Recursion designed as recursion (a\n  parser written today) is left alone: only a cycle closed between existing functions is\n  reported, and only when it is new. So is a walk over a structure, where every call hands on\n  a smaller piece (``node.children``, ``items[1:]``, a loop's element, ``n - 1``): it ends\n  when the data does.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\n\nfrom magellan_lite.findings import Finding, change_rule\nfrom magellan_lite.rules.common import edited, functions, old_graph\nfrom magellan_lite.source import module_name\n\n_GUARDS = (\"depth\", \"level\", \"seen\", \"visited\", \"budget\", \"limit\", \"remaining\", \"max_\",\n           \"memo\", \"cache\", \"ttl\", \"retries\", \"attempt\")\n\n\ndef _short(name: str) -> str:\n    return name.rsplit(\".\", 1)[-1]\n\n\n# -- a function that always calls itself ----------------------------------------------------\ndef _decorators(fn) -> set[str]:\n    out = set()\n    for d in fn.decorator_list:\n        d = d.func if isinstance(d, ast.Call) else d\n        out.add(d.attr if isinstance(d, ast.Attribute) else getattr(d, \"id\", \"\"))\n    return out\n\n\ndef _is_self(node: ast.AST, fn, cls_name: str | None, method: bool) -> bool:\n    \"\"\"Does this node refer to the function it is in?\"\"\"\n    name = fn.name\n    if method:\n        decorators = _decorators(fn)\n        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) \\\n                and node.func.attr == name and isinstance(node.func.value, ast.Name) \\\n                and node.func.value.id in (\"self\", \"cls\", cls_name):\n            return True                                         # self.m(...) in m\n        if isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name) \\\n                and node.value.id == \"self\":\n            if \"property\" in decorators or \"cached_property\" in decorators:\n                return node.attr == name and isinstance(node.ctx, ast.Load)\n            if \"setter\" in decorators:\n                return node.attr == name and isinstance(node.ctx, ast.Store)\n            if name == \"__setattr__\":\n                return isinstance(node.ctx, ast.Store)          # self.x = v in __setattr__\n        return False\n    return isinstance(node, ast.Call) and isinstance(node.func, ast.Name) \\\n        and node.func.id == name\n\n\ndef _always(expr: ast.AST):\n    \"\"\"The parts of an expression that are evaluated every time it is.\"\"\"\n    yield expr\n    if isinstance(expr, ast.IfExp):\n        yield from _always(expr.test)\n        return\n    if isinstance(expr, ast.BoolOp):\n        yield from _always(expr.values[0])\n        return\n    if isinstance(expr, (ast.ListComp, ast.SetComp, ast.GeneratorExp, ast.DictComp)):\n        yield from _always(expr.generators[0].iter)\n        return\n    if isinstance(expr, (ast.Lambda, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):\n        return\n    for child in ast.iter_child_nodes(expr):\n        yield from _always(child)\n\n\ndef _may_leave(stmt: ast.stmt) -> bool:\n    \"\"\"Can control leave the function (or skip ahead) somewhere in this statement?\"\"\"\n    todo = [stmt]\n    while todo:\n        node = todo.pop()\n        if isinstance(node, (ast.Return, ast.Raise, ast.Yield, ast.YieldFrom)):\n            return True\n        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda,\n                                 ast.ClassDef)):\n            todo.extend(ast.iter_child_nodes(node))\n    return False\n\n\ndef _unconditional(body: list[ast.stmt], is_self) -> ast.AST | None:\n    \"\"\"The first reference to itself that every run of ``body`` reaches, if any.\"\"\"\n    for stmt in body:\n        if isinstance(stmt, (ast.Expr, ast.Return, ast.Assign, ast.AugAssign, ast.AnnAssign)):\n            parts = [stmt.value] if stmt.value is not None else []\n            if isinstance(stmt, (ast.Assign, ast.AugAssign, ast.AnnAssign)):\n                parts += stmt.targets if isinstance(stmt, ast.Assign) else [stmt.target]\n            for part in parts:\n                hit = next((n for n in _always(part) if is_self(n)), None)\n                if hit is not None:\n                    return hit\n        elif isinstance(stmt, (ast.If, ast.While)):\n            hit = next((n for n in _always(stmt.test) if is_self(n)), None)\n            if hit is not None:\n                return hit\n        elif isinstance(stmt, ast.For):\n            hit = next((n for n in _always(stmt.iter) if is_self(n)), None)\n            if hit is not None:\n                return hit\n        elif isinstance(stmt, ast.With):\n            for item in stmt.items:\n                hit = next((n for n in _always(item.context_expr) if is_self(n)), None)\n                if hit is not None:\n                    return hit\n            hit = _unconditional(stmt.body, is_self)\n            if hit is not None:\n                return hit\n        elif isinstance(stmt, (ast.Try, ast.AsyncWith, ast.AsyncFor)) \\\n                or isinstance(stmt, getattr(ast, \"TryStar\", ())):\n            return None                       # a handler may catch the RecursionError\n        if _may_leave(stmt):\n            return None\n    return None\n\n\ndef _rebinds(tree: ast.Module, fn, cls: ast.ClassDef | None) -> bool:\n    \"\"\"Is the name rebound elsewhere (``self.run = ...``, ``f = other``)? Then the call may\n    not land on this function at all.\"\"\"\n    scope = cls if cls is not None else tree\n    for node in ast.walk(scope):\n        if cls is not None and isinstance(node, ast.Attribute) and isinstance(node.ctx, ast.Store) \\\n                and node.attr == fn.name and isinstance(node.value, ast.Name) \\\n                and node.value.id == \"self\" and \"setter\" not in _decorators(fn):\n            return True\n        if cls is None and isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store) \\\n                and node.id == fn.name:\n            return True\n    return False\n\n\ndef _self_recursion(fn, cls_node, tree) -> ast.AST | None:\n    \"\"\"Where ``fn`` calls itself on every path, or None.\"\"\"\n    if isinstance(fn, ast.AsyncFunctionDef) \\\n            or any(isinstance(n, (ast.Yield, ast.YieldFrom)) for n in ast.walk(fn)):\n        return None                           # calling it does not run the body yet\n    method = cls_node is not None\n    args = fn.args\n    local = {a.arg for a in [*args.posonlyargs, *args.args, *args.kwonlyargs]}\n    if not method and fn.name in local:\n        return None\n    cls_name = cls_node.name if cls_node is not None else None\n    hit = _unconditional(fn.body, lambda n: _is_self(n, fn, cls_name, method))\n    if hit is not None and _rebinds(tree, fn, cls_node):\n        return None\n    return hit\n\n\n# -- functions that call each other in a circle -----------------------------------------------\ndef _sccs(graph, defs) -> list[list[str]]:\n    \"\"\"Strongly connected call components of two or more Python functions.\"\"\"\n    adj: dict[str, set[str]] = {}\n    for e in graph.edges:\n        if e.kind != \"calls\" or e.guess:\n            continue\n        a, b = defs.get(e.src), defs.get(e.dst)\n        if a and b and not a.lang and not b.lang and a.kind in (\"function\", \"method\") \\\n                and b.kind in (\"function\", \"method\"):\n            adj.setdefault(e.src, set()).add(e.dst)\n    index: dict[str, int] = {}\n    low: dict[str, int] = {}\n    stack: list[str] = []\n    on: set[str] = set()\n    out: list[list[str]] = []\n    counter = 0\n    for root in sorted(adj):\n        if root in index:\n            continue\n        work = [(root, iter(sorted(adj.get(root, ()))))]\n        index[root] = low[root] = counter\n        counter += 1\n        stack.append(root)\n        on.add(root)\n        while work:\n            v, it = work[-1]\n            advanced = False\n            for w in it:\n                if w not in index:\n                    index[w] = low[w] = counter\n                    counter += 1\n                    stack.append(w)\n                    on.add(w)\n                    work.append((w, iter(sorted(adj.get(w, ())))))\n                    advanced = True\n                    break\n                if w in on:\n                    low[v] = min(low[v], index[w])\n            if advanced:\n                continue\n            work.pop()\n            if work:\n                low[work[-1][0]] = min(low[work[-1][0]], low[v])\n            if low[v] == index[v]:\n                comp = []\n                while True:\n                    w = stack.pop()\n                    on.discard(w)\n                    comp.append(w)\n                    if w == v:\n                        break\n                if len(comp) > 1:\n                    out.append(sorted(comp))\n    return out\n\n\ndef _guarded(members: list[str], fns: dict) -> str:\n    for name in members:\n        if name not in fns:\n            continue\n        _path, fn, _cls = fns[name]\n        a = fn.args\n        for arg in [*a.posonlyargs, *a.args, *a.kwonlyargs]:\n            if any(g in arg.arg.lower() for g in _GUARDS):\n                return arg.arg\n        if _decorators(fn) & {\"lru_cache\", \"cache\"}:\n            return \"a cache\"\n    return \"\"\n\n\ndef _smaller(arg: ast.AST, loop_names: set[str]) -> bool:\n    \"\"\"Is this argument a smaller piece of the input: ``node.left``, ``items[1:]``, a loop's\n    element, ``n - 1``? Recursion that hands on smaller pieces walks a structure and ends.\"\"\"\n    if isinstance(arg, ast.Starred):\n        arg = arg.value\n    if isinstance(arg, (ast.Attribute, ast.Subscript)):\n        return True\n    if isinstance(arg, ast.Name):\n        return arg.id in loop_names\n    return isinstance(arg, ast.BinOp) and isinstance(arg.op, (ast.Sub, ast.FloorDiv,\n                                                              ast.RShift)) \\\n        and isinstance(arg.right, ast.Constant)\n\n\ndef _walks_a_structure(ring: list[str], graph, fns) -> bool:\n    \"\"\"Does every call around the cycle hand on a smaller piece of what it was given?\"\"\"\n    for here, there in zip(ring, ring[1:] + ring[:1]):\n        if here not in fns:\n            return False\n        fn = fns[here][1]\n        loop_names = {n.id for node in ast.walk(fn)\n                      if isinstance(node, (ast.For, ast.AsyncFor, ast.comprehension))\n                      for n in ast.walk(node.target) if isinstance(n, ast.Name)}\n        lines = {e.line for e in graph.uses(here) if e.dst == there and e.kind == \"calls\"}\n        calls = [c for c in ast.walk(fn) if isinstance(c, ast.Call) and c.lineno in lines\n                 and _short(there) in ast.unparse(c.func)]\n        if not calls or not all(any(_smaller(a, loop_names)\n                                    for a in [*c.args, *(k.value for k in c.keywords)])\n                                for c in calls):\n            return False\n    return True\n\n\ndef _order(members: list[str], graph) -> list[str]:\n    \"\"\"The cycle in call order, starting from its first member.\"\"\"\n    ring, here = [members[0]], members[0]\n    inside = set(members)\n    while True:\n        nxt = sorted(e.dst for e in graph.uses(here)\n                     if e.kind == \"calls\" and not e.guess and e.dst in inside)\n        nxt = [n for n in nxt if n not in ring] or [n for n in nxt if n == ring[0]]\n        if not nxt or nxt[0] == ring[0]:\n            return ring\n        ring.append(nxt[0])\n        here = nxt[0]\n\n\n@change_rule(\"recursive-cycle\", \"high\", blocking=True,\n             fix=\"Give the recursion an end every path reaches: a base case before the call, \"\n                 \"or a depth/visited argument passed through every call.\")\ndef recursive_cycle(ctx):\n    touched = edited(ctx)\n    if not touched:\n        return\n    fns = functions(ctx.after, {ctx.after_defs[n].path for n in touched if n in ctx.after_defs\n                                and not ctx.after_defs[n].lang})\n    old_fns = None\n    trees = {}\n\n    # 1. a function that calls itself on every path\n    for name in sorted(touched & set(fns)):\n        path, fn, cls = fns[name]\n        tree = trees.setdefault(path, ctx.after.tree(path))\n        cls_node = _class_node(tree, cls, path)\n        hit = _self_recursion(fn, cls_node, tree)\n        if hit is None:\n            continue\n        if old_fns is None:\n            old_fns = functions(ctx.before)\n        if name in old_fns:\n            opath, ofn, ocls = old_fns[name]\n            otree = ctx.before.tree(opath)\n            if _self_recursion(ofn, _class_node(otree, ocls, opath), otree) is not None:\n                continue                                   # it already did: not this change\n        what = (\"reads itself\" if isinstance(hit, ast.Attribute) and isinstance(hit.ctx, ast.Load)\n                else \"sets itself\" if isinstance(hit, ast.Attribute) else \"calls itself\")\n        yield Finding(\n            \"recursive-cycle\", \"high\",\n            f\"{_short(name)}() {what} on every path (line {hit.lineno}): it can never return\",\n            path, hit.lineno,\n            detail=(f\"Nothing before line {hit.lineno} can return or raise, and the line is not \"\n                    f\"inside an if or a loop, so every call to {_short(name)}() starts another \"\n                    f\"one until Python gives up with RecursionError.\"))\n\n    # 2. existing functions that now call each other in a circle\n    old_comp: dict[str, int] = {}\n    cycles = [c for c in _sccs(ctx.graph, ctx.after_defs) if set(c) & touched]\n    if not cycles:\n        return\n    for i, comp in enumerate(_sccs(old_graph(ctx), ctx.before_defs)):\n        for n in comp:\n            old_comp[n] = i\n    for members in cycles:\n        existed = [m for m in members if m in ctx.before_defs]\n        if len(existed) < 2:\n            continue                                # recursion designed as recursion\n        if len({old_comp.get(m, -1 - k) for k, m in enumerate(members)}) == 1:\n            continue                                # the same loop was there before\n        if not all(m in fns for m in members):\n            fns = functions(ctx.after)\n        if _guarded(members, fns):\n            continue\n        ring = _order(members, ctx.graph)\n        if len(ring) == len(members) and _walks_a_structure(ring, ctx.graph, fns):\n            continue                                # node -> node.children: ends with the data\n        names = [f\"{_short(m)}()\" for m in ring]\n        first = ctx.after_defs[sorted(set(members) & touched)[0]]\n        yield Finding(\n            \"recursive-cycle\", \"medium\",\n            f\"this change makes {', '.join(names[:-1])} and {names[-1]} call each other in a \"\n            f\"loop\",\n            first.path, first.line,\n            detail=(f\"{' -> '.join(names + [names[0]])}. Before this change they did not call \"\n                    f\"each other in a circle. None of them takes a depth, limit or visited \"\n                    f\"argument, so nothing visible stops the loop: input that keeps it going \"\n                    f\"ends in RecursionError, or a hang.\"),\n            fix=\"Make sure the loop ends: pass a depth or visited set through every call, or \"\n                \"break the cycle.\")\n\n\ndef _class_node(tree, cls: str | None, path: str):\n    if cls is None or tree is None:\n        return None\n    mod = module_name(path)\n    node, body = None, tree.body\n    for part in cls[len(mod) + 1:].split(\".\"):\n        node = next((s for s in body if isinstance(s, ast.ClassDef) and s.name == part), None)\n        if node is None:\n            return None\n        body = node.body\n    return node\n", "magellan_lite/rules/regexes.py": "\"\"\"regex-catastrophic-backtracking: a regular expression whose matching time can explode.\n\nCloudflare, July 2 2019: a new WAF rule's regular expression ended in ``.*(?:.*=.*)``. On a\nrequest with no match, a backtracking engine tries every way of sharing the text between the\n``.*`` parts before giving up; the work grows with a power of the input's length. The rule\nran on every HTTP request worldwide, the CPUs serving them went to nearly 100%, and Cloudflare\nwas down for 27 minutes.\n\nPython's ``re`` backtracks the same way. The rule reads regex literals passed to\n``re.compile``, ``re.search`` and friends, or kept in a module constant first\n(``WORD = r\"(a+)+$\"`` then ``re.compile(WORD)``), with Python's own regex parser -- it never\nruns them -- and looks for the two classic shapes:\n\n* exponential: an unbounded repeat inside an unbounded repeat with nothing else that must\n  match, ``(a+)+`` or ``(\\\\w+\\\\s?)*``: a run of the same character can be split between them in\n  exponentially many ways;\n* polynomial: unbounded parts one after another that can match the same characters, ``.*.*``\n  (Cloudflare's had four), with something after them that can fail.\n\nOnly reported when something after the ambiguous part can make the match fail: if the first\nattempt always succeeds, there is nothing to backtrack over. A constant is looked up only\nwhen the module assigns it exactly once and no function around the call has a name of its\nown that hides it; the finding then sits on the pattern, where the fix goes.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nimport re\n\ntry:                                                    # Python 3.11+\n    from re import _constants as C, _parser as P\nexcept ImportError:                                     # Python 3.10\n    import sre_constants as C                           # type: ignore[no-redef]\n    import sre_parse as P                               # type: ignore[no-redef]\n\nfrom magellan_lite.findings import rule\n\n_FUNCTIONS = {\"compile\", \"match\", \"search\", \"fullmatch\", \"findall\", \"finditer\", \"sub\", \"subn\",\n              \"split\"}\n_ALPHA = frozenset(range(128))                          # ASCII is enough to see overlaps\n_NL = 10\n_DIGIT = frozenset(range(48, 58))\n_WORD = _DIGIT | frozenset(range(65, 91)) | frozenset(range(97, 123)) | {95}\n_SPACE = frozenset({9, 10, 11, 12, 13, 32})\n_CATEGORIES = {\n    C.CATEGORY_DIGIT: _DIGIT, C.CATEGORY_NOT_DIGIT: _ALPHA - _DIGIT,\n    C.CATEGORY_WORD: _WORD, C.CATEGORY_NOT_WORD: _ALPHA - _WORD,\n    C.CATEGORY_SPACE: _SPACE, C.CATEGORY_NOT_SPACE: _ALPHA - _SPACE,\n}\n_REPEATS = (C.MAX_REPEAT, C.MIN_REPEAT)                 # possessive repeats never backtrack\n_ATOMIC = getattr(C, \"ATOMIC_GROUP\", None)\n\n\nclass _Pattern:\n    def __init__(self, flags: int) -> None:\n        self.dotall = bool(flags & re.DOTALL)\n        self.nocase = bool(flags & re.IGNORECASE)\n\n    # -- what an item can match ----------------------------------------------------------\n    def chars(self, items) -> frozenset:\n        out = set()\n        for op, av in items:\n            out |= self.item_chars(op, av)\n        if self.nocase:\n            out |= {ord(chr(c).swapcase()) for c in out if chr(c).isalpha() and ord(chr(c).swapcase()) < 128}\n        return frozenset(out)\n\n    def item_chars(self, op, av) -> frozenset:\n        if op == C.LITERAL:\n            return frozenset({av})\n        if op == C.NOT_LITERAL:\n            return _ALPHA - {av}\n        if op == C.ANY:\n            return _ALPHA if self.dotall else _ALPHA - {_NL}\n        if op == C.IN:\n            out, negate = set(), False\n            for o, a in av:\n                if o == C.NEGATE:\n                    negate = True\n                elif o == C.LITERAL:\n                    out.add(a)\n                elif o == C.RANGE:\n                    out |= set(range(a[0], min(a[1], 127) + 1))\n                elif o == C.CATEGORY:\n                    out |= _CATEGORIES.get(a, _ALPHA)\n            return _ALPHA - out if negate else frozenset(out)\n        if op in _REPEATS or op == getattr(C, \"POSSESSIVE_REPEAT\", None):\n            return self.chars(av[2])\n        if op == C.SUBPATTERN:\n            return self.chars(av[-1])\n        if op == C.BRANCH:\n            return frozenset().union(*(self.chars(b) for b in av[1]))\n        if op == _ATOMIC:\n            return self.chars(av)\n        if op in (C.GROUPREF, C.GROUPREF_EXISTS):\n            return _ALPHA\n        return frozenset()                              # anchors and lookarounds: no text\n\n    def nullable(self, op, av) -> bool:\n        \"\"\"Can this item match the empty string?\"\"\"\n        if op in (C.LITERAL, C.NOT_LITERAL, C.ANY, C.IN):\n            return False\n        if op in _REPEATS or op == getattr(C, \"POSSESSIVE_REPEAT\", None):\n            return av[0] == 0 or self.all_nullable(av[2])\n        if op == C.SUBPATTERN:\n            return self.all_nullable(av[-1])\n        if op == C.BRANCH:\n            return any(self.all_nullable(b) for b in av[1])\n        if op == _ATOMIC:\n            return self.all_nullable(av)\n        return True\n\n    def all_nullable(self, items) -> bool:\n        return all(self.nullable(op, av) for op, av in items)\n\n    def pure(self, op, av, c: int) -> bool:\n        \"\"\"Can this item match a run of the character ``c`` and nothing else? ``\\\\w+`` can\n        for ``a``; ``(\\\\.\\\\w+)*`` cannot (each round needs a ``.``).\"\"\"\n        if op in (C.LITERAL, C.NOT_LITERAL, C.ANY, C.IN):\n            return c in self.chars([(op, av)])\n        if op in _REPEATS or op == getattr(C, \"POSSESSIVE_REPEAT\", None):\n            return av[1] > 0 and self.all_pure(av[2], c)\n        if op == C.SUBPATTERN:\n            return self.all_pure(av[-1], c)\n        if op == C.BRANCH:\n            return any(self.all_pure(b, c) for b in av[1])\n        if op == _ATOMIC:\n            return self.all_pure(av, c)\n        return False\n\n    def all_pure(self, items, c: int) -> bool:\n        some = False\n        for op, av in items:\n            if self.pure(op, av, c):\n                some = True\n            elif not self.nullable(op, av):\n                return False\n        return some\n\n    # -- the two shapes ------------------------------------------------------------------\n    @staticmethod\n    def flat(items) -> list:\n        \"\"\"Groups opened up into the sequence around them: what matches one after another.\"\"\"\n        out = []\n        for op, av in items:\n            if op == C.SUBPATTERN:\n                out += _Pattern.flat(av[-1])\n            else:\n                out.append((op, av))\n        return out\n\n    @staticmethod\n    def unbounded(op, av) -> bool:\n        return op in _REPEATS and av[1] == C.MAXREPEAT\n\n    def can_fail(self, rest, end_counts: bool) -> bool:\n        \"\"\"Is there something after the ambiguous part that can make the match fail?\"\"\"\n        for op, av in rest:\n            if op == C.AT:\n                if end_counts and av in (C.AT_END, C.AT_END_STRING):\n                    return True\n                continue\n            if not self.nullable(op, av):\n                return True\n        return False\n\n    def problems(self, items, after=()):\n        \"\"\"``(kind, k, char)``: the worst shape in ``items`` (followed by ``after``).\"\"\"\n        seq = self.flat(items)\n        for i, (op, av) in enumerate(seq):\n            rest = [*seq[i + 1:], *after]\n            if self.unbounded(op, av):\n                body = self.flat(av[2])\n                inner = [(o, a) for o, a in body if self.unbounded(o, a)]\n                others = [(o, a) for o, a in body if not self.unbounded(o, a)]\n                runs = [c for c in sorted(_ALPHA) if inner and self.pure(*inner[0], c)]\n                if runs and self.all_nullable(others) and self.can_fail(rest, end_counts=True):\n                    yield \"exponential\", 2, 32 if 32 in runs else runs[0]\n            if op in _REPEATS or op == C.BRANCH or op == C.ASSERT or op == C.ASSERT_NOT:\n                subs = [av[2]] if op in _REPEATS else av[1] if op == C.BRANCH else [av[1]]\n                for sub in subs:\n                    yield from self.problems(sub, rest)\n        # unbounded parts in a row (only parts that can match nothing between them) that can\n        # all take a run of the same character. Two is quadratic, everywhere and mostly\n        # harmless; three or more (Cloudflare's had four) is worth stopping for.\n        candidates = set().union(*(self.item_chars(*s) for s in seq if self.unbounded(*s)))\n        best = None\n        for c in sorted(candidates):\n            count = 0\n            for k, (op, av) in enumerate([*seq, (None, None)]):     # (None, None): the end\n                if op is not None and self.unbounded(op, av) and self.pure(op, av, c):\n                    count += 1\n                elif op is not None and self.nullable(op, av):\n                    continue\n                else:                                   # the run ends here\n                    rest = seq[k:] if op is not None else []\n                    if count >= 3 and self.can_fail([*rest, *after], end_counts=False):\n                        if best is None or count > best[0] or (count == best[0] and c == 32):\n                            best = (count, c)\n                    count = 0\n        if best:\n            yield \"polynomial\", best[0], best[1]\n\n\ndef _flags(call: ast.Call, index: int) -> int:\n    expr = call.args[index] if len(call.args) > index else \\\n        next((k.value for k in call.keywords if k.arg == \"flags\"), None)\n    out = 0\n    for node in ast.walk(expr) if expr is not None else ():\n        if isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name) and node.value.id == \"re\":\n            out |= getattr(re, node.attr, 0) if isinstance(getattr(re, node.attr, 0), int) else 0\n    return out\n\n\ndef _describe(kind: str, k: int, char: int) -> str:\n    c = repr(chr(char))\n    if kind == \"exponential\":\n        return (f\"an unbounded repeat sits inside another, so a run of {c} can be split \"\n                f\"between them in exponentially many ways before the match fails\")\n    words = {2: \"two\", 3: \"three\", 4: \"four\", 5: \"five\"}\n    return (f\"{words.get(k, str(k))} unbounded parts in a row can all match the same text \"\n            f\"(a run of {c}), and what follows can fail: the work grows like n^{k} with the \"\n            f\"input's length\")\n\n\ndef _bound_names(stmts) -> set[str]:\n    \"\"\"Names these statements bind (assign, import, define), without looking inside the\n    functions and classes they define.\"\"\"\n    out: set[str] = set()\n    todo = list(stmts)\n    while todo:\n        node = todo.pop()\n        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):\n            out.add(node.name)\n            continue\n        if isinstance(node, ast.Lambda):\n            continue\n        if isinstance(node, ast.Name) and isinstance(node.ctx, (ast.Store, ast.Del)):\n            out.add(node.id)\n        elif isinstance(node, (ast.Import, ast.ImportFrom)):\n            out |= {(a.asname or a.name).split(\".\")[0] for a in node.names}\n        elif isinstance(node, ast.ExceptHandler) and node.name:\n            out.add(node.name)\n        todo.extend(ast.iter_child_nodes(node))\n    return out\n\n\ndef _constants(tree: ast.Module) -> dict[str, ast.Constant]:\n    \"\"\"Module constants holding a string, ``WORD = r\"(a+)+$\"``: only names the module binds\n    once and no function rebinds with ``global``.\"\"\"\n    strings: dict[str, ast.Constant] = {}\n    count: dict[str, int] = {}\n    for stmt in tree.body:\n        for name in _bound_names([stmt]):\n            count[name] = count.get(name, 0) + 1\n        target = (stmt.targets[0] if isinstance(stmt, ast.Assign) and len(stmt.targets) == 1\n                  else stmt.target if isinstance(stmt, ast.AnnAssign) else None)\n        value = getattr(stmt, \"value\", None)\n        if (isinstance(target, ast.Name) and isinstance(value, ast.Constant)\n                and isinstance(value.value, str)):\n            strings[target.id] = value\n    rebound = {n for g in ast.walk(tree) if isinstance(g, ast.Global) for n in g.names}\n    return {n: v for n, v in strings.items() if count.get(n) == 1 and n not in rebound}\n\n\ndef _local_names(fn: ast.AST) -> set[str]:\n    \"\"\"Names a function (or lambda, or class body) has of its own.\"\"\"\n    out: set[str] = set()\n    args = getattr(fn, \"args\", None)\n    if args is not None:\n        out |= {a.arg for a in [*args.posonlyargs, *args.args, *args.kwonlyargs,\n                                args.vararg, args.kwarg] if a is not None}\n    body = getattr(fn, \"body\", [])\n    if isinstance(body, list):\n        out |= _bound_names(body)\n    return out\n\n\ndef _re_calls(node: ast.AST, hidden: frozenset = frozenset()):\n    \"\"\"Every ``re.<function>(pattern, ...)`` call, with the names that the functions and\n    classes around it have of their own (they hide a module constant of the same name).\"\"\"\n    for child in ast.iter_child_nodes(node):\n        if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda, ast.ClassDef)):\n            yield from _re_calls(child, hidden | _local_names(child))\n            continue\n        if (isinstance(child, ast.Call) and isinstance(child.func, ast.Attribute)\n                and isinstance(child.func.value, ast.Name) and child.func.value.id == \"re\"\n                and child.func.attr in _FUNCTIONS and child.args):\n            yield child, hidden\n        yield from _re_calls(child, hidden)\n\n\ndef _problem(text: str, call: ast.Call):\n    \"\"\"The worst shape in the pattern ``text`` as ``call`` compiles it, or None.\"\"\"\n    flag_index = {\"compile\": 1, \"match\": 2, \"search\": 2, \"fullmatch\": 2, \"findall\": 2,\n                  \"finditer\": 2, \"split\": 3, \"sub\": 4, \"subn\": 4}[call.func.attr]\n    try:\n        parsed = P.parse(text, _flags(call, flag_index))\n    except Exception:                                   # noqa: BLE001 - re.compile would say\n        return None\n    pattern = _Pattern(parsed.state.flags)\n    found = sorted(pattern.problems(list(parsed)), key=lambda p: (p[0] != \"exponential\", -p[1]))\n    return found[0] if found else None\n\n\n@rule(\"regex-catastrophic-backtracking\", \"high\",\n      fix=\"Remove the overlap: drop redundant `.*`s, make the parts match different \"\n          \"characters, or bound them ({0,100}); then time the pattern on a long input that \"\n          \"does not match.\")\ndef regex_catastrophic_backtracking(tree: ast.Module, path: str):\n    constants = _constants(tree)\n    reported: set[str] = set()                          # one finding per constant\n    for call, hidden in _re_calls(tree):\n        arg, name = call.args[0], None\n        if isinstance(arg, ast.Name) and arg.id in constants and arg.id not in hidden:\n            name, literal = arg.id, constants[arg.id]\n            if name in reported:\n                continue\n        elif isinstance(arg, ast.Constant) and isinstance(arg.value, str):\n            literal = arg\n        else:\n            continue\n        problem = _problem(literal.value, call)\n        if problem is None:\n            continue\n        shown = literal.value if len(literal.value) <= 48 else literal.value[:45] + \"...\"\n        where = \"\" if name is None else \\\n            f\" kept in {name} (used by re.{call.func.attr}() on line {call.lineno})\"\n        if name is not None:\n            reported.add(name)\n        yield (literal, f\"the regular expression `{shown}`{where} can backtrack \"\n                        f\"catastrophically: {_describe(*problem)}\",\n               \"A request that almost matches keeps the CPU busy for seconds or more. \"\n               \"Cloudflare, 2019: one such pattern took every server's HTTP CPUs to nearly \"\n               \"100% and the network down for 27 minutes.\")\n", "magellan_lite/rules/reuse.py": "\"\"\"reused-value: a constant's value handed to a new meaning.\n\nKnight Capital, 2012: the flag that used to switch on Power Peg (unused since 2003) was reused\nfor new RLP code. One of eight servers kept the old build; orders carrying the reused flag\nwoke Power Peg up there, and Knight lost over $460 million in 45 minutes. Inside the\nrepository nothing looked wrong: one constant deleted, another added, and the dispatch now\ncalled the new code.\n\nThe signal: a constant's value goes away (the constant is deleted, or given a new value)\nwhile a new constant in the same scope takes that exact value, and a function that read the\nold one now reads the new one *and calls different things*. A plain rename leaves the calls\nalone, and stays quiet.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nimport re\n\nfrom magellan_lite.findings import Finding, change_rule\n\n\ndef _value(text: str):\n    try:\n        return ast.literal_eval(text)\n    except (ValueError, SyntaxError, TypeError, MemoryError, RecursionError):\n        return None\n\n\ndef _as_written(source: str | None, name: str, line: int, fallback: str) -> str:\n    \"\"\"The value as the code spells it (``0x08``, not ``8``).\"\"\"\n    lines = (source or \"\").splitlines()\n    if 0 < line <= len(lines):\n        m = re.match(rf\"\\s*{re.escape(name)}\\s*(?::[^=]+)?=\\s*(.+?)\\s*(#.*)?$\", lines[line - 1])\n        if m:\n            return m.group(1)\n    return fallback\n\n\ndef _calls(graph, fn: str) -> set[str]:\n    return {e.dst for e in graph.uses(fn) if e.kind == \"calls\"}\n\n\ndef _short(name: str) -> str:\n    return name.rsplit(\".\", 1)[-1]\n\n\ndef _and(items: list[str]) -> str:\n    return items[0] if len(items) == 1 else \", \".join(items[:-1]) + \" and \" + items[-1] if items else \"\"\n\n\n@change_rule(\"reused-value\", \"high\",\n             fix=\"Give the new meaning a value of its own, and retire the old one: reject it \"\n                 \"(or log it and refuse), so whatever still sends it fails loudly instead of \"\n                 \"running the new code.\")\ndef reused_value(ctx):\n    from magellan_lite.graph import build_graph\n    old_graph = None\n    for gone, old in ctx.before_defs.items():\n        if old.kind != \"constant\" or _value(old.value) is None:\n            continue\n        now = ctx.after_defs.get(gone)\n        if now is not None and now.value == old.value:\n            continue                                    # still there, same value\n        scope = gone.rsplit(\".\", 1)[0]\n        heirs = [d for n, d in ctx.after_defs.items()\n                 if d.kind == \"constant\" and n != gone and n.rsplit(\".\", 1)[0] == scope\n                 and _value(d.value) == _value(old.value) and type(_value(d.value)) is type(_value(old.value))\n                 and (n not in ctx.before_defs or ctx.before_defs[n].value != d.value)]\n        if not heirs:\n            continue\n        if old_graph is None:\n            old_graph = build_graph(ctx.before, ctx.before_defs)\n        old_readers = {e.src for e in old_graph.callers(gone) if e.kind == \"reads\"}\n        written = _as_written(ctx.before.files.get(old.path), _short(gone), old.line, old.value)\n        for heir in heirs:\n            for e in ctx.graph.callers(heir.name):\n                if e.kind != \"reads\" or e.src not in old_readers:\n                    continue\n                before, after = _calls(old_graph, e.src), _calls(ctx.graph, e.src)\n                if before == after:\n                    continue                            # a rename: same value, same behaviour\n                lost = _and(sorted(_short(c) + \"()\" for c in before - after)) or \"nothing\"\n                new = _and(sorted(_short(c) + \"()\" for c in after - before)) or \"nothing\"\n                yield Finding(\n                    \"reused-value\", \"high\",\n                    f\"{_short(heir.name)} takes over the value {written} that \"\n                    f\"{_short(gone)} had: {_short(e.src)}() used to call {lost} for it, and \"\n                    f\"now calls {new}\",\n                    e.path, e.line,\n                    detail=f\"Anything that still sends, stores or runs with the old meaning \"\n                           f\"of {written} -- another service, saved data, a server still on \"\n                           f\"the previous build -- now gets the new behaviour. Knight \"\n                           f\"Capital, 2012: a reused flag woke dead code on one server and \"\n                           f\"lost $460 million in 45 minutes.\")\n", "magellan_lite/rules/taint.py": "\"\"\"unvalidated-input-reaches-sink: outside input reaching a dangerous call unchecked.\n\nFrom the full Magellan (``magellan/python/rules/dataflow.py``). The dangerous change is rarely\nat the edit site: a route handler gains a parameter and passes it three calls down to\n``subprocess.run``, or a helper that used to get a validated number now gets a string. Nothing\nat either end looks wrong; the *path* is wrong, and the call graph knows the calls.\n\nValues from outside -- request data in a web handler (Flask, Django, FastAPI and friends),\n``sys.argv`` and ``argparse``, ``input()``, a network response -- are followed through\nassignments, string building and calls, into the project's own functions and back out of\nthem. A flow ends in a sink: a shell command, ``eval``/``exec``, a SQL string, an unsafe\ndeserializer (``pickle``, ``yaml.load``), a file path, an outbound URL, a redirect, raw HTML.\n\nA flow is cleared by a sanitizer (``int()``, ``shlex.quote`` for shells only, ``html.escape``\nfor HTML only, ``os.path.basename``, ...), by a guard (``if x in ALLOWED``, ``x.isdigit()``,\n``re.fullmatch(p, x)``, or ``if not valid(x): raise`` before the use), or by a function named\nlike a validator (``validate_*``, ``sanitize_*``, ``check_*``). Only flows through code the\nchange added or edited are reported: a standing flow is not news on every commit.\n\nQuiet on purpose: request data counts only in files that import a web framework, a command\nline tool opening the path it was given is what it is for (only shells, ``eval``, SQL and\ndeserializers count for command-line input, one level lower), and anything the analysis cannot\nfollow (a value smuggled through another object, a call it cannot resolve) is dropped, so a\nmissing finding is not proof of safety.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nimport re\nfrom dataclasses import dataclass, field\n\nfrom magellan_lite.findings import Finding, change_rule\nfrom magellan_lite.rules.common import call_name, dotted, edited, functions, is_test_path\n\nALL = \"*\"\n_WEB = (\"flask\", \"django\", \"fastapi\", \"starlette\", \"aiohttp\", \"tornado\", \"bottle\", \"falcon\",\n        \"sanic\", \"pyramid\", \"werkzeug\", \"quart\", \"litestar\", \"rest_framework\")\n_CLI = (\"click\", \"typer\")\n_REQUEST_NAMES = {\"request\", \"req\", \"flask_request\"}\n_REQUEST_ATTRS = {\"args\", \"form\", \"values\", \"json\", \"data\", \"files\", \"headers\", \"cookies\",\n                  \"GET\", \"POST\", \"body\", \"query_params\", \"path_params\", \"query\", \"params\",\n                  \"url\", \"host\", \"query_string\", \"get_json\", \"get_data\", \"stream\", \"content\",\n                  \"match_info\", \"path\"}\n_ROUTE_DECORATORS = {\"route\", \"get\", \"post\", \"put\", \"patch\", \"delete\", \"websocket\",\n                     \"api_route\", \"api_view\", \"view_config\", \"endpoint\"}\n_CLI_DECORATORS = {\"command\", \"group\"}\n#: handler parameters that are framework objects, not user data\n_NOT_DATA = {\"request\", \"req\", \"response\", \"session\", \"context\", \"db\", \"background_tasks\",\n             \"self\", \"cls\"}\n#: parameter types a framework has already converted (FastAPI, Flask converters)\n_TYPED = {\"int\", \"float\", \"bool\", \"UUID\", \"uuid.UUID\", \"date\", \"datetime\", \"Decimal\"}\n_NETWORK_CALLS = {\"requests.get\", \"requests.post\", \"requests.put\", \"requests.request\",\n                  \"urllib.request.urlopen\", \"httpx.get\", \"httpx.post\", \"httpx.request\"}\n_NETWORK_RESULT = {\"text\", \"json\", \"content\", \"read\"}\n\n\n@dataclass(frozen=True)\nclass SinkSpec:\n    kind: str\n    names: frozenset          # canonical dotted names (after import aliases)\n    tails: frozenset = frozenset()     # matched on the last part: framework functions\n    methods: frozenset = frozenset()   # matched on `<anything>.<method>(...)`\n    builtins: frozenset = frozenset()  # matched on a bare name nothing in the file rebinds\n    args: str = \"first\"       # \"first\" | \"any\"\n    does: str = \"\"\n\n\nSINKS = (\n    SinkSpec(\"exec\", frozenset({\n        \"os.system\", \"os.popen\", \"subprocess.run\", \"subprocess.call\", \"subprocess.check_call\",\n        \"subprocess.check_output\", \"subprocess.Popen\", \"subprocess.getoutput\",\n        \"subprocess.getstatusoutput\", \"os.execv\", \"os.execvp\", \"os.execl\", \"os.execlp\",\n        \"os.spawnl\", \"os.spawnlp\", \"commands.getoutput\", \"asyncio.create_subprocess_shell\"}),\n        does=\"runs a shell command\"),\n    SinkSpec(\"eval\", frozenset({\"builtins.eval\", \"builtins.exec\"}),\n             builtins=frozenset({\"eval\", \"exec\", \"compile\"}), does=\"runs it as Python code\"),\n    SinkSpec(\"sql\", frozenset(), methods=frozenset({\"execute\", \"executemany\", \"executescript\"}),\n             does=\"runs it as part of a SQL statement\"),\n    SinkSpec(\"deserialize\", frozenset({\n        \"pickle.loads\", \"pickle.load\", \"marshal.loads\", \"marshal.load\", \"dill.loads\",\n        \"yaml.unsafe_load\", \"yaml.load\", \"shelve.open\", \"jsonpickle.decode\",\n        \"cPickle.loads\"}), does=\"unpickles it, which can run code\"),\n    SinkSpec(\"path\", frozenset({\n        \"io.open\", \"os.remove\", \"os.unlink\", \"os.rmdir\", \"os.removedirs\", \"os.rename\",\n        \"os.chmod\", \"os.listdir\", \"os.makedirs\", \"shutil.rmtree\", \"shutil.copy\",\n        \"shutil.copyfile\", \"shutil.move\", \"shutil.copytree\"}),\n        tails=frozenset({\"send_file\"}), builtins=frozenset({\"open\"}), args=\"any\",\n        does=\"uses it as a file path\"),\n    SinkSpec(\"ssrf\", frozenset({\n        \"requests.get\", \"requests.post\", \"requests.put\", \"requests.delete\", \"requests.head\",\n        \"requests.patch\", \"requests.request\", \"urllib.request.urlopen\", \"httpx.get\",\n        \"httpx.post\", \"httpx.request\", \"aiohttp.request\"}),\n        does=\"fetches it as a URL from the server\"),\n    SinkSpec(\"redirect\", frozenset(),\n             tails=frozenset({\"redirect\", \"HttpResponseRedirect\", \"RedirectResponse\"}),\n             does=\"redirects the visitor to it\"),\n    SinkSpec(\"html\", frozenset(),\n             tails=frozenset({\"render_template_string\", \"Markup\", \"mark_safe\",\n                              \"HTMLResponse\"}), does=\"puts it into a page as raw HTML\"),\n)\n_SEVERITY = {\"exec\": \"critical\", \"eval\": \"critical\", \"sql\": \"critical\",\n             \"deserialize\": \"critical\", \"path\": \"high\", \"ssrf\": \"high\",\n             \"redirect\": \"medium\", \"html\": \"medium\"}\n_LOCAL_KINDS = {\"cli\", \"stdin\"}             # the person running it typed it\n_LOCAL_SINKS = {\"exec\", \"eval\", \"sql\", \"deserialize\"}\n_FIX = {\n    \"exec\": \"Pass a list of arguments without shell=True, and check the value against a \"\n            \"list of allowed ones; shlex.quote is a last resort.\",\n    \"eval\": \"Never run input as code: parse it (json, ast.literal_eval) or look it up in a \"\n            \"fixed table.\",\n    \"sql\": \"Use a parameterized query: execute(sql, params), never build the SQL string \"\n           \"from the value.\",\n    \"deserialize\": \"Use a data-only format (json), or yaml.safe_load, or check a signature \"\n                   \"before loading.\",\n    \"path\": \"Resolve the path and check it stays inside the allowed folder; use \"\n            \"os.path.basename for a file name.\",\n    \"ssrf\": \"Check the host against an allow-list and refuse internal addresses.\",\n    \"redirect\": \"Only redirect to known relative paths or an allow-listed host.\",\n    \"html\": \"Escape it (html.escape, or let the template escape it) instead of marking it \"\n            \"safe.\",\n}\n\n_CLEAR_ALL = {\"int\", \"float\", \"bool\", \"len\", \"abs\", \"round\", \"ord\", \"hash\", \"id\", \"min\",\n              \"max\", \"isinstance\", \"type\", \"uuid.UUID\", \"UUID\", \"ipaddress.ip_address\",\n              \"Decimal\", \"decimal.Decimal\", \"os.path.basename\", \"secure_filename\",\n              \"werkzeug.utils.secure_filename\", \"slugify\", \"hexdigest\", \"digest\",\n              \"hashlib.sha256\", \"hashlib.sha1\", \"hashlib.md5\", \"datetime.fromisoformat\"}\n_CLEAR_KINDS = {\n    \"shlex.quote\": {\"exec\"}, \"shlex.join\": {\"exec\"}, \"pipes.quote\": {\"exec\"},\n    \"html.escape\": {\"html\"}, \"markupsafe.escape\": {\"html\"}, \"escape\": {\"html\"},\n    \"bleach.clean\": {\"html\"}, \"urllib.parse.quote\": {\"ssrf\", \"redirect\", \"path\"},\n    \"urllib.parse.quote_plus\": {\"ssrf\", \"redirect\", \"path\"}, \"quote\": {\"ssrf\", \"redirect\", \"path\"},\n    \"quote_plus\": {\"ssrf\", \"redirect\", \"path\"}, \"re.escape\": {\"eval\"},\n    \"json.dumps\": {\"eval\", \"html\"},\n}\n_VALIDATOR = re.compile(r\"^_*(validate|sanitize|sanitise|clean|check|verify|is_valid|ensure|\"\n                        r\"assert_valid|require)\", re.I)\n_VALID_METHODS = {\"isdigit\", \"isalnum\", \"isalpha\", \"isnumeric\", \"isidentifier\", \"isdecimal\"}\n\n\n@dataclass(frozen=True)\nclass Source:\n    kind: str\n    desc: str\n    fn: str\n    path: str\n    line: int\n\n\n@dataclass(frozen=True)\nclass Origin:\n    \"\"\"Where a value's taint comes from: a real source, or the function's Nth parameter.\"\"\"\n    src: Source | None = None\n    param: int = -1\n    cleared: frozenset = frozenset()\n\n    def clearing(self, kinds) -> \"Origin\":\n        return Origin(self.src, self.param, self.cleared | frozenset(kinds))\n\n\n@dataclass(frozen=True)\nclass Hop:\n    fn: str               # the function that makes the call\n    path: str\n    line: int\n    callee: str           # the function it hands the value to\n\n\n@dataclass(frozen=True)\nclass SinkHit:\n    kind: str\n    call: str\n    fn: str\n    path: str\n    line: int\n    chain: tuple = ()             # calls leading down to the sink\n\n\n@dataclass\nclass Summary:\n    param_sinks: dict = field(default_factory=dict)      # param index -> {key: SinkHit}\n    param_returns: set = field(default_factory=set)\n    returns_source: set = field(default_factory=set)\n\n\n@dataclass(frozen=True)\nclass Flow:\n    source: Source\n    sink: SinkHit\n    via: str                       # the function the flow was found in\n\n\ndef _short(name: str) -> str:\n    return name.rsplit(\".\", 1)[-1]\n\n\nclass _File:\n    \"\"\"What one module says about its names: imports, and whether it is web or CLI code.\"\"\"\n\n    def __init__(self, tree: ast.Module) -> None:\n        self.aliases: dict[str, str] = {}\n        self.rebound: set[str] = set()\n        roots: set[str] = set()\n        for node in ast.walk(tree):\n            if isinstance(node, ast.Import):\n                for a in node.names:\n                    roots.add(a.name.split(\".\")[0])\n                    self.aliases[a.asname or a.name.split(\".\")[0]] = \\\n                        a.name if a.asname else a.name.split(\".\")[0]\n            elif isinstance(node, ast.ImportFrom) and node.module and not node.level:\n                roots.add(node.module.split(\".\")[0])\n                for a in node.names:\n                    self.aliases[a.asname or a.name] = f\"{node.module}.{a.name}\"\n            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):\n                self.rebound.add(node.name)\n            elif isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):\n                self.rebound.add(node.id)\n        self.web = any(r in _WEB for r in roots)\n        self.cli = any(r in _CLI for r in roots)\n\n    def canonical(self, func: ast.AST) -> str:\n        \"\"\"The dotted name a call target stands for, through the module's imports.\"\"\"\n        name = dotted(func)\n        if not name:\n            if isinstance(func, ast.Attribute):\n                return \"?.\" + func.attr\n            return \"\"\n        head, _, rest = name.partition(\".\")\n        if head in self.aliases:\n            return self.aliases[head] + (\".\" + rest if rest else \"\")\n        return name\n\n\nclass _Analysis:\n    def __init__(self, ctx) -> None:\n        self.ctx = ctx\n        self.fns = functions(ctx.after)\n        self.files: dict[str, _File] = {}\n        self.summaries: dict[str, Summary] = {}\n        self.busy: set[str] = set()\n        self.flows: set[Flow] = set()\n        self.walked: set[str] = set()\n\n    def file(self, path: str) -> _File:\n        if path not in self.files:\n            self.files[path] = _File(self.ctx.after.tree(path))\n        return self.files[path]\n\n    def callees(self, owner: str, call: ast.Call, calls_on_line: int) -> list[str]:\n        \"\"\"The project's definitions this exact call resolves to.\"\"\"\n        edges = [e for e in self.ctx.graph.uses(owner)\n                 if e.kind == \"calls\" and not e.guess and e.line == call.lineno]\n        named = [e.dst for e in edges if _short(e.dst) == call_name(call)]\n        if named:\n            return list(dict.fromkeys(named))\n        return list(dict.fromkeys(e.dst for e in edges)) if calls_on_line == 1 else []\n\n    def target(self, name: str) -> str | None:\n        \"\"\"The function a call to ``name`` runs: itself, or a class's ``__init__``.\"\"\"\n        if name in self.fns:\n            return name\n        init = f\"{name}.__init__\"\n        return init if init in self.fns else None\n\n    def summary(self, name: str) -> Summary | None:\n        if name in self.summaries:\n            return self.summaries[name]\n        if name in self.busy or len(self.busy) > 40:\n            return None                     # recursion, or too deep: nothing known\n        self.walk(name)\n        return self.summaries.get(name)\n\n    def walk(self, name: str) -> None:\n        if name in self.walked or name not in self.fns:\n            return\n        path, fn, cls = self.fns[name]\n        if is_test_path(path):\n            self.walked.add(name)\n            return\n        self.busy.add(name)\n        w = _Walk(self, name, path, fn, cls, self.file(path))\n        w.block(fn.body)\n        self.busy.discard(name)\n        self.walked.add(name)\n        self.summaries[name] = w.summary\n        self.flows |= w.flows\n\n\nclass _Walk:\n    \"\"\"One forward pass over a function body, tracking which names carry outside input.\"\"\"\n\n    def __init__(self, an: _Analysis, name: str, path: str, fn, cls, f: _File) -> None:\n        self.an, self.name, self.path, self.fn, self.f = an, name, path, fn, f\n        self.env: dict[str, frozenset] = {}\n        self.summary = Summary()\n        self.flows: set[Flow] = set()\n        self.depth = 0\n        self.lines: dict[int, int] = {}\n        for n in ast.walk(fn):\n            if isinstance(n, ast.Call):\n                self.lines[n.lineno] = self.lines.get(n.lineno, 0) + 1\n        kind = self._handler()\n        args = fn.args\n        positional = [*args.posonlyargs, *args.args]\n        method = cls is not None and positional[:1] and positional[0].arg in (\"self\", \"cls\")\n        for i, a in enumerate(positional):\n            if method and i == 0:\n                continue\n            if kind and a.arg not in _NOT_DATA and not self._typed(a):\n                self.env[a.arg] = frozenset({Origin(src=Source(\n                    kind, f\"parameter {a.arg} of {_short(name)}()\", name, path, fn.lineno))})\n            elif not kind:\n                self.env[a.arg] = frozenset({Origin(param=i)})\n        for a in [*args.kwonlyargs, args.vararg, args.kwarg]:\n            if a is not None and kind and a.arg not in _NOT_DATA and not self._typed(a):\n                self.env[a.arg] = frozenset({Origin(src=Source(\n                    kind, f\"parameter {a.arg} of {_short(name)}()\", name, path, fn.lineno))})\n\n    def _handler(self) -> str:\n        \"\"\"``http-request`` for a web handler, ``cli`` for a click/typer command, else \"\".\"\"\"\n        for d in self.fn.decorator_list:\n            target = d.func if isinstance(d, ast.Call) else d\n            tail = target.attr if isinstance(target, ast.Attribute) else getattr(target, \"id\", \"\")\n            if tail in _ROUTE_DECORATORS and self.f.web:\n                return \"http-request\"\n            if tail in _CLI_DECORATORS and self.f.cli:\n                return \"cli\"\n        params = [a.arg for a in [*self.fn.args.posonlyargs, *self.fn.args.args]]\n        params = params[1:] if params[:1] in ([\"self\"], [\"cls\"]) else params\n        if params[:1] == [\"request\"] and self.f.web:\n            return \"http-request\"                     # a Django view\n        return \"\"\n\n    @staticmethod\n    def _typed(a: ast.arg) -> bool:\n        return a.annotation is not None and ast.unparse(a.annotation) in _TYPED\n\n    # -- values ---------------------------------------------------------------------------\n    def _src(self, kind: str, desc: str, node: ast.AST) -> frozenset:\n        return frozenset({Origin(src=Source(kind, desc, self.name, self.path,\n                                            getattr(node, \"lineno\", 0)))})\n\n    def T(self, e: ast.AST | None) -> frozenset:\n        if e is None or isinstance(e, ast.Constant):\n            return frozenset()\n        if isinstance(e, ast.Name):\n            return self.env.get(e.id, frozenset())\n        if isinstance(e, ast.Call):\n            return self.call(e)\n        if isinstance(e, ast.Attribute):\n            base = dotted(e)\n            root = base.split(\".\")[0]\n            if root in _REQUEST_NAMES and e.attr in _REQUEST_ATTRS and self.f.web:\n                return self._src(\"http-request\", base, e)\n            if self.f.canonical(e) == \"sys.argv\":\n                return self._src(\"cli\", \"sys.argv\", e)\n            if e.attr in _NETWORK_RESULT and isinstance(e.value, ast.Call) \\\n                    and self.f.canonical(e.value.func) in _NETWORK_CALLS:\n                return self._src(\"network\", f\"the response of {dotted(e.value.func)}()\", e)\n            return self.T(e.value)\n        if isinstance(e, ast.Subscript):\n            if self.f.canonical(e.value) == \"sys.argv\":\n                return self._src(\"cli\", \"sys.argv\", e)\n            return self.T(e.value) | self.T(e.slice)\n        if isinstance(e, ast.Compare):\n            return frozenset()\n        if isinstance(e, (ast.ListComp, ast.SetComp, ast.GeneratorExp, ast.DictComp)):\n            saved = dict(self.env)\n            for gen in e.generators:\n                taint = self.T(gen.iter)\n                for n in ast.walk(gen.target):\n                    if isinstance(n, ast.Name):\n                        self.env[n.id] = taint\n            out = self.T(e.value if isinstance(e, ast.DictComp) else e.elt)\n            if isinstance(e, ast.DictComp):\n                out |= self.T(e.key)\n            self.env = saved\n            return out\n        if isinstance(e, ast.NamedExpr):\n            taint = self.T(e.value)\n            self.env[e.target.id] = taint\n            return taint\n        if isinstance(e, (ast.JoinedStr, ast.FormattedValue, ast.BinOp, ast.BoolOp, ast.IfExp,\n                          ast.Tuple, ast.List, ast.Set, ast.Dict, ast.UnaryOp, ast.Await,\n                          ast.Starred, ast.Slice)):\n            out: frozenset = frozenset()\n            for child in ast.iter_child_nodes(e):\n                if isinstance(child, ast.expr):\n                    out |= self.T(child)\n            return out\n        return frozenset()\n\n    def _reach(self, taint: frozenset, hit: SinkHit) -> None:\n        for o in taint:\n            if hit.kind in o.cleared or ALL in o.cleared:\n                continue\n            if o.src is not None:\n                self.flows.add(Flow(o.src, hit, self.name))\n            elif o.param >= 0:\n                self.summary.param_sinks.setdefault(o.param, {}).setdefault(\n                    (hit.kind, hit.fn, hit.line), hit)\n\n    def call(self, node: ast.Call) -> frozenset:\n        func = node.func\n        name = self.f.canonical(func)\n        tail = name.rsplit(\".\", 1)[-1] if name else \"\"\n        recv = self.T(func.value) if isinstance(func, ast.Attribute) else frozenset()\n        args = [self.T(a) for a in node.args]\n        kwargs = {k.arg: self.T(k.value) for k in node.keywords}\n        every = recv.union(*args, *kwargs.values())\n\n        # sources\n        if name in (\"input\", \"raw_input\") and isinstance(func, ast.Name) \\\n                and func.id not in self.f.rebound:\n            return self._src(\"stdin\", f\"{func.id}()\", node)\n        if name in (\"sys.stdin.read\", \"sys.stdin.readline\", \"sys.stdin.readlines\"):\n            return self._src(\"stdin\", name, node)\n        if tail in (\"recv\", \"recvfrom\") and isinstance(func, ast.Attribute):\n            return self._src(\"socket\", f\"{dotted(func) or tail}()\", node)\n        if tail == \"parse_args\" and isinstance(func, ast.Attribute):\n            return self._src(\"cli\", \"the command line arguments\", node)\n        if tail in _NETWORK_RESULT and isinstance(func, ast.Attribute) \\\n                and isinstance(func.value, ast.Call) \\\n                and self.f.canonical(func.value.func) in _NETWORK_CALLS:\n            return self._src(\"network\", f\"the response of {dotted(func.value.func)}()\", node)\n\n        targets = [t for t in (self.an.target(c) for c in\n                               self.an.callees(self.name, node, self.lines.get(node.lineno, 0)))\n                   if t]\n        if not targets:\n            self._sinks(node, name, args, kwargs)\n        if name in _CLEAR_ALL or tail in _CLEAR_ALL or _VALIDATOR.match(tail or \"\"):\n            return frozenset()\n        cleared = _CLEAR_KINDS.get(name) or _CLEAR_KINDS.get(tail)\n\n        result = every\n        composed = False\n        for t in targets:\n            summ = self.an.summary(t)\n            if summ is None:\n                continue\n            bound = self._bind(node, t, args, kwargs)\n            hop = Hop(self.name, self.path, node.lineno, t)\n            for idx, taint in bound.items():\n                for hit in summ.param_sinks.get(idx, {}).values():\n                    self._reach(taint, SinkHit(hit.kind, hit.call, hit.fn, hit.path, hit.line,\n                                               (hop,) + hit.chain))\n            if not composed:\n                result, composed = frozenset(), True\n            for idx in summ.param_returns:\n                result |= bound.get(idx, frozenset())\n            result |= frozenset(Origin(src=s) for s in summ.returns_source)\n        if cleared:\n            result = frozenset(o.clearing(cleared) for o in result)\n        return result\n\n    def _bind(self, call: ast.Call, target: str, args, kwargs) -> dict[int, frozenset]:\n        _path, fn, cls = self.an.fns[target]\n        positional = [a.arg for a in [*fn.args.posonlyargs, *fn.args.args]]\n        shift = 1 if cls is not None and positional[:1] in ([\"self\"], [\"cls\"]) else 0\n        out: dict[int, frozenset] = {}\n        for i, taint in enumerate(args):\n            if isinstance(call.args[i], ast.Starred):\n                break\n            if i + shift < len(positional):\n                out[i + shift] = out.get(i + shift, frozenset()) | taint\n        for k, taint in kwargs.items():\n            if k in positional:\n                idx = positional.index(k)\n                out[idx] = out.get(idx, frozenset()) | taint\n        return out\n\n    def _sinks(self, node: ast.Call, name: str, args, kwargs) -> None:\n        func = node.func\n        tail = name.rsplit(\".\", 1)[-1] if name else \"\"\n        bare = isinstance(func, ast.Name) and func.id not in self.f.rebound \\\n            and func.id not in self.f.aliases\n        for spec in SINKS:\n            hit = (name in spec.names or (tail in spec.tails and tail)\n                   or (bare and func.id in spec.builtins)\n                   or (isinstance(func, ast.Attribute) and func.attr in spec.methods))\n            if not hit:\n                continue\n            if spec.kind == \"deserialize\" and name == \"yaml.load\":\n                loader = next((ast.unparse(k.value) for k in node.keywords\n                               if k.arg == \"Loader\"), \"\")\n                if len(node.args) > 1:\n                    loader = ast.unparse(node.args[1])\n                if \"Safe\" in loader:\n                    continue\n            if spec.kind == \"exec\" and name.startswith(\"subprocess.\") \\\n                    and name not in (\"subprocess.getoutput\", \"subprocess.getstatusoutput\"):\n                shell = any(k.arg == \"shell\" and isinstance(k.value, ast.Constant)\n                            and k.value.value for k in node.keywords)\n                taint = args[0] if args else kwargs.get(\"args\", frozenset())\n                first = node.args[0] if node.args else None\n                if not shell and isinstance(first, (ast.List, ast.Tuple)):\n                    # an argument list is not re-read by a shell: only the program matters\n                    taint = self.T(first.elts[0]) if first.elts else frozenset()\n            elif spec.args == \"first\":\n                taint = args[0] if args else kwargs.get(\"url\", frozenset())\n            else:\n                taint = frozenset().union(*args[:2]) if args[:2] else frozenset()\n                for k in (\"file\", \"path\", \"src\", \"dst\", \"filename\", \"name\"):\n                    taint |= kwargs.get(k, frozenset())\n            if taint:\n                shown = dotted(func) or tail\n                self._reach(taint, SinkHit(spec.kind, shown, self.name, self.path,\n                                           node.lineno))\n\n    # -- statements ---------------------------------------------------------------------------\n    def validated(self, test: ast.expr) -> tuple[set[str], set[str]]:\n        \"\"\"``(names safe when the test is true, names safe when it is false)``.\"\"\"\n        yes: set[str] = set()\n        no: set[str] = set()\n        if isinstance(test, ast.UnaryOp) and isinstance(test.op, ast.Not):\n            t, f = self.validated(test.operand)\n            return f, t\n        if isinstance(test, ast.BoolOp):\n            for v in test.values:\n                t, f = self.validated(v)\n                if isinstance(test.op, ast.And):\n                    yes |= t\n                else:\n                    no |= f\n            return yes, no\n        if isinstance(test, ast.Compare) and isinstance(test.left, ast.Name) \\\n                and len(test.ops) == 1:\n            op, comp = test.ops[0], test.comparators[0]\n            fixed = isinstance(comp, (ast.Tuple, ast.List, ast.Set, ast.Constant)) or (\n                isinstance(comp, ast.Name) and comp.id.isupper()) or (\n                isinstance(comp, ast.Attribute) and comp.attr.isupper())\n            if fixed and isinstance(op, (ast.In, ast.Eq, ast.Is)):\n                yes.add(test.left.id)\n            elif fixed and isinstance(op, (ast.NotIn, ast.NotEq, ast.IsNot)):\n                no.add(test.left.id)\n        if isinstance(test, ast.Call):\n            f = test.func\n            if isinstance(f, ast.Attribute) and f.attr in _VALID_METHODS \\\n                    and isinstance(f.value, ast.Name):\n                yes.add(f.value.id)\n            name = self.f.canonical(f)\n            if name in (\"re.fullmatch\", \"re.match\") and len(test.args) >= 2 \\\n                    and isinstance(test.args[1], ast.Name):\n                yes.add(test.args[1].id)\n            last = call_name(test)\n            if _VALIDATOR.match(last or \"\") or last.startswith(\"is_\"):\n                yes |= {a.id for a in test.args if isinstance(a, ast.Name)}\n        return yes, no\n\n    def _clear(self, names: set[str]) -> dict[str, frozenset]:\n        saved = {n: self.env[n] for n in names if n in self.env}\n        for n in saved:\n            self.env[n] = frozenset()\n        return saved\n\n    def block(self, body: list[ast.stmt]) -> None:\n        for st in body:\n            self.stmt(st)\n\n    def assign(self, target: ast.AST, taint: frozenset, strong: bool) -> None:\n        if isinstance(target, ast.Name):\n            self.env[target.id] = taint if strong else self.env.get(target.id, frozenset()) | taint\n        elif isinstance(target, (ast.Tuple, ast.List)):\n            for t in target.elts:\n                self.assign(t, taint, strong)\n        elif isinstance(target, ast.Starred):\n            self.assign(target.value, taint, strong)\n        elif isinstance(target, (ast.Subscript, ast.Attribute)):\n            root = target\n            while isinstance(root, (ast.Subscript, ast.Attribute)):\n                root = root.value\n            if isinstance(root, ast.Name):\n                self.env[root.id] = self.env.get(root.id, frozenset()) | taint\n\n    def stmt(self, st: ast.stmt) -> None:\n        if isinstance(st, ast.Assign):\n            taint = self.T(st.value)\n            for t in st.targets:\n                self.assign(t, taint, strong=self.depth == 0)\n        elif isinstance(st, ast.AnnAssign):\n            if st.value is not None:\n                self.assign(st.target, self.T(st.value), strong=self.depth == 0)\n        elif isinstance(st, ast.AugAssign):\n            self.assign(st.target, self.T(st.value) | self.T(st.target), strong=False)\n        elif isinstance(st, ast.Expr):\n            self.T(st.value)\n        elif isinstance(st, ast.Return):\n            for o in self.T(st.value):\n                if ALL in o.cleared:\n                    continue\n                if o.param >= 0:\n                    self.summary.param_returns.add(o.param)\n                elif o.src is not None:\n                    self.summary.returns_source.add(o.src)\n        elif isinstance(st, (ast.For, ast.AsyncFor)):\n            self.assign(st.target, self.T(st.iter), strong=False)\n            self.depth += 1\n            self.block(st.body)\n            self.block(st.orelse)\n            self.depth -= 1\n        elif isinstance(st, ast.While):\n            self.T(st.test)\n            self.depth += 1\n            self.block(st.body)\n            self.block(st.orelse)\n            self.depth -= 1\n        elif isinstance(st, ast.If):\n            self.T(st.test)\n            yes, no = self.validated(st.test)\n            self.depth += 1\n            saved = self._clear(yes)\n            self.block(st.body)\n            self.env.update({k: v for k, v in saved.items() if not self.env.get(k)})\n            saved = self._clear(no)\n            self.block(st.orelse)\n            self.env.update({k: v for k, v in saved.items() if not self.env.get(k)})\n            self.depth -= 1\n            if _exits(st.body) and no:              # if not valid(x): raise\n                self._clear(no)\n            if st.orelse and _exits(st.orelse) and yes:\n                self._clear(yes)\n        elif isinstance(st, ast.Assert):\n            self._clear(self.validated(st.test)[0])\n        elif isinstance(st, (ast.With, ast.AsyncWith)):\n            for item in st.items:\n                taint = self.T(item.context_expr)\n                if item.optional_vars is not None:\n                    self.assign(item.optional_vars, taint, strong=self.depth == 0)\n            self.block(st.body)\n        elif isinstance(st, ast.Try):\n            self.depth += 1\n            self.block(st.body)\n            for h in st.handlers:\n                self.block(h.body)\n            self.block(st.orelse)\n            self.block(st.finalbody)\n            self.depth -= 1\n        elif isinstance(st, getattr(ast, \"Match\", ())):\n            self.T(st.subject)\n            self.depth += 1\n            for case in st.cases:\n                self.block(case.body)\n            self.depth -= 1\n        elif isinstance(st, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):\n            return\n        else:\n            for child in ast.iter_child_nodes(st):\n                if isinstance(child, ast.expr):\n                    self.T(child)\n\n\ndef _exits(body: list[ast.stmt]) -> bool:\n    return bool(body) and isinstance(body[-1], (ast.Return, ast.Raise, ast.Continue, ast.Break))\n\n\ndef _candidates(ctx, touched: set[str], fns: dict) -> list[str]:\n    \"\"\"The edited functions and everything that calls them, directly or not: a flow through\n    edited code is found in one of these.\"\"\"\n    seen = {n for n in touched if n in fns}\n    todo = list(seen)\n    while todo and len(seen) < 3000:\n        for e in ctx.graph.callers(todo.pop()):\n            if e.kind == \"calls\" and not e.guess and e.src not in seen and e.src in fns:\n                seen.add(e.src)\n                todo.append(e.src)\n    return sorted(seen)\n\n\ndef _severity(sink: str, source: str) -> str | None:\n    sev = _SEVERITY[sink]\n    if source in _LOCAL_KINDS:\n        if sink not in _LOCAL_SINKS:\n            return None                     # a local tool doing what its user asked\n        sev = {\"critical\": \"high\", \"high\": \"medium\"}.get(sev, \"low\")\n    return sev\n\n\n_RANK = (\"critical\", \"high\", \"medium\", \"low\")\n_KIND_WORDS = {\"http-request\": \"request data\", \"network\": \"data from the network\",\n               \"socket\": \"data from a socket\", \"cli\": \"command-line input\",\n               \"stdin\": \"typed input\"}\n_WHO = {\"http-request\": \"anyone who can send a request\", \"network\": \"whoever controls that \"\n        \"server\", \"socket\": \"whoever is on the other end\", \"cli\": \"whoever runs it (or a \"\n        \"script that passes it data)\", \"stdin\": \"whoever types or pipes the input\"}\n\n\ndef _route(fl: Flow, path: str, line: int) -> str:\n    src, sink = fl.source, fl.sink\n    steps = [f\"{_short(src.fn)}() reads {src.desc} ({src.path}:{src.line})\"]\n    steps += [f\"{_short(h.fn)}() hands it to {_short(h.callee)}() ({h.path}:{h.line})\"\n              for h in sink.chain]\n    steps.append(f\"{_short(sink.fn)}() passes it to {sink.call}() ({path}:{line})\")\n    return \", then \".join(steps)\n\n\n@change_rule(\"unvalidated-input-reaches-sink\", \"critical\",\n             fix=\"Validate the value before it reaches the call, or use the safe form of the \"\n                 \"call.\")\ndef unvalidated_input_reaches_sink(ctx):\n    if not any(p.endswith(\".py\") for p in ctx.after.files):\n        return\n    an = _Analysis(ctx)\n    touched = {n for n in edited(ctx) if n in an.fns}\n    if not touched:\n        return\n    for name in _candidates(ctx, touched, an.fns):\n        an.walk(name)\n\n    groups: dict[tuple, list[Flow]] = {}\n    for fl in an.flows:\n        involved = {fl.source.fn, fl.via, fl.sink.fn, *(h.fn for h in fl.sink.chain)}\n        if not involved & touched:\n            continue\n        if _severity(fl.sink.kind, fl.source.kind) is None:\n            continue\n        groups.setdefault((fl.sink.path, fl.sink.line, fl.sink.kind), []).append(fl)\n\n    for (path, line, kind), flows in sorted(groups.items())[:20]:\n        flows.sort(key=lambda f: (_RANK.index(_severity(kind, f.source.kind)),\n                                  f.source.path, f.source.line, f.source.desc))\n        first = flows[0]\n        sev = _severity(kind, first.source.kind)\n        spec = next(s for s in SINKS if s.kind == kind)\n        others = sorted({f.source.desc for f in flows[1:]} - {first.source.desc})\n        words = _KIND_WORDS.get(first.source.kind, \"outside input\")\n        yield Finding(\n            \"unvalidated-input-reaches-sink\", sev,\n            f\"{words} ({first.source.desc}) reaches {first.sink.call}() in \"\n            f\"{_short(first.sink.fn)}() unchecked: it {spec.does}\",\n            path, line,\n            detail=(f\"{_route(first, path, line)}. Nothing on the way validates or escapes \"\n                    f\"it, so {_WHO.get(first.source.kind, 'whoever controls the input')} \"\n                    f\"decides what {first.sink.call}() gets.\"\n                    + (f\" Also reached from {', '.join(others[:3])}.\" if others else \"\")),\n            fix=_FIX[kind])\n", "magellan_lite/rules/threads.py": "\"\"\"unsynchronized-shared-state: two threads share an object's fields with no lock between them.\n\nTherac-25, 1985-1987: the operator could correct the prescription while the treatment task was\nstill setting up the magnets. The two tasks shared the beam mode and energy without\nsynchronisation, so a quick edit was only half seen, and the machine fired a beam about 100\ntimes the intended dose. At least six accidents; three patients died of their overdoses.\n\nThe rule looks inside each class for methods started as threads (``Thread(target=self.m)``,\n``Timer(t, self.m)``, ``executor.submit(self.m)``). When one of them writes a ``self.`` field\nthat another reads or writes, and neither holds a lock at that point (``with self.lock:``,\nor any field assigned a ``threading`` Lock, RLock, Condition or Semaphore), the two can\ninterleave halfway through an update.\n\nA method started more than once (in a loop, ``for _ in range(4): Thread(target=self.work)``,\nor from two places) races with itself. It is reported when it updates a field from that\nfield's old value with no lock held (``self.done += 1``, ``self.total = self.total + n``):\ntwo copies can read the same old value, and one update is lost. Quiet when the loop joins\neach thread before starting the next and for a ``Timer`` that re-arms itself (those copies\nrun one after another), and for fields it only sets (``self.running = True``) or only calls\nmethods on (a ``queue.Queue`` locks itself).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\n\nfrom magellan_lite.findings import rule\n\n_LOCK_TYPES = {\"Lock\", \"RLock\", \"Condition\", \"Semaphore\", \"BoundedSemaphore\"}\n_LOOPS = (ast.For, ast.AsyncFor, ast.While, ast.ListComp, ast.SetComp, ast.DictComp,\n          ast.GeneratorExp)\n\n\ndef _self_attr(node: ast.AST) -> str | None:\n    \"\"\"``self.x`` -> ``x``.\"\"\"\n    if isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name) and node.value.id == \"self\":\n        return node.attr\n    return None\n\n\ndef _name(func: ast.AST) -> str:\n    return func.id if isinstance(func, ast.Name) else func.attr if isinstance(func, ast.Attribute) else \"\"\n\n\ndef _started(call: ast.Call) -> str | None:\n    \"\"\"The method a ``Thread``, ``Timer`` or ``submit`` call starts: ``m`` for ``self.m``.\"\"\"\n    name = _name(call.func)\n    target = None\n    if name == \"Thread\":\n        target = next((k.value for k in call.keywords if k.arg == \"target\"), None)\n        if target is None and len(call.args) > 1:\n            target = call.args[1]                       # Thread(group, target, ...)\n    elif name == \"Timer\" and len(call.args) > 1:\n        target = call.args[1]\n    elif name == \"submit\" and call.args:\n        target = call.args[0]\n    return _self_attr(target) if target is not None else None\n\n\ndef _joins(call: ast.AST) -> bool:\n    \"\"\"``t.join()`` or ``t.join(5)``: waits for a thread (not ``\", \".join(names)``).\"\"\"\n    if not (isinstance(call, ast.Call) and isinstance(call.func, ast.Attribute)\n            and call.func.attr == \"join\" and not isinstance(call.func.value, ast.Constant)):\n        return False\n    if not call.args and not call.keywords:\n        return True                                     # t.join()\n    if len(call.args) + len(call.keywords) > 1 or any(k.arg != \"timeout\" for k in call.keywords):\n        return False\n    wait = call.args[0] if call.args else call.keywords[0].value\n    return isinstance(wait, ast.Constant) or call.keywords != [] or _name(wait) == \"timeout\"\n\n\ndef _thread_starts(cls: ast.ClassDef) -> dict[str, list[tuple[int, bool, bool]]]:\n    \"\"\"Methods of ``cls`` started on a thread of their own: ``(line, in a loop, from the\n    method itself)`` for each place that starts one. A loop that also waits for a thread\n    (``t.join()``) runs them one at a time, so it does not count as a loop here; nor does a\n    method that starts itself again (a ``Timer`` that re-arms: one run after another).\"\"\"\n    out: dict[str, list[tuple[int, bool, bool]]] = {}\n\n    def visit(node: ast.AST, looping: bool, current: str | None) -> None:\n        for child in ast.iter_child_nodes(node):\n            inside, within = looping, current\n            if isinstance(child, _LOOPS):\n                inside = looping or not any(_joins(n) for n in ast.walk(child))\n            elif node is cls and isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):\n                within = child.name\n            if isinstance(child, ast.Call) and (method := _started(child)):\n                out.setdefault(method, []).append((child.lineno, looping, method == current))\n            visit(child, inside, within)\n\n    visit(cls, False, None)\n    return out\n\n\ndef _locks(cls: ast.ClassDef) -> set[str]:\n    \"\"\"Fields that hold a lock: assigned a threading lock, or named like one.\"\"\"\n    out = set()\n    for node in ast.walk(cls):\n        if isinstance(node, ast.Assign) and isinstance(node.value, ast.Call):\n            f = node.value.func\n            kind = f.id if isinstance(f, ast.Name) else getattr(f, \"attr\", \"\")\n            if kind in _LOCK_TYPES:\n                out |= {a for t in node.targets if (a := _self_attr(t))}\n        if isinstance(node, ast.Attribute) and \"lock\" in node.attr.lower():\n            if _self_attr(node):\n                out.add(node.attr)\n    return out\n\n\ndef _unlocked(fn: ast.AST, locks: set[str]):\n    \"\"\"Every node of a method that runs with no lock held, without going into nested\n    functions (they run later, maybe elsewhere).\"\"\"\n    def visit(node: ast.AST, locked: bool):\n        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)) and node is not fn:\n            return\n        if isinstance(node, (ast.With, ast.AsyncWith)):\n            holds = any(_self_attr(i.context_expr) in locks for i in node.items)\n            for i in node.items:\n                yield from visit(i.context_expr, locked)\n            for child in node.body:\n                yield from visit(child, locked or holds)\n            return\n        if not locked:\n            yield node\n        for child in ast.iter_child_nodes(node):\n            yield from visit(child, locked)\n    yield from visit(fn, False)\n\n\ndef _accesses(fn: ast.AST, locks: set[str]):\n    \"\"\"``(field, \"write\" or \"read\", line)`` for every ``self.`` field touched with no lock\n    held. Writes include ``self.x += 1`` and calling a method on the field.\"\"\"\n    for node in _unlocked(fn, locks):\n        attr = _self_attr(node)\n        if attr and attr not in locks:                  # self.x += 1 is a Store too\n            yield attr, \"write\" if isinstance(node.ctx, (ast.Store, ast.Del)) else \"read\", node.lineno\n        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):\n            if (attr := _self_attr(node.func.value)) and attr not in locks:\n                yield attr, \"write\", node.lineno        # self.items.append(...) changes it\n\n\ndef _lost_updates(fn: ast.AST, locks: set[str]):\n    \"\"\"``(field, line)`` for every update of a ``self.`` field from its own old value with no\n    lock held: ``self.n += 1``, ``self.counts[key] += 1``, ``self.total = self.total + n``.\"\"\"\n    for node in _unlocked(fn, locks):\n        if isinstance(node, ast.AugAssign):\n            target = node.target.value if isinstance(node.target, ast.Subscript) else node.target\n            if (attr := _self_attr(target)) and attr not in locks:\n                yield attr, node.lineno\n        elif isinstance(node, (ast.Assign, ast.AnnAssign)) and node.value is not None:\n            old = {_self_attr(n) for n in ast.walk(node.value)}\n            for target in (node.targets if isinstance(node, ast.Assign) else [node.target]):\n                if (attr := _self_attr(target)) and attr in old and attr not in locks:\n                    yield attr, node.lineno\n\n\ndef _and(names: list[str]) -> str:\n    return names[0] if len(names) == 1 else \", \".join(names[:-1]) + \" and \" + names[-1]\n\n\n@rule(\"unsynchronized-shared-state\", \"high\",\n      fix=\"Hold one lock around every read and write of the shared fields \"\n          \"(`with self.lock:` in both methods), so one thread never sees half an update.\")\ndef unsynchronized_shared_state(tree: ast.Module, path: str):\n    for cls in ast.walk(tree):\n        if not isinstance(cls, ast.ClassDef):\n            continue\n        methods = {f.name: f for f in cls.body if isinstance(f, (ast.FunctionDef, ast.AsyncFunctionDef))}\n        starts = {m: s for m, s in _thread_starts(cls).items() if m in methods}\n        if not starts:\n            continue\n        targets = {m: s[0][0] for m, s in starts.items()}   # the first line that starts each\n        locks = _locks(cls)\n        reported: set[str] = set()                      # one finding per writer is enough\n\n        # two methods on two threads, one writing what the other uses\n        touched = {m: list(_accesses(methods[m], locks)) for m in targets}\n        for writer, uses in touched.items():\n            writes = {}\n            for attr, how, line in uses:\n                if how == \"write\":\n                    writes.setdefault(attr, line)\n            for other, their in touched.items():\n                if other == writer:\n                    continue\n                shared = sorted(a for a in writes if any(a == b for b, _h, _l in their))\n                if not shared:\n                    continue\n                first = min(writes[a] for a in shared)\n                reported.add(writer)\n                yield (first,\n                       f\"{writer}() writes {_and([f'self.{a}' for a in shared])} while \"\n                       f\"{other}() uses {'it' if len(shared) == 1 else 'them'} on another \"\n                       f\"thread, with no lock held\",\n                       f\"Both are started as threads (lines {targets[writer]} and \"\n                       f\"{targets[other]}), so {other}() can run halfway through {writer}()'s \"\n                       f\"update and see a mix of old and new values. Therac-25: a quick edit \"\n                       f\"was half seen by the setup task, and patients received about 100 \"\n                       f\"times the intended dose.\")\n                break\n\n        # one method on several threads at once, racing with itself\n        for method, lines in starts.items():\n            again = [(n, in_loop) for n, in_loop, itself in lines if not itself]\n            if method in reported or not (len(again) > 1 or any(loop for _, loop in again)):\n                continue\n            lost: dict[str, int] = {}\n            for attr, line in _lost_updates(methods[method], locks):\n                lost.setdefault(attr, line)\n            if not lost:\n                continue\n            looped = next((n for n, in_loop in again if in_loop), None)\n            how = (f\"in a loop (line {looped})\" if looped is not None else\n                   f\"from {len(again)} places (lines {_and([str(n) for n, _ in again])})\")\n            yield (min(lost.values()),\n                   f\"{method}() updates {_and([f'self.{a}' for a in lost])} from the \"\n                   f\"old value with no lock held, and it runs on several threads at once\",\n                   f\"It is started as a thread {how}, so two copies can read the same old \"\n                   f\"value and one of the updates is lost. Therac-25: tasks that shared the \"\n                   f\"machine's settings with no lock between them let it fire a beam about \"\n                   f\"100 times the intended dose.\")\n", "magellan_lite/rules/undefined_names.py": "\"\"\"undefined-name: a name the change left undefined -- the NameError waiting for its line.\n\nFrom the full Magellan (``magellan/python/rules/names.py``). The typical case is not a typo\nbut a removal: an import deleted while code three screens down still uses it, a module\nrenamed (``import httplib`` -> ``import http.client``) with ``httplib.HTTPS`` left behind, a\nhelper renamed in one place only. Nothing points at the old name any more, so a call graph\ncannot see it; it has to be read off the source.\n\nScopes come from the standard library's ``symtable``, which applies Python's own rules\n(class bodies are not visible to their methods, comprehensions have their own scope,\n``global`` and ``nonlocal``). A name is undefined when some scope reads it as a global and\nnothing defines it: not the module, not a builtin. Only names undefined after the change and\nnot before are reported, so old problems stay a linter's business, and a file whose names\ncannot be known (``from x import *``, ``globals()[...] = ...``, ``exec``) is left alone.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nimport builtins\nimport symtable\n\nfrom magellan_lite.findings import Finding, change_rule\nfrom magellan_lite.rules.common import changed_files\nfrom magellan_lite.source import module_name\n\n#: names a module (or a class body) always has at run time\n_IMPLICIT = frozenset({\n    \"__name__\", \"__file__\", \"__doc__\", \"__package__\", \"__spec__\", \"__loader__\",\n    \"__builtins__\", \"__path__\", \"__annotations__\", \"__dict__\", \"__debug__\", \"__cached__\",\n    \"__module__\", \"__qualname__\", \"__class__\",\n})\n#: builtins of other Pythons and platforms than this one, and gettext's installed `_`\n_ELSEWHERE = frozenset({\n    \"WindowsError\", \"ExceptionGroup\", \"BaseExceptionGroup\", \"EncodingWarning\", \"aiter\",\n    \"anext\", \"PythonFinalizationError\", \"_IncompleteInputError\", \"reveal_type\", \"_\",\n})\n_KNOWN = frozenset(dir(builtins)) | _IMPLICIT | _ELSEWHERE\n#: calls that can define module names nothing in the source spells out\n_DYNAMIC = frozenset({\"globals\", \"exec\", \"execfile\", \"vars\", \"locals\", \"__import__\"})\n\n\ndef undefined_names(source: str, path: str = \"<module>\") -> dict[str, list[int]] | None:\n    \"\"\"``{name: [lines that read it]}`` for globals nothing defines, or None when that cannot\n    be known (it does not parse as Python 3, a star import, names made at run time).\"\"\"\n    try:\n        tree = ast.parse(source, filename=path)\n    except (SyntaxError, ValueError):\n        return None                     # Python 2, or broken: not this rule's business\n    for node in ast.walk(tree):\n        if isinstance(node, ast.ImportFrom) and any(a.name == \"*\" for a in node.names):\n            return None                 # a star import can supply anything\n        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) \\\n                and node.func.id in _DYNAMIC:\n            return None\n    try:\n        top = symtable.symtable(source, path, \"exec\")\n    except (SyntaxError, ValueError):\n        return None\n    defined: set[str] = set()\n    read: set[str] = set()\n\n    def walk(table) -> None:\n        module = table.get_type() == \"module\"\n        for sym in table.get_symbols():\n            name = sym.get_name()\n            if module and (sym.is_assigned() or sym.is_imported() or sym.is_namespace()):\n                defined.add(name)\n            if sym.is_declared_global() and sym.is_assigned():\n                defined.add(name)                 # global x; x = ... inside a function\n            if sym.is_referenced() and (module or (sym.is_global() and not sym.is_local())):\n                read.add(name)\n        for child in table.get_children():\n            walk(child)\n\n    walk(top)\n    missing = read - defined - _KNOWN\n    if not missing:\n        return {}\n    annotations_only = _future_annotations(tree)\n    in_annotation = _annotation_names(tree) if annotations_only else set()\n    lines: dict[str, list[int]] = {}\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load) and node.id in missing \\\n                and id(node) not in in_annotation:\n            lines.setdefault(node.id, []).append(node.lineno)\n    return {n: sorted(set(ls)) for n, ls in lines.items()}\n\n\ndef _future_annotations(tree: ast.Module) -> bool:\n    return any(isinstance(n, ast.ImportFrom) and n.module == \"__future__\"\n               and any(a.name == \"annotations\" for a in n.names) for n in tree.body)\n\n\ndef _annotation_names(tree: ast.Module) -> set[int]:\n    \"\"\"ids of the Name nodes inside annotations, which ``from __future__ import annotations``\n    never evaluates.\"\"\"\n    out: set[int] = set()\n    for node in ast.walk(tree):\n        anns = []\n        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):\n            a = node.args\n            anns += [x.annotation for x in [*a.posonlyargs, *a.args, *a.kwonlyargs,\n                                            a.vararg, a.kwarg] if x is not None]\n            anns.append(node.returns)\n        elif isinstance(node, ast.AnnAssign):\n            anns.append(node.annotation)\n        for ann in anns:\n            if ann is not None:\n                out |= {id(n) for n in ast.walk(ann) if isinstance(n, ast.Name)}\n    return out\n\n\ndef _runs_at_import(tree: ast.Module, lines: list[int]) -> list[int]:\n    \"\"\"The lines among ``lines`` outside every def and lambda: they run on import.\"\"\"\n    inside: set[int] = set()\n    for node in ast.walk(tree):\n        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):\n            inside.update(range(node.lineno, (node.end_lineno or node.lineno) + 1))\n    return [ln for ln in lines if ln not in inside]\n\n\ndef _bound_names(source: str) -> set[str]:\n    \"\"\"Every name the old version imported, defined or assigned somewhere.\"\"\"\n    try:\n        tree = ast.parse(source)\n    except (SyntaxError, ValueError):\n        return set()\n    out: set[str] = set()\n    for node in ast.walk(tree):\n        if isinstance(node, (ast.Import, ast.ImportFrom)):\n            out |= {(a.asname or a.name).split(\".\")[0] for a in node.names}\n        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):\n            out.add(node.name)\n        elif isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):\n            out.add(node.id)\n    return out\n\n\ndef _reported_elsewhere(ctx) -> set[tuple[str, int]]:\n    \"\"\"Lines removed-still-referenced already reports (a call to a deleted function): one\n    finding per line is enough.\"\"\"\n    out: set[tuple[str, int]] = set()\n    for c in ctx.changes:\n        if c.kind in (\"removed\", \"renamed\") and c.before is not None \\\n                and c.before.name not in ctx.after_defs:\n            out |= {(e.path, e.line) for e in ctx.graph.callers(c.before.name)}\n    return out\n\n\n@change_rule(\"undefined-name\", \"critical\", blocking=True,\n             fix=\"Import or define the name again, or update the code that still uses it.\")\ndef undefined_name(ctx):\n    skip = None\n    for path in sorted(changed_files(ctx)):\n        after = ctx.after.files.get(path)\n        if after is None:\n            continue\n        now = undefined_names(after, path)\n        if not now:\n            continue\n        before = ctx.before.files.get(path)\n        was = undefined_names(before, path) if before is not None else {}\n        if was is None:\n            continue                                # unknowable before: no comparison\n        if skip is None:\n            skip = _reported_elsewhere(ctx)\n        tree = ast.parse(after)\n        for name, lines in sorted(now.items()):\n            if name in was:\n                continue                            # already undefined: not this change\n            lines = [ln for ln in lines if (path, ln) not in skip]\n            if not lines:\n                continue\n            at_import = _runs_at_import(tree, lines)\n            had = before is not None and name in _bound_names(before)\n            where = (f\"line {lines[0]}\" if len(lines) == 1\n                     else f\"lines {', '.join(map(str, lines[:6]))}\"\n                     + (\" and more\" if len(lines) > 6 else \"\"))\n            yield Finding(\n                \"undefined-name\", \"critical\" if at_import else \"high\",\n                f\"{name} is used in {module_name(path)} but nothing defines it\"\n                + (\" any more\" if had else \"\"),\n                path, lines[0],\n                detail=(f\"Read at {where}. \"\n                        + (f\"Line {at_import[0]} runs when the module is imported, so the \"\n                           f\"import itself fails with NameError. \" if at_import else\n                           \"The first call that reaches it raises NameError. \")\n                        + (f\"The previous version defined or imported {name}; this change \"\n                           f\"removed or renamed it.\" if had else\n                           \"No import, assignment or definition in the module provides it, \"\n                           \"and it is not a builtin.\")))\n", "magellan_lite/security.py": "\"\"\"The website's security headers, in one place: ``magellan-lite serve`` sends them, and\n``demo/build_site.py`` writes them to ``site/_headers``, which Cloudflare Pages applies to\nevery file it serves. Whichever host answers, a page may load and contact exactly this:\n\n- scripts: the site's own, the one inline script (by hash), and Pyodide from the CDN, which\n  runs the engine in the browser (``'wasm-unsafe-eval'`` lets it compile WebAssembly; nothing\n  allows ``eval`` of text);\n- connections: the site itself, the CDN (Pyodide's packages), and GitHub's API and raw files,\n  which the Team suite reads a repository's shared work in progress from;\n- no frames, no plugins, no forms posting anywhere, no ``<base>`` tricks.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport base64\nimport hashlib\nimport re\nfrom pathlib import Path\n\nPYODIDE_CDN = \"https://cdn.jsdelivr.net\"\nGITHUB = (\"https://api.github.com\", \"https://raw.githubusercontent.com\")\n\n\ndef inline_script_hashes(site: Path) -> list[str]:\n    \"\"\"CSP hashes for the inline scripts of the site's pages, so nothing else inline runs.\"\"\"\n    out = set()\n    for page in site.glob(\"*.html\"):\n        for body in re.findall(r\"<script>(.*?)</script>\", page.read_text(\"utf-8\", \"replace\"), re.S):\n            out.add(\"'sha256-\" + base64.b64encode(hashlib.sha256(body.encode()).digest()).decode() + \"'\")\n    return sorted(out)\n\n\ndef csp(site: Path) -> str:\n    return \"; \".join([\n        \"default-src 'self'\",\n        \" \".join([\"script-src 'self'\", *inline_script_hashes(site), PYODIDE_CDN,\n                  \"'wasm-unsafe-eval'\"]),\n        \"worker-src 'self'\",\n        \"style-src 'self' 'unsafe-inline'\",           # style=\"--heat: .8\" on map nodes\n        \"img-src 'self' data:\",\n        \" \".join([\"connect-src 'self'\", PYODIDE_CDN, *GITHUB]),\n        \"object-src 'none'\",\n        \"base-uri 'none'\",\n        \"frame-ancestors 'none'\",\n        \"form-action 'none'\",\n    ])\n\n\ndef headers(site: Path) -> dict[str, str]:\n    \"\"\"Every security header, for every response.\"\"\"\n    return {\n        \"X-Content-Type-Options\": \"nosniff\",\n        \"X-Frame-Options\": \"DENY\",\n        \"Referrer-Policy\": \"no-referrer\",\n        \"Cross-Origin-Opener-Policy\": \"same-origin\",\n        \"Permissions-Policy\": \"camera=(), microphone=(), geolocation=(), payment=()\",\n        \"Strict-Transport-Security\": \"max-age=31536000\",\n        \"Content-Security-Policy\": csp(site),\n    }\n\n\ndef pages_headers(site: Path) -> str:\n    \"\"\"``site/_headers`` for Cloudflare Pages: the same headers on every path.\"\"\"\n    lines = [\"# Security headers for Cloudflare Pages: written by demo/build_site.py from\",\n             \"# magellan_lite/security.py -- do not edit by hand\", \"/*\"]\n    lines += [f\"  {k}: {v}\" for k, v in headers(site).items()]\n    return \"\\n\".join(lines) + \"\\n\"\n", "magellan_lite/settings.py": "\"\"\"A project's own settings, from the ``[tool.magellan-lite]`` table of its pyproject.toml.\n\n    [tool.magellan-lite]\n    fail-on = \"review\"                      # block (the default), review or never\n    disable = [\"compare-to-none\"]           # rules whose findings are left out\n    exclude = [\"migrations/\", \"tests/fixtures/*.py\"]   # paths whose findings are left out\n\n``exclude`` takes paths relative to the pyproject.toml: a directory (``migrations/``) covers\neverything under it, and ``*`` matches across ``/``. A flag on the command line beats the file.\n\nReading TOML needs ``tomllib``, new in Python 3.11. On 3.10 the file is not read and the\ndefaults apply.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom fnmatch import fnmatchcase\nfrom pathlib import Path\n\nfrom magellan_lite.report import VERDICTS, Report\n\nFAIL_ON = (*VERDICTS[1:], \"never\")\nKEYS = (\"fail-on\", \"disable\", \"exclude\")\n\n\nclass SettingsError(ValueError):\n    \"\"\"pyproject.toml cannot be read, or a setting has the wrong kind of value.\"\"\"\n\n\n@dataclass\nclass Settings:\n    fail_on: str | None = None              # None: the command line's default (block)\n    disable: tuple[str, ...] = ()\n    exclude: tuple[str, ...] = ()\n    #: the checked project's place under the pyproject.toml (\"\" when they are the same folder)\n    prefix: str = \"\"\n    #: settings that look like mistakes but do not stop the check (an unknown key or rule)\n    warnings: list[str] = field(default_factory=list)\n\n    def is_excluded(self, path: str) -> bool:\n        path = f\"{self.prefix}/{path}\" if self.prefix else path\n        for pattern in self.exclude:\n            pattern = pattern.replace(\"\\\\\", \"/\").removeprefix(\"./\")\n            if fnmatchcase(path, pattern) or path.startswith(pattern.rstrip(\"/\") + \"/\"):\n                return True\n        return False\n\n\ndef find_pyproject(root: Path) -> Path | None:\n    \"\"\"The nearest pyproject.toml at or above ``root``, not looking past the repository's\n    top (the folder holding ``.git``).\"\"\"\n    for folder in (root, *root.parents):\n        if (folder / \"pyproject.toml\").is_file():\n            return folder / \"pyproject.toml\"\n        if (folder / \".git\").exists():\n            return None\n    return None\n\n\ndef load(root: str | Path) -> Settings:\n    \"\"\"The settings for the project at ``root``; the defaults when there are none.\"\"\"\n    root = Path(root).resolve()\n    path = find_pyproject(root)\n    if path is None:\n        return Settings()\n    try:\n        import tomllib\n    except ImportError:                     # Python 3.10: no TOML reader in the standard library\n        return Settings()\n    try:\n        data = tomllib.loads(path.read_text(encoding=\"utf-8\"))\n    except tomllib.TOMLDecodeError as exc:\n        raise SettingsError(f\"cannot read {path}: {exc}\") from None\n    table = data.get(\"tool\", {}).get(\"magellan-lite\", {})\n    if not isinstance(table, dict):\n        raise SettingsError(f\"{path}: [tool.magellan-lite] must be a table\")\n\n    where = f\"{path} [tool.magellan-lite]\"\n    fail_on = table.get(\"fail-on\")\n    if fail_on is not None and fail_on not in FAIL_ON:\n        raise SettingsError(f\"{where}: fail-on must be one of {', '.join(FAIL_ON)}, \"\n                            f\"not {fail_on!r}\")\n    disable, exclude = _strings(table, \"disable\", where), _strings(table, \"exclude\", where)\n\n    prefix = root.relative_to(path.parent).as_posix() if root != path.parent else \"\"\n    out = Settings(fail_on, disable, exclude, prefix)\n    out.warnings += [f\"{where}: unknown setting {k!r} (known: {', '.join(KEYS)})\"\n                     for k in table if k not in KEYS]\n    import magellan_lite.rules  # noqa: F401  importing the package registers every rule\n    from magellan_lite.findings import RULES\n    out.warnings += [f\"{where}: disable names no rule called {r!r} (see `magellan-lite rules`)\"\n                     for r in disable if r not in RULES]\n    return out\n\n\ndef _strings(table: dict, key: str, where: str) -> tuple[str, ...]:\n    value = table.get(key, [])\n    if isinstance(value, str):\n        value = [value]\n    if not isinstance(value, list) or not all(isinstance(v, str) for v in value):\n        raise SettingsError(f\"{where}: {key} must be a list of strings\")\n    return tuple(value)\n\n\ndef apply(report: Report, settings: Settings) -> Report:\n    \"\"\"Leave out the findings of disabled rules, and the findings and changes in excluded\n    paths. The verdict follows, since it is worked out from the findings.\"\"\"\n    report.findings = [f for f in report.findings\n                       if f.rule not in settings.disable and not settings.is_excluded(f.path)]\n    report.changes = [c for c in report.changes if not settings.is_excluded(c.path)]\n    return report\n", "magellan_lite/source.py": "\"\"\"Reading a project: which files, their text, their syntax trees.\n\nLessons from running the full Magellan on Windows are built in: files are read as UTF-8\nwhatever the system locale, paths use forward slashes on every OS, and line endings never\ncount as a change (definitions are hashed from syntax trees, not text).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nimport os\nfrom pathlib import Path\n\n#: directories that hold no project code (tools, environments, build output)\nSKIP_DIRS = frozenset({\"__pycache__\", \"venv\", \"env\", \"build\", \"dist\", \"node_modules\",\n                       \"site-packages\"})\n\n\ndef is_skipped_dir(name: str) -> bool:\n    return name in SKIP_DIRS or name.startswith(\".\")\n\n\ndef iter_source_files(root: Path) -> list[str]:\n    \"\"\"Every source file under ``root`` that Lite maps (Python, and the languages in\n    languages.py), as sorted forward-slash paths relative to it.\"\"\"\n    from magellan_lite.languages import is_source\n    out: list[str] = []\n    for dirpath, dirnames, filenames in os.walk(root):\n        dirnames[:] = sorted(d for d in dirnames if not is_skipped_dir(d))\n        for name in sorted(filenames):\n            if is_source(name):\n                out.append(Path(dirpath, name).relative_to(root).as_posix())\n    return out\n\n\niter_python_files = iter_source_files       # the old name\n\n\ndef decode(data: bytes) -> str:\n    \"\"\"Source bytes as text: UTF-8 (a BOM is dropped), never the system's code page.\"\"\"\n    return data.decode(\"utf-8-sig\", errors=\"replace\")\n\n\ndef module_name(path: str) -> str:\n    \"\"\"``pkg/mod.py`` -> ``pkg.mod``; ``pkg/__init__.py`` -> ``pkg``; ``src/`` is dropped.\"\"\"\n    parts = path[:-3].split(\"/\") if path.endswith(\".py\") else path.split(\"/\")\n    if parts and parts[0] == \"src\" and len(parts) > 1:\n        parts = parts[1:]\n    if parts and parts[-1] == \"__init__\":\n        parts = parts[:-1]\n    return \".\".join(parts) or \"__init__\"\n\n\nclass Snapshot:\n    \"\"\"One version of a project: ``{relative path: source text}``, parsed on demand.\"\"\"\n\n    def __init__(self, files: dict[str, str], label: str = \"\") -> None:\n        self.files = files\n        self.label = label\n        self.errors: dict[str, str] = {}\n        self._trees: dict[str, ast.Module | None] = {}\n\n    def tree(self, path: str) -> ast.Module | None:\n        \"\"\"A Python file's syntax tree, or None when it does not parse (the error is kept).\n        Python 2 is read too, rewritten into its Python 3 spelling line for line (the full\n        Magellan's py2.py), so old code waiting for its upgrade is still on the map. Other\n        languages have no Python tree: None, and no error.\"\"\"\n        if path not in self._trees:\n            if not path.endswith(\".py\"):\n                self._trees[path] = None\n                return None\n            try:\n                self._trees[path] = ast.parse(self.files[path], filename=path)\n            except SyntaxError as exc:\n                self._trees[path] = self._python2(path)\n                if self._trees[path] is None:\n                    self.errors[path] = f\"{path}:{exc.lineno or 0}: {exc.msg}\"\n        return self._trees[path]\n\n    def _python2(self, path: str) -> ast.Module | None:\n        from magellan_lite.polyglot.python.py2 import to_python3\n        try:\n            return ast.parse(to_python3(self.files[path]), filename=path)\n        except (SyntaxError, ValueError):\n            return None\n\n\ndef working_tree(root: str | Path) -> Snapshot:\n    \"\"\"The project as it is on disk now.\"\"\"\n    root = Path(root)\n    files = {rel: decode((root / rel).read_bytes()) for rel in iter_source_files(root)}\n    return Snapshot(files, label=str(root))\n", "magellan_lite/web.py": "\"\"\"What the website draws for one change: the report, plus the map it was worked out on.\n\nThe local server's ``/api/check``, the website's \"Try it\" box (which runs this module in the\nvisitor's browser, through Pyodide) and ``demo/build_site.py`` all call ``check_with_map``, so\nthe page draws the same thing whichever of them answered. The Team suite calls ``team_live``:\neveryone's shared work in progress at once.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nimport re\nfrom collections import Counter\nfrom pathlib import Path\n\nfrom magellan_lite.combine import _changed, combine, derive\nfrom magellan_lite.defs import Definition, definitions\nfrom magellan_lite.engine import check_snapshots\nfrom magellan_lite.graph import build_graph\nfrom magellan_lite.source import Snapshot, module_name\n\n#: past this many definitions the map keeps only the change's neighbourhood\nMAX_NODES = 60\n#: the whole project, for the 3D scene: past this many, the best connected definitions\nPROJECT_NODES = 1200\n\n\ndef check_with_map(before: dict[str, str], after: dict[str, str]) -> dict:\n    \"\"\"``Report.to_dict()`` for two versions given as ``{path: source}``, plus ``map``.\"\"\"\n    b, a = Snapshot(dict(before), \"before\"), Snapshot(dict(after), \"after\")\n    report = check_snapshots(b, a, Path(\".\"), \"request\").to_dict()\n    report[\"map\"] = code_map(b, a, report)\n    return report\n\n\ndef team_live(base: dict[str, str], works: dict[str, dict[str, str]]) -> dict:\n    \"\"\"Everyone's work in progress, checked alone, two by two, and all together.\n\n    ``base`` is the version everyone builds on (the default branch); ``works`` is each\n    person's version of the project, ``{name: {path: source}}``. Returns\n\n    - ``members``: each person's own check, with its map (``name`` plus ``Report.to_dict()``);\n    - ``pairs``: for each two people, the problems only their two changes together have;\n    - ``team``: everyone's changes applied at once, checked, with a map of the whole project\n      (up to ``PROJECT_NODES`` definitions) whose nodes say whose change made them (``by``) and\n      whose change reaches them (``reached_by``). A file two people both changed is taken from\n      the first of them by name, and listed in ``overlap``. With nobody's work yet, it is the\n      project as it is: something to look at from the first moment.\n    \"\"\"\n    root = Path(\".\")\n    b = Snapshot(dict(base), \"base\")\n    snaps = {name: derive(b, files, name) for name, files in sorted(works.items())}\n    alone = {name: check_snapshots(b, s, root, name) for name, s in snaps.items()}\n\n    members = []\n    for name, s in snaps.items():\n        r = alone[name].to_dict()\n        r[\"map\"] = code_map(b, s, r)\n        members.append({\"name\": name, **r})\n\n    names, pairs = list(snaps), []\n    for i, x in enumerate(names):\n        for y in names[i + 1:]:\n            c = combine(root, b, snaps[x], snaps[y], y, alone=(alone[x], alone[y])).to_dict()\n            pairs.append({\"a\": x, \"b\": y, \"verdict\": c[\"verdict\"], \"findings\": c[\"findings\"],\n                          \"affected\": c[\"affected\"], \"overlap\": c[\"overlap\"]})\n\n    together, owner, overlap = dict(base), {}, {}\n    for name, s in snaps.items():\n        for path in sorted(_changed(b.files, s.files)):\n            if path in owner:\n                overlap.setdefault(path, [owner[path]]).append(name)\n                continue\n            owner[path] = name\n            if path in s.files:\n                together[path] = s.files[path]\n            else:\n                together.pop(path, None)\n    t = derive(b, together, \"team\")\n    team = check_snapshots(b, t, root, \"team\").to_dict()\n    team[\"map\"] = code_map(b, t, team, PROJECT_NODES, whole=True)     # the whole project\n    changed_by = {n: {c.name for c in alone[n].changes} for n in names}\n    reached_by = {n: {a[\"name\"] for a in alone[n].affected} for n in names}\n    for node in team[\"map\"][\"nodes\"]:\n        node[\"by\"] = [n for n in names if node[\"id\"] in changed_by[n]]\n        node[\"reached_by\"] = [n for n in names if node[\"id\"] in reached_by[n]]\n    team[\"overlap\"] = [{\"path\": p, \"names\": ns} for p, ns in sorted(overlap.items())]\n    return {\"members\": members, \"pairs\": pairs, \"team\": team}\n\n\ndef code_map(before: Snapshot, after: Snapshot, report: dict, limit: int = MAX_NODES,\n             whole: bool = False) -> dict:\n    \"\"\"The definitions of the new version (and the ones the change deleted) and who calls or\n    reads whom, each marked with what the change did to it: ``{\"nodes\": [...], \"edges\": [...]}``.\n\n    Past ``limit`` definitions only the change's neighbourhood is kept -- or, with ``whole``\n    (the project map the 3D scene draws), the neighbourhood and then the best connected rest.\n    \"\"\"\n    before_defs, after_defs = definitions(before), definitions(after)\n    graph = build_graph(after, after_defs, before_defs)\n\n    changed = {c[\"name\"]: c[\"kind\"] for c in report[\"changes\"]}\n    affected = {a[\"name\"]: a for a in report[\"affected\"]}\n    defs: dict[str, tuple[Definition, bool]] = {n: (d, False) for n, d in after_defs.items()}\n    defs.update({n: (d, True) for n, d in before_defs.items() if n not in after_defs})\n\n    edges, seen = [], set()\n    for e in graph.edges:\n        key = (e.src, e.dst, e.kind)\n        if e.src in defs and e.dst in defs and e.src != e.dst and key not in seen:\n            seen.add(key)\n            edges.append({\"src\": e.src, \"dst\": e.dst, \"kind\": e.kind, \"guess\": e.guess})\n\n    keep = set(defs)\n    if len(keep) > limit:                       # the change, what it reaches, their neighbours\n        core = set(changed) | set(affected) | {n for n, (d, _) in defs.items()\n                                              if _has_finding(d, report[\"findings\"])}\n        near = {e[\"src\"] for e in edges if e[\"dst\"] in core} | \\\n               {e[\"dst\"] for e in edges if e[\"src\"] in core}\n        keep = set(sorted(core)[:limit])\n        keep |= set(sorted(near - keep)[:max(0, limit - len(keep))])\n        if whole and len(keep) < limit:\n            degree: dict[str, int] = {}\n            for e in edges:\n                degree[e[\"src\"]] = degree.get(e[\"src\"], 0) + 1\n                degree[e[\"dst\"]] = degree.get(e[\"dst\"], 0) + 1\n            rest = sorted(set(defs) - keep, key=lambda n: (-degree.get(n, 0), n))\n            keep |= set(rest[:limit - len(keep)])\n        edges = [e for e in edges if e[\"src\"] in keep and e[\"dst\"] in keep]\n\n    unused = _unmentioned(after, {n: d for n, (d, removed) in defs.items() if not removed})\n    nodes = []\n    for name in sorted(keep):\n        d, removed = defs[name]\n        mod = module_name(d.path)\n        hit = affected.get(name)\n        nodes.append({\n            \"id\": name,\n            \"label\": d.label or (name[len(mod) + 1:] if name.startswith(mod + \".\") else name),\n            \"path\": d.path, \"line\": d.line, \"kind\": d.kind, \"lang\": d.lang or \"python\",\n            \"change\": changed.get(name, \"\"),\n            \"removed\": removed,\n            \"score\": hit[\"score\"] if hit else 0,\n            \"hops\": hit[\"hops\"] if hit else 0,\n            \"finding\": not removed and _has_finding(d, report[\"findings\"]),\n            \"unused\": name in unused,\n        })\n    return {\"nodes\": nodes, \"edges\": edges}\n\n\ndef _has_finding(d: Definition, findings: list[dict]) -> bool:\n    return any(f[\"path\"] == d.path and d.line <= f[\"line\"] <= d.end_line and d.kind != \"class\"\n               for f in findings)\n\n\n_WORDS = re.compile(r\"[A-Za-z_][A-Za-z0-9_-]*\")\n\n\ndef _unmentioned(snapshot: Snapshot, defs: dict[str, Definition]) -> set[str]:\n    \"\"\"Definitions whose name appears nowhere in the project except where they are defined:\n    nothing calls, reads, imports or re-exports them under that name -- probably dead code\n    (the 3D view's skull). Only a call by a computed name, or a user outside the project,\n    can still reach them. Text, not the call graph: a name used at module level or in a class\n    body counts too, which the graph does not see.\n\n    Left out, because something finds them without naming them: decorated definitions (the\n    decorator registers them: a route, a rule, a fixture), dunder methods, subclasses and the\n    members of subclasses (a framework calls the overrides, a registry finds the subclass),\n    and tests (the runner finds them by their names).\"\"\"\n    mentions = Counter()\n    for text in snapshot.files.values():\n        mentions.update(_WORDS.findall(text))\n    short = {name: (d.label or d.short).split(\"(\", 1)[0] for name, d in defs.items()}\n    defined = Counter(short.values())\n    candidates = {name for name, word in short.items() if mentions[word] <= defined[word]}\n\n    decorated: set[tuple[str, int]] = set()\n    for path in {defs[n].path for n in candidates if defs[n].path.endswith(\".py\")}:\n        tree = snapshot.tree(path)\n        for node in ast.walk(tree) if tree is not None else ():\n            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) and node.decorator_list:\n                decorated.add((path, node.lineno))\n\n    def found_otherwise(name: str) -> bool:\n        d = defs[name]\n        word = short[name]\n        if (d.path, d.line) in decorated or (word.startswith(\"__\") and word.endswith(\"__\")):\n            return True\n        if d.path.endswith(\".py\") and _TEST_PATH.search(d.path):\n            return True\n        if not d.path.endswith(\".py\"):                      # Java annotations, C attributes\n            lines = snapshot.files.get(d.path, \"\").splitlines()\n            i = d.line - 2\n            while 0 <= i < len(lines) and not lines[i].strip():\n                i -= 1\n            if 0 <= i < len(lines) and lines[i].lstrip().startswith(\"@\"):\n                return True\n        subclass = lambda c: bool(c and c.kind == \"class\" and c.signature.strip() not in (\"\", \"object\"))   # noqa: E731\n        return subclass(d) or subclass(defs.get(name.rsplit(\".\", 1)[0]))\n\n    return {name for name in candidates if not found_otherwise(name)}\n\n\n_TEST_PATH = re.compile(r\"(^|/)(tests?/|test_[^/]*$|[^/]*_test\\.py$|conftest\\.py$)\")\n"}};
